    var writer = external_owner_seal.Writer.init("MARURDA1");
    writer.writeUsize(aggregate.saved_self_addr);
    writer.writeUsize(aggregate.owner_aggregate_addr);
    writer.writeU8(aggregate.count);
    for (aggregate.entries[0..aggregate.count]) |entry|
        writer.writeBytes(&entry.digest);
    return writer.finish();
}

fn immutableRecoveryCommitOutputDigest(
    output: *const ImmutableRecoveryCommitOutput,
) external_owner_seal.Digest {
    var writer = external_owner_seal.Writer.init("MARURCO1");
    writer.writeUsize(output.saved_self_addr);
    writer.writeUsize(output.aggregate_addr);
    writer.writeUsize(output.ledger_addr);
    writer.writeUsize(output.storage_addr);
    writer.writeUsize(output.live_commit_addr);
    writer.writeBytes(&output.live_commit_digest);
    writer.writeBytes(&output.ledger_output.digest);
    writer.writeU16(output.token.slot);
    writer.writeU64(output.token.generation);
    writer.writeBytes(&output.semantic_digest);
    writeRecoveryIntentForPump(&writer, output.recovery_intent);
    writer.writeU8(@intFromEnum(output.origin));
    writer.writeU64(output.recovery_epoch);
    writer.writeBool(output.is_snapshot);
    writer.writeU64(output.start_absolute);
    writer.writeU64(output.end_absolute);
    writer.writeU8(@intFromEnum(output.lifecycle));
    return writer.finish();
}

fn preparedRecoverySnapshotCommitDigest(
    prepared: *const PreparedRecoverySnapshotCommit,
) external_owner_seal.Digest {
    var writer = external_owner_seal.Writer.init("MARURPC1");
    writer.writeUsize(prepared.saved_self_addr);
    writer.writeUsize(prepared.aggregate_addr);
    writer.writeUsize(prepared.storage_addr);
    writer.writeUsize(prepared.ledger_addr);
    writer.writeUsize(prepared.lease_addr);
    writer.writeUsize(prepared.scratch_addr);
    writer.writeBytes(&prepared.lease_digest);
    writer.writeU64(prepared.owner_incarnation);
    writer.writeU64(prepared.operation_generation);
    writer.writeU64(prepared.turn_generation);
    writer.writeBytes(&prepared.parser_seal.digest);
    writeAuthorityGeneration(&writer, prepared.authority_generation);
    writer.writeBytes(&prepared.authority_seal_digest);
    writeRecoveryAuthorityState(&writer, prepared.authority_state);
    writeRecoveryAuthorityState(&writer, prepared.binding_next_state);
    writer.writeBytes(&prepared.prepared_live_commit_digest);
    writer.writeU8(@intFromEnum(std.meta.activeTag(prepared.source)));
    switch (prepared.source) {
        .commit_pending => |source| {
            writer.writeUsize(source.live_commit_addr);
            writer.writeBytes(&source.live_commit_digest);
        },
        .already_committed => |source| {
            writer.writeUsize(source.output_addr);
            writer.writeBytes(&source.output_digest);
        },
    }
    writer.writeU8(@intFromEnum(prepared.source_discriminator));
    writer.writeUsize(prepared.ack_transition_addr);
    writer.writeBytes(&prepared.ack_transition_digest);
    writer.writeUsize(prepared.dispositions_addr);
    writer.writeBytes(&prepared.dispositions_root_digest);
    writer.writeUsize(prepared.committed_output_addr);
    writer.writeBytes(&prepared.committed_output_pristine_digest);
    writer.writeUsize(prepared.binding_destination_addr);
    writer.writeBytes(&prepared.binding_destination_pristine_digest);
    writer.writeBool(prepared.has_binding);
    writer.writeU8(prepared.binding_entry_index);
    writer.writeU8(prepared.ledger_output_index);
    writer.writeU8(@intFromEnum(prepared.lifecycle));
    return writer.finish();
}

fn committedRecoverySnapshotBindingDigest(
    binding: *const CommittedRecoverySnapshotBinding,
) external_owner_seal.Digest {
    var writer = external_owner_seal.Writer.init("MARURCB1");
    writer.writeUsize(binding.saved_self_addr);
    writer.writeUsize(binding.aggregate_addr);
    writer.writeUsize(binding.scratch_addr);
    writer.writeUsize(binding.storage_addr);
    writer.writeUsize(binding.ledger_addr);
    writer.writeUsize(binding.lease_addr);
    writer.writeBytes(&binding.lease_digest);
    writer.writeU64(binding.owner_incarnation);
    writer.writeU64(binding.operation_generation);
    writer.writeU64(binding.turn_generation);
    writer.writeU64(binding.parser_generation);
    writer.writeBytes(&binding.parser_seal.digest);
    writeAuthorityGeneration(&writer, binding.authority_generation);
    writer.writeBytes(&binding.authority_seal_digest);
    writeRecoveryAuthorityState(&writer, binding.awaiting_state);
    writer.writeBytes(&binding.awaiting_state_digest);
    writer.writeBytes(&binding.ledger_authority_digest);
    writer.writeU16(binding.token.slot);
    writer.writeU64(binding.token.generation);
    writer.writeBytes(&binding.semantic_digest);
    writeRecoveryIntentForPump(&writer, binding.recovery_intent);
    writer.writeU8(@intFromEnum(binding.origin));
    writer.writeU64(binding.recovery_epoch);
    writer.writeBool(binding.is_snapshot);
    writer.writeU64(binding.start_absolute);
    writer.writeU64(binding.end_absolute);
    writer.writeUsize(binding.source_output_addr);
    writer.writeBytes(&binding.source_output_digest);
    writer.writeUsize(binding.side_intent_addr);
    writer.writeBytes(&binding.side_intent_digest);
    writer.writeBytes(&binding.destination_pristine_digest);
    writer.writeU8(@intFromEnum(binding.source_discriminator));
    writer.writeBytes(&binding.source_provenance_digest);
    writer.writeUsize(binding.ack_transition_addr);
    writer.writeBytes(&binding.ack_transition_digest);
    writer.writeU8(@intFromEnum(binding.lifecycle));
    return writer.finish();
}

fn preparedRxAggregateDigest(
    aggregate: *const PreparedRxAggregate,
) external_owner_seal.Digest {
    var writer = external_owner_seal.Writer.init("MARURAG1");
    writer.writeUsize(aggregate.saved_self_addr);
    writer.writeUsize(aggregate.handle_addr);
    writer.writeUsize(aggregate.storage_addr);
    writer.writeU64(aggregate.turn_generation);
    writer.writeU128(@bitCast(aggregate.turn_now_ns));
    writer.writeUsize(aggregate.intent_handle_addr);
    writer.writeU64(aggregate.intent_reservation_generation);
    writer.writeBytes(&aggregate.live_batch.digest);
    writer.writeBytes(&aggregate.live_batch.progress_digest);
    writer.writeBytes(&aggregate.live_batch.working_simulation_digest);
    writer.writeBytes(&aggregate.live_commit.digest);
    writer.writeBytes(&aggregate.retirement.digest);
    for (aggregate.dispositions) |disposition| switch (disposition) {
        .unused => writer.writeU8(0),
        .final_live => |root| {
            writer.writeU8(1);
            writer.writeU16(root.token.slot);
            writer.writeU64(root.token.generation);
            writer.writeU8(switch (root.phase) {
                .partial => 0,
                .completed => 1,
            });
        },
        .cleanup_final => |root| {
            writer.writeU8(3);
            writer.writeU16(root.token.slot);
            writer.writeU64(root.token.generation);
            writer.writeU8(switch (root.phase) {
                .partial => 0,
                .completed => 1,
            });
        },
        .superseded_tombstone => writer.writeU8(2),
    };
    for (aggregate.screen_transfers) |transfer|
        writer.writeBytes(&transfer.digest);
    for (aggregate.screen_proofs) |proof|
        writer.writeBytes(&proof.digest);
    for (aggregate.neutral_payloads) |payload|
        writer.writeBytes(&payload.digest);
    writer.writeBytes(&aggregate.intent_commit.digest);
    for (aggregate.event_retirements) |retirement|
        writer.writeBytes(&retirement.digest);
    for (aggregate.event_cleanup) |cleanup|
        writer.writeBytes(&cleanup.content_digest);
    writer.writeBytes(&aggregate.event_reduction.digest);
    writer.writeBytes(
        &external_event_materialization
            .preparedLiveMetadataDestinationAuthorityDigest(
            &aggregate.metadata_destination,
        ),
    );
    writer.writeBytes(&aggregate.metadata_summary_expected_digest);
    writer.writeU64(aggregate.metadata_summary_next_generation);
    writer.writeBytes(&aggregate.metadata_summary_next.digest);
    writer.writeBytes(&aggregate.metadata_cleanup_content_digest);
    writer.writeBytes(&aggregate.authority_destination.digest);
    writer.writeBytes(&aggregate.resize_destination.digest);
    writer.writeBytes(&aggregate.screen_destination.digest);
    writer.writeBytes(&aggregate.response_destination.digest);
    writer.writeBytes(&aggregate.recovery_dispositions.root_digest);
    writer.writeBytes(&aggregate.recovery_snapshot_commit.digest);
    writer.writeBytes(&aggregate.recovery_commit_output.digest);
    writer.writeBytes(&aggregate.recovery_snapshot_binding.digest);
    writer.writeU8(aggregate.destination_write_count);
    for (aggregate.destination_writes) |write|
        writer.writeBytes(&write.digest);
    writer.writeU8(@intFromEnum(aggregate.lifecycle));
    return writer.finish();
}

fn screenDestinationPlanDigest(
    plan: *const FrozenScreenDestinationPlan,
) external_owner_seal.Digest {
    var writer = external_owner_seal.Writer.init("MARURDP1");
    writer.writeUsize(plan.saved_self_addr);
    writer.writeUsize(plan.aggregate_addr);
    writer.writeUsize(plan.storage_addr);
    writer.writeBytes(&plan.live_commit_digest);
    writer.writeBytes(&plan.expected_screen_digest);
    writer.writeU8(plan.expected_screen_head);
    writer.writeU8(plan.expected_screen_len);
    writer.writeU64(plan.expected_screen_generation);
    writer.writeU64(plan.next_screen_generation);
    writer.writeBool(plan.expected_partial_empty);
    writer.writeU16(plan.expected_partial_token.slot);
    writer.writeU64(plan.expected_partial_token.generation);
    writer.writeU64(plan.expected_partial_generation);
    writer.writeBytes(&plan.expected_partial_digest);
    writer.writeU64(plan.next_partial_generation);
    writer.writeU8(plan.entry_count);
    writer.writeU8(plan.partial_count);
    writer.writeU8(plan.completed_count);
    for (plan.entries[0..plan.entry_count]) |entry| {
        writer.writeU16(entry.token.slot);
        writer.writeU64(entry.token.generation);
        writer.writeU8(switch (entry.phase) {
            .partial => 0,
            .completed => 1,
        });
    }
    writer.writeU8(@intFromEnum(plan.lifecycle));
    return writer.finish();
}

fn responseDestinationPlanDigest(
    plan: *const FrozenResponseDestinationPlan,
) external_owner_seal.Digest {
    var writer = external_owner_seal.Writer.init("MARURRP1");
    writer.writeUsize(plan.saved_self_addr);
    writer.writeUsize(plan.aggregate_addr);
    writer.writeUsize(plan.storage_addr);
    writer.writeUsize(plan.neutral_addr);
    writer.writeU8(plan.intent_index);
    writer.writeU64(plan.request_id);
    writer.writeU8(@intFromEnum(plan.control_kind));
    writeControlExpectation(&writer, plan.expectation);
    writer.writeU64(plan.target_stream_id);
    writer.writeU64(plan.expected_controller_generation);
    writer.writeUsize(plan.control_wire_len);
    writer.writeU64(plan.expected_correlation_generation);
    writer.writeBytes(&plan.expected_correlation_digest);
    writer.writeU64(plan.source_turn_generation);
    writer.writeU64(plan.source_parser_generation);
    writer.writeU64(plan.source_start_absolute);
    writer.writeU64(plan.source_end_absolute);
    writer.writeBytes(&plan.source_owner_digest);
    writer.writeBytes(&plan.payload_digest);
    writer.writeBytes(&plan.response_payload_digest);
    writer.writeUsize(plan.payload_allocator_ptr_addr);
    writer.writeUsize(plan.payload_allocator_vtable_addr);
    writer.writeUsize(plan.payload_addr);
    writer.writeUsize(plan.payload_len);
    writer.writeU64(plan.expected_generation);
    writer.writeU64(plan.next_generation);
    writer.writeU8(@intFromEnum(plan.lifecycle));
    return writer.finish();
}

fn screenTransferDigest(
    transfer: *const ScreenTransferOwner,
) external_owner_seal.Digest {
    var writer = external_owner_seal.Writer.init("MARURST1");
    writer.writeUsize(transfer.saved_self_addr);
    writer.writeUsize(transfer.aggregate_addr);
    writer.writeU8(transfer.intent_index);
    writer.writeU16(transfer.header.major);
    writer.writeU16(@intFromEnum(transfer.header.kind));
    writer.writeU64(transfer.header.stream_id);
    writer.writeU64(transfer.header.request_id);
    writer.writeU64(transfer.header.flags);
    writer.writeU64(transfer.header.payload_len);
    writer.writeU64(transfer.range.identity.attach_instance_id);
    writer.writeUsize(transfer.range.identity.destination_slot_addr);
    writer.writeU64(transfer.range.start_absolute);
    writer.writeU64(transfer.range.end_absolute);
    writer.writeBytes(&transfer.payload_digest);
    writer.writeBytes(&transfer.neutral.digest);
    writer.writeUsize(@intFromPtr(transfer.ledger_payload.allocator.ptr));
    writer.writeUsize(@intFromPtr(transfer.ledger_payload.allocator.vtable));
    writer.writeUsize(if (transfer.ledger_payload.allocation_ptr) |ptr|
        @intFromPtr(ptr)
    else
        0);
    writer.writeUsize(transfer.ledger_payload.logical_len);
    writer.writeUsize(transfer.batch_addr);
    writer.writeU8(transfer.mutation_index);
    writer.writeU8(@intFromEnum(transfer.lifecycle));
    return writer.finish();
}

fn screenTransferPristine(transfer: *const ScreenTransferOwner) bool {
    return transfer.saved_self_addr == 0 and
        transfer.aggregate_addr == 0 and
        transfer.intent_index == 0 and
        std.meta.eql(transfer.header, protocol.Header{ .kind = .hello }) and
        transfer.range.identity.attach_instance_id == 0 and
        transfer.range.identity.destination_slot_addr == 0 and
        transfer.range.start_absolute == 0 and
        transfer.range.end_absolute == 0 and
        std.mem.allEqual(u8, &transfer.payload_digest, 0) and
        transfer.batch_addr == 0 and
        transfer.mutation_index == 0 and
        transfer.lifecycle == .empty and
        transfer.ledger_payload.allocation_ptr == null and
        transfer.ledger_payload.logical_len == 0 and
        std.mem.allEqual(u8, &transfer.digest, 0);
}

fn screenTransferSemantic(
    transfer: *const ScreenTransferOwner,
) ?external_inbox_ledger.PayloadSemantic {
    const span = std.math.sub(
        u64,
        transfer.range.end_absolute,
        transfer.range.start_absolute,
    ) catch return null;
    const compact_span = std.math.cast(u32, span) orelse return null;
    const provenance: external_inbox_ledger.StoredRxBatchProvenance =
        .{ .external = .{
            .start_absolute = transfer.range.start_absolute,
            .span = compact_span,
        } };
    return if (protocol.Flags.hasEndStream(transfer.header.flags))
        .{ .completed = .{
            .stream_id = transfer.header.stream_id,
            .is_snapshot = transfer.header.kind == .snapshot_chunk,
            .provenance = provenance,
        } }
    else
        .{ .partial = .{
            .stream_id = transfer.header.stream_id,
            .is_snapshot = transfer.header.kind == .snapshot_chunk,
            .chunk_count = 1,
            .provenance = provenance,
        } };
}

fn bindRecoveryIntentForCurrentState(
    storage: *const ExternalPumpStorage,
    semantic: external_inbox_ledger.PayloadSemantic,
) external_inbox_ledger.PayloadSemantic {
    var next = semantic;
    const active = switch (storage.semantic_state) {
        .active => |value| value,
        else => return next,
    };
    const intent_and_barrier: struct {
        intent: external_inbox_ledger.RecoveryIntent,
        barrier: u64,
    } = switch (active) {
        .host_recovery => |phase| switch (phase) {
            .awaiting_snapshot => |waiting| .{
                .intent = .{ .host = waiting.context.epoch },
                .barrier = waiting.recovery_barrier_absolute,
            },
            else => return next,
        },
        .client_recovery => |phase| switch (phase) {
            .awaiting_snapshot => |waiting| .{
                .intent = .{ .client = waiting.context.epoch },
                .barrier = waiting.recovery_barrier_absolute,
            },
            else => return next,
        },
        .valid => return next,
    };
    switch (next) {
        .partial => |*value| switch (value.provenance) {
            .external => |range| if (value.is_snapshot and
                value.stream_id == storage.evidence_snapshot.stream_id and
                range.start_absolute >= intent_and_barrier.barrier)
            {
                value.recovery_intent = intent_and_barrier.intent;
            },
            .untracked => {},
        },
        .completed => |*value| switch (value.provenance) {
            .external => |range| if (value.is_snapshot and
                value.stream_id == storage.evidence_snapshot.stream_id and
                range.start_absolute >= intent_and_barrier.barrier)
            {
                value.recovery_intent = intent_and_barrier.intent;
            },
            .untracked => {},
        },
        .frame, .lease => {},
    }
    return next;
}

fn continuedScreenTransferSemantic(
    storage: *const ExternalPumpStorage,
    aggregate: *const PreparedRxAggregate,
    transfer: *const ScreenTransferOwner,
    mutation_index: u8,
) ?external_inbox_ledger.PayloadSemantic {
    var start_absolute = transfer.range.start_absolute;
    var prior_chunk_count: u8 = 0;
    var recovery_intent: external_inbox_ledger.RecoveryIntent = .none;
    var cursor = mutation_index;
    while (cursor != 0) {
        const prior_mutation = cursor - 1;
        var prior_transfer: ?*const ScreenTransferOwner = null;
        for (&aggregate.screen_transfers) |*candidate| {
            if ((candidate.lifecycle == .batch_owned or
                candidate.lifecycle == .mutation_bound) and
                candidate.mutation_index == prior_mutation)
            {
                prior_transfer = candidate;
                break;
            }
        }
        const prior = prior_transfer orelse return null;
        const prior_semantic = screenTransferSemantic(prior) orelse return null;
        if (prior_semantic != .partial or
            prior.range.end_absolute != start_absolute)
            return null;
        start_absolute = prior.range.start_absolute;
        prior_chunk_count = std.math.add(u8, prior_chunk_count, 1) catch
            return null;
        cursor = prior_mutation;
    }
    switch (storage.live_partial) {
        .assembling => |assembling| {
            const observed = storage.inbox_ledger.partialSnapshot(
                assembling.ledger_token,
            ) catch return null;
            const range = switch (observed.provenance) {
                .external => |range| range,
                .untracked => return null,
            };
            if (range.end_absolute != start_absolute or
                !std.meta.eql(range.identity, transfer.range.identity))
                return null;
            start_absolute = range.start_absolute;
            prior_chunk_count = std.math.add(
                u8,
                prior_chunk_count,
                observed.chunk_count,
            ) catch return null;
            recovery_intent = observed.recovery_intent;
        },
        .none => {},
        .terminal => return null,
    }
    const span = std.math.sub(
        u64,
        transfer.range.end_absolute,
        start_absolute,
    ) catch return null;
    const compact_span = std.math.cast(u32, span) orelse return null;
    const provenance: external_inbox_ledger.StoredRxBatchProvenance =
        .{ .external = .{
            .start_absolute = start_absolute,
            .span = compact_span,
        } };
    return if (protocol.Flags.hasEndStream(transfer.header.flags))
        .{ .completed = .{
            .stream_id = transfer.header.stream_id,
            .is_snapshot = transfer.header.kind == .snapshot_chunk,
            .recovery_intent = recovery_intent,
            .provenance = provenance,
        } }
    else
        .{ .partial = .{
            .stream_id = transfer.header.stream_id,
            .is_snapshot = transfer.header.kind == .snapshot_chunk,
            .chunk_count = std.math.add(
                u8,
                prior_chunk_count,
                1,
            ) catch return null,
            .recovery_intent = recovery_intent,
            .provenance = provenance,
        } };
}

fn validateRxAggregateScreenGraph(
    storage: *const ExternalPumpStorage,
    aggregate: *const PreparedRxAggregate,
    intent_handle: *external_rx_intent.ExternalRxIntentHandle,
) bool {
    for (&aggregate.screen_transfers, 0..) |*transfer, index| {
        if (transfer.lifecycle == .empty) {
            if (!screenTransferPristine(transfer)) return false;
            continue;
        }
        if (transfer.saved_self_addr != @intFromPtr(transfer) or
            transfer.aggregate_addr != @intFromPtr(aggregate) or
            transfer.intent_index != index or
            !std.mem.eql(
                u8,
                &transfer.digest,
                &screenTransferDigest(transfer),
            ) or !external_rx_intent.validateStagedScreenBinding(
            intent_handle,
            @intCast(index),
            @intFromPtr(aggregate),
            @intFromPtr(&transfer.neutral),
            transfer.header,
            transfer.range,
            transfer.payload_digest,
        ))
            return false;
        switch (transfer.lifecycle) {
            .neutral_owned => {
                const borrowed = external_rx_intent.borrowMovedIntentPayload(
                    &transfer.neutral,
                    @intFromPtr(aggregate),
                ) orelse return false;
                if (!std.mem.eql(
                    u8,
                    &borrowed.content_digest,
                    &transfer.payload_digest,
                ) or transfer.ledger_payload.allocation_ptr != null or
                    transfer.ledger_payload.logical_len != 0 or
                    transfer.batch_addr != 0)
                    return false;
            },
            .ledger_owned => {
                if (!external_rx_intent.validateMovedIntentPayloadTombstone(
                    &transfer.neutral,
                    @intFromPtr(aggregate),
                ) or !std.mem.eql(
                    u8,
                    &external_owner_cleanup.contentDigest(
                        transfer.ledger_payload.bytes(),
                    ),
                    &transfer.payload_digest,
                ) or transfer.batch_addr != 0)
                    return false;
            },
            .batch_owned, .mutation_bound => {
                if (!external_rx_intent.validateMovedIntentPayloadTombstone(
                    &transfer.neutral,
                    @intFromPtr(aggregate),
                ) or transfer.ledger_payload.allocation_ptr != null or
                    transfer.ledger_payload.logical_len != 0 or
                    transfer.batch_addr != @intFromPtr(&aggregate.live_batch) or
                    transfer.mutation_index >=
                        aggregate.live_batch.mutation_count or
                    !storage.inbox_ledger.validatePreparedLiveScreenBinding(
                        &aggregate.live_batch,
                        transfer.mutation_index,
                        switch (aggregate.live_batch.mutations[
                            transfer.mutation_index
                        ]) {
                            .merge => bindRecoveryIntentForCurrentState(
                                storage,
                                continuedScreenTransferSemantic(
                                    storage,
                                    aggregate,
                                    transfer,
                                    transfer.mutation_index,
                                ) orelse return false,
                            ),
                            else => bindRecoveryIntentForCurrentState(
                                storage,
                                screenTransferSemantic(transfer) orelse
                                    return false,
                            ),
                        },
                        transfer.payload_digest,
                    ))
                    return false;
                for (aggregate.screen_transfers[0..index]) |prior|
                    if ((prior.lifecycle == .batch_owned or
                        prior.lifecycle == .mutation_bound) and
                        prior.mutation_index == transfer.mutation_index)
                        return false;
                if (transfer.lifecycle == .mutation_bound and
                    !external_rx_intent.validateScreenMutationScalar(
                        intent_handle,
                        @intCast(index),
                        @intFromPtr(aggregate),
                        &aggregate.screen_proofs[index],
                    ))
                    return false;
            },
            .committed, .aborted, .poisoned, .empty => return false,
        }
    }
    return true;
}

fn validateCommittedRecoveryScreenGraph(
    aggregate: *const PreparedRxAggregate,
    intent_handle: *external_rx_intent.ExternalRxIntentHandle,
) bool {
    if (aggregate.live_batch.lifecycle != .committed or
        aggregate.live_commit.lifecycle != .consumed)
        return false;
    for (&aggregate.screen_transfers, 0..) |*transfer, index| {
        if (transfer.lifecycle == .empty) {
            if (!screenTransferPristine(transfer)) return false;
            continue;
        }
        if (transfer.lifecycle != .mutation_bound or
            transfer.saved_self_addr != @intFromPtr(transfer) or
            transfer.aggregate_addr != @intFromPtr(aggregate) or
            transfer.intent_index != index or
            transfer.batch_addr != @intFromPtr(&aggregate.live_batch) or
            transfer.mutation_index >= aggregate.live_commit.mutation_count or
            !std.mem.eql(u8, &transfer.digest, &screenTransferDigest(transfer)) or
            !external_rx_intent.validateMovedIntentPayloadTombstone(
                &transfer.neutral,
                @intFromPtr(aggregate),
            ) or transfer.ledger_payload.allocation_ptr != null or
            transfer.ledger_payload.logical_len != 0 or
            !external_rx_intent.validateScreenMutationScalar(
                intent_handle,
                @intCast(index),
                @intFromPtr(aggregate),
                &aggregate.screen_proofs[index],
            )) return false;
    }
    return true;
}

fn prepareScreenDestinationPlan(
    storage: *const ExternalPumpStorage,
    aggregate: *PreparedRxAggregate,
) bool {
    const plan = &aggregate.screen_destination;
    if (plan.saved_self_addr != 0 or plan.lifecycle != .empty or
        !storage.liveScreenValid() or !storage.livePartialValid())
        return false;
    var entries = [_]ScreenDestinationEntry{.{}} **
        external_inbox_ledger.max_live_mutations;
    var entry_count: usize = 0;
    var partial_count: usize = 0;
    var completed_count: usize = 0;
    for (aggregate.dispositions[0..aggregate.live_batch.mutation_count]) |disposition| {
        switch (disposition) {
            .final_live => |root| {
                entries[entry_count] = .{
                    .token = root.token,
                    .phase = switch (root.phase) {
                        .partial => .partial,
                        .completed => .completed,
                    },
                };
                entry_count += 1;
                switch (root.phase) {
                    .partial => partial_count += 1,
                    .completed => completed_count += 1,
                }
            },
            .cleanup_final, .superseded_tombstone => {},
            .unused => return false,
        }
    }
    const existing_partial = switch (storage.live_partial) {
        .none => null,
        .assembling => |assembling| assembling,
        .terminal => return false,
    };
    if (partial_count != aggregate.live_commit.final_partial_count or
        completed_count != aggregate.live_commit.final_completed_count or
        partial_count > 1 or
        storage.live_screen.len + completed_count >
            external_inbox_ledger.max_live_mutations)
        return false;
    const next_partial_generation: u64 = if (existing_partial) |partial|
        std.math.add(u64, partial.generation, 1) catch return false
    else if (partial_count != 0)
        @as(u64, 1)
    else
        @as(u64, 0);
    const next_generation = if (completed_count == 0)
        storage.live_screen.generation
    else
        std.math.add(
            u64,
            storage.live_screen.generation,
            1,
        ) catch return false;
    plan.* = .{
        .saved_self_addr = @intFromPtr(plan),
        .aggregate_addr = @intFromPtr(aggregate),
        .storage_addr = @intFromPtr(storage),
        .live_commit_digest = aggregate.live_commit.digest,
        .expected_screen_digest = storage.live_screen.owner_digest,
        .expected_screen_head = storage.live_screen.head,
        .expected_screen_len = storage.live_screen.len,
        .expected_screen_generation = storage.live_screen.generation,
        .next_screen_generation = next_generation,
        .expected_partial_empty = storage.live_partial == .none,
        .expected_partial_token = if (existing_partial) |partial|
            partial.ledger_token
        else
            .{ .slot = 0, .generation = 0 },
        .expected_partial_generation = if (existing_partial) |partial|
            partial.generation
        else
            0,
        .expected_partial_digest = if (existing_partial) |partial|
            partial.owner_digest
        else
            [_]u8{0} ** 32,
        .next_partial_generation = next_partial_generation,
        .entries = entries,
        .entry_count = @intCast(entry_count),
        .partial_count = @intCast(partial_count),
        .completed_count = @intCast(completed_count),
        .lifecycle = .prepared,
        .digest = undefined,
    };
    plan.digest = screenDestinationPlanDigest(plan);
    return true;
}

const EventReductionContext = struct {
    storage: *const ExternalPumpStorage,
    intent_handle: *external_rx_intent.ExternalRxIntentHandle,
    identity: runtime_event_wire.ExpectedIdentity,
    event_to_intent: *const [external_rx_intent.max_intents]u8,
    event_count: *const u8,

    fn validateInitial(
        self: *const EventReductionContext,
        seed: runtime_event_reducer.InitialMetadataSeed,
    ) bool {
        const current = self.storage.owner_metadata.reductionSeed(self.storage) orelse
            return false;
        return std.meta.eql(current, seed);
    }

    fn compareMetadata(
        self: *const EventReductionContext,
        current: runtime_event_reducer.MetadataCandidate,
        next_payload: []const u8,
        next_preflight: runtime_event_wire.EventPreflight,
    ) runtime_event_reducer.MetadataComparison {
        return switch (current.origin) {
            .initial => blk: {
                const ordinal = self.event_count.*;
                if (ordinal >= self.event_to_intent.len) break :blk .stale;
                const intent_index = self.event_to_intent[ordinal];
                if (intent_index == std.math.maxInt(u8)) break :blk .stale;
                const next = external_rx_intent.borrowClassifiedEvent(
                    self.intent_handle,
                    intent_index,
                ) orelse break :blk .stale;
                break :blk self.storage.owner_metadata.compareCurrentWithExactEvent(
                    self.storage,
                    next.allocator,
                    next_payload,
                    self.identity,
                    next_preflight,
                );
            },
            .event => |ordinal| blk: {
                if (ordinal >= self.event_count.*) break :blk .stale;
                const intent_index = self.event_to_intent[ordinal];
                if (intent_index == std.math.maxInt(u8)) break :blk .stale;
                const prior = external_rx_intent.borrowClassifiedEvent(
                    self.intent_handle,
                    intent_index,
                ) orelse break :blk .stale;
                const prior_preflight = switch (current.proof) {
                    .event => |proof| proof,
                    .initial => break :blk .stale,
                };
                const prior_metadata = switch (prior_preflight.event) {
                    .metadata => |metadata| metadata,
                    else => break :blk .stale,
                };
                const next_metadata = switch (next_preflight.event) {
                    .metadata => |metadata| metadata,
                    else => break :blk .stale,
                };
                break :blk if (runtime_event_wire.metadataSemanticEqlExact(
                    prior.payload,
                    &prior_metadata,
                    next_payload,
                    &next_metadata,
                ))
                    .equal
                else
                    .different;
            },
        };
    }
};

fn ownerEventAuthority(
    storage: *const ExternalPumpStorage,
) ?runtime_event_types.EventAuthorityView {
    if (!ownerAuthorityValid(storage)) return null;
    const current = switch (storage.owner_authority) {
        .current => |value| value,
        .empty => return null,
    };
    if (current.flow != .clear) return null;
    return .{
        .role = switch (current.role) {
            .observer => .observer,
            .controller => .controller,
        },
        .generation = switch (current.generation) {
            .untracked => .untracked,
            .tracked => |generation| .{ .tracked = generation },
        },
    };
}

const PrepareEventReductionResult = enum {
    prepared,
    terminal_runtime_ended,
    rejected,
};

fn prepareEventReduction(
    storage: *const ExternalPumpStorage,
    aggregate: *PreparedRxAggregate,
    intent_handle: *external_rx_intent.ExternalRxIntentHandle,
) PrepareEventReductionResult {
    const reduction = &aggregate.event_reduction;
    const pristine_reduction = PreparedEventReduction{};
    if (!std.mem.eql(
        u8,
        &eventReductionDigest(reduction),
        &eventReductionDigest(&pristine_reduction),
    )) return .rejected;
    var has_event = false;
    for (aggregate.intent_commit.slot_kinds[0..aggregate.intent_commit.intent_count]) |kind|
        has_event = has_event or kind == .event;
    if (!has_event) return .prepared;
    const client = if (storage.owned_client) |*owned| owned else return .rejected;
    const profile = client.externalTransferProfile() orelse return .rejected;
    const authority = ownerEventAuthority(storage) orelse return .rejected;
    const identity = runtime_event_types.EventIdentity{
        .runtime_id = storage.evidence_snapshot.runtime_id,
        .stream_id = storage.evidence_snapshot.stream_id,
    };
    if (identity.runtime_id == 0 or identity.stream_id == 0) return .rejected;

    var event_to_intent =
        [_]u8{std.math.maxInt(u8)} ** external_rx_intent.max_intents;
    var event_count: u8 = 0;
    var accumulator: runtime_event_reducer.Accumulator = .{};
    const seed = storage.owner_metadata.reductionSeed(storage);
    var context = EventReductionContext{
        .storage = storage,
        .intent_handle = intent_handle,
        .identity = .{
            .runtime_id = identity.runtime_id,
            .stream_id = identity.stream_id,
        },
        .event_to_intent = &event_to_intent,
        .event_count = &event_count,
    };
    if (seed) |initial|
        accumulator.initWithMetadataInPlace(
            authority,
            initial,
            &context,
            EventReductionContext.validateInitial,
        )
    else
        accumulator.initInPlace(authority);

    for (aggregate.intent_commit.slot_kinds[0..aggregate.intent_commit.intent_count], 0..) |
        kind,
        intent_index,
    | {
        if (kind != .event) continue;
        const borrowed = external_rx_intent.borrowClassifiedEvent(
            intent_handle,
            @intCast(intent_index),
        ) orelse return .rejected;
        event_to_intent[event_count] = @intCast(intent_index);
        const verdict = runtime_event_wire.preflightEvent(
            borrowed.payload,
            context.identity,
        );
        accumulator.stepAt(
            &context,
            EventReductionContext.compareMetadata,
            event_count,
            .{
                .identity = identity,
                .preflight = .{
                    .expected_major = profile.wire_major,
                    .metadata_support = profile.metadata_support,
                    .verdict = verdict,
                },
                .frame = .{
                    .major = borrowed.candidate.header.major,
                    .kind = borrowed.candidate.header.kind,
                    .stream_id = borrowed.candidate.header.stream_id,
                    .request_id = borrowed.candidate.header.request_id,
                    .flags = borrowed.candidate.header.flags,
                    .payload_len = borrowed.candidate.header.payload_len,
                    .payload = borrowed.payload,
                },
            },
        );
        event_count += 1;
    }
    if (event_count == 0) return .prepared;
    const outcome = accumulator.finalize();
    switch (outcome) {
        .ended => return .terminal_runtime_ended,
        .terminal, .invalidated => return .rejected,
        .revoked, .adopted => {},
    }
    // Decoder and allocator callbacks have completed. Rebind every live authority source before
    // publishing a prepared reduction permit.
    const current_client = if (storage.owned_client) |*owned| owned else return .rejected;
    const current_profile = current_client.externalTransferProfile() orelse return .rejected;
    const current_authority = ownerEventAuthority(storage) orelse return .rejected;
    if (!std.meta.eql(profile, current_profile) or
        !std.meta.eql(authority, current_authority) or
        storage.evidence_snapshot.runtime_id != identity.runtime_id or
        storage.evidence_snapshot.stream_id != identity.stream_id)
        return .rejected;
    const final_state = switch (outcome) {
        .revoked => |state| state,
        .adopted => |state| state,
        .terminal, .ended, .invalidated => unreachable,
    };
    const authority_intent_index: u8 = if (final_state.authority_ordinal) |ordinal|
        if (ordinal < event_count)
            event_to_intent[ordinal]
        else
            return .rejected
    else
        std.math.maxInt(u8);
    const resize_intent_index: u8 = if (final_state.resize) |candidate|
        if (candidate.ordinal < event_count)
            event_to_intent[candidate.ordinal]
        else
            return .rejected
    else
        std.math.maxInt(u8);
    const metadata_intent_index: u8 = if (final_state.metadata) |candidate|
        switch (candidate.origin) {
            .initial => std.math.maxInt(u8),
            .event => |ordinal| if (ordinal < event_count)
                event_to_intent[ordinal]
            else
                return .rejected,
        }
    else
        std.math.maxInt(u8);
    reduction.* = .{
        .saved_self_addr = @intFromPtr(reduction),
        .aggregate_addr = @intFromPtr(aggregate),
        .storage_addr = @intFromPtr(storage),
        .intent_handle_addr = @intFromPtr(intent_handle),
        .wire_major = profile.wire_major,
        .metadata_support = profile.metadata_support,
        .identity = identity,
        .authority = authority,
        .authority_digest = storage.owner_authority_seal.digest,
        .event_to_intent = event_to_intent,
        .event_count = event_count,
        .authority_intent_index = authority_intent_index,
        .resize_intent_index = resize_intent_index,
        .metadata_intent_index = metadata_intent_index,
        .outcome = outcome,
        .lifecycle = .prepared,
        .digest = undefined,
    };
    reduction.digest = eventReductionDigest(reduction);
    return .prepared;
}

fn validateEventReduction(
    storage: *const ExternalPumpStorage,
    aggregate: *const PreparedRxAggregate,
    intent_handle: *external_rx_intent.ExternalRxIntentHandle,
) bool {
    const reduction = &aggregate.event_reduction;
    var expected_count: usize = 0;
    for (aggregate.intent_commit.slot_kinds[0..aggregate.intent_commit.intent_count], 0..) |
        kind,
        intent_index,
    | if (kind == .event) {
        if (expected_count >= reduction.event_count or
            reduction.event_to_intent[expected_count] != intent_index or
            external_rx_intent.borrowClassifiedEvent(
                intent_handle,
                @intCast(intent_index),
            ) == null)
            return false;
        expected_count += 1;
    };
    if (expected_count == 0) {
        const pristine_reduction = PreparedEventReduction{};
        return std.mem.eql(
            u8,
            &eventReductionDigest(reduction),
            &eventReductionDigest(&pristine_reduction),
        );
    }
    if (expected_count != reduction.event_count or
        reduction.saved_self_addr != @intFromPtr(reduction) or
        reduction.aggregate_addr != @intFromPtr(aggregate) or
        reduction.storage_addr != @intFromPtr(storage) or
        reduction.intent_handle_addr != @intFromPtr(intent_handle) or
        reduction.lifecycle != .prepared or
        !std.mem.eql(u8, &reduction.digest, &eventReductionDigest(reduction)) or
        !std.mem.eql(
            u8,
            &reduction.authority_digest,
            &storage.owner_authority_seal.digest,
        ))
        return false;
    for (reduction.event_to_intent[reduction.event_count..]) |intent_index|
        if (intent_index != std.math.maxInt(u8)) return false;
    const client = if (storage.owned_client) |*owned| owned else return false;
    const profile = client.externalTransferProfile() orelse return false;
    if (profile.wire_major != reduction.wire_major or
        profile.metadata_support != reduction.metadata_support or
        !std.meta.eql(ownerEventAuthority(storage) orelse return false, reduction.authority) or
        storage.evidence_snapshot.runtime_id != reduction.identity.runtime_id or
        storage.evidence_snapshot.stream_id != reduction.identity.stream_id)
        return false;
    const state = switch (reduction.outcome) {
        .revoked => |state| state,
        .adopted => |state| state,
        .terminal, .ended, .invalidated => return false,
    };
    const expected_authority_intent: u8 =
        if (state.authority_ordinal) |ordinal|
            if (ordinal < reduction.event_count)
                reduction.event_to_intent[ordinal]
            else
                return false
        else
            std.math.maxInt(u8);
    const expected_resize_intent: u8 = if (state.resize) |candidate|
        if (candidate.ordinal < reduction.event_count)
            reduction.event_to_intent[candidate.ordinal]
        else
            return false
    else
        std.math.maxInt(u8);
    const expected_metadata_intent: u8 = if (state.metadata) |candidate|
        switch (candidate.origin) {
            .initial => std.math.maxInt(u8),
            .event => |ordinal| if (ordinal < reduction.event_count)
                reduction.event_to_intent[ordinal]
            else
                return false,
        }
    else
        std.math.maxInt(u8);
    if (expected_authority_intent != reduction.authority_intent_index or
        expected_resize_intent != reduction.resize_intent_index or
        expected_metadata_intent != reduction.metadata_intent_index)
        return false;
    return switch (reduction.outcome) {
        .revoked, .adopted => true,
        .terminal, .ended, .invalidated => false,
    };
}

fn prepareEventRetirements(
    aggregate: *PreparedRxAggregate,
    intent_handle: *external_rx_intent.ExternalRxIntentHandle,
) bool {
    for (aggregate.intent_commit.slot_kinds[0..aggregate.intent_commit.intent_count], 0..) |
        kind,
        intent_index,
    | {
        if (kind != .event) continue;
        external_rx_intent.prepareNeutralRetirement(
            intent_handle,
            @intCast(intent_index),
            &aggregate.screen_proofs,
            &aggregate.neutral_payloads,
            &aggregate.intent_commit,
            &aggregate.event_cleanup[intent_index],
            &aggregate.event_retirements[intent_index],
        ) catch return false;
    }
    return true;
}

fn validateEventRetirements(
    aggregate: *const PreparedRxAggregate,
    intent_handle: *external_rx_intent.ExternalRxIntentHandle,
) bool {
    for (aggregate.intent_commit.slot_kinds, 0..) |kind, intent_index| {
        if (kind == .event) {
            if (!external_rx_intent.validatePreparedNeutralRetirement(
                intent_handle,
                &aggregate.screen_proofs,
                &aggregate.neutral_payloads,
                &aggregate.intent_commit,
                &aggregate.event_cleanup[intent_index],
                &aggregate.event_retirements[intent_index],
            ))
                return false;
        } else if (!external_rx_intent.preparedNeutralRetirementPristine(
            &aggregate.event_retirements[intent_index],
        ) or !external_owner_cleanup.isPristine(
            &aggregate.event_cleanup[intent_index],
        ))
            return false;
    }
    return true;
}

fn reductionState(
    reduction: *const PreparedEventReduction,
) ?runtime_event_reducer.ReducedState {
    return switch (reduction.outcome) {
        .revoked => |state| state,
        .adopted => |state| state,
        .terminal, .ended, .invalidated => null,
    };
}

fn prepareMetadataDestination(
    storage: *ExternalPumpStorage,
    aggregate: *PreparedRxAggregate,
    intent_handle: *external_rx_intent.ExternalRxIntentHandle,
) bool {
    const index = aggregate.event_reduction.metadata_intent_index;
    if (index == std.math.maxInt(u8)) {
        const destination_empty = external_event_materialization
            .preparedLiveMetadataDestinationPristine(
            &aggregate.metadata_destination,
        );
        const expected_empty = std.mem.allEqual(
            u8,
            &aggregate.metadata_summary_expected_digest,
            0,
        );
        const summary_empty = std.meta.eql(
            aggregate.metadata_summary_next,
            MetadataPendingSummarySeal{},
        );
        const cleanup_empty = std.mem.allEqual(
            u8,
            &aggregate.metadata_cleanup_content_digest,
            0,
        );
        return destination_empty and expected_empty and
            aggregate.metadata_summary_next_generation == 0 and
            summary_empty and cleanup_empty;
    }
    if (!storage.metadataPendingSummaryValid() or
        storage.metadata_pending_summary.generation == std.math.maxInt(u64))
        return false;
    aggregate.metadata_summary_expected_digest =
        storage.metadata_pending_summary.digest;
    aggregate.metadata_summary_next_generation =
        storage.metadata_pending_summary.generation + 1;
    aggregate.digest = preparedRxAggregateDigest(aggregate);
    const state = reductionState(&aggregate.event_reduction) orelse return false;
    const candidate = state.metadata orelse return false;
    const ordinal = switch (candidate.origin) {
        .event => |value| value,
        .initial => return false,
    };
    if (ordinal >= aggregate.event_reduction.event_count or
        aggregate.event_reduction.event_to_intent[ordinal] != index)
        return false;
    const borrowed = external_rx_intent.borrowClassifiedEvent(
        intent_handle,
        index,
    ) orelse return false;
    if (candidate.proof != .event) return false;
    external_event_materialization.prepareExactEventOwnedMetadata(
        &aggregate.metadata_destination.staged,
        borrowed.allocator,
        borrowed.payload,
        .{
            .runtime_id = aggregate.event_reduction.identity.runtime_id,
            .stream_id = aggregate.event_reduction.identity.stream_id,
        },
        candidate,
    ) catch return false;
    aggregate.digest = preparedRxAggregateDigest(aggregate);
    if (!external_event_materialization.prepareLiveMetadataAbort(
        &aggregate.metadata_destination.staged,
        &aggregate.metadata_destination.abort_cleanup,
        &aggregate.metadata_destination.abort,
    )) {
        aggregate.lifecycle = .poisoned;
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        storage.rx_aggregate_handle.lifecycle = .poisoned;
        storage.rx_aggregate_handle.digest =
            rxAggregateHandleDigest(&storage.rx_aggregate_handle);
        storage.rx_aggregate_reservation =
            .{ .lifecycle = .poisoned_tombstone };
        storage.semantic_state = .{ .terminal = .{
            .reason = .invariant_failure,
            .fd_disposition = .owner_cleanup,
        } };
        latchCrossOwnerQuarantine();
        return false;
    }
    aggregate.digest = preparedRxAggregateDigest(aggregate);
    _ = external_event_materialization.prepareOwnerMetadataReplacement(
        &aggregate.metadata_destination.replacement,
        &storage.owner_metadata,
        storage,
        &aggregate.metadata_destination.staged,
        &aggregate.metadata_destination.frozen,
    ) catch {
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        return false;
    };
    const next_summary: external_event_materialization.MetadataStateSummary =
        switch (aggregate.metadata_destination.replacement.disposition) {
            .publish_first, .replace_newer => .{ .current = .{
                .revision = aggregate.metadata_destination.replacement.incoming_revision,
                .pending = true,
            } },
            .cleanup_only_older, .cleanup_only_duplicate => storage.owner_metadata.pendingStateSummary(storage) orelse {
                aggregate.digest = preparedRxAggregateDigest(aggregate);
                return false;
            },
        };
    aggregate.metadata_summary_next = metadataPendingSealFromSummary(
        storage,
        next_summary,
        aggregate.metadata_summary_next_generation,
    );
    aggregate.digest = preparedRxAggregateDigest(aggregate);
    return true;
}

fn validateMetadataDestination(
    storage: *const ExternalPumpStorage,
    aggregate: *const PreparedRxAggregate,
) bool {
    if (aggregate.event_reduction.metadata_intent_index ==
        std.math.maxInt(u8))
        return external_event_materialization
            .preparedLiveMetadataDestinationPristine(
            &aggregate.metadata_destination,
        ) and std.mem.allEqual(
            u8,
            &aggregate.metadata_summary_expected_digest,
            0,
        ) and aggregate.metadata_summary_next_generation == 0 and
            std.meta.eql(
                aggregate.metadata_summary_next,
                MetadataPendingSummarySeal{},
            ) and std.mem.allEqual(
            u8,
            &aggregate.metadata_cleanup_content_digest,
            0,
        );
    return aggregate.metadata_destination.replacement.validate(
        &storage.owner_metadata,
        storage,
        &aggregate.metadata_destination.staged,
        &aggregate.metadata_destination.frozen,
    ) and external_event_materialization.validateLiveMetadataAbort(
        &aggregate.metadata_destination.staged,
        &aggregate.metadata_destination.abort_cleanup,
        &aggregate.metadata_destination.abort,
    ) and storage.metadataPendingSummaryValid() and
        std.mem.eql(
            u8,
            &aggregate.metadata_summary_expected_digest,
            &storage.metadata_pending_summary.digest,
        ) and aggregate.metadata_summary_next_generation ==
        storage.metadata_pending_summary.generation + 1 and
        std.mem.eql(
            u8,
            &aggregate.metadata_summary_next.digest,
            &metadataPendingSummaryDigest(aggregate.metadata_summary_next),
        ) and aggregate.metadata_summary_next.generation ==
        aggregate.metadata_summary_next_generation;
}

fn prepareEventScalarDestinations(
    storage: *ExternalPumpStorage,
    aggregate: *PreparedRxAggregate,
) bool {
    const authority_plan = &aggregate.authority_destination;
    const resize_plan = &aggregate.resize_destination;
    const pristine_authority = FrozenAuthorityDestinationPlan{};
    const pristine_resize = FrozenResizeDestinationPlan{};
    if (!std.mem.eql(
        u8,
        &authorityDestinationDigest(authority_plan),
        &authorityDestinationDigest(&pristine_authority),
    ) or !std.mem.eql(
        u8,
        &resizeDestinationDigest(resize_plan),
        &resizeDestinationDigest(&pristine_resize),
    ))
        return false;
    if (aggregate.event_reduction.event_count == 0) return true;
    const state = reductionState(&aggregate.event_reduction) orelse return false;
    if (aggregate.event_reduction.outcome == .revoked) {
        if (std.meta.eql(state.authority, aggregate.event_reduction.authority))
            return false;
        authority_plan.* = .{
            .saved_self_addr = @intFromPtr(authority_plan),
            .storage_addr = @intFromPtr(storage),
            .expected_digest = storage.owner_authority_seal.digest,
            .expected = aggregate.event_reduction.authority,
            .next = state.authority,
            .lifecycle = .prepared,
            .digest = undefined,
        };
        authority_plan.digest = authorityDestinationDigest(authority_plan);
    } else if (!std.meta.eql(
        state.authority,
        aggregate.event_reduction.authority,
    ))
        return false;

    if (state.resize) |candidate| {
        if (candidate.event.runtime_id !=
            aggregate.event_reduction.identity.runtime_id)
            return false;
        switch (storage.owner_resize) {
            .none => {
                resize_plan.* = .{
                    .saved_self_addr = @intFromPtr(resize_plan),
                    .storage_addr = @intFromPtr(storage),
                    .expected_present = false,
                    .next = candidate.event,
                    .lifecycle = .prepared,
                    .digest = undefined,
                };
                resize_plan.digest = resizeDestinationDigest(resize_plan);
            },
            .current => |current| {
                switch (runtime_event_reducer.compareResizeBaseline(
                    current.event,
                    candidate.event,
                )) {
                    .older, .duplicate => return true,
                    .equivocation => return false,
                    .newer => {
                        resize_plan.* = .{
                            .saved_self_addr = @intFromPtr(resize_plan),
                            .storage_addr = @intFromPtr(storage),
                            .expected_present = true,
                            .expected_digest = current.seal.digest,
                            .next = candidate.event,
                            .lifecycle = .prepared,
                            .digest = undefined,
                        };
                        resize_plan.digest =
                            resizeDestinationDigest(resize_plan);
                    },
                }
            },
        }
    }
    return true;
}

fn validateEventScalarDestinations(
    storage: *const ExternalPumpStorage,
    aggregate: *const PreparedRxAggregate,
) bool {
    const authority_plan = &aggregate.authority_destination;
    const resize_plan = &aggregate.resize_destination;
    if (aggregate.event_reduction.event_count == 0) {
        const pristine_authority = FrozenAuthorityDestinationPlan{};
        const pristine_resize = FrozenResizeDestinationPlan{};
        return std.mem.eql(
            u8,
            &authorityDestinationDigest(authority_plan),
            &authorityDestinationDigest(&pristine_authority),
        ) and std.mem.eql(
            u8,
            &resizeDestinationDigest(resize_plan),
            &resizeDestinationDigest(&pristine_resize),
        );
    }
    const state = reductionState(&aggregate.event_reduction) orelse return false;
    if (aggregate.event_reduction.outcome == .revoked) {
        if (authority_plan.saved_self_addr != @intFromPtr(authority_plan) or
            authority_plan.storage_addr != @intFromPtr(storage) or
            !std.mem.eql(
                u8,
                &authority_plan.expected_digest,
                &storage.owner_authority_seal.digest,
            ) or !std.meta.eql(
            authority_plan.expected,
            aggregate.event_reduction.authority,
        ) or !std.meta.eql(authority_plan.next, state.authority) or
            authority_plan.lifecycle != .prepared or
            !std.mem.eql(
                u8,
                &authority_plan.digest,
                &authorityDestinationDigest(authority_plan),
            ))
            return false;
    } else {
        const pristine_authority = FrozenAuthorityDestinationPlan{};
        if (!std.mem.eql(
            u8,
            &authorityDestinationDigest(authority_plan),
            &authorityDestinationDigest(&pristine_authority),
        )) return false;
    }
    const expected_resize = state.resize;
    if (resize_plan.lifecycle == .empty) {
        const pristine_resize = FrozenResizeDestinationPlan{};
        if (!std.mem.eql(
            u8,
            &resizeDestinationDigest(resize_plan),
            &resizeDestinationDigest(&pristine_resize),
        )) return false;
        if (expected_resize) |candidate| switch (storage.owner_resize) {
            .none => return false,
            .current => |current| {
                if (candidate.event.resize_generation >
                    current.event.resize_generation or
                    (candidate.event.resize_generation ==
                        current.event.resize_generation and
                        !std.meta.eql(candidate.event, current.event)))
                    return false;
            },
        };
        return true;
    }
    const candidate = expected_resize orelse return false;
    const expected_digest = switch (storage.owner_resize) {
        .none => [_]u8{0} ** 32,
        .current => |current| current.seal.digest,
    };
    return resize_plan.saved_self_addr == @intFromPtr(resize_plan) and
        resize_plan.storage_addr == @intFromPtr(storage) and
        resize_plan.expected_present == (storage.owner_resize == .current) and
        std.mem.eql(u8, &resize_plan.expected_digest, &expected_digest) and
        std.meta.eql(resize_plan.next, candidate.event) and
        resize_plan.lifecycle == .prepared and
        std.mem.eql(
            u8,
            &resize_plan.digest,
            &resizeDestinationDigest(resize_plan),
        );
}

fn commitAuthorityDestinationUnchecked(
    storage: *ExternalPumpStorage,
    plan: *FrozenAuthorityDestinationPlan,
    target: *OwnerAuthorityState,
) void {
    target.* = .{ .current = .{
        .role = switch (plan.next.role) {
            .observer => .observer,
            .controller => .controller,
        },
        .generation = switch (plan.next.generation) {
            .untracked => .untracked,
            .tracked => |generation| .{ .tracked = generation },
        },
        .flow = .clear,
    } };
    bindOwnerAuthority(storage);
    plan.lifecycle = .consumed;
    plan.digest = authorityDestinationDigest(plan);
}

fn commitResizeDestinationUnchecked(
    storage: *ExternalPumpStorage,
    plan: *FrozenResizeDestinationPlan,
    target: *OwnerResizeState,
) void {
    target.* = .{ .current = .{
        .event = plan.next,
        .pending = true,
        .seal = undefined,
    } };
    const current = &target.current;
    current.seal = .{
        .domain = owner_resize_seal_domain,
        .version = owner_resize_seal_version,
        .current_addr = @intFromPtr(current),
        .storage_addr = @intFromPtr(storage),
        .runtime_id = plan.next.runtime_id,
        .generation = plan.next.resize_generation,
        .cols = plan.next.cols,
        .rows = plan.next.rows,
        .pending = true,
        .digest = undefined,
    };
    current.seal.digest = ownerResizeDigest(current.seal);
    plan.lifecycle = .consumed;
    plan.digest = resizeDestinationDigest(plan);
}

fn frozenAggregateCleanupDigest(
    cleanup: *const FrozenAggregateCleanup,
) external_owner_seal.Digest {
    var writer = external_owner_seal.Writer.init("MARUFAC1");
    writer.writeUsize(cleanup.saved_self_addr);
    writer.writeU16(cleanup.expected_count);
    writer.writeUsize(cleanup.expected_total_bytes);
    writer.writeU16(cleanup.cleanup_count);
    writer.writeUsize(cleanup.total_bytes);
    for (cleanup.cleanup[0..cleanup.cleanup_count]) |descriptor|
        writer.writeBytes(&descriptor.digest);
    writer.writeU8(@intFromEnum(cleanup.lifecycle));
    return writer.finish();
}

const RevokedCleanupOwnerProof = struct {
    saved_self_addr: usize,
    scratch_addr: usize,
    scratch_len: usize,
    graph_addr: usize,
    graph_len: usize,
    cleanup_addr: usize,
    lease_addr: usize,
    storage_addr: usize,
    owner_incarnation: u64,
    digest: external_owner_seal.Digest,
};

fn revokedCleanupOwnerProofDigest(
    proof: *const RevokedCleanupOwnerProof,
) external_owner_seal.Digest {
    var writer = external_owner_seal.Writer.init("MARURCP1");
    writer.writeUsize(proof.saved_self_addr);
    writer.writeUsize(proof.scratch_addr);
    writer.writeUsize(proof.scratch_len);
    writer.writeUsize(proof.graph_addr);
    writer.writeUsize(proof.graph_len);
    writer.writeUsize(proof.cleanup_addr);
    writer.writeUsize(proof.lease_addr);
    writer.writeUsize(proof.storage_addr);
    writer.writeU64(proof.owner_incarnation);
    return writer.finish();
}

fn revokedCleanupOwnerProofValid(
    proof: *const RevokedCleanupOwnerProof,
    out: *const FrozenAggregateCleanup,
    storage: *const ExternalPumpStorage,
) bool {
    const scratch_end = std.math.add(usize, proof.scratch_addr, proof.scratch_len) catch return false;
    const graph_end = std.math.add(usize, proof.graph_addr, proof.graph_len) catch return false;
    const expected_graph_addr = std.math.add(
        usize,
        proof.scratch_addr,
        @offsetOf(ExternalRxTurnScratch, "revoked_commit_graph"),
    ) catch return false;
    const expected_cleanup_addr = std.math.add(
        usize,
        proof.graph_addr,
        @offsetOf(PreparedRevokedCommitGraphStorage, "event_cleanup"),
    ) catch return false;
    return proof.saved_self_addr == @intFromPtr(proof) and
        proof.scratch_len == @sizeOf(ExternalRxTurnScratch) and
        proof.graph_len == @sizeOf(PreparedRevokedCommitGraph) and
        proof.graph_addr == expected_graph_addr and
        proof.graph_addr >= proof.scratch_addr and graph_end <= scratch_end and
        proof.cleanup_addr == @intFromPtr(out) and
        proof.cleanup_addr == expected_cleanup_addr and
        proof.lease_addr != 0 and proof.storage_addr == @intFromPtr(storage) and
        proof.owner_incarnation == storage.owner_incarnation and
        std.mem.eql(u8, &proof.digest, &revokedCleanupOwnerProofDigest(proof));
}

fn prepareEventAggregateCleanup(
    storage: *const ExternalPumpStorage,
    aggregate: *PreparedRxAggregate,
    out: *FrozenAggregateCleanup,
    intent_handle: *external_rx_intent.ExternalRxIntentHandle,
    allowed_out_owner: ?*const RevokedCleanupOwnerProof,
) bool {
    if (!std.meta.eql(out.*, FrozenAggregateCleanup{}))
        return false;
    var count: usize = 0;
    var total_bytes: usize = 0;
    var metadata_content_digest: external_owner_cleanup.Digest =
        [_]u8{0} ** 32;
    for (aggregate.intent_commit.slot_kinds[0..aggregate.intent_commit.intent_count], 0..) |
        kind,
        intent_index,
    | {
        if (kind != .event) continue;
        const retirement = &aggregate.event_retirements[intent_index];
        if (retirement.allocation_addr == 0 or retirement.allocation_len == 0)
            return false;
        total_bytes = std.math.add(
            usize,
            total_bytes,
            retirement.allocation_len,
        ) catch return false;
        for (aggregate.intent_commit.slot_kinds[0..intent_index], 0..) |
            prior_kind,
            prior_index,
        | if (prior_kind == .event) {
            const prior = &aggregate.event_retirements[prior_index];
            if (rangesOverlap(
                retirement.allocation_addr,
                retirement.allocation_len,
                prior.allocation_addr,
                prior.allocation_len,
            ))
                return false;
        };
        if (rangesOverlap(
            retirement.allocation_addr,
            retirement.allocation_len,
            @intFromPtr(out),
            @sizeOf(FrozenAggregateCleanup),
        ))
            return false;
        count += 1;
    }
    if (aggregate.event_reduction.metadata_intent_index !=
        std.math.maxInt(u8))
    {
        const metadata_range =
            external_event_materialization.preparedReplacementCleanupRange(
                &aggregate.metadata_destination.replacement,
                &storage.owner_metadata,
                storage,
                &aggregate.metadata_destination.staged,
                &aggregate.metadata_destination.frozen,
            ) orelse return false;
        if ((metadata_range.address == 0) != (metadata_range.len == 0))
            return false;
        metadata_content_digest = metadata_range.content_digest;
        if (metadata_range.len != 0) {
            var existing_ranges: external_owner_range.Scratch = .{};
            external_rx_intent.appendBoundOwnerRanges(
                intent_handle,
                &existing_ranges,
            ) catch return false;
            storage.inbox_ledger.appendActiveOwnerRanges(
                &existing_ranges,
            ) catch return false;
            const forbidden = [_]external_owner_range.Range{
                .{
                    .start = metadata_range.address,
                    .len = metadata_range.len,
                },
                .{
                    .start = @intFromPtr(storage),
                    .len = @sizeOf(ExternalPumpStorage),
                },
                .{
                    .start = @intFromPtr(aggregate),
                    .len = @sizeOf(PreparedRxAggregate),
                },
            };
            existing_ranges.validate(&forbidden) catch return false;
            const out_range = external_owner_range.Range{
                .start = @intFromPtr(out),
                .len = @sizeOf(FrozenAggregateCleanup),
            };
            if (allowed_out_owner) |proof| {
                if (!revokedCleanupOwnerProofValid(proof, out, storage)) return false;
            } else {
                existing_ranges.validate(&.{out_range}) catch return false;
            }
            total_bytes = std.math.add(
                usize,
                total_bytes,
                metadata_range.len,
            ) catch return false;
            for (aggregate.intent_commit.slot_kinds[0..aggregate.intent_commit.intent_count], 0..) |
                kind,
                intent_index,
            | if (kind == .event) {
                const retirement = &aggregate.event_retirements[intent_index];
                if (rangesOverlap(
                    metadata_range.address,
                    metadata_range.len,
                    retirement.allocation_addr,
                    retirement.allocation_len,
                ))
                    return false;
            };
            if (rangesOverlap(
                metadata_range.address,
                metadata_range.len,
                @intFromPtr(out),
                @sizeOf(FrozenAggregateCleanup),
            ))
                return false;
            count += 1;
        }
    }
    if (!aggregateCleanupCountFits(count))
        return false;
    out.* = .{
        .saved_self_addr = @intFromPtr(out),
        .expected_count = @intCast(count),
        .expected_total_bytes = total_bytes,
        .lifecycle = .prepared,
        .digest = undefined,
    };
    out.digest = frozenAggregateCleanupDigest(out);
    aggregate.metadata_cleanup_content_digest = metadata_content_digest;
    aggregate.digest = preparedRxAggregateDigest(aggregate);
    return true;
}

fn appendEventAggregateCleanupUnchecked(
    aggregate: *PreparedRxAggregate,
    out: *FrozenAggregateCleanup,
) void {
    for (aggregate.intent_commit.slot_kinds[0..aggregate.intent_commit.intent_count], 0..) |
        kind,
        intent_index,
    | {
        if (kind != .event) continue;
        const destination = &out.cleanup[out.cleanup_count];
        external_owner_cleanup.moveFrozenUnchecked(
            &aggregate.event_cleanup[intent_index],
            destination,
        );
        out.cleanup_count +%= 1;
        out.total_bytes +%= destination.allocation_len;
    }
    if (aggregate.metadata_destination.frozen.saved_self_addr != 0) {
        const destination = &out.cleanup[out.cleanup_count];
        external_event_materialization.commitFrozenCleanupToDescriptorUnchecked(
            &aggregate.metadata_destination.frozen,
            destination,
            aggregate.metadata_cleanup_content_digest,
        );
        if (destination.lifecycle == .frozen) {
            out.cleanup_count +%= 1;
            out.total_bytes +%= destination.allocation_len;
        }
    }
    out.lifecycle = .frozen;
    out.digest = frozenAggregateCleanupDigest(out);
}

fn finishFrozenAggregateCleanup(
    cleanup: *FrozenAggregateCleanup,
) bool {
    if (cleanup.saved_self_addr != @intFromPtr(cleanup) or
        cleanup.lifecycle != .frozen or
        cleanup.cleanup_count != cleanup.expected_count or
        cleanup.total_bytes != cleanup.expected_total_bytes or
        !std.mem.eql(u8, &cleanup.digest, &frozenAggregateCleanupDigest(cleanup)))
    {
        cleanup.lifecycle = .quarantined;
        return false;
    }
    var clean = true;
    for (cleanup.cleanup[0..cleanup.cleanup_count]) |*descriptor| {
        if (external_owner_cleanup.finishCallbackHidden(descriptor) != .cleaned) {
            clean = false;
        }
    }
    cleanup.lifecycle = if (clean) .spent else .quarantined;
    cleanup.digest = frozenAggregateCleanupDigest(cleanup);
    return clean;
}

const ResponsePlanPrepareResult = enum {
    prepared,
    deadline_exceeded,
    rejected,
};

fn prepareResponseDestinationPlan(
    storage: *const ExternalPumpStorage,
    aggregate: *PreparedRxAggregate,
    intent_handle: *external_rx_intent.ExternalRxIntentHandle,
) ResponsePlanPrepareResult {
    const plan = &aggregate.response_destination;
    if (plan.saved_self_addr != 0 or plan.lifecycle != .empty)
        return .rejected;
    var response_index: ?usize = null;
    for (aggregate.intent_commit.slot_kinds[0..aggregate.intent_commit.intent_count], 0..) |
        kind,
        index,
    | switch (kind) {
        .response => {
            if (response_index != null) return .rejected;
            response_index = index;
        },
        .event => {},
        .screen => {},
        .unused => return .rejected,
    };
    if (response_index == null) return .prepared;
    if (storage.completed_control != .none or
        storage.completed_control_generation == std.math.maxInt(u64))
        return .rejected;
    const index = response_index.?;
    const payload = external_rx_intent.borrowPreparedClassifiedPayload(
        intent_handle,
        @intCast(index),
        &aggregate.screen_proofs,
        &aggregate.neutral_payloads,
        &aggregate.intent_commit,
    ) orelse return .rejected;
    const request_id = aggregate.intent_commit.response_request_ids[index];
    if (request_id == 0 or
        aggregate.intent_commit.source_parser_generations[index] == 0 or
        std.mem.allEqual(
            u8,
            &aggregate.intent_commit.source_owner_digests[index],
            0,
        ))
        return .rejected;
    if (!controlCorrelationValid(storage))
        return .rejected;
    const in_flight = switch (storage.control_correlation.state) {
        .in_flight => |value| value,
        .idle, .completed, .terminal => return .rejected,
    };
    switch (client_control_correlation.classifyResponse(
        in_flight,
        request_id,
        aggregate.turn_now_ns,
    )) {
        .accept => {},
        .deadline_exceeded => return .deadline_exceeded,
        .early, .wrong_request, .unsolicited => return .rejected,
    }
    plan.* = .{
        .saved_self_addr = @intFromPtr(plan),
        .aggregate_addr = @intFromPtr(aggregate),
        .storage_addr = @intFromPtr(storage),
        .neutral_addr = @intFromPtr(&aggregate.neutral_payloads[index]),
        .intent_index = @intCast(index),
        .request_id = request_id,
        .control_kind = in_flight.kind,
        .expectation = in_flight.expectation,
        .target_stream_id = in_flight.target.stream_id,
        .expected_controller_generation = in_flight.target.controller_generation,
        .control_wire_len = in_flight.wire_len,
        .expected_correlation_generation = storage.control_correlation.generation,
        .expected_correlation_digest = storage.control_correlation.digest,
        .source_turn_generation = aggregate.turn_generation,
        .source_parser_generation = aggregate.intent_commit.source_parser_generations[index],
        .source_start_absolute = aggregate.intent_commit.source_start_absolutes[index],
        .source_end_absolute = aggregate.intent_commit.source_end_absolutes[index],
        .source_owner_digest = aggregate.intent_commit.source_owner_digests[index],
        .payload_digest = aggregate.intent_commit.payload_digests[index],
        .response_payload_digest = responsePayloadDigest(if (payload.allocation_len == 0)
            &.{}
        else
            @as([*]const u8, @ptrFromInt(payload.allocation_addr))[0..payload.allocation_len]),
        .payload_allocator = payload.allocator,
        .payload_allocator_ptr_addr = @intFromPtr(payload.allocator.ptr),
        .payload_allocator_vtable_addr = @intFromPtr(payload.allocator.vtable),
        .payload_addr = payload.allocation_addr,
        .payload_len = payload.allocation_len,
        .expected_generation = storage.completed_control_generation,
        .next_generation = storage.completed_control_generation + 1,
        .lifecycle = .prepared,
        .digest = undefined,
    };
    plan.digest = responseDestinationPlanDigest(plan);
    return .prepared;
}

fn validateResponseDestinationPlan(
    storage: *const ExternalPumpStorage,
    aggregate: *const PreparedRxAggregate,
) bool {
    const plan = &aggregate.response_destination;
    var response_index: ?usize = null;
    for (aggregate.intent_commit.slot_kinds[0..aggregate.intent_commit.intent_count], 0..) |
        kind,
        index,
    | switch (kind) {
        .response => {
            if (response_index != null) return false;
            response_index = index;
        },
        .event => {},
        .screen => {},
        .unused => return false,
    };
    if (response_index == null)
        return plan.saved_self_addr == 0 and plan.lifecycle == .empty and
            std.mem.allEqual(u8, &plan.digest, 0);
    const index = response_index.?;
    const in_flight = switch (storage.control_correlation.state) {
        .in_flight => |value| value,
        .idle, .completed, .terminal => return false,
    };
    return controlCorrelationValid(storage) and
        storage.completed_control == .none and
        plan.saved_self_addr == @intFromPtr(plan) and
        plan.aggregate_addr == @intFromPtr(aggregate) and
        plan.storage_addr == @intFromPtr(storage) and
        plan.neutral_addr == @intFromPtr(&aggregate.neutral_payloads[index]) and
        plan.intent_index == index and
        plan.request_id == aggregate.intent_commit.response_request_ids[index] and
        plan.control_kind == in_flight.kind and
        std.meta.eql(plan.expectation, in_flight.expectation) and
        plan.target_stream_id == in_flight.target.stream_id and
        plan.expected_controller_generation ==
            in_flight.target.controller_generation and
        plan.control_wire_len == in_flight.wire_len and
        plan.expected_correlation_generation ==
            storage.control_correlation.generation and
        std.mem.eql(
            u8,
            &plan.expected_correlation_digest,
            &storage.control_correlation.digest,
        ) and
        client_control_correlation.classifyResponse(
            in_flight,
            plan.request_id,
            aggregate.turn_now_ns,
        ) == .accept and
        plan.source_turn_generation == aggregate.turn_generation and
        plan.source_parser_generation ==
            aggregate.intent_commit.source_parser_generations[index] and
        plan.source_start_absolute ==
            aggregate.intent_commit.source_start_absolutes[index] and
        plan.source_end_absolute ==
            aggregate.intent_commit.source_end_absolutes[index] and
        plan.source_end_absolute > plan.source_start_absolute and
        std.mem.eql(
            u8,
            &plan.source_owner_digest,
            &aggregate.intent_commit.source_owner_digests[index],
        ) and
        std.mem.eql(
            u8,
            &plan.payload_digest,
            &aggregate.intent_commit.payload_digests[index],
        ) and
        @intFromPtr(plan.payload_allocator.ptr) ==
            plan.payload_allocator_ptr_addr and
        @intFromPtr(plan.payload_allocator.vtable) ==
            plan.payload_allocator_vtable_addr and
        ((plan.payload_addr == 0) == (plan.payload_len == 0)) and
        plan.expected_generation == storage.completed_control_generation and
        plan.next_generation == plan.expected_generation + 1 and
        plan.lifecycle == .prepared and
        std.mem.eql(u8, &plan.digest, &responseDestinationPlanDigest(plan));
}

fn commitResponseDestinationPlanUnchecked(
    storage: *ExternalPumpStorage,
    plan: *FrozenResponseDestinationPlan,
    target: *CompletedControlOwner,
    neutral: *external_rx_intent.MovedIntentPayload,
) void {
    const owned = external_inbox_ledger.OwnedPayload{
        .allocator = plan.payload_allocator,
        .allocation_ptr = if (plan.payload_len == 0)
            null
        else
            @ptrFromInt(plan.payload_addr),
        .logical_len = plan.payload_len,
    };
    tombstoneMovedIntentPayloadUnchecked(neutral);
    var pending = CompletedControlState{
        .payload = owned,
        .seal = .{
            .payload_addr = plan.payload_addr,
            .payload_len = plan.payload_len,
            .allocator_ptr_addr = plan.payload_allocator_ptr_addr,
            .allocator_vtable_addr = plan.payload_allocator_vtable_addr,
            .payload_digest = plan.response_payload_digest,
        },
        .request_id = plan.request_id,
        .control_kind = plan.control_kind,
        .expectation = plan.expectation,
        .target_stream_id = plan.target_stream_id,
        .expected_controller_generation = plan.expected_controller_generation,
        .control_wire_len = plan.control_wire_len,
        .correlation_generation = plan.expected_correlation_generation + 1,
        .source_turn_generation = plan.source_turn_generation,
        .source_parser_generation = plan.source_parser_generation,
        .source_start_absolute = plan.source_start_absolute,
        .source_end_absolute = plan.source_end_absolute,
        .source_owner_digest = plan.source_owner_digest,
        .generation = plan.next_generation,
        .owner_digest = undefined,
    };
    pending.owner_digest = completedControlDigest(storage, &pending);
    storage.completed_control_generation = plan.next_generation;
    target.* = .{ .completed = pending };
    storage.control_correlation.generation =
        plan.expected_correlation_generation + 1;
    storage.control_correlation.state = .{ .completed = .{
        .kind = plan.control_kind,
        .expectation = plan.expectation,
        .target = .{
            .stream_id = plan.target_stream_id,
            .controller_generation = plan.expected_controller_generation,
        },
        .request_id = plan.request_id,
        .wire_len = plan.control_wire_len,
    } };
    storage.control_correlation.digest =
        controlCorrelationDigest(&storage.control_correlation);
    plan.lifecycle = .consumed;
    plan.digest = responseDestinationPlanDigest(plan);
}

fn destinationWriteDigest(
    write: *const FrozenDestinationWrite,
) external_owner_seal.Digest {
    var writer = external_owner_seal.Writer.init("MARUFDW1");
    writer.writeUsize(write.saved_self_addr);
    writer.writeUsize(write.aggregate_addr);
    writer.writeU8(write.intent_index);
    writer.writeU8(write.mutation_index);
    writer.writeU8(@intFromEnum(write.kind));
    writer.writeBool(write.final_for_kind);
    writer.writeU16(write.screen_token.slot);
    writer.writeU64(write.screen_token.generation);
    writer.writeUsize(write.target_addr);
    writer.writeU8(write.expected_lifecycle);
    writer.writeBytes(&write.expected_digest);
    writer.writeUsize(write.prepared_backing_addr);
    writer.writeUsize(write.prepared_backing_len);
    writer.writeBytes(&write.prepared_backing_digest);
    writer.writeUsize(write.retirement_backing_addr);
    writer.writeUsize(write.retirement_backing_len);
    writer.writeBytes(&write.retirement_backing_digest);
    writer.writeUsize(write.retirement_target_addr);
    writer.writeUsize(write.source_backing_addr);
    writer.writeUsize(write.source_backing_len);
    writer.writeBytes(&write.source_backing_digest);
    return writer.finish();
}

fn expectedDestinationWrite(
    storage: *const ExternalPumpStorage,
    aggregate: *const PreparedRxAggregate,
    intent_index: usize,
) ?FrozenDestinationWrite {
    if (intent_index >= aggregate.intent_commit.intent_count) return null;
    var write = FrozenDestinationWrite{
        .saved_self_addr = @intFromPtr(&aggregate.destination_writes[intent_index]),
        .aggregate_addr = @intFromPtr(aggregate),
        .intent_index = @intCast(intent_index),
        .digest = undefined,
    };
    switch (aggregate.intent_commit.slot_kinds[intent_index]) {
        .screen => {
            const transfer = &aggregate.screen_transfers[intent_index];
            write.mutation_index = transfer.mutation_index;
            switch (aggregate.dispositions[transfer.mutation_index]) {
                .cleanup_final, .superseded_tombstone => {
                    write.kind = .screen_cleanup;
                    write.target_addr = @intFromPtr(transfer);
                    write.expected_lifecycle =
                        @intFromEnum(transfer.lifecycle);
                    write.expected_digest = transfer.digest;
                },
                .final_live => |root| switch (root.phase) {
                    .partial => {
                        write.kind = .screen_partial;
                        write.screen_token = root.token;
                        write.target_addr = @intFromPtr(&storage.live_partial);
                        write.expected_lifecycle =
                            @intFromEnum(std.meta.activeTag(storage.live_partial));
                        write.expected_digest = [_]u8{0} ** 32;
                    },
                    .completed => {
                        write.kind = .screen_completed;
                        write.screen_token = root.token;
                        var completed_ordinal: usize = 0;
                        for (aggregate.dispositions[0..transfer.mutation_index]) |
                            prior,
                        | switch (prior) {
                            .final_live => |prior_root| if (prior_root.phase ==
                                .completed)
                            {
                                completed_ordinal += 1;
                            },
                            .cleanup_final, .superseded_tombstone => {},
                            .unused => return null,
                        };
                        const tail = (storage.live_screen.head +
                            storage.live_screen.len + completed_ordinal) %
                            external_inbox_ledger.max_live_mutations;
                        write.target_addr =
                            @intFromPtr(&storage.live_screen.tokens[tail]);
                        write.expected_lifecycle =
                            @intFromEnum(storage.live_screen.lifecycle);
                        write.expected_digest = storage.live_screen.owner_digest;
                    },
                },
                .unused => return null,
            }
            write.prepared_backing_addr = @intFromPtr(transfer);
            write.prepared_backing_len = @sizeOf(ScreenTransferOwner);
            write.prepared_backing_digest = transfer.digest;
            write.source_backing_addr =
                @intFromPtr(&aggregate.screen_destination);
            write.source_backing_len =
                @sizeOf(FrozenScreenDestinationPlan);
            write.source_backing_digest =
                aggregate.screen_destination.digest;
            write.final_for_kind = true;
            for (aggregate.intent_commit.slot_kinds[intent_index + 1 .. aggregate.intent_commit.intent_count]) |later_kind|
                if (later_kind == .screen) {
                    write.final_for_kind = false;
                    break;
                };
        },
        .event => {
            const retirement = &aggregate.event_retirements[intent_index];
            const neutral = &aggregate.neutral_payloads[intent_index];
            write.retirement_backing_addr = @intFromPtr(retirement);
            write.retirement_backing_len =
                @sizeOf(external_rx_intent.PreparedNeutralRetirement);
            write.retirement_backing_digest = retirement.digest;
            write.retirement_target_addr =
                @intFromPtr(&aggregate.event_cleanup[intent_index]);
            write.source_backing_addr = @intFromPtr(neutral);
            write.source_backing_len =
                @sizeOf(external_rx_intent.MovedIntentPayload);
            write.source_backing_digest = neutral.digest;
            if (aggregate.event_reduction.metadata_intent_index ==
                intent_index)
            {
                switch (aggregate.metadata_destination.replacement.disposition) {
                    .cleanup_only_older, .cleanup_only_duplicate => {
                        write.kind = .metadata_cleanup;
                        write.target_addr =
                            @intFromPtr(&aggregate.metadata_destination.frozen);
                        write.expected_lifecycle = @intFromEnum(
                            aggregate.metadata_destination.frozen.lifecycle,
                        );
                    },
                    .publish_first => {
                        write.kind = .metadata_publish_first;
                        write.target_addr = @intFromPtr(&storage.owner_metadata);
                        write.expected_lifecycle =
                            @intFromEnum(storage.owner_metadata.lifecycle);
                    },
                    .replace_newer => {
                        write.kind = .metadata_replace_newer;
                        write.target_addr = @intFromPtr(&storage.owner_metadata);
                        write.expected_lifecycle =
                            @intFromEnum(storage.owner_metadata.lifecycle);
                    },
                }
                write.expected_digest =
                    aggregate.metadata_summary_expected_digest;
                write.prepared_backing_addr =
                    @intFromPtr(&aggregate.metadata_destination);
                write.prepared_backing_len = @sizeOf(
                    external_event_materialization.PreparedLiveMetadataDestination,
                );
                write.prepared_backing_digest =
                    external_event_materialization
                        .preparedLiveMetadataDestinationAuthorityDigest(
                        &aggregate.metadata_destination,
                    );
            } else if (aggregate.event_reduction.resize_intent_index ==
                intent_index and
                aggregate.resize_destination.lifecycle == .prepared)
            {
                write.kind = .resize;
                write.target_addr = @intFromPtr(&storage.owner_resize);
                write.expected_lifecycle =
                    @intFromEnum(std.meta.activeTag(storage.owner_resize));
                write.expected_digest = aggregate.resize_destination.expected_digest;
                write.prepared_backing_addr =
                    @intFromPtr(&aggregate.resize_destination);
                write.prepared_backing_len =
                    @sizeOf(FrozenResizeDestinationPlan);
                write.prepared_backing_digest =
                    aggregate.resize_destination.digest;
            } else if (aggregate.event_reduction.authority_intent_index ==
                intent_index and
                aggregate.authority_destination.lifecycle == .prepared)
            {
                write.kind = .authority;
                write.target_addr = @intFromPtr(&storage.owner_authority);
                write.expected_lifecycle =
                    @intFromEnum(std.meta.activeTag(storage.owner_authority));
                write.expected_digest =
                    aggregate.authority_destination.expected_digest;
                write.prepared_backing_addr =
                    @intFromPtr(&aggregate.authority_destination);
                write.prepared_backing_len =
                    @sizeOf(FrozenAuthorityDestinationPlan);
                write.prepared_backing_digest =
                    aggregate.authority_destination.digest;
            } else {
                write.kind = .event_retirement;
                write.target_addr =
                    @intFromPtr(&aggregate.event_cleanup[intent_index]);
                write.expected_lifecycle = @intFromEnum(
                    aggregate.event_cleanup[intent_index].lifecycle,
                );
                write.expected_digest =
                    aggregate.event_cleanup[intent_index].digest;
                write.prepared_backing_addr = @intFromPtr(retirement);
                write.prepared_backing_len =
                    @sizeOf(external_rx_intent.PreparedNeutralRetirement);
                write.prepared_backing_digest = retirement.digest;
            }
        },
        .response => {
            write.kind = .response;
            write.target_addr = @intFromPtr(&storage.completed_control);
            write.expected_lifecycle =
                @intFromEnum(std.meta.activeTag(storage.completed_control));
            write.expected_digest = aggregate.response_destination.digest;
            write.prepared_backing_addr =
                @intFromPtr(&aggregate.response_destination);
            write.prepared_backing_len =
                @sizeOf(FrozenResponseDestinationPlan);
            write.prepared_backing_digest =
                aggregate.response_destination.digest;
            write.source_backing_addr =
                aggregate.response_destination.neutral_addr;
            write.source_backing_len =
                @sizeOf(external_rx_intent.MovedIntentPayload);
            write.source_backing_digest =
                aggregate.intent_commit.payload_digests[intent_index];
        },
        .unused => return null,
    }
    write.digest = destinationWriteDigest(&write);
    return write;
}

fn prepareDestinationWrites(
    storage: *const ExternalPumpStorage,
    aggregate: *PreparedRxAggregate,
    intent_handle: *external_rx_intent.ExternalRxIntentHandle,
) bool {
    if (aggregate.destination_write_count != 0 or
        aggregate.intent_commit.intent_count == 0)
        return false;
    @memset(std.mem.asBytes(&aggregate.destination_writes), 0);
    for (0..aggregate.intent_commit.intent_count) |intent_index| {
        aggregate.destination_writes[intent_index] =
            expectedDestinationWrite(
                storage,
                aggregate,
                intent_index,
            ) orelse return false;
    }
    aggregate.destination_write_count =
        aggregate.intent_commit.intent_count;
    external_rx_intent.bindIntentDestinationPlan(
        intent_handle,
        &aggregate.screen_proofs,
        &aggregate.neutral_payloads,
        &aggregate.intent_commit,
        std.mem.asBytes(&aggregate.destination_writes),
    ) catch return false;
    return true;
}

fn validateDestinationWrites(
    storage: *const ExternalPumpStorage,
    aggregate: *const PreparedRxAggregate,
    intent_handle: *external_rx_intent.ExternalRxIntentHandle,
) bool {
    if (aggregate.destination_write_count !=
        aggregate.intent_commit.intent_count)
        return false;
    for (0..aggregate.destination_write_count) |intent_index| {
        const write = &aggregate.destination_writes[intent_index];
        const expected = expectedDestinationWrite(
            storage,
            aggregate,
            intent_index,
        ) orelse return false;
        if (!std.mem.eql(u8, &write.digest, &destinationWriteDigest(write)) or
            !std.mem.eql(u8, &write.digest, &expected.digest))
            return false;
    }
    for (aggregate.destination_writes[aggregate.destination_write_count..]) |write|
        if (write.saved_self_addr != 0 or write.kind != .unused or
            !std.mem.allEqual(u8, &write.digest, 0))
            return false;
    return external_rx_intent.validateIntentDestinationPlan(
        intent_handle,
        &aggregate.screen_proofs,
        &aggregate.neutral_payloads,
        &aggregate.intent_commit,
        std.mem.asBytes(&aggregate.destination_writes),
    );
}

fn validateScreenDestinationPlan(
    storage: *const ExternalPumpStorage,
    aggregate: *const PreparedRxAggregate,
) bool {
    const plan = &aggregate.screen_destination;
    const expected_live_commit_digest = if (aggregate.recovery_snapshot_commit.lifecycle == .prepared) aggregate.recovery_snapshot_commit.prepared_live_commit_digest else aggregate.live_commit.digest;
    const expected_partial_valid = switch (storage.live_partial) {
        .none => plan.expected_partial_empty and
            plan.expected_partial_token.generation == 0 and
            plan.expected_partial_token.slot == 0 and
            plan.expected_partial_generation == 0 and
            std.mem.allEqual(u8, &plan.expected_partial_digest, 0) and
            plan.next_partial_generation == if (plan.partial_count == 0)
                @as(u64, 0)
            else
                @as(u64, 1),
        .assembling => |partial| !plan.expected_partial_empty and
            std.meta.eql(plan.expected_partial_token, partial.ledger_token) and
            plan.expected_partial_generation == partial.generation and
            std.mem.eql(
                u8,
                &plan.expected_partial_digest,
                &partial.owner_digest,
            ) and
            plan.next_partial_generation ==
                (std.math.add(u64, partial.generation, 1) catch return false),
        .terminal => false,
    };
    if (plan.saved_self_addr != @intFromPtr(plan) or
        plan.aggregate_addr != @intFromPtr(aggregate) or
        plan.storage_addr != @intFromPtr(storage) or
        plan.lifecycle != .prepared or
        !std.mem.eql(
            u8,
            &plan.live_commit_digest,
            &expected_live_commit_digest,
        ) or !std.mem.eql(
        u8,
        &plan.digest,
        &screenDestinationPlanDigest(plan),
    ) or !storage.liveScreenValid() or !storage.livePartialValid() or
        plan.expected_screen_head != storage.live_screen.head or
        plan.expected_screen_len != storage.live_screen.len or
        plan.expected_screen_generation != storage.live_screen.generation or
        !std.mem.eql(
            u8,
            &plan.expected_screen_digest,
            &storage.live_screen.owner_digest,
        ) or !expected_partial_valid or
        plan.entry_count != plan.partial_count + plan.completed_count or
        plan.partial_count != aggregate.live_commit.final_partial_count or
        plan.completed_count != aggregate.live_commit.final_completed_count or
        plan.expected_screen_len + plan.completed_count >
            external_inbox_ledger.max_live_mutations)
        return false;
    var partial_count: usize = 0;
    var completed_count: usize = 0;
    for (plan.entries[0..plan.entry_count]) |entry| {
        if (entry.token.generation == 0) return false;
        switch (entry.phase) {
            .partial => partial_count += 1,
            .completed => completed_count += 1,
        }
    }
    return partial_count == plan.partial_count and
        completed_count == plan.completed_count;
}

const ScreenWritePhase = enum {
    cleanup,
    partial,
    completed,
};

fn commitScreenDestinationPlanUnchecked(
    comptime phase: ScreenWritePhase,
    storage: *ExternalPumpStorage,
    write: *const FrozenDestinationWrite,
) void {
    const plan: *FrozenScreenDestinationPlan =
        @ptrFromInt(write.source_backing_addr);
    const transfer: *ScreenTransferOwner =
        @ptrFromInt(write.prepared_backing_addr);
    if (!plan.expected_partial_empty and write.mutation_index == 0)
        storage.live_partial = .none;
    if (phase == .partial) {
        const target: *@TypeOf(storage.live_partial) =
            @ptrFromInt(write.target_addr);
        target.* = .{ .assembling = .{
            .ledger_token = write.screen_token,
            .generation = plan.next_partial_generation,
            .owner_digest = livePartialDigest(
                storage,
                write.screen_token,
                plan.next_partial_generation,
            ),
        } };
    } else if (phase == .completed) {
        if (storage.live_screen.lifecycle == .empty) {
            storage.live_screen.saved_self_addr =
                @intFromPtr(&storage.live_screen);
            storage.live_screen.storage_addr = @intFromPtr(storage);
            storage.live_screen.lifecycle = .active;
        }
        const target: *external_inbox_ledger.Token =
            @ptrFromInt(write.target_addr);
        target.* = write.screen_token;
    }
    transfer.lifecycle = .committed;
    transfer.digest = screenTransferDigest(transfer);
    if (write.final_for_kind) {
        if (plan.completed_count != 0) {
            // Prefix validation proved this sum fits the fixed ring. Publish the already-sealed
            // final length once, after every token slot has been written; the no-fail suffix must
            // not perform Debug checked arithmetic or expose an intermediate logical length.
            storage.live_screen.len =
                plan.expected_screen_len +% plan.completed_count;
            storage.live_screen.generation = plan.next_screen_generation;
            storage.live_screen.owner_digest =
                liveScreenDigest(storage, &storage.live_screen);
        }
        plan.lifecycle = .consumed;
        plan.digest = screenDestinationPlanDigest(plan);
    }
}

fn tombstoneMovedIntentPayloadUnchecked(
    payload: *external_rx_intent.MovedIntentPayload,
) void {
    external_rx_intent.commitMovedIntentPayloadTransferUnchecked(payload);
}

fn commitEventRetirementUnchecked(
    write: *const FrozenDestinationWrite,
) void {
    const neutral: *external_rx_intent.MovedIntentPayload =
        @ptrFromInt(write.source_backing_addr);
    const retirement: *external_rx_intent.PreparedNeutralRetirement =
        @ptrFromInt(write.retirement_backing_addr);
    const cleanup: *external_owner_cleanup.FrozenOwnerCleanupDescriptor =
        @ptrFromInt(write.retirement_target_addr);
    external_rx_intent.commitNeutralRetirementUnchecked(
        neutral,
        retirement,
        cleanup,
    );
}

/// Executes the presealed destination program in intent order. Every branch is a fixed writer:
/// the checked prefix has already selected its target, backing and disposition, so this suffix
/// performs no allocation, callback, decode, capacity calculation or fallible validation.
fn commitDestinationWriteUnchecked(
    storage: *ExternalPumpStorage,
    aggregate: *PreparedRxAggregate,
    write: *const FrozenDestinationWrite,
) void {
    switch (write.kind) {
        .screen_cleanup => commitScreenDestinationPlanUnchecked(
            .cleanup,
            storage,
            write,
        ),
        .screen_partial => commitScreenDestinationPlanUnchecked(
            .partial,
            storage,
            write,
        ),
        .screen_completed => commitScreenDestinationPlanUnchecked(
            .completed,
            storage,
            write,
        ),
        .event_retirement => commitEventRetirementUnchecked(write),
        .authority => {
            commitAuthorityDestinationUnchecked(
                storage,
                @ptrFromInt(write.prepared_backing_addr),
                @ptrFromInt(write.target_addr),
            );
            commitEventRetirementUnchecked(write);
        },
        .resize => {
            commitResizeDestinationUnchecked(
                storage,
                @ptrFromInt(write.prepared_backing_addr),
                @ptrFromInt(write.target_addr),
            );
            commitEventRetirementUnchecked(write);
        },
        .metadata_cleanup => {
            const metadata: *external_event_materialization.PreparedLiveMetadataDestination =
                @ptrFromInt(write.prepared_backing_addr);
            external_event_materialization.commitOwnerMetadataCleanupOnlyUnchecked(
                &metadata.replacement,
                &metadata.staged,
                @ptrFromInt(write.target_addr),
            );
            storage.metadata_pending_summary =
                aggregate.metadata_summary_next;
            commitEventRetirementUnchecked(write);
        },
        .metadata_publish_first => {
            const metadata: *external_event_materialization.PreparedLiveMetadataDestination =
                @ptrFromInt(write.prepared_backing_addr);
            external_event_materialization.commitOwnerMetadataPublishFirstUnchecked(
                &metadata.replacement,
                @ptrFromInt(write.target_addr),
                &metadata.staged,
            );
            storage.metadata_pending_summary =
                aggregate.metadata_summary_next;
            commitEventRetirementUnchecked(write);
        },
        .metadata_replace_newer => {
            const metadata: *external_event_materialization.PreparedLiveMetadataDestination =
                @ptrFromInt(write.prepared_backing_addr);
            external_event_materialization.commitOwnerMetadataReplaceNewerUnchecked(
                &metadata.replacement,
                @ptrFromInt(write.target_addr),
                &metadata.staged,
                &metadata.frozen,
            );
            storage.metadata_pending_summary =
                aggregate.metadata_summary_next;
            commitEventRetirementUnchecked(write);
        },
        .response => commitResponseDestinationPlanUnchecked(
            storage,
            @ptrFromInt(write.prepared_backing_addr),
            @ptrFromInt(write.target_addr),
            @ptrFromInt(write.source_backing_addr),
        ),
        .unused => unreachable,
    }
}

fn wholeTurnLeaseDigest(lease: ExternalWholeTurnLease) external_owner_seal.Digest {
    var writer = external_owner_seal.Writer.init("MARUWTL2");
    writer.writeUsize(lease.saved_self_addr);
    writer.writeUsize(lease.storage_addr);
    writer.writeUsize(lease.scratch_addr);
    writer.writeUsize(lease.scratch_len);
    writer.writeU64(lease.operation_generation);
    writer.writeUsize(lease.rx_resident_cap);
    writer.writeBytes(&lease.rx_resident_cap_digest);
    writer.writeUsize(lease.rx_client_addr);
    writer.writeUsize(lease.rx_parser_addr);
    writer.writeBytes(&lease.rx_authority_digest);
    writer.writeU8(@intFromEnum(lease.lifecycle));
    return writer.finish();
}

fn rxAuthorityDigest(
    client_addr: usize,
    parser_addr: usize,
    provenance: client_external_mode.RxProvenance,
) external_owner_seal.Digest {
    var writer = external_owner_seal.Writer.init("MARURXA1");
    writer.writeUsize(client_addr);
    writer.writeUsize(parser_addr);
    writer.writeBool(provenance.identity != null);
    if (provenance.identity) |identity| {
        writer.writeU64(identity.attach_instance_id);
        writer.writeUsize(identity.destination_slot_addr);
    }
    writer.writeUsize(provenance.destination_slot_len);
    writer.writeU64(provenance.rx_absolute_next);
    writer.writeU64(provenance.buffer_start_absolute);
    writer.writeUsize(provenance.resident_cap);
    writer.writeBytes(&provenance.parser_seal.digest);
    writer.writeU64(provenance.parser_seal.generation);
    writer.writeU8(@intFromEnum(provenance.lifecycle));
    return writer.finish();
}

fn rxResidentCapDigest(
    storage_addr: usize,
    rx_resident_cap: usize,
) external_owner_seal.Digest {
    var writer = external_owner_seal.Writer.init("MARURCP1");
    writer.writeUsize(storage_addr);
    writer.writeUsize(rx_resident_cap);
    return writer.finish();
}

fn rxResidentCapValid(storage: *const ExternalPumpStorage) bool {
    return storage.saved_self_addr == @intFromPtr(storage) and
        storage.rx_resident_cap != 0 and
        storage.rx_resident_cap <= max_rx_resident_bytes and
        std.mem.eql(
            u8,
            &storage.rx_resident_cap_digest,
            &rxResidentCapDigest(
                @intFromPtr(storage),
                storage.rx_resident_cap,
            ),
        );
}

fn clientRxResidentCap(client: *const client_mod.Client) ?usize {
    const state = switch (client.io_mode) {
        .external => |*external| external,
        .blocking => return null,
    };
    if (!client_external_mode.parserSealValid(state, &client.parser))
        return null;
    return state.rx_provenance.resident_cap;
}

fn rxResidentCapOwnerValid(storage: *const ExternalPumpStorage) bool {
    if (!rxResidentCapValid(storage)) return false;
    const client = if (storage.owned_client) |*owned| owned else return false;
    return clientRxResidentCap(client) == storage.rx_resident_cap;
}

fn restoreRxResidentCapFromClient(storage: *ExternalPumpStorage) bool {
    const client = if (storage.owned_client) |*owned| owned else return false;
    const resident_cap = clientRxResidentCap(client) orelse return false;
    if (resident_cap == 0 or resident_cap > max_rx_resident_bytes)
        return false;
    storage.saved_self_addr = @intFromPtr(storage);
    storage.rx_resident_cap = resident_cap;
    storage.rx_resident_cap_digest =
        rxResidentCapDigest(@intFromPtr(storage), resident_cap);
    return true;
}

const RxResidentCapAuthoritySnapshot = struct {
    storage_addr: usize,
    client_addr: usize,
    parser_addr: usize,
    resident_cap: usize,
    resident_cap_digest: external_owner_seal.Digest,
    provenance: client_external_mode.RxProvenance,
};

fn snapshotRxResidentCapAuthority(
    storage: *const ExternalPumpStorage,
) ?RxResidentCapAuthoritySnapshot {
    if (!rxResidentCapOwnerValid(storage)) return null;
    const client = if (storage.owned_client) |*owned| owned else return null;
    const state = switch (client.io_mode) {
        .external => |*external| external,
        .blocking => return null,
    };
    return .{
        .storage_addr = @intFromPtr(storage),
        .client_addr = @intFromPtr(client),
        .parser_addr = @intFromPtr(&client.parser),
        .resident_cap = storage.rx_resident_cap,
        .resident_cap_digest = storage.rx_resident_cap_digest,
        .provenance = state.rx_provenance,
    };
}

fn rxResidentCapAuthorityMatches(
    storage: *const ExternalPumpStorage,
    snapshot: RxResidentCapAuthoritySnapshot,
) bool {
    if (snapshot.storage_addr != @intFromPtr(storage) or
        storage.rx_resident_cap != snapshot.resident_cap or
        !std.mem.eql(
            u8,
            &storage.rx_resident_cap_digest,
            &snapshot.resident_cap_digest,
        ))
        return false;
    const client = if (storage.owned_client) |*owned| owned else return false;
    if (snapshot.client_addr != @intFromPtr(client) or
        snapshot.parser_addr != @intFromPtr(&client.parser))
        return false;
    const state = switch (client.io_mode) {
        .external => |*external| external,
        .blocking => return false,
    };
    return std.meta.eql(state.rx_provenance, snapshot.provenance) and
        rxResidentCapOwnerValid(storage);
}

fn restoreRxResidentCapAuthority(
    storage: *ExternalPumpStorage,
    snapshot: RxResidentCapAuthoritySnapshot,
) bool {
    if (snapshot.storage_addr != @intFromPtr(storage)) return false;
    const client = if (storage.owned_client) |*owned| owned else return false;
    if (snapshot.client_addr != @intFromPtr(client) or
        snapshot.parser_addr != @intFromPtr(&client.parser))
        return false;
    const state = switch (client.io_mode) {
        .external => |*external| external,
        .blocking => return false,
    };
    storage.saved_self_addr = snapshot.storage_addr;
    storage.rx_resident_cap = snapshot.resident_cap;
    storage.rx_resident_cap_digest = snapshot.resident_cap_digest;
    state.rx_provenance = snapshot.provenance;
    return rxResidentCapAuthorityMatches(storage, snapshot);
}

fn screenPendingSummaryDigest(
    seal: ScreenPendingSummarySeal,
) external_owner_seal.Digest {
    var writer = external_owner_seal.Writer.init("MARUSPS1");
    writer.writeUsize(seal.screen_owner_addr);
    writer.writeUsize(seal.storage_addr);
    writer.writeU64(seal.owner_incarnation);
    writer.writeUsize(seal.retained_count);
    writer.writeBool(seal.committed);
    writer.writeU64(seal.generation);
    writer.writeU8(@intFromEnum(seal.lifecycle));
    return writer.finish();
}

fn metadataPendingSummaryDigest(
    seal: MetadataPendingSummarySeal,
) external_owner_seal.Digest {
    var writer = external_owner_seal.Writer.init("MARUMPS1");
    writer.writeUsize(seal.metadata_owner_addr);
    writer.writeUsize(seal.storage_addr);
    writer.writeU64(seal.owner_incarnation);
    writer.writeU64(seal.revision);
    writer.writeBool(seal.pending);
    writer.writeBool(seal.supported);
    writer.writeU64(seal.generation);
    writer.writeU8(@intFromEnum(seal.lifecycle));
    return writer.finish();
}

fn metadataPendingSealFromSummary(
    storage: *const ExternalPumpStorage,
    summary: external_event_materialization.MetadataStateSummary,
    generation: u64,
) MetadataPendingSummarySeal {
    var seal = MetadataPendingSummarySeal{
        .metadata_owner_addr = @intFromPtr(&storage.owner_metadata),
        .storage_addr = @intFromPtr(storage),
        .owner_incarnation = storage.owner_incarnation,
        .generation = generation,
        .lifecycle = .bound,
    };
    switch (summary) {
        .unsupported => {},
        .unavailable => seal.supported = true,
        .current => |current| {
            seal.supported = true;
            seal.revision = current.revision;
            seal.pending = current.pending;
        },
    }
    seal.digest = metadataPendingSummaryDigest(seal);
    return seal;
}

fn inheritedSnapshotDigest(
    snapshot: InheritedRxBlockerSnapshot,
) external_owner_seal.Digest {
    var writer = external_owner_seal.Writer.init("MARUIRS1");
    writer.writeUsize(snapshot.saved_self_addr);
    writer.writeUsize(snapshot.storage_addr);
    writer.writeUsize(snapshot.lease_addr);
    writer.writeU64(snapshot.operation_generation);
    writer.writeBool(snapshot.committed_screen_pending);
    writer.writeBool(snapshot.live_partial_pending);
    writer.writeBool(snapshot.live_screen_pending);
    writer.writeBool(snapshot.metadata_projection_pending);
    writer.writeBool(snapshot.resize_projection_pending);
    writer.writeBool(snapshot.response_correlation_pending);
    switch (snapshot.authority_generation) {
        .untracked => writer.writeBool(false),
        .tracked => |generation| {
            writer.writeBool(true);
            writer.writeU64(generation);
        },
    }
    writer.writeU64(snapshot.generation);
    writer.writeU8(@intFromEnum(snapshot.lifecycle));
    writer.writeBytes(&snapshot.owner_digest);
    return writer.finish();
}

pub fn crossOwnerQuarantineStatus() CrossOwnerQuarantineStatus {
    const events = cross_owner_quarantine_events.load(.acquire);
    const latched = events != 0;
    return .{
        .latched = latched,
        .event_count = events,
        .leaked_bytes_upper_bound = if (latched)
            max_cross_owner_quarantine_bytes
        else
            0,
    };
}

const ExternalPumpCleanupScratchLifecycle = enum {
    empty,
    ready,
    frozen,
    poisoned,
};
const ExternalPumpRangeScratchKind = enum { source, teardown };

const LiveOwnerTeardownLifecycle = enum {
    empty,
    prepared,
    frozen,
    consumed,
    aborted,
};

const PreparedLiveOwnerTeardown = struct {
    saved_self_addr: usize = 0,
    storage_addr: usize = 0,
    known_tokens: [external_inbox_ledger.max_live_mutations + 1]external_inbox_ledger.Token =
        [_]external_inbox_ledger.Token{.{ .slot = 0, .generation = 0 }} **
        (external_inbox_ledger.max_live_mutations + 1),
    known_token_count: u8 = 0,
    partial_owner_digest: external_owner_seal.Digest = [_]u8{0} ** 32,
    screen_owner_digest: external_owner_seal.Digest = [_]u8{0} ** 32,
    response_owner_digest: external_owner_seal.Digest = [_]u8{0} ** 32,
    response_seal: ResponsePayloadSeal = ResponsePayloadSeal.empty(),
    lifecycle: LiveOwnerTeardownLifecycle = .empty,
    digest: external_owner_seal.Digest = [_]u8{0} ** 32,
};

const FrozenResponsePayloadCleanup = struct {
    payload: external_inbox_ledger.OwnedPayload =
        .{ .allocator = std.heap.page_allocator },
    seal: ResponsePayloadSeal = ResponsePayloadSeal.empty(),
    has_payload: bool = false,

    fn valid(self: *const FrozenResponsePayloadCleanup) bool {
        return if (self.has_payload)
            self.seal.validatesPayload(&self.payload)
        else
            self.payload.allocation_ptr == null and
                self.payload.logical_len == 0 and
                std.meta.eql(self.seal, ResponsePayloadSeal.empty());
    }

    /// The primitive owns the only callback-visible step. It tombstones itself before free so
    /// teardown and the later exact response take can share the same no-reentry cleanup rule.
    fn finishCallbackHidden(self: *FrozenResponsePayloadCleanup) bool {
        if (!self.valid()) return false;
        const has_payload = self.has_payload;
        var payload = self.payload;
        self.* = .{};
        if (has_payload) payload.deinit();
        return true;
    }
};

const FrozenLiveOwnerCleanup = struct {
    saved_self_addr: usize = 0,
    response: FrozenResponsePayloadCleanup = .{},
    lifecycle: LiveOwnerTeardownLifecycle = .empty,
    digest: external_owner_seal.Digest = [_]u8{0} ** 32,

    fn finishCallbackHidden(self: *FrozenLiveOwnerCleanup) bool {
        if (self.saved_self_addr != @intFromPtr(self) or
            self.lifecycle != .frozen or
            !std.mem.eql(u8, &self.digest, &frozenLiveOwnerDigest(self)))
            return false;
        var response = self.response;
        self.* = .{ .lifecycle = .consumed };
        return response.finishCallbackHidden();
    }
};

fn preparedLiveOwnerTeardownDigest(
    prepared: *const PreparedLiveOwnerTeardown,
) external_owner_seal.Digest {
    var writer = external_owner_seal.Writer.init("MARULOT1");
    writer.writeUsize(prepared.saved_self_addr);
    writer.writeUsize(prepared.storage_addr);
    writer.writeU8(prepared.known_token_count);
    for (prepared.known_tokens) |token| {
        writer.writeU16(token.slot);
        writer.writeU64(token.generation);
    }
    writer.writeBytes(&prepared.partial_owner_digest);
    writer.writeBytes(&prepared.screen_owner_digest);
    writer.writeBytes(&prepared.response_owner_digest);
    prepared.response_seal.writeDigest(&writer);
    writer.writeU8(@intFromEnum(prepared.lifecycle));
    return writer.finish();
}

fn frozenLiveOwnerDigest(
    frozen: *const FrozenLiveOwnerCleanup,
) external_owner_seal.Digest {
    var writer = external_owner_seal.Writer.init("MARULOF1");
    writer.writeUsize(frozen.saved_self_addr);
    writer.writeBool(frozen.response.has_payload);
    frozen.response.seal.writeDigest(&writer);
    writer.writeUsize(if (frozen.response.payload.allocation_ptr) |ptr|
        @intFromPtr(ptr)
    else
        0);
    writer.writeUsize(frozen.response.payload.logical_len);
    writer.writeUsize(@intFromPtr(frozen.response.payload.allocator.ptr));
    writer.writeUsize(@intFromPtr(frozen.response.payload.allocator.vtable));
    writer.writeU8(@intFromEnum(frozen.lifecycle));
    return writer.finish();
}

fn appendPreparedLiveOwnerRanges(
    prepared: *const PreparedLiveOwnerTeardown,
    ranges: *external_owner_range.Scratch,
) external_owner_range.Error!void {
    try ranges.append(
        prepared.response_seal.payload_addr,
        prepared.response_seal.payload_len,
    );
}

const RetainedRxAggregateDestroyExecution = struct {
    aggregate: *PreparedRxAggregate,
    allocator: std.mem.Allocator,
};

/// Persistent caller-owned cleanup authority shared by prepare and its immediate suffix.
///
/// The aggregate is initialized only at its final address. A successful recovery or terminal
/// suffix freezes its descriptors before the first allocator callback and restores `.ready` only
/// after every descriptor has been consumed.
pub const ExternalPumpCleanupScratch = struct {
    saved_self_addr: usize = 0,
    lifecycle: ExternalPumpCleanupScratchLifecycle = .empty,
    client: client_mod.ExternalAdoptionCleanupScratch = undefined,
    range_scratch_kind: ExternalPumpRangeScratchKind = .source,
    range_scratch: union {
        source: client_mod.ExternalSourceOwnerRangeScratch,
        teardown: external_owner_range.Scratch,
    } = .{ .source = .{} },
    recovery_discard: client_mod.ExternalRecoveryDiscardSeal = .{},
    ledger_permit: external_inbox_ledger.OwnerTeardownPermit = .{},
    ledger_prepared: external_inbox_ledger.PreparedLedgerTeardown = .{},
    ledger_frozen: external_inbox_ledger.FrozenLedgerCleanup = .{},
    screen_plan: external_inbox_ledger.FrozenScreenTokenPlan = .{},
    screen_prepared: client_external_adoption.PreparedCommittedScreenCleanup = .{},
    screen_frozen: client_external_adoption.FrozenCommittedScreenCleanup = .{},
    metadata_prepared: external_event_materialization.PreparedOwnerMetadataCleanup = .{},
    metadata_frozen: external_event_materialization.FrozenOwnerMetadataCleanup = .{},
    take_prepared: client_mod.PreparedExternalAdoptionTakeCleanup = .{},
    take_frozen: client_mod.FrozenExternalAdoptionTakeCleanup = .{},
    live_prepared: PreparedLiveOwnerTeardown = .{},
    live_frozen: FrozenLiveOwnerCleanup = .{},
    intent_destroy_prepared: external_rx_intent.PreparedDestroy = .{},
    aggregate_cleanup: external_owner_cleanup.FrozenOwnerCleanupDescriptor = .{},
    aggregate_execution: ?RetainedRxAggregateDestroyExecution = null,
    moved_client: ?client_mod.Client = null,
    moved_evidence: ?PreparedAdoptionEvidence = null,

    pub fn initInPlace(out: *ExternalPumpCleanupScratch) bool {
        if (out.lifecycle != .empty or out.saved_self_addr != 0) return false;
        out.saved_self_addr = @intFromPtr(out);
        out.lifecycle = .ready;
        out.range_scratch_kind = .source;
        out.range_scratch.source = .{};
        out.recovery_discard = .{};
        out.ledger_permit = .{};
        out.ledger_prepared = .{};
        out.ledger_frozen = .{};
        out.screen_plan = .{};
        out.screen_prepared = .{};
        out.screen_frozen = .{};
        out.metadata_prepared = .{};
        out.metadata_frozen = .{};
        out.take_prepared = .{};
        out.take_frozen = .{};
        out.live_prepared = .{};
        out.live_frozen = .{};
        out.intent_destroy_prepared = .{};
        out.aggregate_cleanup = .{};
        out.aggregate_execution = null;
        out.moved_client = null;
        out.moved_evidence = null;
        return true;
    }

    fn isReady(self: *const ExternalPumpCleanupScratch) bool {
        return self.saved_self_addr == @intFromPtr(self) and
            self.lifecycle == .ready and
            self.range_scratch_kind == .source and
            self.recovery_discard.isEmpty() and
            self.ledger_permit.saved_self_addr == 0 and
            self.ledger_prepared.saved_self_addr == 0 and
            self.ledger_frozen.saved_self_addr == 0 and
            self.screen_plan.saved_self_addr == 0 and
            self.screen_prepared.saved_self_addr == 0 and
            self.screen_frozen.saved_self_addr == 0 and
            self.metadata_prepared.saved_self_addr == 0 and
            self.metadata_frozen.saved_self_addr == 0 and
            self.take_prepared.saved_self_addr == 0 and
            self.take_frozen.saved_self_addr == 0 and
            self.live_prepared.saved_self_addr == 0 and
            self.live_frozen.saved_self_addr == 0 and
            self.aggregate_cleanup.saved_self_addr == 0 and
            self.aggregate_execution == null and
            self.moved_client == null and self.moved_evidence == null;
    }

    fn resetReady(self: *ExternalPumpCleanupScratch) void {
        self.saved_self_addr = @intFromPtr(self);
        self.range_scratch_kind = .source;
        self.range_scratch.source = .{};
        self.recovery_discard = .{};
        self.ledger_permit = .{};
        self.ledger_prepared = .{};
        self.ledger_frozen = .{};
        self.screen_plan = .{};
        self.screen_prepared = .{};
        self.screen_frozen = .{};
        self.metadata_prepared = .{};
        self.metadata_frozen = .{};
        self.take_prepared = .{};
        self.take_frozen = .{};
        self.live_prepared = .{};
        self.live_frozen = .{};
        self.intent_destroy_prepared = .{};
        self.aggregate_cleanup = .{};
        self.aggregate_execution = null;
        self.moved_client = null;
        self.moved_evidence = null;
        self.lifecycle = .ready;
    }
};

pub const max_external_pump_cleanup_scratch_bytes: usize = 1024 * 1024;
pub const max_external_pump_callback_local_bytes: usize = 768 * 1024;

comptime {
    if (@sizeOf(PreparedRxAggregate) >
        external_inbox_ledger.max_live_aggregate_scratch_bytes)
        @compileError("prepared RX aggregate exceeds 256 KiB");
    if (@sizeOf(ExternalPumpCleanupScratch) >
        max_external_pump_cleanup_scratch_bytes)
        @compileError("external pump cleanup scratch exceeds 1 MiB");
    const teardown_callback_local_bytes =
        @sizeOf(external_inbox_ledger.FrozenLedgerCleanup) +
        @sizeOf(external_event_materialization.FrozenOwnerMetadataCleanup) +
        @sizeOf(client_mod.FrozenExternalAdoptionTakeCleanup) +
        @sizeOf(client_mod.ExternalAdoptionCleanupScratch) +
        @sizeOf(client_external_adoption.FrozenCommittedScreenCleanup) +
        @sizeOf(FrozenLiveOwnerCleanup) +
        @sizeOf(external_rx_intent.FrozenDestroy) +
        @sizeOf(client_mod.Client) +
        @sizeOf(PreparedAdoptionEvidence) +
        rx_aggregate_abort_frame_bytes;
    const rx_aggregate_commit_callback_frame_bytes =
        @sizeOf(FrozenAggregateCleanup) +
        @sizeOf(PreparedRxAggregate);
    const callback_local_bytes = @max(
        teardown_callback_local_bytes,
        rx_aggregate_commit_callback_frame_bytes,
    );
    if (callback_local_bytes > max_external_pump_callback_local_bytes)
        @compileError("external pump callback-hidden locals exceed 768 KiB");
}

fn resetCrossOwnerQuarantineForTest() void {
    cross_owner_quarantine_events.store(0, .release);
}

fn tryLatchCrossOwnerQuarantineEvent() ?u64 {
    return checked_event_counter.increment(&cross_owner_quarantine_events);
}

fn latchCrossOwnerQuarantine() void {
    _ = tryLatchCrossOwnerQuarantineEvent();
}

pub fn accountGuardedAdmitQuarantine(
    prepared: *client_external_mode.PreparedRxAppend,
    outcome_tag: client_external_mode.GuardedQuarantineOutcomeTag,
    quarantine: client_external_mode.GuardedAdmitQuarantine,
    out: *client_external_mode.GuardedQuarantineAccountingReceipt,
) bool {
    const prepared_addr = @intFromPtr(prepared);
    if (guarded_admit_accounting_prepared_addr.cmpxchgStrong(
        0,
        prepared_addr,
        .acq_rel,
        .acquire,
    ) != null)
        return false;
    defer {
        _ = guarded_admit_accounting_prepared_addr.cmpxchgStrong(
            prepared_addr,
            0,
            .acq_rel,
            .acquire,
        );
    }
    if (quarantine.quarantined_bytes_upper_bound >
        max_guarded_admit_quarantine_bytes)
        return false;
    if (!client_external_mode.markQuarantinedPreparedAdmitAccounted(
        prepared,
        outcome_tag,
        quarantine,
        &cross_owner_quarantine_events,
        out,
    )) {
        return false;
    }
    return true;
}

pub const quarantine_testing = if (builtin.is_test) struct {
    pub fn reset() void {
        resetCrossOwnerQuarantineForTest();
        guarded_admit_accounting_prepared_addr.store(0, .release);
    }

    pub fn forceEventGeneration(value: u64) void {
        cross_owner_quarantine_events.store(value, .release);
    }
} else struct {};

fn releaseActiveStorage(address: usize) void {
    _ = active_storage_addr.cmpxchgStrong(
        address,
        0,
        .acq_rel,
        .acquire,
    );
}

pub const ExternalPumpStorage = struct {
    access_claim: std.atomic.Value(u8) =
        .init(@intFromEnum(StorageClaim.idle)),
    lifecycle: StorageLifecycle = .empty,
    saved_self_addr: usize = 0,
    rx_resident_cap: usize = 0,
    rx_resident_cap_digest: external_owner_seal.Digest = [_]u8{0} ** 32,
    semantic_state: client_pump.ExternalPumpState = .constructing,
    evidence_snapshot: AttachmentEvidence = .{
        .runtime_id = 0,
        .stream_id = 0,
        .initial_role = .observer,
        .initial_controller_generation = 0,
    },
    owned_client: ?client_mod.Client = null,
    /// Temporary seed owner. c3c replaces this with the final `OwnerMetadataState`; until then it is
    /// the only thing that owns the metadata seed after the paired take, so teardown must free it.
    owned_evidence: ?PreparedAdoptionEvidence = null,
    /// Staging token for the Client move. It is meaningful only inside `initInPlace`: after
    /// `finishExternalPumpTransfer` it is a spent `.committed` record whose source address has been
    /// cleared, and nothing may read it as a description of live state.
    client_transfer: client_mod.PreparedExternalPumpTransfer = .{},
    inbox_ledger: external_inbox_ledger.ExternalInboxLedger = .{},
    prepared_adoption: PreparedExternalAdoption = .{},
    client_cleanup_take: client_mod.ExternalAdoptionTake = .{},
    committed_screen: client_external_adoption.CommittedScreenBacklog = .{},
    /// The sole charged token currently borrowed by the bound `RemoteAttachment`. This is owner
    /// state, not a callback lease: storage teardown must refuse while it is present so the Client
    /// object and ledger outlive attachment cleanup even after connection poison.
    attachment_lease: ?external_inbox_ledger.Token = null,
    live_partial: LivePartialBatch = .none,
    live_screen: LiveScreenBacklog = .{},
    completed_control: CompletedControlOwner = .none,
    completed_control_generation: u64 = 0,
    screen_pending_summary: ScreenPendingSummarySeal = .{},
    owner_metadata: external_event_materialization.OwnerMetadataState = .{},
    metadata_pending_summary: MetadataPendingSummarySeal = .{},
    owner_resize: OwnerResizeState = .none,
    owner_authority: OwnerAuthorityState = .empty,
    owner_authority_seal: OwnerAuthoritySeal = .{},
    owner_request_ids: ?client_pump.RequestIdState = null,
    control_correlation: ControlCorrelationOwner = .{},
    owner_incarnation: u64 = 0,
    owner_incarnation_seal: OwnerIncarnationSeal = .{},
    owner_event_projection_generation: u64 = 0,
    operation_generation: u64 = 0,
    operation_reentry_latched: bool = false,
    callback_quarantine_pending: bool = false,
    callback_quarantine_accounted: bool = false,
    owner_teardown_generation: u64 = 0,
    intent_scratch_generation: u64 = 0,
    intent_scratch_reservation: IntentScratchReservation = .{},
    rx_aggregate_generation: u64 = 0,
    rx_aggregate_handle: PreparedRxAggregateHandle = .{},
    rx_aggregate_reservation: RxAggregateScratchReservation = .{},

    fn bindPendingSummaries(self: *ExternalPumpStorage) void {
        self.screen_pending_summary = .{
            .screen_owner_addr = @intFromPtr(&self.committed_screen),
            .storage_addr = @intFromPtr(self),
            .owner_incarnation = self.owner_incarnation,
            .retained_count = self.committed_screen.retained_count,
            // The final permit proved the destination was pristine and the preceding no-fail take
            // published the committed owner. Revalidation belongs to readers, not this suffix.
            .committed = true,
            .generation = 1,
            .lifecycle = .bound,
        };
        self.screen_pending_summary.digest =
            screenPendingSummaryDigest(self.screen_pending_summary);
        const summary = switch (self.owner_metadata.metadata) {
            .unsupported => external_event_materialization.MetadataStateSummary.unsupported,
            .unavailable => external_event_materialization.MetadataStateSummary.unavailable,
            .current => |current| external_event_materialization.MetadataStateSummary{
                .current = .{
                    .revision = current.logical.revision,
                    .pending = current.pending,
                },
            },
        };
        self.metadata_pending_summary = metadataPendingSealFromSummary(
            self,
            summary,
            1,
        );
    }

    fn screenPendingSummaryValid(self: *const ExternalPumpStorage) bool {
        const seal = self.screen_pending_summary;
        const retained_count =
            self.committed_screen.pendingCountSummary(self) orelse return false;
        return seal.lifecycle == .bound and
            seal.screen_owner_addr == @intFromPtr(&self.committed_screen) and
            seal.storage_addr == @intFromPtr(self) and
            seal.owner_incarnation == self.owner_incarnation and
            seal.retained_count == retained_count and seal.committed and
            std.mem.eql(u8, &seal.digest, &screenPendingSummaryDigest(seal));
    }

    fn metadataPendingSummaryValid(self: *const ExternalPumpStorage) bool {
        const seal = self.metadata_pending_summary;
        if (seal.lifecycle != .bound or
            seal.metadata_owner_addr != @intFromPtr(&self.owner_metadata) or
            seal.storage_addr != @intFromPtr(self) or
            seal.owner_incarnation != self.owner_incarnation or
            !std.mem.eql(u8, &seal.digest, &metadataPendingSummaryDigest(seal)))
            return false;
        const summary = self.owner_metadata.pendingStateSummary(self) orelse return false;
        return switch (summary) {
            .unsupported => !seal.supported and seal.revision == 0 and !seal.pending,
            .unavailable => seal.supported and seal.revision == 0 and !seal.pending,
            .current => |current| seal.supported and
                seal.revision == current.revision and
                seal.pending == current.pending,
        };
    }

    fn livePartialValid(self: *const ExternalPumpStorage) bool {
        return switch (self.live_partial) {
            .none, .terminal => true,
            .assembling => |assembling| assembling.generation != 0 and
                assembling.ledger_token.generation != 0 and
                std.mem.eql(
                    u8,
                    &assembling.owner_digest,
                    &livePartialDigest(
                        self,
                        assembling.ledger_token,
                        assembling.generation,
                    ),
                ),
        };
    }

    fn liveScreenValid(self: *const ExternalPumpStorage) bool {
        const backlog = &self.live_screen;
        switch (backlog.lifecycle) {
            .empty, .terminal, .cleaned_tombstone => {
                if (backlog.saved_self_addr == 0 and
                    backlog.storage_addr == 0 and backlog.head == 0 and
                    backlog.len == 0 and backlog.generation == 0 and
                    std.mem.allEqual(u8, &backlog.owner_digest, 0))
                {
                    for (backlog.tokens) |token|
                        if (token.slot != 0 or token.generation != 0)
                            return false;
                    return true;
                }
                return false;
            },
            .active => {},
        }
        if (backlog.saved_self_addr != @intFromPtr(backlog) or
            backlog.storage_addr != @intFromPtr(self) or
            backlog.generation == 0 or
            backlog.len == 0 or
            backlog.len > external_inbox_ledger.max_live_mutations or
            backlog.head >= external_inbox_ledger.max_live_mutations or
            !std.mem.eql(
                u8,
                &backlog.owner_digest,
                &liveScreenDigest(self, backlog),
            ))
            return false;
        const capacity = external_inbox_ledger.max_live_mutations;
        for (backlog.tokens, 0..) |token, index| {
            const offset = (index + capacity - backlog.head) % capacity;
            const active = offset < backlog.len;
            if (!active) {
                if (token.slot != 0 or token.generation != 0) return false;
                continue;
            }
            if (token.generation == 0 or
                @as(usize, token.slot) >= external_inbox_ledger.max_items)
                return false;
            for (0..offset) |prior_offset| {
                const prior_index = (backlog.head + prior_offset) % capacity;
                if (backlog.tokens[prior_index].slot == token.slot)
                    return false;
            }
        }
        return true;
    }

    fn completedControlValid(self: *const ExternalPumpStorage) bool {
        return switch (self.completed_control) {
            // A private prepared take temporarily moves the payload into its frozen owner while
            // the same whole-turn lease keeps the completed correlation as backpressure.
            .none => true,
            .terminal => true,
            .completed => |*pending| blk: {
                const completed = switch (self.control_correlation.state) {
                    .completed => |value| value,
                    .idle, .in_flight, .terminal => break :blk false,
                };
                if (pending.generation == 0 or
                    pending.generation != self.completed_control_generation or
                    pending.request_id == 0 or
                    pending.control_kind != completed.kind or
                    !std.meta.eql(pending.expectation, completed.expectation) or
                    pending.target_stream_id != completed.target.stream_id or
                    pending.expected_controller_generation !=
                        completed.target.controller_generation or
                    pending.request_id != completed.request_id or
                    pending.control_wire_len != completed.wire_len or
                    pending.correlation_generation !=
                        self.control_correlation.generation or
                    pending.source_turn_generation == 0 or
                    pending.source_parser_generation == 0 or
                    pending.source_end_absolute <= pending.source_start_absolute or
                    std.mem.allEqual(u8, &pending.source_owner_digest, 0) or
                    !pending.seal.validatesPayload(&pending.payload))
                    break :blk false;
                break :blk std.mem.eql(
                    u8,
                    &pending.owner_digest,
                    &completedControlDigest(self, pending),
                );
            },
        };
    }

    fn semanticAuthorityMatchesCompleted(
        self: *const ExternalPumpStorage,
        completed: *const CompletedControlState,
    ) bool {
        if (!ownerAuthorityValid(self) or
            self.owner_authority.current.flow != .clear)
            return false;
        if (!controlGenerationMatches(
            completed.control_kind,
            self.owner_authority.current.generation,
            completed.expected_controller_generation,
        ) or
            completed.target_stream_id != self.evidence_snapshot.stream_id or
            !completed.expectation.isCanonical())
            return false;
        return switch (completed.expectation) {
            .resize => self.owner_authority.current.role == .controller and
                self.semantic_state == .active and
                self.semantic_state.active == .valid,
            .resync => |expected| blk: {
                if (self.owner_authority.current.role != .controller)
                    break :blk false;
                if (expected.owner_incarnation != self.owner_incarnation or
                    expected.origin != .client)
                    break :blk false;
                const active = switch (self.semantic_state) {
                    .active => |value| value,
                    else => break :blk false,
                };
                break :blk switch (active) {
                    .client_recovery => |phase| switch (phase) {
                        .control_in_flight => |context| expected.recovery_epoch == context.epoch,
                        else => false,
                    },
                    else => false,
                };
            },
            .detach => self.semantic_state == .active and
                self.semantic_state.active == .valid,
        };
    }

    fn completedSemanticPreparationCurrent(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        summary: RxPreparedSummary,
        expected_completed_digest: external_owner_seal.Digest,
        expected_correlation_digest: external_owner_seal.Digest,
        expected_parser_seal: client_external_mode.ParserAuthoritySeal,
        expected_tx_generation: u64,
    ) bool {
        if (!self.wholeTurnLeaseIdentityValid(lease) or
            scratch.saved_self_addr != @intFromPtr(scratch) or
            scratch.lifecycle != .busy or
            summary.policy.terminal != null or
            summary.policy.rx_frame_budget_exhausted or
            summary.policy.rx_read_budget_exhausted or
            summary.policy.work_budget_exhausted or
            summary.policy.parser != .empty or
            self.operation_reentry_latched or
            active_callback_region_addr != 0 or
            active_callback_release_addr != 0 or
            !controlSemanticDestinationsPristine(scratch) or
            !self.completedControlValid())
            return false;
        const evidence = &scratch.drain_evidence;
        if (evidence.lifecycle != .finished or
            evidence.mode != .completed_control or
            evidence.work_budget_exhausted or
            !rxDrainEvidenceSealed(evidence) or
            !self.finishedRxDrainEvidenceCurrentUnderHeldLease(
                lease,
                scratch,
                .completed_control,
            ))
            return false;
        const projection = self.currentDrainBlockerProjectionForMode(
            .completed_control,
        ) orelse return false;
        if (!projection.all_clear or
            !std.mem.eql(
                u8,
                &projection.completed_exception_digest,
                &evidence.completed_exception_digest,
            ))
            return false;
        const completed = switch (self.completed_control) {
            .completed => |*value| value,
            .none, .terminal => return false,
        };
        const client = if (self.owned_client) |*owned| owned else return false;
        const external = switch (client.io_mode) {
            .external => |*state| state,
            .blocking => return false,
        };
        const readiness = client_external_mode.parserReadiness(
            external,
            &client.parser,
        ) catch return false;
        return readiness == .empty and
            client_external_mode.parserSealValid(external, &client.parser) and
            std.meta.eql(external.rx_provenance.parser_seal, expected_parser_seal) and
            expected_parser_seal.rx_absolute_next >= completed.source_end_absolute and
            completed.source_end_absolute > completed.source_start_absolute and
            std.mem.eql(u8, &completed.owner_digest, &expected_completed_digest) and
            std.mem.eql(
                u8,
                &self.control_correlation.digest,
                &expected_correlation_digest,
            ) and external.tx_queue_generation == expected_tx_generation and
            client_external_tx.requestFrameProgress(
                external,
                completed.request_id,
                completed.control_wire_len,
            ) == .missing and self.semanticAuthorityMatchesCompleted(completed);
    }

    fn publishControlSemanticTerminalPreparation(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        reason: client_pump.TerminalReason,
    ) ControlSemanticPreparationResult {
        const out = &scratch.control_semantic_terminal;
        if (!std.meta.eql(out.*, PreparedControlSemanticTerminal{}) or
            !self.completedControlValid())
            return .not_ready;
        const completed = switch (self.completed_control) {
            .completed => |*value| value,
            .none, .terminal => return .not_ready,
        };
        out.* = .{
            .saved_self_addr = @intFromPtr(out),
            .storage_addr = @intFromPtr(self),
            .lease_addr = @intFromPtr(lease),
            .owner_incarnation = self.owner_incarnation,
            .operation_generation = self.operation_generation,
            .completed_owner_generation = completed.generation,
            .correlation_generation = self.control_correlation.generation,
            .request_id = completed.request_id,
            .completed_payload_seal = completed.seal,
            .reason = reason,
            .lifecycle = .prepared,
        };
        out.digest = preparedControlSemanticTerminalDigest(out);
        return .terminal_prepared;
    }

    fn prepareCompletedControlSemanticUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        summary: RxPreparedSummary,
    ) ControlSemanticPreparationResult {
        if (!controlSemanticDestinationsPristine(scratch) or
            !self.completedControlValid())
            return .not_ready;
        const completed_before = switch (self.completed_control) {
            .completed => |*value| value,
            .none, .terminal => return .not_ready,
        };
        const client = if (self.owned_client) |*owned| owned else return .not_ready;
        const external = switch (client.io_mode) {
            .external => |*state| state,
            .blocking => return .not_ready,
        };
        const completed_digest = completed_before.owner_digest;
        const correlation_digest = self.control_correlation.digest;
        const parser_seal = external.rx_provenance.parser_seal;
        const tx_generation = external.tx_queue_generation;
        if (!self.completedSemanticPreparationCurrent(
            lease,
            scratch,
            summary,
            completed_digest,
            correlation_digest,
            parser_seal,
            tx_generation,
        )) return .not_ready;

        const decoded: ControlSemanticValue = decode: {
            const payload = completed_before.payload.bytes();
            switch (completed_before.control_kind) {
                .resize => {
                    const reply = control_response_wire.decodeResizeResponse(
                        completed_before.payload.allocator,
                        payload,
                        completed_before.expectation,
                    ) catch |err| {
                        const current = self.completedSemanticPreparationCurrent(
                            lease,
                            scratch,
                            summary,
                            completed_digest,
                            correlation_digest,
                            parser_seal,
                            tx_generation,
                        );
                        if (!current) return .not_ready;
                        return self.publishControlSemanticTerminalPreparation(
                            lease,
                            scratch,
                            switch (err) {
                                error.OutOfMemory => .resource_exhausted,
                                else => .protocol_error,
                            },
                        );
                    };
                    switch (reply) {
                        .stale => {
                            const current = self.completedSemanticPreparationCurrent(
                                lease,
                                scratch,
                                summary,
                                completed_digest,
                                correlation_digest,
                                parser_seal,
                                tx_generation,
                            );
                            if (!current) return .not_ready;
                            return self.publishControlSemanticTerminalPreparation(
                                lease,
                                scratch,
                                .protocol_error,
                            );
                        },
                        .applied => break :decode .{ .resize = reply },
                    }
                },
                .resync => {
                    control_response_wire.decodeResyncResponse(
                        completed_before.payload.allocator,
                        payload,
                        completed_before.expectation,
                    ) catch |err| {
                        const current = self.completedSemanticPreparationCurrent(
                            lease,
                            scratch,
                            summary,
                            completed_digest,
                            correlation_digest,
                            parser_seal,
                            tx_generation,
                        );
                        if (!current) return .not_ready;
                        return self.publishControlSemanticTerminalPreparation(
                            lease,
                            scratch,
                            switch (err) {
                                error.OutOfMemory => .resource_exhausted,
                                else => .protocol_error,
                            },
                        );
                    };
                    break :decode .resync_ack;
                },
                // Cleanup closes immediately after the request frame is fully sent, so a detach
                // response can only be observed through a hostile/racing extra RX turn. Treat it
                // as a terminal acknowledgement instead of publishing reusable control state.
                .detach => return self.publishControlSemanticTerminalPreparation(
                    lease,
                    scratch,
                    .runtime_ended,
                ),
            }
        };

        if (!self.completedSemanticPreparationCurrent(
            lease,
            scratch,
            summary,
            completed_digest,
            correlation_digest,
            parser_seal,
            tx_generation,
        )) return .not_ready;
        if (decoded == .resize) {
            const applied = switch (decoded.resize) {
                .applied => |value| value,
                .stale => unreachable,
            };
            const resize_plan = planResizeSemanticCommit(
                self.owner_resize,
                self.evidence_snapshot.runtime_id,
                completed_before.target_stream_id,
                self.evidence_snapshot.stream_id,
                applied,
            );
            switch (resize_plan.disposition) {
                .protocol_terminal => return self.publishControlSemanticTerminalPreparation(
                    lease,
                    scratch,
                    .protocol_error,
                ),
                .invariant_terminal => return self.publishControlSemanticTerminalPreparation(
                    lease,
                    scratch,
                    .invariant_failure,
                ),
                .publish_new, .preserve_current => {},
            }
        }
        const completed = switch (self.completed_control) {
            .completed => |*value| value,
            .none, .terminal => return .not_ready,
        };
        const authority = self.owner_authority.current;
        const permit = &scratch.whole_drain_permit;
        const verdict = &scratch.control_semantic_verdict;
        permit.* = .{
            .saved_self_addr = @intFromPtr(permit),
            .verdict_addr = @intFromPtr(verdict),
            .storage_addr = @intFromPtr(self),
            .lease_addr = @intFromPtr(lease),
            .owner_incarnation = self.owner_incarnation,
            .operation_generation = self.operation_generation,
            .turn_generation = scratch.turn_generation,
            .parser_generation = parser_seal.generation,
            .parser_absolute_start = completed.source_start_absolute,
            .parser_absolute_end = parser_seal.rx_absolute_next,
            .parser_seal_digest = parser_seal.digest,
            .drain_evidence_addr = @intFromPtr(&scratch.drain_evidence),
            .drain_evidence_digest = scratch.drain_evidence.digest,
            .completed_exception_digest = scratch.drain_evidence.completed_exception_digest,
            .sampled_now_ns = summary.policy.turn.now_ns,
            .authority_generation = authority.generation,
            .authority_seal_digest = self.owner_authority_seal.digest,
            .completed_owner_generation = completed.generation,
            .correlation_generation = self.control_correlation.generation,
            .tx_queue_generation = tx_generation,
            .lifecycle = .prepared,
        };
        verdict.* = .{
            .saved_self_addr = @intFromPtr(verdict),
            .permit_addr = @intFromPtr(permit),
            .storage_addr = @intFromPtr(self),
            .lease_addr = @intFromPtr(lease),
            .owner_incarnation = self.owner_incarnation,
            .operation_generation = self.operation_generation,
            .correlation_generation = self.control_correlation.generation,
            .completed_payload_seal = completed.seal,
            .request_id = completed.request_id,
            .control_kind = completed.control_kind,
            .target = .{
                .stream_id = completed.target_stream_id,
                .controller_generation = completed.expected_controller_generation,
            },
            .authority_generation = authority.generation,
            .authority_seal_digest = self.owner_authority_seal.digest,
            .expectation = completed.expectation,
            .value = decoded,
            .lifecycle = .prepared,
        };
        const pair_digest = controlSemanticPairDigest(permit, verdict);
        permit.pair_digest = pair_digest;
        verdict.pair_digest = pair_digest;
        permit.digest = preparedWholeDrainPermitDigest(permit);
        verdict.permit_digest = permit.digest;
        verdict.digest = preparedControlSemanticVerdictDigest(verdict);
        return .prepared_pair;
    }

    fn preparedControlSemanticPairCurrent(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
    ) bool {
        const permit = &scratch.whole_drain_permit;
        const verdict = &scratch.control_semantic_verdict;
        if (!self.wholeTurnLeaseIdentityValid(lease) or
            scratch.saved_self_addr != @intFromPtr(scratch) or
            scratch.lifecycle != .busy or
            permit.saved_self_addr != @intFromPtr(permit) or
            permit.verdict_addr != @intFromPtr(verdict) or
            verdict.saved_self_addr != @intFromPtr(verdict) or
            verdict.permit_addr != @intFromPtr(permit) or
            permit.storage_addr != @intFromPtr(self) or
            verdict.storage_addr != @intFromPtr(self) or
            permit.lease_addr != @intFromPtr(lease) or
            verdict.lease_addr != @intFromPtr(lease) or
            permit.owner_incarnation != self.owner_incarnation or
            verdict.owner_incarnation != self.owner_incarnation or
            permit.operation_generation != self.operation_generation or
            verdict.operation_generation != self.operation_generation or
            permit.turn_generation != scratch.turn_generation or
            permit.drain_evidence_addr != @intFromPtr(&scratch.drain_evidence) or
            scratch.drain_evidence.lifecycle != .finished or
            scratch.drain_evidence.mode != .completed_control or
            !rxDrainEvidenceSealed(&scratch.drain_evidence) or
            !std.mem.eql(
                u8,
                &permit.drain_evidence_digest,
                &scratch.drain_evidence.digest,
            ) or !std.mem.eql(
            u8,
            &permit.completed_exception_digest,
            &scratch.drain_evidence.completed_exception_digest,
        ) or
            permit.lifecycle != .prepared or
            verdict.lifecycle != .prepared or
            !std.mem.eql(u8, &permit.pair_digest, &verdict.pair_digest) or
            !std.mem.eql(
                u8,
                &permit.pair_digest,
                &controlSemanticPairDigest(permit, verdict),
            ) or !std.mem.eql(
            u8,
            &permit.digest,
            &preparedWholeDrainPermitDigest(permit),
        ) or !std.mem.eql(u8, &verdict.permit_digest, &permit.digest) or
            !std.mem.eql(
                u8,
                &verdict.digest,
                &preparedControlSemanticVerdictDigest(verdict),
            ) or !self.completedControlValid())
            return false;
        if (!self.finishedRxDrainEvidenceCurrentUnderHeldLease(
            lease,
            scratch,
            .completed_control,
        )) return false;
        const completed = switch (self.completed_control) {
            .completed => |*value| value,
            .none, .terminal => return false,
        };
        const client = if (self.owned_client) |*owned| owned else return false;
        const external = switch (client.io_mode) {
            .external => |*state| state,
            .blocking => return false,
        };
        const authority = switch (self.owner_authority) {
            .current => |value| value,
            .empty => return false,
        };
        const projection = self.currentDrainBlockerProjectionForMode(
            .completed_control,
        ) orelse return false;
        return permit.parser_generation == external.rx_provenance.parser_seal.generation and
            permit.parser_absolute_start == completed.source_start_absolute and
            permit.parser_absolute_end == external.rx_provenance.parser_seal.rx_absolute_next and
            permit.parser_absolute_end >= completed.source_end_absolute and
            std.mem.eql(
                u8,
                &permit.parser_seal_digest,
                &external.rx_provenance.parser_seal.digest,
            ) and std.meta.eql(permit.authority_generation, authority.generation) and
            std.meta.eql(verdict.authority_generation, authority.generation) and
            std.mem.eql(
                u8,
                &permit.authority_seal_digest,
                &self.owner_authority_seal.digest,
            ) and std.mem.eql(
            u8,
            &verdict.authority_seal_digest,
            &self.owner_authority_seal.digest,
        ) and permit.completed_owner_generation == completed.generation and
            permit.correlation_generation == self.control_correlation.generation and
            verdict.correlation_generation == self.control_correlation.generation and
            permit.tx_queue_generation == external.tx_queue_generation and
            projection.all_clear and std.mem.eql(
            u8,
            &projection.completed_exception_digest,
            &permit.completed_exception_digest,
        ) and
            std.meta.eql(verdict.completed_payload_seal, completed.seal) and
            verdict.request_id == completed.request_id and
            verdict.control_kind == completed.control_kind and
            verdict.target.stream_id == completed.target_stream_id and
            verdict.target.controller_generation == completed.expected_controller_generation and
            std.meta.eql(verdict.expectation, completed.expectation) and
            client_external_tx.requestFrameProgress(
                external,
                completed.request_id,
                completed.control_wire_len,
            ) == .missing and self.semanticAuthorityMatchesCompleted(completed);
    }

    fn prepareResizeSemanticCommitUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
    ) bool {
        const permit = &scratch.whole_drain_permit;
        const verdict = &scratch.control_semantic_verdict;
        const receipt = &scratch.resize_semantic_commit;
        const take = &scratch.resize_semantic_response_take;
        const frozen = &scratch.resize_semantic_frozen_response;
        const wrapper = &scratch.control_semantic_take;
        if (!self.preparedControlSemanticPairCurrent(lease, scratch) or
            !resizeSemanticDestinationRangesCurrent(self, lease, scratch) or
            !ownerResizeValid(self) or
            verdict.control_kind != .resize or verdict.value != .resize or
            !std.meta.eql(receipt.*, PreparedResizeSemanticCommit{}) or
            !std.meta.eql(wrapper.*, PreparedControlSemanticTake{}) or
            !std.meta.eql(take.*, PreparedControlResponseTake{}) or
            !frozenControlResponsePristine(frozen))
            return false;
        const applied = switch (verdict.value.resize) {
            .applied => |value| value,
            .stale => return false,
        };
        const plan = planResizeSemanticCommit(
            self.owner_resize,
            self.evidence_snapshot.runtime_id,
            verdict.target.stream_id,
            self.evidence_snapshot.stream_id,
            applied,
        );
        if (plan.disposition == .protocol_terminal or
            plan.disposition == .invariant_terminal) return false;
        const completed = switch (self.completed_control) {
            .completed => |*value| value,
            .none, .terminal => return false,
        };
        const client = if (self.owned_client) |*owned| owned else return false;
        const external = switch (client.io_mode) {
            .external => |*state| state,
            .blocking => return false,
        };
        if (!self.prepareControlResponseTakeUnderHeldLease(lease, take))
            return false;
        receipt.* = .{
            .saved_self_addr = @intFromPtr(receipt),
            .storage_addr = @intFromPtr(self),
            .scratch_addr = @intFromPtr(scratch),
            .lease_addr = @intFromPtr(lease),
            .owner_incarnation = self.owner_incarnation,
            .operation_generation = self.operation_generation,
            .turn_generation = scratch.turn_generation,
            .permit_addr = @intFromPtr(permit),
            .permit_digest = permit.digest,
            .verdict_addr = @intFromPtr(verdict),
            .verdict_digest = verdict.digest,
            .completed_owner_digest = completed.owner_digest,
            .correlation_digest = self.control_correlation.digest,
            .authority_seal_digest = self.owner_authority_seal.digest,
            .tx_queue_generation = external.tx_queue_generation,
            .evidence_digest = attachmentEvidenceDigest(self.evidence_snapshot),
            .runtime_id = self.evidence_snapshot.runtime_id,
            .stream_id = self.evidence_snapshot.stream_id,
            .expected_owner_resize_present = self.owner_resize == .current,
            .expected_owner_resize_digest = switch (self.owner_resize) {
                .none => [_]u8{0} ** 32,
                .current => |value| value.seal.digest,
            },
            .applied_cols = applied.cols,
            .applied_rows = applied.rows,
            .applied_generation = applied.resize_generation,
            .applied_changed = applied.changed,
            .disposition = plan.disposition,
            .response_take_addr = @intFromPtr(take),
            .response_take_digest = take.digest,
            .frozen_response_addr = @intFromPtr(frozen),
            .frozen_response_pristine_digest = frozenControlResponsePristineProjectionDigest(frozen),
            .lifecycle = .prepared,
        };
        receipt.digest = preparedResizeSemanticCommitDigest(receipt);
        wrapper.* = .{
            .saved_self_addr = @intFromPtr(wrapper),
            .branch = .{ .resize = .{
                .receipt_addr = @intFromPtr(receipt),
                .receipt_digest = receipt.digest,
            } },
            .lifecycle = .prepared,
        };
        wrapper.digest = preparedControlSemanticTakeDigest(wrapper);
        return true;
    }

    fn preparedResizeSemanticCommitCurrent(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
    ) bool {
        const receipt = &scratch.resize_semantic_commit;
        const wrapper = &scratch.control_semantic_take;
        const verdict = &scratch.control_semantic_verdict;
        const take = &scratch.resize_semantic_response_take;
        const frozen = &scratch.resize_semantic_frozen_response;
        if (!self.preparedControlSemanticPairCurrent(lease, scratch) or
            !resizeSemanticDestinationRangesCurrent(self, lease, scratch) or
            receipt.saved_self_addr != @intFromPtr(receipt) or
            receipt.storage_addr != @intFromPtr(self) or
            receipt.scratch_addr != @intFromPtr(scratch) or
            receipt.lease_addr != @intFromPtr(lease) or
            receipt.owner_incarnation != self.owner_incarnation or
            receipt.operation_generation != self.operation_generation or
            receipt.turn_generation != scratch.turn_generation or
            receipt.permit_addr != @intFromPtr(&scratch.whole_drain_permit) or
            receipt.verdict_addr != @intFromPtr(verdict) or
            !std.mem.eql(u8, &receipt.permit_digest, &scratch.whole_drain_permit.digest) or
            !std.mem.eql(u8, &receipt.verdict_digest, &verdict.digest) or
            receipt.lifecycle != .prepared or
            !std.mem.eql(u8, &receipt.digest, &preparedResizeSemanticCommitDigest(receipt)) or
            wrapper.saved_self_addr != @intFromPtr(wrapper) or
            wrapper.lifecycle != .prepared or wrapper.branch != .resize or
            wrapper.branch.resize.receipt_addr != @intFromPtr(receipt) or
            !std.mem.eql(u8, &wrapper.branch.resize.receipt_digest, &receipt.digest) or
            !std.mem.eql(u8, &wrapper.digest, &preparedControlSemanticTakeDigest(wrapper)) or
            verdict.control_kind != .resize or verdict.value != .resize or
            receipt.runtime_id != self.evidence_snapshot.runtime_id or
            receipt.stream_id != self.evidence_snapshot.stream_id or
            !std.mem.eql(u8, &receipt.evidence_digest, &attachmentEvidenceDigest(self.evidence_snapshot)) or
            receipt.response_take_addr != @intFromPtr(take) or
            !std.mem.eql(u8, &receipt.response_take_digest, &take.digest) or
            receipt.frozen_response_addr != @intFromPtr(frozen) or
            !std.mem.eql(u8, &receipt.frozen_response_pristine_digest, &frozenControlResponsePristineProjectionDigest(frozen)) or
            !self.validateControlResponseTakeUnderHeldLease(lease, take, frozen))
            return false;
        const applied = switch (verdict.value.resize) {
            .applied => |value| value,
            .stale => return false,
        };
        const plan = planResizeSemanticCommit(
            self.owner_resize,
            self.evidence_snapshot.runtime_id,
            verdict.target.stream_id,
            self.evidence_snapshot.stream_id,
            applied,
        );
        const expected_digest = switch (self.owner_resize) {
            .none => [_]u8{0} ** 32,
            .current => |value| value.seal.digest,
        };
        return plan.disposition == receipt.disposition and
            receipt.expected_owner_resize_present == (self.owner_resize == .current) and
            std.mem.eql(u8, &receipt.expected_owner_resize_digest, &expected_digest) and
            receipt.applied_cols == applied.cols and receipt.applied_rows == applied.rows and
            receipt.applied_generation == applied.resize_generation and
            receipt.applied_changed == applied.changed;
    }

    fn consumeResizeSemanticCommitUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
    ) ConsumeResizeSemanticResult {
        if (!self.preparedResizeSemanticCommitCurrent(lease, scratch))
            return .invalid_precommit;
        var response_aggregate_cleanup: external_owner_cleanup.FrozenOwnerCleanupDescriptor = .{};
        var response_aggregate_execution: ?RetainedRxAggregateDestroyExecution = null;
        var response_intent_destroy: external_rx_intent.PreparedDestroy = .{};
        var response_intent: ?*external_rx_intent.ExternalRxIntentHandle = null;
        var response_intent_scratch: ?*anyopaque = null;
        if (!self.prepareCompletedResponseOwnerCleanup(
            &response_aggregate_cleanup,
            &response_aggregate_execution,
            &response_intent_destroy,
            &response_intent,
            &response_intent_scratch,
        )) return .invalid_precommit;
        const response_aggregate_execution_value = response_aggregate_execution orelse
            return .invalid_precommit;
        const response_intent_value = response_intent orelse return .invalid_precommit;
        const response_intent_scratch_value = response_intent_scratch orelse
            return .invalid_precommit;
        var frozen_response_intent: external_rx_intent.FrozenDestroy = undefined;
        var frozen_response_payload = external_inbox_ledger.OwnedPayload.empty(
            scratch.resize_semantic_frozen_response.payload.allocator,
        );
        const receipt = &scratch.resize_semantic_commit;
        self.publishControlResponseTakeUnchecked(
            &scratch.resize_semantic_response_take,
            &scratch.resize_semantic_frozen_response,
        );
        if (receipt.disposition == .publish_new) bindOwnerResize(self, .{
            .runtime_id = receipt.runtime_id,
            .cols = receipt.applied_cols,
            .rows = receipt.applied_rows,
            .resize_generation = receipt.applied_generation,
        });
        if (self.control_correlation.generation != std.math.maxInt(u64))
            self.control_correlation.generation += 1;
        self.control_correlation.state = .idle;
        self.control_correlation.digest = controlCorrelationDigest(&self.control_correlation);
        scratch.whole_drain_permit.lifecycle = .consumed_tombstone;
        scratch.whole_drain_permit.digest = preparedWholeDrainPermitDigest(&scratch.whole_drain_permit);
        scratch.control_semantic_verdict.lifecycle = .consumed_tombstone;
        scratch.control_semantic_verdict.permit_digest = scratch.whole_drain_permit.digest;
        scratch.control_semantic_verdict.digest = preparedControlSemanticVerdictDigest(&scratch.control_semantic_verdict);
        receipt.lifecycle = .consumed_tombstone;
        receipt.digest = preparedResizeSemanticCommitDigest(receipt);
        scratch.control_semantic_take.branch.resize.receipt_digest = receipt.digest;
        scratch.control_semantic_take.lifecycle = .consumed_tombstone;
        scratch.control_semantic_take.digest = preparedControlSemanticTakeDigest(&scratch.control_semantic_take);
        self.commitCompletedResponseOwnerCleanupUnchecked(
            &response_aggregate_cleanup,
            response_aggregate_execution_value,
            response_intent_value,
            response_intent_scratch_value,
            &response_intent_destroy,
            &frozen_response_intent,
        );
        freezeControlResponsePayloadCleanupUnchecked(
            &scratch.resize_semantic_frozen_response,
            &frozen_response_payload,
        );
        const canonical = self.captureResizeSemanticCleanupSnapshot(
            scratch,
            &scratch.resize_semantic_frozen_response,
        );
        _ = external_owner_cleanup.finishCallbackHidden(
            &response_aggregate_cleanup,
        );
        external_rx_intent.finishFrozenDestroy(frozen_response_intent);
        frozen_response_payload.deinit();
        if (self.detectAndRestoreResizeSemanticCleanupDrift(scratch, canonical)) {
            self.callback_quarantine_pending = true;
            self.callback_quarantine_accounted = true;
            latchCrossOwnerQuarantine();
            return .cleaned_with_invariant;
        }
        return .consumed_resize_cleaned;
    }

    fn prepareResyncAckTransitionUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
    ) bool {
        const permit = &scratch.whole_drain_permit;
        const verdict = &scratch.control_semantic_verdict;
        const transition = &scratch.resync_ack_transition;
        const take = &scratch.resync_ack_response_take;
        const frozen = &scratch.resync_ack_frozen_response;
        if (!self.preparedControlSemanticPairCurrent(lease, scratch) or
            !std.meta.eql(transition.*, PreparedResyncAckTransition{}) or
            !std.meta.eql(take.*, PreparedControlResponseTake{}) or
            !frozenControlResponsePristine(frozen) or
            verdict.control_kind != .resync or verdict.value != .resync_ack or
            permit.parser_absolute_end == 0)
            return false;
        const active = switch (self.semantic_state) {
            .active => |value| value,
            else => return false,
        };
        const deadline = client_pump.recoveryDeadline(active) orelse return false;
        const plan = client_pump.planRecoveryTransition(.{
            .state = active,
            .trigger = .resync_ack,
            .control = .response_wait,
            .now_ns = permit.sampled_now_ns,
            .recovery_barrier_absolute = permit.parser_absolute_end,
        });
        if (plan.disposition != .acknowledged) return false;
        const completed = switch (self.completed_control) {
            .completed => |*value| value,
            .none, .terminal => return false,
        };
        const client = if (self.owned_client) |*owned| owned else return false;
        const external = switch (client.io_mode) {
            .external => |*state| state,
            .blocking => return false,
        };
        const authority = switch (self.owner_authority) {
            .current => |value| value,
            .empty => return false,
        };
        if (!self.prepareControlResponseTakeUnderHeldLease(lease, take))
            return false;
        transition.* = .{
            .saved_self_addr = @intFromPtr(transition),
            .storage_addr = @intFromPtr(self),
            .scratch_addr = @intFromPtr(scratch),
            .lease_addr = @intFromPtr(lease),
            .owner_incarnation = self.owner_incarnation,
            .operation_generation = self.operation_generation,
            .turn_generation = scratch.turn_generation,
            .parser_generation = external.rx_provenance.parser_seal.generation,
            .parser_seal = external.rx_provenance.parser_seal,
            .parser_seal_digest = external.rx_provenance.parser_seal.digest,
            .sampled_now_ns = permit.sampled_now_ns,
            .recovery_deadline_ns = deadline,
            .authority_state = active,
            .authority_generation = authority.generation,
            .authority_seal_digest = self.owner_authority_seal.digest,
            .permit_addr = @intFromPtr(permit),
            .permit_digest = permit.digest,
            .verdict_addr = @intFromPtr(verdict),
            .verdict_digest = verdict.digest,
            .completed_owner_digest = completed.owner_digest,
            .correlation_digest = self.control_correlation.digest,
            .tx_queue_generation = external.tx_queue_generation,
            .recovery_barrier_absolute = permit.parser_absolute_end,
            .next_state = plan.next,
            .response_take_addr = @intFromPtr(take),
            .response_take_digest = take.digest,
            .frozen_response_addr = @intFromPtr(frozen),
            .frozen_response_pristine_digest = frozenControlResponsePristineProjectionDigest(frozen),
            .lifecycle = .prepared,
        };
        transition.digest = preparedResyncAckTransitionDigest(transition);
        return true;
    }

    fn preparedResyncAckTransitionCurrent(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        permit: *const PreparedWholeDrainPermit,
        verdict: *const PreparedControlSemanticVerdict,
        transition: *const PreparedResyncAckTransition,
    ) bool {
        if (!self.validateWholeTurnLease(lease) or
            transition.saved_self_addr != @intFromPtr(transition) or
            transition.storage_addr != @intFromPtr(self) or
            transition.lease_addr != @intFromPtr(lease) or
            transition.owner_incarnation != self.owner_incarnation or
            transition.operation_generation != self.operation_generation or
            transition.permit_addr != @intFromPtr(permit) or
            transition.verdict_addr != @intFromPtr(verdict) or
            transition.lifecycle != .prepared or
            !std.mem.eql(u8, &transition.digest, &preparedResyncAckTransitionDigest(transition)))
            return false;
        const take = &scratch.resync_ack_response_take;
        const frozen = &scratch.resync_ack_frozen_response;
        if (transition.scratch_addr != @intFromPtr(scratch) or
            scratch.saved_self_addr != @intFromPtr(scratch) or
            scratch.lifecycle != .busy or
            scratch.turn_generation != transition.turn_generation or
            @intFromPtr(&scratch.whole_drain_permit) != @intFromPtr(permit) or
            @intFromPtr(&scratch.control_semantic_verdict) != @intFromPtr(verdict) or
            @intFromPtr(&scratch.resync_ack_transition) != @intFromPtr(transition) or
            !self.preparedControlSemanticPairCurrent(lease, scratch) or
            !std.mem.eql(u8, &transition.permit_digest, &permit.digest) or
            !std.mem.eql(u8, &transition.verdict_digest, &verdict.digest) or
            verdict.control_kind != .resync or verdict.value != .resync_ack)
            return false;
        const completed = switch (self.completed_control) {
            .completed => |*value| value,
            .none, .terminal => return false,
        };
        const client = if (self.owned_client) |*owned| owned else return false;
        const external = switch (client.io_mode) {
            .external => |*state| state,
            .blocking => return false,
        };
        const authority = switch (self.owner_authority) {
            .current => |value| value,
            .empty => return false,
        };
        const active = switch (self.semantic_state) {
            .active => |value| value,
            else => return false,
        };
        const plan = client_pump.planRecoveryTransition(.{
            .state = active,
            .trigger = .resync_ack,
            .control = .response_wait,
            .now_ns = transition.sampled_now_ns,
            .recovery_barrier_absolute = transition.recovery_barrier_absolute,
        });
        return transition.parser_generation == external.rx_provenance.parser_seal.generation and
            std.meta.eql(transition.parser_seal, external.rx_provenance.parser_seal) and
            std.mem.eql(u8, &transition.parser_seal_digest, &external.rx_provenance.parser_seal.digest) and
            transition.sampled_now_ns == permit.sampled_now_ns and
            transition.recovery_deadline_ns == (client_pump.recoveryDeadline(active) orelse
                return false) and
            std.meta.eql(transition.authority_state, active) and
            std.meta.eql(transition.authority_generation, authority.generation) and
            std.mem.eql(u8, &transition.authority_seal_digest, &self.owner_authority_seal.digest) and
            std.mem.eql(u8, &transition.completed_owner_digest, &completed.owner_digest) and
            std.mem.eql(u8, &transition.correlation_digest, &self.control_correlation.digest) and
            transition.tx_queue_generation == external.tx_queue_generation and
            transition.recovery_barrier_absolute == permit.parser_absolute_end and
            plan.disposition == .acknowledged and std.meta.eql(transition.next_state, plan.next) and
            transition.response_take_addr == @intFromPtr(take) and
            std.mem.eql(u8, &transition.response_take_digest, &take.digest) and
            transition.frozen_response_addr == @intFromPtr(frozen) and
            std.mem.eql(
                u8,
                &transition.frozen_response_pristine_digest,
                &frozenControlResponsePristineProjectionDigest(frozen),
            ) and self.validateControlResponseTakeUnderHeldLease(lease, take, frozen);
    }

    fn consumeResyncAckUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        permit: *PreparedWholeDrainPermit,
        verdict: *PreparedControlSemanticVerdict,
        transition: *PreparedResyncAckTransition,
    ) ConsumeResyncAckResult {
        if (!self.preparedResyncAckTransitionCurrent(
            lease,
            scratch,
            permit,
            verdict,
            transition,
        )) return .invalid;
        self.publishResyncAckUnchecked(scratch, permit, verdict, transition);
        return .consumed;
    }

    fn publishResyncAckUnchecked(
        self: *ExternalPumpStorage,
        scratch: *ExternalRxTurnScratch,
        permit: *PreparedWholeDrainPermit,
        verdict: *PreparedControlSemanticVerdict,
        transition: *PreparedResyncAckTransition,
    ) void {
        const take = &scratch.resync_ack_response_take;
        const frozen = &scratch.resync_ack_frozen_response;
        self.publishControlResponseTakeUnchecked(take, frozen);
        self.semantic_state = .{ .active = transition.next_state };
        // A response already accepted at max generation must still retire exactly once.  The
        // following admission is what reports exhaustion; wrapping here would reopen an ABA slot.
        if (self.control_correlation.generation != std.math.maxInt(u64))
            self.control_correlation.generation += 1;
        self.control_correlation.state = .idle;
        self.control_correlation.digest = controlCorrelationDigest(&self.control_correlation);
        permit.lifecycle = .consumed_tombstone;
        permit.digest = preparedWholeDrainPermitDigest(permit);
        verdict.lifecycle = .consumed_tombstone;
        verdict.permit_digest = permit.digest;
        verdict.digest = preparedControlSemanticVerdictDigest(verdict);
        transition.lifecycle = .consumed_tombstone;
        transition.digest = preparedResyncAckTransitionDigest(transition);
    }

    fn prepareResyncSemanticCommitUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        aggregate: ?*const PreparedRxAggregate,
    ) bool {
        const receipt = &scratch.resync_semantic_commit;
        const wrapper = &scratch.control_semantic_take;
        if (!resyncSemanticDestinationRangesCurrent(self, lease, scratch, aggregate) or
            !std.meta.eql(receipt.*, PreparedResyncSemanticCommit{}) or
            !std.meta.eql(wrapper.*, PreparedControlSemanticTake{}) or
            !std.meta.eql(
                scratch.projected_recovery_snapshot_commit,
                ProjectedRecoverySnapshotCommit{},
            )) return false;
        if (!self.prepareResyncAckTransitionUnderHeldLease(lease, scratch))
            return false;
        const transition = &scratch.resync_ack_transition;
        var candidate: ProjectedRecoverySnapshotCommit = .{};
        if (!self.prepareRecoverySnapshotCommitForProjectedAckUnderHeldLease(
            lease,
            scratch,
            transition,
            aggregate,
            &candidate,
        )) return false;
        receipt.* = .{
            .saved_self_addr = @intFromPtr(receipt),
            .storage_addr = @intFromPtr(self),
            .scratch_addr = @intFromPtr(scratch),
            .lease_addr = @intFromPtr(lease),
            .ack_transition_addr = @intFromPtr(transition),
            .ack_transition_digest = transition.digest,
            .projected_state_digest = candidate.projected_state_digest,
            .projected_commit_addr = @intFromPtr(
                &scratch.projected_recovery_snapshot_commit,
            ),
            .projected_commit_digest = candidate.digest,
            .aggregate_present = aggregate != null,
            .aggregate_addr = if (aggregate) |value| @intFromPtr(value) else 0,
            .aggregate_digest = if (aggregate) |value| value.digest else [_]u8{0} ** 32,
            .lifecycle = .prepared,
        };
        receipt.digest = preparedResyncSemanticCommitDigest(receipt);
        wrapper.* = .{
            .saved_self_addr = @intFromPtr(wrapper),
            .branch = .{ .resync = .{
                .receipt_addr = @intFromPtr(receipt),
                .receipt_digest = receipt.digest,
            } },
            .lifecycle = .prepared,
        };
        wrapper.digest = preparedControlSemanticTakeDigest(wrapper);
        return true;
    }

    fn preparedResyncSemanticCommitCurrent(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        aggregate: ?*const PreparedRxAggregate,
        candidate: *ProjectedRecoverySnapshotCommit,
    ) bool {
        const receipt = &scratch.resync_semantic_commit;
        const wrapper = &scratch.control_semantic_take;
        const transition = &scratch.resync_ack_transition;
        if (!resyncSemanticDestinationRangesCurrent(self, lease, scratch, aggregate) or
            receipt.saved_self_addr != @intFromPtr(receipt) or
            receipt.storage_addr != @intFromPtr(self) or
            receipt.scratch_addr != @intFromPtr(scratch) or
            receipt.lease_addr != @intFromPtr(lease) or
            receipt.ack_transition_addr != @intFromPtr(transition) or
            !std.mem.eql(u8, &receipt.ack_transition_digest, &transition.digest) or
            receipt.projected_commit_addr != @intFromPtr(
                &scratch.projected_recovery_snapshot_commit,
            ) or receipt.aggregate_present != (aggregate != null) or
            receipt.aggregate_addr != (if (aggregate) |value| @intFromPtr(value) else 0) or
            receipt.lifecycle != .prepared or
            !std.mem.eql(u8, &receipt.digest, &preparedResyncSemanticCommitDigest(receipt)) or
            wrapper.saved_self_addr != @intFromPtr(wrapper) or
            wrapper.lifecycle != .prepared or wrapper.branch != .resync or
            wrapper.branch.resync.receipt_addr != @intFromPtr(receipt) or
            !std.mem.eql(u8, &wrapper.branch.resync.receipt_digest, &receipt.digest) or
            !std.mem.eql(u8, &wrapper.digest, &preparedControlSemanticTakeDigest(wrapper)))
            return false;
        if (aggregate) |value| {
            if (!std.mem.eql(u8, &receipt.aggregate_digest, &value.digest)) return false;
        } else if (!std.mem.allEqual(u8, &receipt.aggregate_digest, 0)) return false;
        candidate.* = .{};
        if (!self.prepareRecoverySnapshotCommitForProjectedAckUnderHeldLease(
            lease,
            scratch,
            transition,
            aggregate,
            candidate,
        ) or !std.mem.eql(
            u8,
            &receipt.projected_state_digest,
            &candidate.projected_state_digest,
        ) or !std.mem.eql(
            u8,
            &receipt.projected_commit_digest,
            &candidate.digest,
        )) return false;
        return self.validatePreparedRecoverySnapshotForProjectedAckUnderHeldLease(
            lease,
            scratch,
            transition,
            aggregate,
            candidate,
        );
    }

    fn consumeResyncSemanticCommitUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        aggregate: ?*PreparedRxAggregate,
    ) ConsumeResyncSemanticResult {
        var candidate: ProjectedRecoverySnapshotCommit = .{};
        if (!self.preparedResyncSemanticCommitCurrent(
            lease,
            scratch,
            aggregate,
            &candidate,
        )) return .invalid_precommit;
        // Resolve the already-validated source pointer before the first publication write. The
        // unchecked suffix receives this exact pointer and performs no raw-address lookup.
        const source_intent: ?*external_rx_intent.ExternalRxIntentHandle = if (aggregate) |value|
            @ptrFromInt(value.intent_handle_addr)
        else
            null;
        var response_aggregate_cleanup: external_owner_cleanup.FrozenOwnerCleanupDescriptor = .{};
        var response_aggregate_execution: ?RetainedRxAggregateDestroyExecution = null;
        var response_intent_destroy: external_rx_intent.PreparedDestroy = .{};
        var response_intent: ?*external_rx_intent.ExternalRxIntentHandle = null;
        var response_intent_scratch: ?*anyopaque = null;
        if (!self.prepareCompletedResponseOwnerCleanup(
            &response_aggregate_cleanup,
            &response_aggregate_execution,
            &response_intent_destroy,
            &response_intent,
            &response_intent_scratch,
        )) return .invalid_precommit;
        const response_aggregate_execution_value = response_aggregate_execution orelse
            return .invalid_precommit;
        const response_intent_value = response_intent orelse return .invalid_precommit;
        const response_intent_scratch_value = response_intent_scratch orelse
            return .invalid_precommit;
        var frozen_response_intent: external_rx_intent.FrozenDestroy = undefined;
        var frozen_response_payload = external_inbox_ledger.OwnedPayload.empty(
            scratch.resync_ack_frozen_response.payload.allocator,
        );
        // MARU_F3C2_POST_FIRST_WRITE_BEGIN
        scratch.projected_recovery_snapshot_commit = candidate;
        self.publishResyncAckUnchecked(
            scratch,
            &scratch.whole_drain_permit,
            &scratch.control_semantic_verdict,
            &scratch.resync_ack_transition,
        );
        if (aggregate) |value| {
            self.consumeProjectedRecoverySnapshotUnchecked(
                &scratch.projected_recovery_snapshot_commit,
                value,
                source_intent.?,
            );
        }
        scratch.projected_recovery_snapshot_commit.lifecycle = .consumed_tombstone;
        scratch.projected_recovery_snapshot_commit.digest =
            projectedRecoverySnapshotCommitDigest(
                &scratch.projected_recovery_snapshot_commit,
            );
        scratch.resync_semantic_commit.projected_commit_digest =
            scratch.projected_recovery_snapshot_commit.digest;
        scratch.resync_semantic_commit.ack_transition_digest =
            scratch.resync_ack_transition.digest;
        scratch.resync_semantic_commit.lifecycle = .consumed_tombstone;
        scratch.resync_semantic_commit.digest = preparedResyncSemanticCommitDigest(
            &scratch.resync_semantic_commit,
        );
        scratch.control_semantic_take.branch.resync.receipt_digest =
            scratch.resync_semantic_commit.digest;
        scratch.control_semantic_take.lifecycle = .consumed_tombstone;
        scratch.control_semantic_take.digest = preparedControlSemanticTakeDigest(
            &scratch.control_semantic_take,
        );
        self.commitCompletedResponseOwnerCleanupUnchecked(
            &response_aggregate_cleanup,
            response_aggregate_execution_value,
            response_intent_value,
            response_intent_scratch_value,
            &response_intent_destroy,
            &frozen_response_intent,
        );
        freezeControlResponsePayloadCleanupUnchecked(
            &scratch.resync_ack_frozen_response,
            &frozen_response_payload,
        );
        // MARU_F3C2_POST_FIRST_WRITE_END
        const canonical = self.captureResyncSemanticCleanupSnapshot(
            scratch,
            aggregate,
            &scratch.resync_ack_frozen_response,
        );
        if (aggregate) |value| _ = value.retirement.retire();
        _ = external_owner_cleanup.finishCallbackHidden(
            &response_aggregate_cleanup,
        );
        external_rx_intent.finishFrozenDestroy(frozen_response_intent);
        frozen_response_payload.deinit();
        if (self.detectResyncSemanticCleanupDrift(scratch, aggregate, canonical)) {
            self.callback_quarantine_pending = true;
            self.callback_quarantine_accounted = true;
            latchCrossOwnerQuarantine();
            return .cleaned_with_invariant;
        }
        return .consumed_resync_cleaned;
    }

    fn preparedControlSemanticTerminalCurrent(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *const ExternalRxTurnScratch,
    ) bool {
        const terminal = &scratch.control_semantic_terminal;
        if (!self.validateWholeTurnLease(lease) or
            terminal.saved_self_addr != @intFromPtr(terminal) or
            terminal.storage_addr != @intFromPtr(self) or
            terminal.lease_addr != @intFromPtr(lease) or
            terminal.owner_incarnation != self.owner_incarnation or
            terminal.operation_generation != self.operation_generation or
            terminal.lifecycle != .prepared or
            !std.mem.eql(
                u8,
                &terminal.digest,
                &preparedControlSemanticTerminalDigest(terminal),
            ) or !std.meta.eql(
            scratch.whole_drain_permit,
            PreparedWholeDrainPermit{},
        ) or !std.meta.eql(
            scratch.control_semantic_verdict,
            PreparedControlSemanticVerdict{},
        ) or !self.completedControlValid())
            return false;
        const completed = switch (self.completed_control) {
            .completed => |*value| value,
            .none, .terminal => return false,
        };
        return terminal.completed_owner_generation == completed.generation and
            terminal.correlation_generation == self.control_correlation.generation and
            terminal.request_id == completed.request_id and
            std.meta.eql(terminal.completed_payload_seal, completed.seal);
    }

    fn prepareControlSemanticTerminalBindingUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
    ) bool {
        const terminal = &scratch.control_semantic_terminal;
        const binding = &scratch.control_semantic_terminal_binding;
        const take = &scratch.control_terminal_response_take;
        const frozen = &scratch.control_terminal_frozen_response;
        if (!self.preparedControlSemanticTerminalCurrent(lease, scratch) or
            !std.meta.eql(binding.*, PreparedControlSemanticTerminalBinding{}) or
            !std.meta.eql(take.*, PreparedControlResponseTake{}) or
            !frozenControlResponsePristine(frozen))
            return false;
        const completed = switch (self.completed_control) {
            .completed => |*value| value,
            .none, .terminal => return false,
        };
        const client = if (self.owned_client) |*owned| owned else return false;
        const external = switch (client.io_mode) {
            .external => |*state| state,
            .blocking => return false,
        };
        const authority = switch (self.owner_authority) {
            .current => |value| value,
            .empty => return false,
        };
        if (!self.finishedRxDrainEvidenceCurrentUnderHeldLease(
            lease,
            scratch,
            .completed_control,
        ) or !self.semanticAuthorityMatchesCompleted(completed) or
            !client_external_mode.parserSealValid(external, &client.parser) or
            controlRequestFrameMissing(
                external,
                completed.request_id,
                completed.control_wire_len,
            ) == false)
            return false;
        if (!self.prepareControlResponseTakeUnderHeldLease(lease, take))
            return false;
        binding.* = .{
            .saved_self_addr = @intFromPtr(binding),
            .storage_addr = @intFromPtr(self),
            .lease_addr = @intFromPtr(lease),
            .owner_incarnation = self.owner_incarnation,
            .operation_generation = self.operation_generation,
            .scratch_addr = @intFromPtr(scratch),
            .scratch_len = @sizeOf(ExternalRxTurnScratch),
            .turn_generation = scratch.turn_generation,
            .terminal_addr = @intFromPtr(terminal),
            .terminal_digest = terminal.digest,
            .completed_owner_digest = completed.owner_digest,
            .correlation_digest = self.control_correlation.digest,
            .parser_seal = external.rx_provenance.parser_seal,
            .drain_evidence_addr = @intFromPtr(&scratch.drain_evidence),
            .drain_evidence_digest = scratch.drain_evidence.digest,
            .completed_exception_digest = scratch.drain_evidence.completed_exception_digest,
            .authority_generation = authority.generation,
            .authority_seal_digest = self.owner_authority_seal.digest,
            .tx_queue_generation = external.tx_queue_generation,
            .response_take_addr = @intFromPtr(take),
            .response_take_digest = take.digest,
            .frozen_response_addr = @intFromPtr(frozen),
            .frozen_response_pristine_digest = frozenControlResponsePristineProjectionDigest(frozen),
            .lifecycle = .prepared,
        };
        binding.digest = preparedControlSemanticTerminalBindingDigest(binding);
        return true;
    }

    fn preparedControlSemanticTerminalBindingCurrent(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
    ) bool {
        const terminal = &scratch.control_semantic_terminal;
        const binding = &scratch.control_semantic_terminal_binding;
        const take = &scratch.control_terminal_response_take;
        const frozen = &scratch.control_terminal_frozen_response;
        const completed = switch (self.completed_control) {
            .completed => |*value| value,
            .none, .terminal => return false,
        };
        const client = if (self.owned_client) |*owned| owned else return false;
        const external = switch (client.io_mode) {
            .external => |*state| state,
            .blocking => return false,
        };
        const authority = switch (self.owner_authority) {
            .current => |value| value,
            .empty => return false,
        };
        return self.preparedControlSemanticTerminalCurrent(lease, scratch) and
            binding.saved_self_addr == @intFromPtr(binding) and
            binding.storage_addr == @intFromPtr(self) and
            binding.lease_addr == @intFromPtr(lease) and
            binding.owner_incarnation == self.owner_incarnation and
            binding.operation_generation == self.operation_generation and
            binding.scratch_addr == @intFromPtr(scratch) and
            binding.scratch_len == @sizeOf(ExternalRxTurnScratch) and
            terminalBindingDestinationRangesCurrent(scratch) and
            binding.turn_generation == scratch.turn_generation and
            binding.terminal_addr == @intFromPtr(terminal) and
            std.mem.eql(u8, &binding.terminal_digest, &terminal.digest) and
            std.mem.eql(u8, &binding.completed_owner_digest, &completed.owner_digest) and
            std.mem.eql(u8, &binding.correlation_digest, &self.control_correlation.digest) and
            std.meta.eql(binding.parser_seal, external.rx_provenance.parser_seal) and
            client_external_mode.parserSealValid(external, &client.parser) and
            binding.drain_evidence_addr == @intFromPtr(&scratch.drain_evidence) and
            std.mem.eql(u8, &binding.drain_evidence_digest, &scratch.drain_evidence.digest) and
            std.mem.eql(
                u8,
                &binding.completed_exception_digest,
                &scratch.drain_evidence.completed_exception_digest,
            ) and self.finishedRxDrainEvidenceCurrentUnderHeldLease(
            lease,
            scratch,
            .completed_control,
        ) and std.meta.eql(binding.authority_generation, authority.generation) and
            std.mem.eql(u8, &binding.authority_seal_digest, &self.owner_authority_seal.digest) and
            binding.tx_queue_generation == external.tx_queue_generation and
            self.semanticAuthorityMatchesCompleted(completed) and
            controlRequestFrameMissing(
                external,
                completed.request_id,
                completed.control_wire_len,
            ) and
            binding.response_take_addr == @intFromPtr(take) and
            std.mem.eql(u8, &binding.response_take_digest, &take.digest) and
            binding.frozen_response_addr == @intFromPtr(frozen) and
            std.mem.eql(
                u8,
                &binding.frozen_response_pristine_digest,
                &frozenControlResponsePristineProjectionDigest(frozen),
            ) and
            binding.lifecycle == .prepared and
            std.mem.eql(
                u8,
                &binding.digest,
                &preparedControlSemanticTerminalBindingDigest(binding),
            ) and self.validateControlResponseTakeUnderHeldLease(
            lease,
            take,
            frozen,
        );
    }

    fn consumeControlSemanticTerminalUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
    ) ConsumeControlSemanticTerminalResult {
        if (!self.preparedControlSemanticTerminalBindingCurrent(
            lease,
            scratch,
        ))
            return .invalid_precommit;
        const terminal = &scratch.control_semantic_terminal;
        const binding = &scratch.control_semantic_terminal_binding;
        const take = &scratch.control_terminal_response_take;
        const frozen = &scratch.control_terminal_frozen_response;
        const reason = terminal.reason;

        self.publishControlResponseTakeUnchecked(take, frozen);
        if (self.control_correlation.generation != std.math.maxInt(u64))
            self.control_correlation.generation += 1;
        self.control_correlation.state = .terminal;
        self.control_correlation.digest = controlCorrelationDigest(&self.control_correlation);
        self.semantic_state = .{ .terminal = .{
            .reason = reason,
            .fd_disposition = .owner_cleanup,
        } };
        terminal.lifecycle = .consumed_tombstone;
        terminal.digest = preparedControlSemanticTerminalDigest(terminal);
        binding.lifecycle = .consumed_tombstone;
        binding.digest = preparedControlSemanticTerminalBindingDigest(binding);

        const canonical = self.captureControlSemanticTerminalCleanupSnapshot(
            scratch,
            frozen,
        );
        finishControlResponsePayloadCleanupUnchecked(frozen);
        if (self.detectAndRestoreControlSemanticTerminalCleanupDrift(
            scratch,
            canonical,
        )) {
            latchCrossOwnerQuarantine();
            return .cleaned_with_invariant;
        }
        return .consumed_cleaned;
    }

    fn prepareControlResponseTake(
        self: *ExternalPumpStorage,
        out: *PreparedControlResponseTake,
    ) bool {
        if (active_external_operation_addr != 0 or
            !std.meta.eql(out.*, PreparedControlResponseTake{}) or
            !self.completedControlValid() or
            self.operation_generation == std.math.maxInt(u64))
            return false;
        const completed = switch (self.completed_control) {
            .completed => |*value| value,
            .none, .terminal => return false,
        };
        const correlation = switch (self.control_correlation.state) {
            .completed => |value| value,
            .idle, .in_flight, .terminal => return false,
        };
        if (completed.request_id != correlation.request_id or
            completed.correlation_generation !=
                self.control_correlation.generation)
            return false;
        out.* = .{
            .saved_self_addr = @intFromPtr(out),
            .storage_addr = @intFromPtr(self),
            .lease_addr = 0,
            .owner_incarnation = self.owner_incarnation,
            .operation_generation = self.operation_generation + 1,
            .completed_generation = self.completed_control_generation,
            .correlation_generation = self.control_correlation.generation,
            .request_id = completed.request_id,
            .owner_digest = completed.owner_digest,
            .payload_seal = completed.seal,
            .lifecycle = .prepared,
        };
        out.digest = preparedControlResponseTakeDigest(out);
        return true;
    }

    fn prepareControlResponseTakeUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        out: *PreparedControlResponseTake,
    ) bool {
        if (!self.validateWholeTurnLease(lease) or
            !std.meta.eql(out.*, PreparedControlResponseTake{}) or
            !self.completedControlValid())
            return false;
        const completed = switch (self.completed_control) {
            .completed => |*value| value,
            .none, .terminal => return false,
        };
        const correlation = switch (self.control_correlation.state) {
            .completed => |value| value,
            .idle, .in_flight, .terminal => return false,
        };
        if (completed.request_id != correlation.request_id or
            completed.correlation_generation != self.control_correlation.generation)
            return false;
        out.* = .{
            .saved_self_addr = @intFromPtr(out),
            .storage_addr = @intFromPtr(self),
            .lease_addr = @intFromPtr(lease),
            .owner_incarnation = self.owner_incarnation,
            .operation_generation = self.operation_generation,
            .completed_generation = self.completed_control_generation,
            .correlation_generation = self.control_correlation.generation,
            .request_id = completed.request_id,
            .owner_digest = completed.owner_digest,
            .payload_seal = completed.seal,
            .lifecycle = .prepared,
        };
        out.digest = preparedControlResponseTakeDigest(out);
        return true;
    }

    fn validateControlResponseTakeUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        take: *const PreparedControlResponseTake,
        out: *const FrozenControlResponse,
    ) bool {
        if (!self.validateWholeTurnLease(lease) or
            take.saved_self_addr != @intFromPtr(take) or
            take.storage_addr != @intFromPtr(self) or
            (take.lease_addr != 0 and take.lease_addr != @intFromPtr(lease)) or
            take.owner_incarnation != self.owner_incarnation or
            take.operation_generation != self.operation_generation or
            take.completed_generation != self.completed_control_generation or
            take.correlation_generation != self.control_correlation.generation or
            take.lifecycle != .prepared or
            !std.mem.eql(u8, &take.digest, &preparedControlResponseTakeDigest(take)) or
            out.saved_self_addr != 0 or out.storage_addr != 0 or
            out.owner_incarnation != 0 or out.correlation_generation != 0 or
            out.target_stream_id != 0 or
            out.expected_controller_generation != 0 or
            out.request_id != 0 or out.wire_len != 0 or
            out.payload.allocation_ptr != null or out.payload.logical_len != 0 or
            !std.meta.eql(out.payload_seal, ResponsePayloadSeal.empty()) or
            out.lifecycle != .empty or
            !std.mem.allEqual(u8, &out.digest, 0) or
            !self.completedControlValid())
            return false;
        const completed = switch (self.completed_control) {
            .completed => |*value| value,
            .none, .terminal => return false,
        };
        const correlation = switch (self.control_correlation.state) {
            .completed => |value| value,
            .idle, .in_flight, .terminal => return false,
        };
        return take.request_id == completed.request_id and
            take.request_id == correlation.request_id and
            std.mem.eql(u8, &take.owner_digest, &completed.owner_digest) and
            std.meta.eql(take.payload_seal, completed.seal);
    }

    fn publishControlResponseTakeUnchecked(
        self: *ExternalPumpStorage,
        take: *PreparedControlResponseTake,
        out: *FrozenControlResponse,
    ) void {
        self.publishCompletedControlResponseUnchecked(out);
        take.lifecycle = .consumed_tombstone;
        take.digest = preparedControlResponseTakeDigest(take);
    }

    fn publishCompletedControlResponseUnchecked(
        self: *ExternalPumpStorage,
        out: *FrozenControlResponse,
    ) void {
        const completed = self.completed_control.completed;
        out.* = .{
            .saved_self_addr = @intFromPtr(out),
            .storage_addr = @intFromPtr(self),
            .owner_incarnation = self.owner_incarnation,
            .correlation_generation = self.control_correlation.generation,
            .kind = completed.control_kind,
            .expectation = completed.expectation,
            .target_stream_id = completed.target_stream_id,
            .expected_controller_generation = completed.expected_controller_generation,
            .request_id = completed.request_id,
            .wire_len = completed.control_wire_len,
            .payload = completed.payload,
            .payload_seal = completed.seal,
            .lifecycle = .owned,
        };
        out.digest = frozenControlResponseDigest(out);
        self.completed_control = .none;
    }

    fn commitControlResponseTakeUncheckedUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        take: *PreparedControlResponseTake,
        out: *FrozenControlResponse,
    ) bool {
        if (!self.validateControlResponseTakeUnderHeldLease(
            lease,
            take,
            out,
        ))
            return false;
        self.publishControlResponseTakeUnchecked(take, out);
        return true;
    }

    fn finishControlResponseUncheckedUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        response: *FrozenControlResponse,
    ) FinishControlResponseResult {
        if (!self.validateWholeTurnLease(lease) or
            response.saved_self_addr != @intFromPtr(response) or
            response.storage_addr != @intFromPtr(self) or
            response.owner_incarnation != self.owner_incarnation or
            response.correlation_generation !=
                self.control_correlation.generation or
            response.lifecycle != .owned or
            !response.payload_seal.validatesPayload(&response.payload) or
            !std.mem.eql(
                u8,
                &response.digest,
                &frozenControlResponseDigest(response),
            ) or self.completed_control != .none or
            self.control_correlation.generation == std.math.maxInt(u64))
            return .invalid;
        const completed = switch (self.control_correlation.state) {
            .completed => |value| value,
            .idle, .in_flight, .terminal => return .invalid,
        };
        if (response.kind != completed.kind or
            !std.meta.eql(response.expectation, completed.expectation) or
            response.target_stream_id != completed.target.stream_id or
            response.expected_controller_generation !=
                completed.target.controller_generation or
            response.request_id != completed.request_id or
            response.wire_len != completed.wire_len)
            return .invalid;
        finishControlResponsePayloadCleanupUnchecked(response);
        self.control_correlation.generation += 1;
        self.control_correlation.state = .terminal;
        self.control_correlation.digest =
            controlCorrelationDigest(&self.control_correlation);
        self.semantic_state = .{ .terminal = .{
            .reason = .protocol_error,
            .fd_disposition = .owner_cleanup,
        } };
        return .rejected_terminal;
    }

    fn finishControlResponsePayloadCleanupUnchecked(
        response: *FrozenControlResponse,
    ) void {
        var payload = external_inbox_ledger.OwnedPayload.empty(
            response.payload.allocator,
        );
        freezeControlResponsePayloadCleanupUnchecked(response, &payload);
        payload.deinit();
    }

    fn freezeControlResponsePayloadCleanupUnchecked(
        response: *FrozenControlResponse,
        payload: *external_inbox_ledger.OwnedPayload,
    ) void {
        payload.* = response.payload;
        response.payload = external_inbox_ledger.OwnedPayload.empty(
            payload.allocator,
        );
        response.lifecycle = .cleaned_tombstone;
        response.digest = frozenControlResponseDigest(response);
    }

    /// f2 keeps the frozen payload owner inside this call and can only reject-terminal after
    /// exact cleanup. f3 supplies the separate typed success verdict and drain permit.
    fn takeControlResponseUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        take: *PreparedControlResponseTake,
    ) FinishControlResponseResult {
        var frozen: FrozenControlResponse = .{};
        if (!self.commitControlResponseTakeUncheckedUnderHeldLease(
            lease,
            take,
            &frozen,
        )) return .invalid_commit;
        const finished = self.finishControlResponseUncheckedUnderHeldLease(
            lease,
            &frozen,
        );
        return if (finished == .invalid) .invalid_finish else finished;
    }

    fn liveOwnersValid(self: *const ExternalPumpStorage) bool {
        return self.livePartialValid() and self.liveScreenValid() and
            self.completedControlValid();
    }

    fn intentScratchReservationValid(
        self: *const ExternalPumpStorage,
    ) bool {
        const reservation = self.intent_scratch_reservation;
        return switch (reservation.lifecycle) {
            .empty => reservation.storage_addr == 0 and
                reservation.handle_addr == 0 and reservation.generation == 0 and
                std.mem.allEqual(u8, &reservation.digest, 0),
            .active, .destroying => reservation.storage_addr ==
                @intFromPtr(self) and
                reservation.handle_addr != 0 and
                reservation.generation != 0 and
                reservation.generation == self.intent_scratch_generation and
                std.mem.eql(
                    u8,
                    &reservation.digest,
                    &intentScratchReservationDigest(reservation),
                ),
            .poisoned_tombstone => reservation.storage_addr == 0 and
                reservation.handle_addr == 0,
        };
    }

    fn createIntentScratch(
        self: *ExternalPumpStorage,
        handle: *external_rx_intent.ExternalRxIntentHandle,
        allocator: std.mem.Allocator,
        authority_ops: external_rx_intent.AuthorityOps,
    ) external_rx_intent.CreateResult {
        if (self.lifecycle != .live or
            !self.intentScratchReservationValid() or
            self.intent_scratch_reservation.lifecycle != .empty or
            self.intent_scratch_generation == std.math.maxInt(u64))
            return .authority_drift;
        const result = external_rx_intent.allocate(
            handle,
            allocator,
            authority_ops,
        );
        if (result != .allocated) {
            if (result == .quarantined) {
                self.intent_scratch_reservation = .{
                    .lifecycle = .poisoned_tombstone,
                };
                self.semantic_state = .{ .terminal = .{
                    .reason = .invariant_failure,
                    .fd_disposition = .owner_cleanup,
                } };
                latchCrossOwnerQuarantine();
            }
            return result;
        }
        const current = authority_ops.current(authority_ops.context) orelse {
            _ = external_rx_intent.discardAllocated(handle);
            return .authority_drift;
        };
        if (current.storage_addr != @intFromPtr(self) or
            current.storage_len != @sizeOf(ExternalPumpStorage) or
            current.operation_generation != self.operation_generation or
            current.reservation_handle_addr != 0 or
            current.reservation_generation != 0)
        {
            _ = external_rx_intent.discardAllocated(handle);
            return .authority_drift;
        }
        const generation = self.intent_scratch_generation + 1;
        var reservation = IntentScratchReservation{
            .storage_addr = @intFromPtr(self),
            .handle_addr = @intFromPtr(handle),
            .generation = generation,
            .lifecycle = .active,
        };
        reservation.digest = intentScratchReservationDigest(reservation);
        self.intent_scratch_generation = generation;
        self.intent_scratch_reservation = reservation;
        var bound = current;
        bound.reservation_handle_addr = @intFromPtr(handle);
        bound.reservation_generation = generation;
        if (external_rx_intent.bindReservation(handle, bound) != .bound) {
            self.intent_scratch_reservation = .{};
            self.intent_scratch_generation -= 1;
            _ = external_rx_intent.discardAllocated(handle);
            return .authority_drift;
        }
        return .allocated;
    }

    fn rxAggregateReservationValid(
        self: *const ExternalPumpStorage,
    ) bool {
        const reservation = self.rx_aggregate_reservation;
        return switch (reservation.lifecycle) {
            .empty => reservation.storage_addr == 0 and
                reservation.handle_addr == 0 and
                reservation.aggregate_addr == 0 and
                reservation.turn_generation == 0 and
                reservation.generation == 0 and
                std.mem.allEqual(u8, &reservation.digest, 0),
            .active, .destroying => reservation.storage_addr ==
                @intFromPtr(self) and
                reservation.handle_addr == @intFromPtr(&self.rx_aggregate_handle) and
                reservation.aggregate_addr != 0 and
                reservation.turn_generation == self.operation_generation and
                reservation.generation != 0 and
                reservation.generation == self.rx_aggregate_generation and
                std.mem.eql(
                    u8,
                    &reservation.digest,
                    &rxAggregateReservationDigest(reservation),
                ),
            .poisoned_tombstone => reservation.storage_addr == 0 and
                reservation.handle_addr == 0 and
                reservation.aggregate_addr == 0,
        };
    }

    fn validateReadyRxAggregate(
        self: *const ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
    ) ?*PreparedRxAggregate {
        if (external_owner_cleanup.callbackActive() or
            !self.validateWholeTurnLease(lease) or
            !self.intentScratchReservationValid() or
            self.intent_scratch_reservation.lifecycle != .active or
            !self.rxAggregateReservationValid() or
            self.rx_aggregate_reservation.lifecycle != .active)
            return null;
        const handle = &self.rx_aggregate_handle;
        if (handle.saved_self_addr != @intFromPtr(handle) or
            handle.aggregate_addr != self.rx_aggregate_reservation.aggregate_addr or
            handle.allocation_len != @sizeOf(PreparedRxAggregate) or
            handle.storage_addr != @intFromPtr(self) or
            handle.turn_generation != self.operation_generation or
            handle.reservation_generation != self.rx_aggregate_reservation.generation or
            handle.lifecycle != .active or
            @intFromPtr(handle.allocator.ptr) != handle.allocator_ptr_addr or
            @intFromPtr(handle.allocator.vtable) != handle.allocator_vtable_addr or
            !std.mem.eql(
                u8,
                &handle.digest,
                &rxAggregateHandleDigest(handle),
            ))
            return null;
        const aggregate: *PreparedRxAggregate =
            @ptrFromInt(handle.aggregate_addr);
        if (aggregate.saved_self_addr != @intFromPtr(aggregate) or
            aggregate.handle_addr != @intFromPtr(handle) or
            aggregate.storage_addr != @intFromPtr(self) or
            aggregate.turn_generation != self.operation_generation or
            aggregate.intent_handle_addr !=
                self.intent_scratch_reservation.handle_addr or
            aggregate.intent_reservation_generation !=
                self.intent_scratch_reservation.generation or
            (aggregate.lifecycle != .ready and
                aggregate.lifecycle != .preparing and
                aggregate.lifecycle != .finalized) or
            !std.mem.eql(
                u8,
                &aggregate.digest,
                &preparedRxAggregateDigest(aggregate),
            ))
            return null;
        return aggregate;
    }

    fn createRxAggregate(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        intent_handle: *external_rx_intent.ExternalRxIntentHandle,
        allocator: std.mem.Allocator,
        ranges: *external_owner_range.Scratch,
    ) RxAggregateCreateResult {
        if (comptime !builtin.is_test) unreachable;
        return self.createRxAggregateImpl(
            lease,
            intent_handle,
            allocator,
            null,
            0,
            ranges,
        );
    }

    fn createRxAggregateWithAuthority(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        intent_handle: *external_rx_intent.ExternalRxIntentHandle,
        allocator: std.mem.Allocator,
        authority_ops: external_rx_intent.AuthorityOps,
        now_ns: i128,
        ranges: *external_owner_range.Scratch,
    ) RxAggregateCreateResult {
        return self.createRxAggregateImpl(
            lease,
            intent_handle,
            allocator,
            authority_ops,
            now_ns,
            ranges,
        );
    }

    fn createRxAggregateImpl(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        intent_handle: *external_rx_intent.ExternalRxIntentHandle,
        allocator: std.mem.Allocator,
        authority_ops: ?external_rx_intent.AuthorityOps,
        now_ns: i128,
        ranges: *external_owner_range.Scratch,
    ) RxAggregateCreateResult {
        if (external_owner_cleanup.callbackActive() or
            !self.validateWholeTurnLease(lease) or
            !rangeContains(
                lease.scratch_addr,
                lease.scratch_len,
                @intFromPtr(ranges),
                @sizeOf(external_owner_range.Scratch),
            ) or
            !self.intentScratchReservationValid() or
            self.intent_scratch_reservation.lifecycle != .active or
            self.intent_scratch_reservation.handle_addr != @intFromPtr(intent_handle) or
            !self.rxAggregateReservationValid() or
            self.rx_aggregate_reservation.lifecycle != .empty or
            self.rx_aggregate_generation == std.math.maxInt(u64))
            return .invalid_state;
        const retained = retainedRxAggregateValid(self);
        if (!retained and !rxAggregateHandlePristine(&self.rx_aggregate_handle))
            return .invalid_state;
        if (retained and
            (@intFromPtr(allocator.ptr) !=
                self.rx_aggregate_handle.allocator_ptr_addr or
                @intFromPtr(allocator.vtable) !=
                    self.rx_aggregate_handle.allocator_vtable_addr))
            return .invalid_state;
        const operation_generation = self.operation_generation;
        const intent_reservation = self.intent_scratch_reservation;
        const authority_before = if (authority_ops) |ops|
            ops.current(ops.context) orelse return .authority_drift
        else
            null;
        if (authority_before) |view|
            if (@intFromPtr(view.allocator.ptr) !=
                @intFromPtr(allocator.ptr) or
                @intFromPtr(view.allocator.vtable) !=
                    @intFromPtr(allocator.vtable))
                return .authority_drift;
        const inventory_forbidden = [_]external_owner_range.Range{
            .{
                .start = @intFromPtr(self),
                .len = @sizeOf(ExternalPumpStorage),
            },
            .{
                .start = @intFromPtr(lease),
                .len = @sizeOf(ExternalWholeTurnLease),
            },
            .{
                .start = @intFromPtr(ranges),
                .len = @sizeOf(external_owner_range.Scratch),
            },
        };
        ranges.reset();
        external_rx_intent.appendBoundOwnerRanges(
            intent_handle,
            ranges,
        ) catch {
            self.rejectForgedRxAggregateAllocation();
            return .quarantined;
        };
        if (authority_before) |view|
            for (view.forbidden_ranges) |range|
                ranges.append(range.start, range.len) catch {
                    self.rejectForgedRxAggregateAllocation();
                    return .quarantined;
                };
        ranges.validate(&inventory_forbidden) catch {
            self.rejectForgedRxAggregateAllocation();
            return .quarantined;
        };
        for (ranges.ranges[0..ranges.len]) |range| {
            if (rangesOverlap(
                range.start,
                range.len,
                lease.scratch_addr,
                lease.scratch_len,
            ) and !(range.start == @intFromPtr(intent_handle) and
                range.len == @sizeOf(external_rx_intent.ExternalRxIntentHandle)))
            {
                self.rejectForgedRxAggregateAllocation();
                return .quarantined;
            }
        }
        const inventory_digest = external_rx_intent.sealAuthorityRanges(
            ranges.ranges[0..ranges.len],
            operation_generation,
        ) orelse {
            self.rejectForgedRxAggregateAllocation();
            return .quarantined;
        };
        const allocation_len = @sizeOf(PreparedRxAggregate);
        const allocation_addr = if (retained)
            self.rx_aggregate_handle.aggregate_addr
        else
            @intFromPtr(allocator.rawAlloc(
                allocation_len,
                .of(PreparedRxAggregate),
                @returnAddress(),
            ) orelse return .out_of_memory);
        if (!retained and
            (allocation_addr % @alignOf(PreparedRxAggregate) != 0 or
                rangesOverlap(
                    allocation_addr,
                    allocation_len,
                    @intFromPtr(self),
                    @sizeOf(ExternalPumpStorage),
                ) or rangesOverlap(
                allocation_addr,
                allocation_len,
                @intFromPtr(lease),
                @sizeOf(ExternalWholeTurnLease),
            ) or rangesOverlap(
                allocation_addr,
                allocation_len,
                lease.scratch_addr,
                lease.scratch_len,
            ) or rangesOverlap(
                allocation_addr,
                allocation_len,
                @intFromPtr(ranges),
                @sizeOf(external_owner_range.Scratch),
            ) or rangesOverlap(
                allocation_addr,
                allocation_len,
                @intFromPtr(intent_handle),
                @sizeOf(external_rx_intent.ExternalRxIntentHandle),
            )))
        {
            // A hostile allocator returned caller/storage authority. It is not allocator-owned,
            // so quarantine must not call destroy on the forged pointer.
            self.rejectForgedRxAggregateAllocation();
            return .quarantined;
        }
        const aggregate: *PreparedRxAggregate = @ptrFromInt(allocation_addr);
        const authority_after = if (authority_ops) |ops|
            ops.current(ops.context) orelse {
                self.rejectForgedRxAggregateAllocation();
                return .quarantined;
            }
        else
            null;
        ranges.reset();
        external_rx_intent.appendBoundOwnerRanges(
            intent_handle,
            ranges,
        ) catch {
            self.rejectForgedRxAggregateAllocation();
            return .quarantined;
        };
        if (authority_after) |view|
            for (view.forbidden_ranges) |range|
                ranges.append(range.start, range.len) catch {
                    self.rejectForgedRxAggregateAllocation();
                    return .quarantined;
                };
        const forbidden = [_]external_owner_range.Range{
            .{
                .start = @intFromPtr(self),
                .len = @sizeOf(ExternalPumpStorage),
            },
            .{
                .start = @intFromPtr(lease),
                .len = @sizeOf(ExternalWholeTurnLease),
            },
            .{
                .start = @intFromPtr(ranges),
                .len = @sizeOf(external_owner_range.Scratch),
            },
            .{
                .start = allocation_addr,
                .len = allocation_len,
            },
        };
        ranges.validate(&forbidden) catch {
            // The allocation may be an alias of one of the active owners in `ranges`; never free
            // an untrusted overlapping pointer.
            self.rejectForgedRxAggregateAllocation();
            return .quarantined;
        };
        const current_inventory_digest = external_rx_intent.sealAuthorityRanges(
            ranges.ranges[0..ranges.len],
            operation_generation,
        ) orelse {
            self.rejectForgedRxAggregateAllocation();
            return .quarantined;
        };
        if (!std.mem.eql(
            u8,
            &inventory_digest,
            &current_inventory_digest,
        ) or !std.meta.eql(authority_before, authority_after)) {
            self.rejectForgedRxAggregateAllocation();
            return .quarantined;
        }
        if (!self.validateWholeTurnLease(lease) or
            self.operation_generation != operation_generation or
            !std.meta.eql(intent_reservation, self.intent_scratch_reservation) or
            !self.rxAggregateReservationValid() or
            self.rx_aggregate_reservation.lifecycle != .empty or
            (if (retained)
                !retainedRxAggregateValid(self)
            else
                !rxAggregateHandlePristine(&self.rx_aggregate_handle)))
        {
            if (!retained) allocator.rawFree(
                @as([*]u8, @ptrCast(aggregate))[0..allocation_len],
                .of(PreparedRxAggregate),
                @returnAddress(),
            );
            return .authority_drift;
        }
        const generation = self.rx_aggregate_generation + 1;
        aggregate.* = .{
            .saved_self_addr = allocation_addr,
            .handle_addr = @intFromPtr(&self.rx_aggregate_handle),
            .storage_addr = @intFromPtr(self),
            .turn_generation = operation_generation,
            .turn_now_ns = now_ns,
            .intent_handle_addr = @intFromPtr(intent_handle),
            .intent_reservation_generation = intent_reservation.generation,
            .live_batch = .{},
            .live_commit = .{},
            .retirement = .{},
            .dispositions = [_]external_inbox_ledger.LiveCommitDisposition{.unused} **
                external_inbox_ledger.max_live_mutations,
            .screen_transfers = [_]ScreenTransferOwner{.{}} ** external_rx_intent.max_intents,
            .screen_proofs = [_]external_rx_intent.StagedScreenMutationProof{.{}} **
                external_rx_intent.max_intents,
            .neutral_payloads = [_]external_rx_intent.MovedIntentPayload{.{}} **
                external_rx_intent.max_intents,
            .intent_commit = .{},
            .event_retirements = [_]external_rx_intent.PreparedNeutralRetirement{.{}} **
                external_rx_intent.max_intents,
            .event_cleanup = [_]external_owner_cleanup.FrozenOwnerCleanupDescriptor{.{}} **
                external_rx_intent.max_intents,
            .event_reduction = .{},
            .metadata_destination = .{},
            .metadata_summary_expected_digest = [_]u8{0} ** 32,
            .metadata_summary_next_generation = 0,
            .metadata_summary_next = .{},
            .metadata_cleanup_content_digest = [_]u8{0} ** 32,
            .authority_destination = .{},
            .resize_destination = .{},
            .screen_destination = .{},
            .response_destination = .{},
            .recovery_dispositions = .{},
            .recovery_snapshot_commit = .{},
            .recovery_commit_output = .{},
            .recovery_snapshot_binding = .{},
            .destination_writes = [_]FrozenDestinationWrite{.{}} **
                external_rx_intent.max_intents,
            .destination_write_count = 0,
            .lifecycle = .ready,
            .digest = undefined,
        };
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        self.rx_aggregate_handle = .{
            .saved_self_addr = @intFromPtr(&self.rx_aggregate_handle),
            .aggregate_addr = allocation_addr,
            .allocation_len = allocation_len,
            .allocator = allocator,
            .allocator_ptr_addr = @intFromPtr(allocator.ptr),
            .allocator_vtable_addr = @intFromPtr(allocator.vtable),
            .storage_addr = @intFromPtr(self),
            .turn_generation = operation_generation,
            .reservation_generation = generation,
            .lifecycle = .active,
            .digest = undefined,
        };
        self.rx_aggregate_handle.digest =
            rxAggregateHandleDigest(&self.rx_aggregate_handle);
        self.rx_aggregate_reservation = .{
            .storage_addr = @intFromPtr(self),
            .handle_addr = @intFromPtr(&self.rx_aggregate_handle),
            .aggregate_addr = allocation_addr,
            .turn_generation = operation_generation,
            .generation = generation,
            .lifecycle = .active,
            .digest = undefined,
        };
        self.rx_aggregate_reservation.digest =
            rxAggregateReservationDigest(self.rx_aggregate_reservation);
        self.rx_aggregate_generation = generation;
        return .allocated;
    }

    fn retainRxAggregateAllocation(
        self: *ExternalPumpStorage,
        aggregate: *PreparedRxAggregate,
    ) void {
        self.rx_aggregate_handle.lifecycle = .retained;
        self.rx_aggregate_handle.digest =
            rxAggregateHandleDigest(&self.rx_aggregate_handle);
        self.rx_aggregate_reservation = .{};
        _ = aggregate;
    }

    fn moveScreenIntoRxAggregate(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        intent_handle: *external_rx_intent.ExternalRxIntentHandle,
        intent_index: u8,
        authority_ops: external_rx_intent.AuthorityOps,
    ) RxAggregateTransferResult {
        const aggregate = self.validateReadyRxAggregate(lease) orelse
            return .invalid_state;
        if (intent_index >= aggregate.screen_transfers.len)
            return .wrong_intent;
        const transfer = &aggregate.screen_transfers[intent_index];
        if (!screenTransferPristine(transfer))
            return .invalid_state;
        switch (external_rx_intent.moveScreenToNeutral(
            intent_handle,
            intent_index,
            authority_ops,
            @intFromPtr(aggregate),
            @sizeOf(PreparedRxAggregate),
            &transfer.neutral,
        )) {
            .moved => {},
            .invalid_index, .wrong_class => return .wrong_intent,
            .authority_drift => return .authority_drift,
            .invalid_state, .alias => return .invalid_state,
        }
        const borrowed = external_rx_intent.borrowMovedScreen(
            intent_handle,
            intent_index,
            &transfer.neutral,
            @intFromPtr(aggregate),
        ) orelse {
            self.poisonRxAggregateReservation();
            return .quarantined;
        };
        transfer.saved_self_addr = @intFromPtr(transfer);
        transfer.aggregate_addr = @intFromPtr(aggregate);
        transfer.intent_index = intent_index;
        transfer.header = borrowed.candidate.header;
        transfer.range = borrowed.candidate.range;
        transfer.payload_digest = borrowed.payload.content_digest;
        transfer.lifecycle = .neutral_owned;
        transfer.digest = screenTransferDigest(transfer);
        aggregate.lifecycle = .preparing;
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        return .staged;
    }

    fn transferScreenToLedger(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        intent_handle: *external_rx_intent.ExternalRxIntentHandle,
        intent_index: u8,
    ) RxAggregateTransferResult {
        const aggregate = self.validateReadyRxAggregate(lease) orelse
            return .invalid_state;
        if (intent_index >= aggregate.screen_transfers.len)
            return .wrong_intent;
        const transfer = &aggregate.screen_transfers[intent_index];
        if (transfer.saved_self_addr != @intFromPtr(transfer) or
            transfer.aggregate_addr != @intFromPtr(aggregate) or
            transfer.intent_index != intent_index or
            transfer.lifecycle != .neutral_owned or
            !std.mem.eql(
                u8,
                &transfer.digest,
                &screenTransferDigest(transfer),
            ))
            return .invalid_state;
        const borrowed = external_rx_intent.borrowMovedScreen(
            intent_handle,
            intent_index,
            &transfer.neutral,
            @intFromPtr(aggregate),
        ) orelse return .invalid_state;
        if (!std.meta.eql(transfer.header, borrowed.candidate.header) or
            !std.mem.eql(
                u8,
                &transfer.payload_digest,
                &borrowed.payload.content_digest,
            ))
            return .invalid_state;
        transfer.ledger_payload = .{
            .allocator = borrowed.payload.allocator,
            .allocation_ptr = if (borrowed.payload.allocation_len == 0)
                null
            else
                @ptrFromInt(borrowed.payload.allocation_addr),
            .logical_len = borrowed.payload.allocation_len,
        };
        tombstoneMovedIntentPayloadUnchecked(&transfer.neutral);
        transfer.lifecycle = .ledger_owned;
        transfer.digest = screenTransferDigest(transfer);
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        return .staged;
    }

    fn admitScreenToLiveBatch(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        intent_index: u8,
    ) RxAggregateTransferResult {
        const aggregate = self.validateReadyRxAggregate(lease) orelse
            return .invalid_state;
        if (intent_index >= aggregate.screen_transfers.len)
            return .wrong_intent;
        const transfer = &aggregate.screen_transfers[intent_index];
        if (transfer.saved_self_addr != @intFromPtr(transfer) or
            transfer.aggregate_addr != @intFromPtr(aggregate) or
            transfer.intent_index != intent_index or
            transfer.lifecycle != .ledger_owned or
            !std.mem.eql(
                u8,
                &transfer.digest,
                &screenTransferDigest(transfer),
            ))
            return .invalid_state;
        if (aggregate.live_batch.saved_self_addr == 0) {
            self.inbox_ledger.beginLiveBatch(
                &aggregate.live_batch,
                transfer.ledger_payload.allocator,
                transfer.range.identity,
            ) catch return .rejected;
            aggregate.digest = preparedRxAggregateDigest(aggregate);
        }
        const mutation_index = aggregate.live_batch.mutation_count;
        const semantic = bindRecoveryIntentForCurrentState(
            self,
            screenTransferSemantic(transfer) orelse return .rejected,
        );
        var merge_destination: ?external_inbox_ledger.LiveTokenRef = null;
        if (mutation_index == 0) {
            merge_destination = switch (self.live_partial) {
                .assembling => |assembling| .{ .existing = assembling.ledger_token },
                .none => null,
                .terminal => return .invalid_state,
            };
        } else {
            for (aggregate.screen_transfers[0..intent_index]) |prior| {
                if ((prior.lifecycle != .batch_owned and
                    prior.lifecycle != .mutation_bound) or
                    prior.mutation_index + 1 != mutation_index)
                    continue;
                const prior_semantic = screenTransferSemantic(&prior) orelse
                    return .rejected;
                if (prior_semantic == .partial)
                    merge_destination =
                        .{ .planned = prior.mutation_index };
            }
        }
        if (merge_destination) |destination| {
            const merged_semantic = bindRecoveryIntentForCurrentState(
                self,
                continuedScreenTransferSemantic(
                    self,
                    aggregate,
                    transfer,
                    mutation_index,
                ) orelse return .rejected,
            );
            var source = external_inbox_ledger.PreparedLiveMergeSource{
                .owned = transfer.ledger_payload,
            };
            transfer.ledger_payload =
                external_inbox_ledger.OwnedPayload.empty(
                    transfer.ledger_payload.allocator,
                );
            var replacement: external_inbox_ledger.PreparedLiveReplacement =
                .coalesced;
            self.inbox_ledger.prepareLiveMerge(
                &aggregate.live_batch,
                destination,
                merged_semantic,
                transfer.range,
                &source,
                &replacement,
            ) catch {
                transfer.ledger_payload = source.owned;
                return .rejected;
            };
        } else {
            _ = self.inbox_ledger.prepareLiveAdmission(
                &aggregate.live_batch,
                semantic,
                &transfer.ledger_payload,
            ) catch return .rejected;
        }
        transfer.batch_addr = @intFromPtr(&aggregate.live_batch);
        transfer.mutation_index = mutation_index;
        transfer.lifecycle = .batch_owned;
        transfer.digest = screenTransferDigest(transfer);
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        if (!external_rx_intent.bindScreenMutationScalar(
            @ptrFromInt(aggregate.intent_handle_addr),
            intent_index,
            @intFromPtr(aggregate),
            @sizeOf(PreparedRxAggregate),
            @intFromPtr(&aggregate.live_batch),
            mutation_index,
            transfer.payload_digest,
            &aggregate.screen_proofs[intent_index],
        ))
            return .rejected;
        transfer.lifecycle = .mutation_bound;
        transfer.digest = screenTransferDigest(transfer);
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        return .staged;
    }

    fn finalizeRxAggregate(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        intent_handle: *external_rx_intent.ExternalRxIntentHandle,
    ) RxAggregateFinalizeResult {
        const aggregate = self.validateReadyRxAggregate(lease) orelse
            return .invalid_state;
        if ((aggregate.lifecycle != .ready and
            aggregate.lifecycle != .preparing) or
            aggregate.intent_handle_addr != @intFromPtr(intent_handle) or
            !validateRxAggregateScreenGraph(
                self,
                aggregate,
                intent_handle,
            ))
            return .invalid_state;
        var proof_count: usize = 0;
        for (&aggregate.screen_transfers) |*transfer| {
            switch (transfer.lifecycle) {
                .mutation_bound => {
                    if (transfer.batch_addr != @intFromPtr(&aggregate.live_batch) or
                        transfer.mutation_index != proof_count)
                        return .invalid_state;
                    proof_count += 1;
                },
                .empty => {},
                else => return .invalid_state,
            }
        }
        external_rx_intent.prepareIntentCommit(
            intent_handle,
            @intFromPtr(aggregate),
            @sizeOf(PreparedRxAggregate),
            &aggregate.screen_proofs,
            &aggregate.neutral_payloads,
            &aggregate.intent_commit,
        ) catch {
            return .rejected;
        };
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        if (proof_count != aggregate.intent_commit.proof_count)
            return .invalid_state;
        if (proof_count != 0) {
            if (aggregate.live_batch.saved_self_addr !=
                @intFromPtr(&aggregate.live_batch) or
                proof_count != aggregate.live_batch.mutation_count)
                return .invalid_state;
            self.inbox_ledger.finishLiveBatch(
                &aggregate.live_batch,
            ) catch {
                return .rejected;
            };
            aggregate.digest = preparedRxAggregateDigest(aggregate);
            self.inbox_ledger.prepareLiveCommit(
                &aggregate.live_batch,
                &aggregate.retirement,
                &aggregate.dispositions,
                @intFromPtr(aggregate),
                @intFromPtr(self),
                aggregate.turn_generation,
                &aggregate.live_commit,
            ) catch {
                return .rejected;
            };
            aggregate.digest = preparedRxAggregateDigest(aggregate);
            if (!self.inbox_ledger.validatePreparedLiveCommit(
                &aggregate.live_batch,
                &aggregate.retirement,
                &aggregate.dispositions,
                &aggregate.live_commit,
                @intFromPtr(aggregate),
                @intFromPtr(self),
                aggregate.turn_generation,
            )) return .invalid_state;
            if (!self.prepareRecoverySnapshotCommitUnderHeldLease(
                lease,
                aggregate,
            )) return .invalid_state;
            if (!prepareScreenDestinationPlan(self, aggregate))
                return .invalid_state;
        }
        if (!external_rx_intent.validatePreparedIntentCommit(
            intent_handle,
            &aggregate.screen_proofs,
            &aggregate.neutral_payloads,
            &aggregate.intent_commit,
        ))
            return .invalid_state;
        switch (prepareEventReduction(self, aggregate, intent_handle)) {
            .prepared => {},
            .terminal_runtime_ended => {
                aggregate.digest = preparedRxAggregateDigest(aggregate);
                return .terminal_runtime_ended;
            },
            .rejected => {
                aggregate.digest = preparedRxAggregateDigest(aggregate);
                return .rejected;
            },
        }
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        if (!prepareEventRetirements(aggregate, intent_handle)) {
            aggregate.digest = preparedRxAggregateDigest(aggregate);
            return .invalid_state;
        }
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        if (!prepareMetadataDestination(self, aggregate, intent_handle)) {
            return .rejected;
        }
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        if (!prepareEventScalarDestinations(self, aggregate)) {
            aggregate.digest = preparedRxAggregateDigest(aggregate);
            return .rejected;
        }
        switch (prepareResponseDestinationPlan(
            self,
            aggregate,
            intent_handle,
        )) {
            .prepared => {},
            .deadline_exceeded => {
                aggregate.digest = preparedRxAggregateDigest(aggregate);
                return .terminal_deadline;
            },
            .rejected => {
                aggregate.digest = preparedRxAggregateDigest(aggregate);
                return .rejected;
            },
        }
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        if (!prepareDestinationWrites(self, aggregate, intent_handle)) {
            aggregate.digest = preparedRxAggregateDigest(aggregate);
            return .rejected;
        }
        if (proof_count != 0 and
            !bindRecoveryCleanupDestinationDigests(aggregate))
        {
            aggregate.digest = preparedRxAggregateDigest(aggregate);
            return .invalid_state;
        }
        if (proof_count != 0 and
            !self.preparedRecoverySnapshotCommitCurrent(lease, aggregate))
        {
            aggregate.digest = preparedRxAggregateDigest(aggregate);
            return .invalid_state;
        }
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        aggregate.lifecycle = .finalized;
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        return .finalized;
    }

    /// Destination writes are prepared after the recovery candidate table because their shape
    /// also depends on metadata/response reductions. Bind the final write seal into every
    /// candidate before the aggregate becomes commit-ready; this prevents a valid write from a
    /// sibling ordinal being spliced under an otherwise coherent disposition root.
    fn bindRecoveryCleanupDestinationDigests(
        aggregate: *PreparedRxAggregate,
    ) bool {
        const prepared = &aggregate.recovery_snapshot_commit;
        if (prepared.lifecycle == .empty)
            return aggregate.recovery_dispositions.count == 0;
        for (aggregate.recovery_dispositions.entries[0..aggregate.recovery_dispositions.count]) |
            *entry,
        | {
            var found = false;
            for (aggregate.destination_writes[0..aggregate.destination_write_count]) |*write| {
                if (@intFromPtr(write) == entry.cleanup_destination_addr) {
                    if (found or write.mutation_index != entry.mutation_index or
                        !std.mem.eql(u8, &write.digest, &destinationWriteDigest(write)))
                        return false;
                    entry.cleanup_destination_digest = write.digest;
                    entry.digest = recoverySnapshotDispositionEntryDigest(entry);
                    found = true;
                }
            }
            if (!found) return false;
        }
        aggregate.recovery_dispositions.root_digest =
            recoverySnapshotDispositionRootDigest(
                &aggregate.recovery_dispositions,
            );
        prepared.dispositions_root_digest =
            aggregate.recovery_dispositions.root_digest;
        prepared.digest = preparedRecoverySnapshotCommitDigest(prepared);
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        return true;
    }

    fn commitRxAggregate(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        intent_handle: *external_rx_intent.ExternalRxIntentHandle,
    ) RxAggregateCommitResult {
        var event_cleanup: FrozenAggregateCleanup = .{};
        const aggregate = self.validateAndPrepareRxAggregateCommit(
            lease,
            intent_handle,
            &event_cleanup,
            null,
        ) orelse return .invalid_state;
        return self.commitRxAggregateUnchecked(
            aggregate,
            intent_handle,
            &event_cleanup,
        );
    }

    fn prepareRecoverySnapshotCommitUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        aggregate: *PreparedRxAggregate,
    ) bool {
        if (!std.meta.eql(
            aggregate.recovery_dispositions,
            RecoverySnapshotDispositionAggregate{},
        ) or !std.meta.eql(
            aggregate.recovery_snapshot_commit,
            PreparedRecoverySnapshotCommit{},
        ) or !std.meta.eql(
            aggregate.recovery_commit_output,
            ImmutableRecoveryCommitOutput{},
        ) or !std.meta.eql(
            aggregate.recovery_snapshot_binding,
            CommittedRecoverySnapshotBinding{},
        )) return false;
        const active = switch (self.semantic_state) {
            .active => |value| value,
            else => return true,
        };
        switch (active) {
            .host_recovery => |phase| switch (phase) {
                .awaiting_snapshot => {},
                else => return true,
            },
            .client_recovery => |phase| switch (phase) {
                .awaiting_snapshot => {},
                else => return true,
            },
            .valid => return true,
        }
        const authority = switch (self.owner_authority) {
            .current => |value| value,
            .empty => return false,
        };
        var count: u8 = 0;
        var bound_selected = false;
        var binding_entry_index: u8 = 0;
        var ledger_output_index: u8 = 0;
        var selected_ledger_output_index: u8 = 0;
        var binding_next_state: client_pump.AuthorityState = .valid;
        for (aggregate.dispositions, 0..) |disposition, mutation_index| {
            const root = switch (disposition) {
                .final_live, .cleanup_final => |value| value,
                .unused, .superseded_tombstone => continue,
            };
            const current_output_index = ledger_output_index;
            ledger_output_index += 1;
            if (root.phase != .completed) continue;
            var semantic: ?external_inbox_ledger.PayloadSemantic = null;
            for (aggregate.live_commit.simulation.nodes) |node| {
                if (node.live and std.meta.eql(node.token, root.token)) {
                    semantic = node.semantic;
                    break;
                }
            }
            const completed = switch (semantic orelse {
                return false;
            }) {
                .completed => |value| value,
                else => continue,
            };
            if (count == external_inbox_ledger.max_live_mutations)
                return false;
            const range = switch (completed.provenance) {
                .external => |value| value,
                .untracked => {
                    return false;
                },
            };
            const end_absolute = std.math.add(
                u64,
                range.start_absolute,
                range.span,
            ) catch {
                return false;
            };
            const origin: client_pump.RecoveryOrigin = switch (completed.recovery_intent) {
                .host => .host,
                .client, .none => .client,
            };
            const epoch: u64 = switch (completed.recovery_intent) {
                .host, .client => |value| value,
                .none => 0,
            };
            const entry = &aggregate.recovery_dispositions.entries[count];
            var transfer_addr: usize = 0;
            var transfer_intent_index: u8 = 0;
            for (&aggregate.screen_transfers) |*transfer| {
                if (transfer.lifecycle == .mutation_bound and
                    transfer.mutation_index == mutation_index)
                {
                    transfer_addr = @intFromPtr(transfer);
                    transfer_intent_index = transfer.intent_index;
                    break;
                }
            }
            if (transfer_addr == 0) return false;
            const cleanup_destination_addr = @intFromPtr(
                &aggregate.destination_writes[transfer_intent_index],
            );
            const candidate_plan = client_pump.planRecoverySnapshotBinding(
                active,
                .{
                    .origin = origin,
                    .recovery_epoch = epoch,
                    .is_snapshot = completed.is_snapshot,
                    .start_absolute = range.start_absolute,
                    .end_absolute = end_absolute,
                    .committed_token_generation = root.token.generation,
                },
            );
            const will_bind = !bound_selected and
                candidate_plan.disposition == .bound;
            const cleanup_lifecycle: u8 = if (will_bind)
                @intFromEnum(self.live_screen.lifecycle)
            else
                @intFromEnum(
                    aggregate.screen_transfers[transfer_intent_index].lifecycle,
                );
            entry.* = .{
                .transfer_addr = transfer_addr,
                .mutation_index = @intCast(mutation_index),
                .commit_output_index = current_output_index,
                .token_source = .pending_commit,
                .token = root.token,
                .committed_semantic_digest = external_inbox_ledger.payloadSemanticAuthorityDigest(
                    semantic.?,
                ),
                .origin = origin,
                .recovery_epoch = epoch,
                .is_snapshot = completed.is_snapshot,
                .start_absolute = range.start_absolute,
                .end_absolute = end_absolute,
                .disposition = if (will_bind)
                    .bind
                else
                    .drop,
                .cleanup_destination_addr = cleanup_destination_addr,
                .cleanup_lifecycle = cleanup_lifecycle,
                .cleanup_destination_digest = [_]u8{0} ** 32,
            };
            entry.digest = recoverySnapshotDispositionEntryDigest(entry);
            if (entry.disposition == .bind) {
                bound_selected = true;
                binding_next_state = candidate_plan.next;
                binding_entry_index = count;
                selected_ledger_output_index = current_output_index;
            }
            count += 1;
        }
        if (count == 0) return true;
        var cleanup_selection = [_]bool{false} ** external_inbox_ledger.max_live_mutations;
        for (aggregate.recovery_dispositions.entries[0..count]) |entry| {
            if (entry.disposition == .drop) {
                cleanup_selection[entry.mutation_index] = true;
            }
        }
        self.inbox_ledger.markPreparedFinalRootsForCleanup(
            &aggregate.live_batch,
            &aggregate.retirement,
            &aggregate.dispositions,
            &aggregate.live_commit,
            &cleanup_selection,
            @intFromPtr(aggregate),
            @intFromPtr(self),
            aggregate.turn_generation,
        ) catch return false;
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        aggregate.recovery_dispositions.saved_self_addr =
            @intFromPtr(&aggregate.recovery_dispositions);
        aggregate.recovery_dispositions.owner_aggregate_addr =
            @intFromPtr(aggregate);
        aggregate.recovery_dispositions.count = count;
        aggregate.recovery_dispositions.root_digest =
            recoverySnapshotDispositionRootDigest(
                &aggregate.recovery_dispositions,
            );
        aggregate.recovery_snapshot_commit = .{
            .saved_self_addr = @intFromPtr(&aggregate.recovery_snapshot_commit),
            .aggregate_addr = @intFromPtr(aggregate),
            .storage_addr = @intFromPtr(self),
            .ledger_addr = @intFromPtr(&self.inbox_ledger),
            .lease_addr = @intFromPtr(lease),
            .scratch_addr = lease.scratch_addr,
            .lease_digest = lease.digest,
            .owner_incarnation = self.owner_incarnation,
            .operation_generation = self.operation_generation,
            .turn_generation = aggregate.turn_generation,
            .parser_seal = lease.rx_provenance.parser_seal,
            .authority_generation = authority.generation,
            .authority_seal_digest = self.owner_authority_seal.digest,
            .authority_state = active,
            .binding_next_state = binding_next_state,
            .prepared_live_commit_digest = aggregate.live_commit.digest,
            .source = .{ .commit_pending = .{
                .live_commit_addr = @intFromPtr(&aggregate.live_commit),
                .live_commit_digest = aggregate.live_commit.digest,
            } },
            .dispositions_addr = @intFromPtr(&aggregate.recovery_dispositions),
            .dispositions_root_digest = aggregate.recovery_dispositions.root_digest,
            .committed_output_addr = @intFromPtr(&aggregate.recovery_commit_output),
            .committed_output_pristine_digest = immutableRecoveryCommitOutputDigest(
                &aggregate.recovery_commit_output,
            ),
            .binding_destination_addr = @intFromPtr(
                &aggregate.recovery_snapshot_binding,
            ),
            .binding_destination_pristine_digest = committedRecoverySnapshotBindingDigest(
                &aggregate.recovery_snapshot_binding,
            ),
            .has_binding = bound_selected,
            .binding_entry_index = binding_entry_index,
            .ledger_output_index = selected_ledger_output_index,
            .lifecycle = .prepared,
        };
        aggregate.recovery_snapshot_commit.digest =
            preparedRecoverySnapshotCommitDigest(
                &aggregate.recovery_snapshot_commit,
            );
        return true;
    }

    /// Canonical F3d producer precondition for same-turn projected ACK binding. Ordinary aggregate
    /// finalization prepares recovery against the current pre-ACK authority. Before F3c2 may
    /// project against the post-ACK authority, retire that unconsumed plan through the ledger's
    /// abort/reset transaction and rebuild its live-commit permit; never erase a live permit in a
    /// fixture or caller.
    fn reprepareRxAggregateForProjectedRecoveryUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        aggregate: *PreparedRxAggregate,
    ) bool {
        if (!self.validateWholeTurnLease(lease) or
            aggregate.saved_self_addr != @intFromPtr(aggregate) or
            aggregate.storage_addr != @intFromPtr(self) or
            aggregate.lifecycle != .finalized or
            !std.mem.eql(u8, &aggregate.digest, &preparedRxAggregateDigest(aggregate)) or
            !self.preparedRecoverySnapshotCommitCurrent(lease, aggregate))
            return false;
        if (self.inbox_ledger.abortPreparedLiveCommit(
            &aggregate.live_batch,
            &aggregate.retirement,
            &aggregate.dispositions,
            &aggregate.live_commit,
        ) != .aborted) return false;
        if (!external_inbox_ledger.ExternalInboxLedger.resetPreparedLiveCommit(
            &aggregate.live_commit,
        )) return false;
        aggregate.recovery_dispositions = .{};
        aggregate.recovery_snapshot_commit = .{};
        self.inbox_ledger.prepareLiveCommit(
            &aggregate.live_batch,
            &aggregate.retirement,
            &aggregate.dispositions,
            @intFromPtr(aggregate),
            @intFromPtr(self),
            aggregate.turn_generation,
            &aggregate.live_commit,
        ) catch return false;
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        return true;
    }

    /// Computes the recovery graph against the ACK's projected authority without publishing it.
    /// Every self/destination address in the returned value names its eventual final storage;
    /// `candidate` itself is stack-local evidence and never becomes authority.
    fn prepareRecoverySnapshotCommitForProjectedAckUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        transition: *const PreparedResyncAckTransition,
        aggregate: ?*const PreparedRxAggregate,
        candidate: *ProjectedRecoverySnapshotCommit,
    ) bool {
        candidate.* = .{};
        if (!resyncSemanticDestinationRangesCurrent(
            self,
            lease,
            scratch,
            aggregate,
        ) or !self.preparedResyncAckTransitionCurrent(
            lease,
            scratch,
            &scratch.whole_drain_permit,
            &scratch.control_semantic_verdict,
            transition,
        ) or !std.meta.eql(
            scratch.projected_recovery_snapshot_commit,
            ProjectedRecoverySnapshotCommit{},
        )) return false;

        candidate.saved_self_addr = @intFromPtr(
            &scratch.projected_recovery_snapshot_commit,
        );
        candidate.storage_addr = @intFromPtr(self);
        candidate.scratch_addr = @intFromPtr(scratch);
        candidate.lease_addr = @intFromPtr(lease);
        candidate.projected_state_digest = recoveryAuthorityStateDigest(
            transition.next_state,
        );
        candidate.lifecycle = .prepared;

        const source = aggregate orelse {
            candidate.digest = projectedRecoverySnapshotCommitDigest(candidate);
            return true;
        };
        if (source.saved_self_addr != @intFromPtr(source) or
            source.storage_addr != @intFromPtr(self) or
            // PreparedRxAggregate.turn_generation is the storage operation generation; the
            // scratch turn counter is a separate per-poll epoch and need not have the same value.
            source.turn_generation != self.operation_generation or
            source.lifecycle != .finalized or
            !std.mem.eql(u8, &source.digest, &preparedRxAggregateDigest(source)) or
            !std.meta.eql(source.recovery_dispositions, RecoverySnapshotDispositionAggregate{}) or
            !std.meta.eql(source.recovery_snapshot_commit, PreparedRecoverySnapshotCommit{}) or
            !std.meta.eql(source.recovery_commit_output, ImmutableRecoveryCommitOutput{}) or
            !std.meta.eql(source.recovery_snapshot_binding, CommittedRecoverySnapshotBinding{}))
            return false;
        if (source.intent_handle_addr == 0) return false;
        const source_intent: *external_rx_intent.ExternalRxIntentHandle =
            @ptrFromInt(source.intent_handle_addr);
        if (!external_rx_intent.validatePreparedIntentCommit(
            source_intent,
            &source.screen_proofs,
            &source.neutral_payloads,
            &source.intent_commit,
        )) return false;

        var recovery: RecoverySnapshotDispositionAggregate = .{
            .saved_self_addr = @intFromPtr(
                &scratch.projected_recovery_snapshot_commit.recovery_dispositions,
            ),
            .owner_aggregate_addr = @intFromPtr(source),
        };
        var cleanup_selection = [_]bool{false} ** external_inbox_ledger.max_live_mutations;
        var count: u8 = 0;
        var ledger_output_index: u8 = 0;
        var bound_selected = false;
        var binding_entry_index: u8 = 0;
        var selected_ledger_output_index: u8 = 0;
        var binding_next_state: client_pump.AuthorityState = .valid;
        for (source.dispositions, 0..) |disposition, mutation_index| {
            const root = switch (disposition) {
                .final_live, .cleanup_final => |value| value,
                .unused, .superseded_tombstone => continue,
            };
            const current_output_index = ledger_output_index;
            ledger_output_index += 1;
            if (root.phase != .completed) continue;
            var semantic: ?external_inbox_ledger.PayloadSemantic = null;
            for (source.live_commit.simulation.nodes) |node| {
                if (node.live and std.meta.eql(node.token, root.token)) {
                    semantic = node.semantic;
                    break;
                }
            }
            const completed = switch (semantic orelse return false) {
                .completed => |value| value,
                else => continue,
            };
            if (count == external_inbox_ledger.max_live_mutations) return false;
            const range = switch (completed.provenance) {
                .external => |value| value,
                .untracked => return false,
            };
            const end_absolute = std.math.add(
                u64,
                range.start_absolute,
                range.span,
            ) catch return false;
            const origin: client_pump.RecoveryOrigin = switch (completed.recovery_intent) {
                .host => .host,
                .client, .none => .client,
            };
            const epoch: u64 = switch (completed.recovery_intent) {
                .host, .client => |value| value,
                .none => 0,
            };
            var transfer_addr: usize = 0;
            var transfer_intent_index: u8 = 0;
            for (&source.screen_transfers) |*transfer| {
                if (transfer.lifecycle == .mutation_bound and
                    transfer.mutation_index == mutation_index)
                {
                    transfer_addr = @intFromPtr(transfer);
                    transfer_intent_index = transfer.intent_index;
                    break;
                }
            }
            if (transfer_addr == 0) {
                return false;
            }
            if (transfer_intent_index >= source.destination_write_count) {
                return false;
            }
            const destination = &source.destination_writes[transfer_intent_index];
            if (destination.saved_self_addr != @intFromPtr(destination) or
                destination.aggregate_addr != @intFromPtr(source) or
                destination.intent_index != transfer_intent_index or
                destination.mutation_index != mutation_index or
                !std.mem.eql(
                    u8,
                    &destination.digest,
                    &destinationWriteDigest(destination),
                ))
            {
                return false;
            }
            const plan = client_pump.planRecoverySnapshotBinding(
                transition.next_state,
                .{
                    .origin = origin,
                    .recovery_epoch = epoch,
                    .is_snapshot = completed.is_snapshot,
                    .start_absolute = range.start_absolute,
                    .end_absolute = end_absolute,
                    .committed_token_generation = root.token.generation,
                },
            );
            const will_bind = !bound_selected and plan.disposition == .bound;
            const expected_kind: DestinationWriteKind = if (will_bind)
                .screen_completed
            else
                .screen_cleanup;
            const expected_lifecycle: u8 = if (will_bind)
                @intFromEnum(self.live_screen.lifecycle)
            else
                @intFromEnum(source.screen_transfers[transfer_intent_index].lifecycle);
            if (destination.kind != expected_kind or
                destination.expected_lifecycle != expected_lifecycle)
            {
                return false;
            }
            const entry = &recovery.entries[count];
            entry.* = .{
                .transfer_addr = transfer_addr,
                .mutation_index = @intCast(mutation_index),
                .commit_output_index = current_output_index,
                .token_source = .pending_commit,
                .token = root.token,
                .committed_semantic_digest = external_inbox_ledger.payloadSemanticAuthorityDigest(
                    semantic.?,
                ),
                .origin = origin,
                .recovery_epoch = epoch,
                .is_snapshot = completed.is_snapshot,
                .start_absolute = range.start_absolute,
                .end_absolute = end_absolute,
                .disposition = if (will_bind) .bind else .drop,
                .cleanup_destination_addr = @intFromPtr(
                    destination,
                ),
                .cleanup_lifecycle = expected_lifecycle,
                .cleanup_destination_digest = destination.digest,
            };
            entry.digest = recoverySnapshotDispositionEntryDigest(entry);
            if (will_bind) {
                bound_selected = true;
                binding_next_state = plan.next;
                binding_entry_index = count;
                selected_ledger_output_index = current_output_index;
            } else {
                cleanup_selection[mutation_index] = true;
            }
            count += 1;
        }
        if (count == 0) return false;
        recovery.count = count;
        recovery.root_digest = recoverySnapshotDispositionRootDigest(&recovery);

        const ledger_candidate = self.inbox_ledger.planPreparedFinalRootsForCleanup(
            &source.live_batch,
            &source.retirement,
            &source.dispositions,
            &source.live_commit,
            &cleanup_selection,
            @intFromPtr(
                &scratch.projected_recovery_snapshot_commit.ledger_candidate.dispositions,
            ),
            @intFromPtr(
                &scratch.projected_recovery_snapshot_commit.ledger_candidate.permit,
            ),
            @intFromPtr(source),
            @intFromPtr(self),
            source.turn_generation,
        ) catch return false;

        var recovery_commit: PreparedRecoverySnapshotCommit = .{
            .saved_self_addr = @intFromPtr(
                &scratch.projected_recovery_snapshot_commit.recovery_commit,
            ),
            .aggregate_addr = @intFromPtr(source),
            .storage_addr = @intFromPtr(self),
            .ledger_addr = @intFromPtr(&self.inbox_ledger),
            .lease_addr = @intFromPtr(lease),
            .scratch_addr = @intFromPtr(scratch),
            .lease_digest = lease.digest,
            .owner_incarnation = self.owner_incarnation,
            .operation_generation = self.operation_generation,
            .turn_generation = source.turn_generation,
            .parser_seal = lease.rx_provenance.parser_seal,
            .authority_generation = self.owner_authority.current.generation,
            .authority_seal_digest = self.owner_authority_seal.digest,
            .authority_state = transition.next_state,
            .binding_next_state = binding_next_state,
            .prepared_live_commit_digest = ledger_candidate.permit.digest,
            .source = .{ .commit_pending = .{
                .live_commit_addr = @intFromPtr(
                    &scratch.projected_recovery_snapshot_commit.ledger_candidate.permit,
                ),
                .live_commit_digest = ledger_candidate.permit.digest,
            } },
            .source_discriminator = .same_drain_side_intent,
            .ack_transition_addr = @intFromPtr(transition),
            .ack_transition_digest = transition.digest,
            .dispositions_addr = @intFromPtr(
                &scratch.projected_recovery_snapshot_commit.recovery_dispositions,
            ),
            .dispositions_root_digest = recovery.root_digest,
            .committed_output_addr = @intFromPtr(&source.recovery_commit_output),
            .committed_output_pristine_digest = immutableRecoveryCommitOutputDigest(
                &source.recovery_commit_output,
            ),
            .binding_destination_addr = @intFromPtr(&source.recovery_snapshot_binding),
            .binding_destination_pristine_digest = committedRecoverySnapshotBindingDigest(
                &source.recovery_snapshot_binding,
            ),
            .has_binding = bound_selected,
            .binding_entry_index = binding_entry_index,
            .ledger_output_index = selected_ledger_output_index,
            .lifecycle = .prepared,
        };
        recovery_commit.digest = preparedRecoverySnapshotCommitDigest(&recovery_commit);
        candidate.aggregate_addr = @intFromPtr(source);
        candidate.dispositions_count = count;
        candidate.dispositions_root_digest = recovery.root_digest;
        candidate.output_addr = @intFromPtr(&source.recovery_commit_output);
        candidate.output_pristine_digest = immutableRecoveryCommitOutputDigest(
            &source.recovery_commit_output,
        );
        candidate.binding_addr = @intFromPtr(&source.recovery_snapshot_binding);
        candidate.binding_pristine_digest = committedRecoverySnapshotBindingDigest(
            &source.recovery_snapshot_binding,
        );
        candidate.ledger_candidate = ledger_candidate;
        candidate.recovery_dispositions = recovery;
        candidate.recovery_commit = recovery_commit;
        candidate.digest = projectedRecoverySnapshotCommitDigest(candidate);
        return true;
    }

    /// Last read-only boundary before the projected candidate may be copied to final storage.
    fn validatePreparedRecoverySnapshotForProjectedAckUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        transition: *const PreparedResyncAckTransition,
        aggregate: ?*const PreparedRxAggregate,
        candidate: *const ProjectedRecoverySnapshotCommit,
    ) bool {
        if (candidate.lifecycle != .prepared or
            candidate.saved_self_addr != @intFromPtr(
                &scratch.projected_recovery_snapshot_commit,
            ) or !std.mem.eql(
            u8,
            &candidate.digest,
            &projectedRecoverySnapshotCommitDigest(candidate),
        )) return false;
        var expected: ProjectedRecoverySnapshotCommit = .{};
        if (!self.prepareRecoverySnapshotCommitForProjectedAckUnderHeldLease(
            lease,
            scratch,
            transition,
            aggregate,
            &expected,
        )) return false;
        return std.meta.eql(candidate.*, expected);
    }

    fn preparedRecoverySnapshotCommitCurrent(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        aggregate: *const PreparedRxAggregate,
    ) bool {
        const prepared = &aggregate.recovery_snapshot_commit;
        if (prepared.lifecycle == .empty)
            return std.meta.eql(
                aggregate.recovery_dispositions,
                RecoverySnapshotDispositionAggregate{},
            ) and std.meta.eql(
                aggregate.recovery_commit_output,
                ImmutableRecoveryCommitOutput{},
            ) and std.meta.eql(
                aggregate.recovery_snapshot_binding,
                CommittedRecoverySnapshotBinding{},
            );
        if (!self.validateWholeTurnLease(lease) or
            prepared.saved_self_addr != @intFromPtr(prepared) or
            prepared.aggregate_addr != @intFromPtr(aggregate) or
            prepared.storage_addr != @intFromPtr(self) or
            prepared.ledger_addr != @intFromPtr(&self.inbox_ledger) or
            prepared.lease_addr != @intFromPtr(lease) or
            prepared.scratch_addr != lease.scratch_addr or
            !std.mem.eql(u8, &prepared.lease_digest, &lease.digest) or
            prepared.owner_incarnation != self.owner_incarnation or
            prepared.operation_generation != self.operation_generation or
            prepared.turn_generation != aggregate.turn_generation or
            !std.meta.eql(prepared.parser_seal, lease.rx_provenance.parser_seal) or
            !ownerAuthorityValid(self) or
            !std.meta.eql(
                prepared.authority_generation,
                self.owner_authority.current.generation,
            ) or !std.mem.eql(
            u8,
            &prepared.authority_seal_digest,
            &self.owner_authority_seal.digest,
        ) or
            prepared.dispositions_addr != @intFromPtr(&aggregate.recovery_dispositions) or
            prepared.committed_output_addr != @intFromPtr(&aggregate.recovery_commit_output) or
            prepared.binding_destination_addr != @intFromPtr(
                &aggregate.recovery_snapshot_binding,
            ) or
            prepared.lifecycle != .prepared or
            !std.mem.eql(u8, &prepared.digest, &preparedRecoverySnapshotCommitDigest(prepared)) or
            !std.meta.eql(aggregate.recovery_snapshot_binding, CommittedRecoverySnapshotBinding{}) or
            !std.mem.eql(
                u8,
                &prepared.binding_destination_pristine_digest,
                &committedRecoverySnapshotBindingDigest(
                    &aggregate.recovery_snapshot_binding,
                ),
            ))
            return false;
        const source_current = switch (prepared.source) {
            .commit_pending => |source| source.live_commit_addr ==
                @intFromPtr(&aggregate.live_commit) and
                std.mem.eql(u8, &source.live_commit_digest, &aggregate.live_commit.digest) and
                std.meta.eql(
                    aggregate.recovery_commit_output,
                    ImmutableRecoveryCommitOutput{},
                ) and std.mem.eql(
                u8,
                &prepared.committed_output_pristine_digest,
                &immutableRecoveryCommitOutputDigest(
                    &aggregate.recovery_commit_output,
                ),
            ),
            .already_committed => |source| blk: {
                var expected = ImmutableRecoveryCommitOutput{};
                expected.ledger_output = aggregate.recovery_commit_output.ledger_output;
                break :blk std.meta.eql(aggregate.recovery_commit_output, expected) and
                    source.output_addr == @intFromPtr(
                        &aggregate.recovery_commit_output.ledger_output,
                    ) and aggregate.recovery_commit_output.ledger_output.permit_addr ==
                    @intFromPtr(&aggregate.live_commit) and std.mem.eql(
                    u8,
                    &aggregate.recovery_commit_output.ledger_output.permit_digest,
                    &aggregate.live_commit.digest,
                ) and std.mem.eql(
                    u8,
                    &source.output_digest,
                    &aggregate.recovery_commit_output.ledger_output.digest,
                ) and external_inbox_ledger.claimedCommittedLiveOutputValid(
                    &self.inbox_ledger,
                    &aggregate.recovery_commit_output.ledger_output,
                    @intFromPtr(prepared),
                );
            },
        };
        const source_provenance_current = switch (prepared.source_discriminator) {
            .later_turn_commit => prepared.ack_transition_addr == 0 and
                std.mem.allEqual(u8, &prepared.ack_transition_digest, 0),
            .same_drain_side_intent => blk: {
                const expected_addr = std.math.add(
                    usize,
                    lease.scratch_addr,
                    @offsetOf(ExternalRxTurnScratch, "resync_ack_transition"),
                ) catch break :blk false;
                if (prepared.ack_transition_addr == 0 or
                    prepared.ack_transition_addr != expected_addr)
                    break :blk false;
                const transition: *const PreparedResyncAckTransition =
                    @ptrFromInt(prepared.ack_transition_addr);
                break :blk std.mem.eql(
                    u8,
                    &prepared.ack_transition_digest,
                    &transition.digest,
                ) and self.consumedResyncAckReceiptCurrent(
                    lease,
                    transition,
                );
            },
        };
        return source_current and source_provenance_current and
            aggregate.recovery_dispositions.saved_self_addr ==
                @intFromPtr(&aggregate.recovery_dispositions) and
            aggregate.recovery_dispositions.owner_aggregate_addr == @intFromPtr(aggregate) and
            aggregate.recovery_dispositions.count != 0 and
            (!prepared.has_binding or
                (prepared.binding_entry_index < aggregate.recovery_dispositions.count and
                    prepared.ledger_output_index == aggregate.recovery_dispositions.entries[
                        prepared.binding_entry_index
                    ].commit_output_index and
                    aggregate.recovery_dispositions.entries[
                        prepared.binding_entry_index
                    ].disposition == .bind)) and
            recoverySnapshotDispositionsCurrent(aggregate) and
            std.mem.eql(
                u8,
                &aggregate.recovery_dispositions.root_digest,
                &recoverySnapshotDispositionRootDigest(
                    &aggregate.recovery_dispositions,
                ),
            ) and std.mem.eql(
            u8,
            &prepared.dispositions_root_digest,
            &aggregate.recovery_dispositions.root_digest,
        ) and switch (self.semantic_state) {
            .active => |value| std.meta.eql(value, prepared.authority_state),
            else => false,
        };
    }

    /// Commits transport ownership without publishing recovery authority. f3c2 may place this
    /// side-intent between the ACK transaction and the snapshot binding transaction; the claimed
    /// final-address output is then the only accepted `already_committed` source and cannot be
    /// replayed by a second receipt.
    fn commitRecoveryTransportSideIntentUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        aggregate: *PreparedRxAggregate,
        ack_transition: *const PreparedResyncAckTransition,
    ) bool {
        if (!self.preparedRecoverySnapshotCommitCurrent(lease, aggregate) or
            std.meta.activeTag(aggregate.recovery_snapshot_commit.source) !=
                .commit_pending)
            return false;
        if (!self.consumedResyncAckReceiptCurrent(lease, ack_transition))
            return false;
        aggregate.recovery_snapshot_commit.source_discriminator =
            .same_drain_side_intent;
        aggregate.recovery_snapshot_commit.ack_transition_addr =
            @intFromPtr(ack_transition);
        aggregate.recovery_snapshot_commit.ack_transition_digest =
            ack_transition.digest;
        aggregate.recovery_snapshot_commit.digest =
            preparedRecoverySnapshotCommitDigest(
                &aggregate.recovery_snapshot_commit,
            );
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        if (!self.preparedRecoverySnapshotCommitCurrent(lease, aggregate))
            return false;
        self.commitRecoveryTransportSourceUnchecked(aggregate);
        return true;
    }

    fn consumedResyncAckReceiptCurrent(
        self: *const ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        transition: *const PreparedResyncAckTransition,
    ) bool {
        if (lease.scratch_len != @sizeOf(ExternalRxTurnScratch)) return false;
        const expected_addr = std.math.add(
            usize,
            lease.scratch_addr,
            @offsetOf(ExternalRxTurnScratch, "resync_ack_transition"),
        ) catch return false;
        const scratch: *const ExternalRxTurnScratch =
            @ptrFromInt(lease.scratch_addr);
        const active = switch (self.semantic_state) {
            .active => |value| value,
            else => return false,
        };
        const authority = switch (self.owner_authority) {
            .current => |value| value,
            .empty => return false,
        };
        const plan = client_pump.planRecoveryTransition(.{
            .state = transition.authority_state,
            .trigger = .resync_ack,
            .control = .response_wait,
            .now_ns = transition.sampled_now_ns,
            .recovery_barrier_absolute = transition.recovery_barrier_absolute,
        });
        return expected_addr == @intFromPtr(transition) and
            transition.saved_self_addr == @intFromPtr(transition) and
            transition.storage_addr == @intFromPtr(self) and
            transition.scratch_addr == lease.scratch_addr and
            transition.lease_addr == @intFromPtr(lease) and
            transition.owner_incarnation == self.owner_incarnation and
            transition.operation_generation == self.operation_generation and
            scratch.saved_self_addr == @intFromPtr(scratch) and
            transition.turn_generation == scratch.turn_generation and
            transition.parser_generation <= lease.rx_provenance.parser_seal.generation and
            transition.recovery_barrier_absolute != 0 and
            transition.recovery_deadline_ns ==
                (client_pump.recoveryDeadline(transition.authority_state) orelse
                    return false) and
            plan.disposition == .acknowledged and
            std.meta.eql(plan.next, transition.next_state) and
            std.meta.eql(transition.authority_generation, authority.generation) and
            std.mem.eql(
                u8,
                &transition.authority_seal_digest,
                &self.owner_authority_seal.digest,
            ) and std.meta.eql(transition.next_state, active) and
            transition.lifecycle == .consumed_tombstone and
            std.mem.eql(
                u8,
                &transition.digest,
                &preparedResyncAckTransitionDigest(transition),
            );
    }

    /// The sole irreversible ledger-commit leaf for a recovery source. Every caller completes all
    /// validation before entering it; after the first write there is deliberately no boolean or
    /// error return that could misdescribe a consumed permit as an ordinary precommit rejection.
    fn commitRecoveryTransportSourceUnchecked(
        self: *ExternalPumpStorage,
        aggregate: *PreparedRxAggregate,
    ) void {
        self.inbox_ledger.consumePreparedLiveCommitWithOutputUnchecked(
            &aggregate.live_batch,
            &aggregate.retirement,
            &aggregate.dispositions,
            &aggregate.live_commit,
            &aggregate.recovery_commit_output.ledger_output,
        );
        publishCommittedRecoverySourceUnchecked(aggregate);
        aggregate.digest = preparedRxAggregateDigest(aggregate);
    }

    // MARU_F3C2_PROJECTED_UNCHECKED_BEGIN
    /// Consumes the projected final-address authority directly.  The source aggregate supplies
    /// payload-bearing batch/retirement storage and immutable destinations only; no projected
    /// receipt is copied into it after the first publication write.
    fn consumeProjectedRecoverySnapshotUnchecked(
        self: *ExternalPumpStorage,
        projected: *ProjectedRecoverySnapshotCommit,
        source: *PreparedRxAggregate,
        source_intent: *external_rx_intent.ExternalRxIntentHandle,
    ) void {
        const permit = &projected.ledger_candidate.permit;
        const dispositions = &projected.ledger_candidate.dispositions;
        const prepared = &projected.recovery_commit;
        const recovery_dispositions = &projected.recovery_dispositions;
        const output = &source.recovery_commit_output;
        const ledger_output = &output.ledger_output;

        self.inbox_ledger.consumePreparedLiveCommitWithOutputUnchecked(
            &source.live_batch,
            &source.retirement,
            dispositions,
            permit,
            ledger_output,
        );
        external_rx_intent.consumePreparedIntentCommitUnchecked(
            source_intent,
            &source.screen_proofs,
            &source.neutral_payloads,
            &source.intent_commit,
        );
        external_inbox_ledger.claimCommittedLiveOutputUnchecked(
            ledger_output,
            @intFromPtr(prepared),
        );
        for (recovery_dispositions.entries[0..recovery_dispositions.count]) |*entry| {
            entry.token_source = .committed_output;
            entry.digest = recoverySnapshotDispositionEntryDigest(entry);
        }
        recovery_dispositions.root_digest = recoverySnapshotDispositionRootDigest(
            recovery_dispositions,
        );
        prepared.source = .{ .already_committed = .{
            .output_addr = @intFromPtr(ledger_output),
            .output_digest = ledger_output.digest,
        } };
        prepared.dispositions_root_digest = recovery_dispositions.root_digest;
        prepared.digest = preparedRecoverySnapshotCommitDigest(prepared);

        if (!prepared.has_binding) {
            external_inbox_ledger.consumeClaimedCommittedLiveOutputUnchecked(
                ledger_output,
            );
            consumeProjectedRecoveryDispositionAuthorityUnchecked(
                recovery_dispositions,
                prepared,
            );
            prepared.lifecycle = .consumed_tombstone;
            prepared.digest = preparedRecoverySnapshotCommitDigest(prepared);
        } else {
            const entry = &recovery_dispositions.entries[prepared.binding_entry_index];
            const actual = ledger_output.entries[prepared.ledger_output_index];
            output.saved_self_addr = @intFromPtr(output);
            output.aggregate_addr = @intFromPtr(source);
            output.ledger_addr = @intFromPtr(&self.inbox_ledger);
            output.storage_addr = @intFromPtr(self);
            output.live_commit_addr = @intFromPtr(permit);
            output.live_commit_digest = permit.digest;
            output.token = actual.token;
            output.semantic_digest = actual.semantic_digest;
            output.recovery_intent = switch (entry.origin) {
                .host => .{ .host = entry.recovery_epoch },
                .client => .{ .client = entry.recovery_epoch },
            };
            output.origin = entry.origin;
            output.recovery_epoch = entry.recovery_epoch;
            output.is_snapshot = entry.is_snapshot;
            output.start_absolute = entry.start_absolute;
            output.end_absolute = entry.end_absolute;
            output.lifecycle = .committed;
            output.digest = immutableRecoveryCommitOutputDigest(output);

            const binding = &source.recovery_snapshot_binding;
            binding.* = .{
                .saved_self_addr = @intFromPtr(binding),
                .aggregate_addr = @intFromPtr(source),
                .scratch_addr = prepared.scratch_addr,
                .storage_addr = @intFromPtr(self),
                .ledger_addr = @intFromPtr(&self.inbox_ledger),
                .lease_addr = prepared.lease_addr,
                .lease_digest = prepared.lease_digest,
                .owner_incarnation = prepared.owner_incarnation,
                .operation_generation = prepared.operation_generation,
                .turn_generation = prepared.turn_generation,
                .parser_generation = prepared.parser_seal.generation,
                .parser_seal = prepared.parser_seal,
                .authority_generation = prepared.authority_generation,
                .authority_seal_digest = prepared.authority_seal_digest,
                .awaiting_state = prepared.authority_state,
                .awaiting_state_digest = recoveryAuthorityStateDigest(prepared.authority_state),
                .ledger_authority_digest = self.inbox_ledger.projectionAuthorityDigest(),
                .token = output.token,
                .semantic_digest = output.semantic_digest,
                .recovery_intent = output.recovery_intent,
                .origin = output.origin,
                .recovery_epoch = output.recovery_epoch,
                .is_snapshot = output.is_snapshot,
                .start_absolute = output.start_absolute,
                .end_absolute = output.end_absolute,
                .source_output_addr = @intFromPtr(output),
                .source_output_digest = output.digest,
                .side_intent_addr = @intFromPtr(ledger_output),
                .side_intent_digest = ledger_output.digest,
                .destination_pristine_digest = prepared.binding_destination_pristine_digest,
                .source_discriminator = .same_drain_side_intent,
                .source_provenance_digest = prepared.ack_transition_digest,
                .ack_transition_addr = prepared.ack_transition_addr,
                .ack_transition_digest = prepared.ack_transition_digest,
                .lifecycle = .committed,
            };
            binding.digest = committedRecoverySnapshotBindingDigest(binding);
            self.semantic_state = .{ .active = prepared.binding_next_state };
            external_inbox_ledger.consumeClaimedCommittedLiveOutputUnchecked(ledger_output);
            output.lifecycle = .consumed_tombstone;
            output.digest = immutableRecoveryCommitOutputDigest(output);
            binding.source_output_digest = output.digest;
            binding.side_intent_digest = ledger_output.digest;
            binding.lifecycle = .consumed_tombstone;
            binding.digest = committedRecoverySnapshotBindingDigest(binding);
            consumeProjectedRecoveryDispositionAuthorityUnchecked(
                recovery_dispositions,
                prepared,
            );
            prepared.lifecycle = .consumed_tombstone;
            prepared.digest = preparedRecoverySnapshotCommitDigest(prepared);
        }
        source.lifecycle = .side_intent_consumed;
        source.digest = preparedRxAggregateDigest(source);
    }
    // MARU_F3C2_PROJECTED_UNCHECKED_END

    fn consumeProjectedRecoveryDispositionAuthorityUnchecked(
        dispositions: *RecoverySnapshotDispositionAggregate,
        prepared: *PreparedRecoverySnapshotCommit,
    ) void {
        for (dispositions.entries[0..dispositions.count]) |*entry| {
            entry.token_source = .consumed_tombstone;
            entry.digest = recoverySnapshotDispositionEntryDigest(entry);
        }
        dispositions.root_digest = recoverySnapshotDispositionRootDigest(dispositions);
        prepared.dispositions_root_digest = dispositions.root_digest;
    }

    /// Converges both transport source forms on one exact claimed output. The caller has either
    /// just committed the sealed ledger permit or is the side-intent helper above; no allocation,
    /// callback, clock, syscall, or fallible lookup may enter this suffix.
    fn publishCommittedRecoverySourceUnchecked(
        aggregate: *PreparedRxAggregate,
    ) void {
        external_inbox_ledger.claimCommittedLiveOutputUnchecked(
            &aggregate.recovery_commit_output.ledger_output,
            @intFromPtr(&aggregate.recovery_snapshot_commit),
        );
        for (aggregate.recovery_dispositions.entries[0..aggregate.recovery_dispositions.count]) |
            *entry,
        | {
            entry.token_source = .committed_output;
            entry.digest = recoverySnapshotDispositionEntryDigest(entry);
        }
        aggregate.recovery_dispositions.root_digest =
            recoverySnapshotDispositionRootDigest(
                &aggregate.recovery_dispositions,
            );
        aggregate.recovery_snapshot_commit.source = .{ .already_committed = .{
            .output_addr = @intFromPtr(
                &aggregate.recovery_commit_output.ledger_output,
            ),
            .output_digest = aggregate.recovery_commit_output.ledger_output.digest,
        } };
        aggregate.recovery_snapshot_commit.dispositions_root_digest =
            aggregate.recovery_dispositions.root_digest;
        aggregate.recovery_snapshot_commit.digest =
            preparedRecoverySnapshotCommitDigest(
                &aggregate.recovery_snapshot_commit,
            );
    }

    fn recoverySnapshotDispositionsCurrent(
        aggregate: *const PreparedRxAggregate,
    ) bool {
        const dispositions = &aggregate.recovery_dispositions;
        if (dispositions.saved_self_addr != @intFromPtr(dispositions) or
            dispositions.owner_aggregate_addr != @intFromPtr(aggregate) or
            dispositions.count == 0 or
            dispositions.count > external_inbox_ledger.max_live_mutations)
            return false;
        var seen = std.StaticBitSet(external_inbox_ledger.max_live_mutations).initEmpty();
        var bind_count: u8 = 0;
        const expected_token_source: RecoverySnapshotTokenSource = switch (aggregate.recovery_snapshot_commit.source) {
            .commit_pending => .pending_commit,
            .already_committed => .committed_output,
        };
        for (dispositions.entries[0..dispositions.count]) |entry| {
            if (!std.mem.eql(
                u8,
                &entry.digest,
                &recoverySnapshotDispositionEntryDigest(&entry),
            ) or entry.token_source != expected_token_source or
                entry.mutation_index >= aggregate.live_commit.mutation_count or
                seen.isSet(entry.mutation_index) or
                entry.token.generation == 0 or
                entry.end_absolute <= entry.start_absolute)
                return false;
            seen.set(entry.mutation_index);
            const root = switch (aggregate.dispositions[entry.mutation_index]) {
                .final_live, .cleanup_final => |value| value,
                .unused, .superseded_tombstone => return false,
            };
            if (root.phase != .completed or !std.meta.eql(root.token, entry.token))
                return false;
            var expected_output_index: u8 = 0;
            for (aggregate.dispositions[0..entry.mutation_index]) |prior|
                if (prior == .final_live or prior == .cleanup_final) {
                    expected_output_index += 1;
                };
            if (entry.commit_output_index != expected_output_index)
                return false;
            const committed_semantic: ?external_inbox_ledger.PayloadSemantic = switch (aggregate.recovery_snapshot_commit.source) {
                .commit_pending => blk: {
                    for (aggregate.live_commit.simulation.nodes) |node| {
                        if (node.live and std.meta.eql(node.token, root.token))
                            break :blk node.semantic;
                    }
                    break :blk null;
                },
                .already_committed => blk: {
                    const output = &aggregate.recovery_commit_output.ledger_output;
                    if (entry.commit_output_index >= output.count)
                        break :blk null;
                    const actual = output.entries[entry.commit_output_index];
                    if (!std.meta.eql(actual.token, entry.token) or
                        actual.phase != .completed or
                        actual.cleanup_only != (entry.disposition == .drop) or
                        !std.mem.eql(
                            u8,
                            &actual.semantic_digest,
                            &entry.committed_semantic_digest,
                        )) break :blk null;
                    break :blk actual.semantic;
                },
            };
            const completed = switch (committed_semantic orelse return false) {
                .completed => |value| value,
                else => return false,
            };
            const range = switch (completed.provenance) {
                .external => |value| value,
                .untracked => return false,
            };
            const semantic_end = std.math.add(
                u64,
                range.start_absolute,
                range.span,
            ) catch return false;
            const semantic_origin: client_pump.RecoveryOrigin = switch (completed.recovery_intent) {
                .host => .host,
                .client => .client,
                .none => .client,
            };
            const semantic_epoch: u64 = switch (completed.recovery_intent) {
                .host, .client => |value| value,
                .none => 0,
            };
            if (entry.is_snapshot != completed.is_snapshot or
                entry.origin != semantic_origin or
                entry.recovery_epoch != semantic_epoch or
                entry.start_absolute != range.start_absolute or
                entry.end_absolute != semantic_end)
                return false;
            if (!std.mem.eql(
                u8,
                &entry.committed_semantic_digest,
                &external_inbox_ledger.payloadSemanticAuthorityDigest(
                    committed_semantic.?,
                ),
            )) return false;
            var transfer_current = false;
            for (&aggregate.screen_transfers) |*transfer| {
                if (@intFromPtr(transfer) == entry.transfer_addr and
                    transfer.lifecycle == .mutation_bound and
                    transfer.mutation_index == entry.mutation_index)
                {
                    transfer_current = true;
                    break;
                }
            }
            if (!transfer_current) return false;
            var destination_current = false;
            const expected_write_kind: DestinationWriteKind = switch (entry.disposition) {
                .bind => .screen_completed,
                .drop => .screen_cleanup,
                .unused, .terminal => return false,
            };
            for (aggregate.destination_writes[0..aggregate.destination_write_count]) |*write| {
                if (@intFromPtr(write) == entry.cleanup_destination_addr and
                    write.mutation_index == entry.mutation_index and
                    write.kind == expected_write_kind and
                    write.expected_lifecycle == entry.cleanup_lifecycle and
                    std.mem.eql(
                        u8,
                        &write.digest,
                        &entry.cleanup_destination_digest,
                    ))
                {
                    destination_current = true;
                    break;
                }
            }
            if (!destination_current) return false;
            if (entry.disposition == .bind) {
                bind_count += 1;
                const plan = client_pump.planRecoverySnapshotBinding(
                    aggregate.recovery_snapshot_commit.authority_state,
                    .{
                        .origin = entry.origin,
                        .recovery_epoch = entry.recovery_epoch,
                        .is_snapshot = entry.is_snapshot,
                        .start_absolute = entry.start_absolute,
                        .end_absolute = entry.end_absolute,
                        .committed_token_generation = entry.token.generation,
                    },
                );
                if (bind_count != 1 or plan.disposition != .bound or
                    !std.meta.eql(
                        plan.next,
                        aggregate.recovery_snapshot_commit.binding_next_state,
                    ))
                {
                    return false;
                }
            } else if (entry.disposition != .drop) return false;
        }
        for (dispositions.entries[dispositions.count..]) |entry|
            if (!std.meta.eql(entry, RecoverySnapshotDispositionEntry{}))
                return false;
        return bind_count == @intFromBool(
            aggregate.recovery_snapshot_commit.has_binding,
        ) and (bind_count != 0 or
            std.meta.eql(
                aggregate.recovery_snapshot_commit.binding_next_state,
                client_pump.AuthorityState.valid,
            ));
    }

    fn validateAndPrepareRxAggregateCommit(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        intent_handle: *external_rx_intent.ExternalRxIntentHandle,
        event_cleanup: *FrozenAggregateCleanup,
        allowed_cleanup_owner: ?*const RevokedCleanupOwnerProof,
    ) ?*PreparedRxAggregate {
        const aggregate = self.validateReadyRxAggregate(lease) orelse
            {
                return null;
            };
        const already_committed = std.meta.activeTag(
            aggregate.recovery_snapshot_commit.source,
        ) == .already_committed;
        if (aggregate.lifecycle != .finalized or
            aggregate.intent_handle_addr != @intFromPtr(intent_handle) or
            !(if (already_committed)
                validateCommittedRecoveryScreenGraph(
                    aggregate,
                    intent_handle,
                )
            else
                validateRxAggregateScreenGraph(
                    self,
                    aggregate,
                    intent_handle,
                )))
        {
            return null;
        }
        const proof_count: usize = aggregate.intent_commit.proof_count;
        const valid_intent = external_rx_intent.validatePreparedIntentCommit(
            intent_handle,
            &aggregate.screen_proofs,
            &aggregate.neutral_payloads,
            &aggregate.intent_commit,
        );
        const valid_reduction =
            validateEventReduction(self, aggregate, intent_handle);
        const valid_retirements =
            validateEventRetirements(aggregate, intent_handle);
        const valid_metadata = validateMetadataDestination(self, aggregate);
        const valid_scalars =
            validateEventScalarDestinations(self, aggregate);
        const valid_response =
            validateResponseDestinationPlan(self, aggregate);
        const valid_destination_writes =
            validateDestinationWrites(self, aggregate, intent_handle);
        if (!valid_intent) {
            return null;
        }
        if (!valid_reduction) {
            return null;
        }
        if (!valid_retirements) {
            return null;
        }
        if (!valid_metadata) {
            return null;
        }
        if (!valid_scalars) {
            return null;
        }
        if (!valid_response) {
            return null;
        }
        if (!valid_destination_writes) {
            return null;
        }
        if (proof_count != 0) {
            switch (aggregate.recovery_snapshot_commit.source) {
                .commit_pending => if (!self.inbox_ledger.validatePreparedLiveCommit(
                    &aggregate.live_batch,
                    &aggregate.retirement,
                    &aggregate.dispositions,
                    &aggregate.live_commit,
                    @intFromPtr(aggregate),
                    @intFromPtr(self),
                    aggregate.turn_generation,
                )) return null,
                .already_committed => {},
            }
            if (!validateScreenDestinationPlan(self, aggregate)) {
                return null;
            }
            if (!self.preparedRecoverySnapshotCommitCurrent(lease, aggregate))
                return null;
        }
        if (!prepareEventAggregateCleanup(
            self,
            aggregate,
            event_cleanup,
            intent_handle,
            allowed_cleanup_owner,
        )) return null;
        return aggregate;
    }

    const PublishedRxAggregateCommit = struct {
        callback_entry_digest: external_owner_seal.Digest,
        expected_after_callbacks: PreparedRxAggregate,
        /// Cleanup callbacks execute after the semantic publication point, but they are still
        /// untrusted allocator code. Freeze every storage-level authority that this transaction
        /// must leave unchanged so a callback cannot coherently reseal a different owner/ledger
        /// graph while leaving the aggregate receipt byte-for-byte valid.
        storage_lifecycle: StorageLifecycle,
        semantic_state: client_pump.ExternalPumpState,
        owner_authority: OwnerAuthorityState,
        owner_authority_seal: OwnerAuthoritySeal,
        owner_incarnation: u64,
        owner_incarnation_seal: OwnerIncarnationSeal,
        operation_generation: u64,
        ledger_projection_digest: external_owner_seal.Digest,
        proof_count: usize,
    };

    fn publishRxAggregateUnchecked(
        self: *ExternalPumpStorage,
        aggregate: *PreparedRxAggregate,
        intent_handle: *external_rx_intent.ExternalRxIntentHandle,
        event_cleanup: *FrozenAggregateCleanup,
        published: *PublishedRxAggregateCommit,
    ) void {
        const proof_count: usize = aggregate.intent_commit.proof_count;
        aggregate.lifecycle = .committing;
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        if (proof_count != 0) {
            if (aggregate.recovery_snapshot_commit.lifecycle == .prepared) {
                switch (aggregate.recovery_snapshot_commit.source) {
                    .commit_pending => {
                        self.commitRecoveryTransportSourceUnchecked(aggregate);
                    },
                    .already_committed => {},
                }
            } else {
                self.inbox_ledger.consumePreparedLiveCommitUnchecked(
                    &aggregate.live_batch,
                    &aggregate.retirement,
                    &aggregate.dispositions,
                    &aggregate.live_commit,
                );
            }
        }
        if (proof_count != 0 and
            aggregate.recovery_snapshot_commit.lifecycle == .prepared)
            self.publishRecoverySnapshotCommitUnchecked(aggregate);
        external_rx_intent.consumePreparedIntentCommitUnchecked(
            intent_handle,
            &aggregate.screen_proofs,
            &aggregate.neutral_payloads,
            &aggregate.intent_commit,
        );

        for (aggregate.destination_writes[0..aggregate.destination_write_count]) |
            *write,
        | commitDestinationWriteUnchecked(self, aggregate, write);
        appendEventAggregateCleanupUnchecked(aggregate, event_cleanup);
        aggregate.lifecycle = .committed;
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        var expected_after_callbacks = aggregate.*;
        if (proof_count != 0)
            expected_after_callbacks.retirement = .{ .lifecycle = .retired };
        expected_after_callbacks.digest =
            preparedRxAggregateDigest(&expected_after_callbacks);
        published.* = .{
            .callback_entry_digest = aggregate.digest,
            .expected_after_callbacks = expected_after_callbacks,
            .storage_lifecycle = self.lifecycle,
            .semantic_state = self.semantic_state,
            .owner_authority = self.owner_authority,
            .owner_authority_seal = self.owner_authority_seal,
            .owner_incarnation = self.owner_incarnation,
            .owner_incarnation_seal = self.owner_incarnation_seal,
            .operation_generation = self.operation_generation,
            .ledger_projection_digest = self.inbox_ledger.projectionAuthorityDigest(),
            .proof_count = proof_count,
        };
        self.retainRxAggregateAllocation(aggregate);
    }

    fn publishRecoverySnapshotCommitUnchecked(
        self: *ExternalPumpStorage,
        aggregate: *PreparedRxAggregate,
    ) void {
        const prepared = &aggregate.recovery_snapshot_commit;
        const output = &aggregate.recovery_commit_output;
        const ledger_output = &output.ledger_output;
        if (!prepared.has_binding) {
            external_inbox_ledger.consumeClaimedCommittedLiveOutputUnchecked(
                ledger_output,
            );
            consumeRecoveryDispositionAuthorityUnchecked(aggregate);
            prepared.lifecycle = .consumed_tombstone;
            prepared.digest = preparedRecoverySnapshotCommitDigest(prepared);
            return;
        }
        const entry = &aggregate.recovery_dispositions.entries[
            prepared.binding_entry_index
        ];
        const actual = ledger_output.entries[prepared.ledger_output_index];
        output.saved_self_addr = @intFromPtr(output);
        output.aggregate_addr = @intFromPtr(aggregate);
        output.ledger_addr = @intFromPtr(&self.inbox_ledger);
        output.storage_addr = @intFromPtr(self);
        output.live_commit_addr = @intFromPtr(&aggregate.live_commit);
        output.live_commit_digest = aggregate.live_commit.digest;
        output.token = actual.token;
        output.semantic_digest = actual.semantic_digest;
        output.recovery_intent = switch (entry.origin) {
            .host => .{ .host = entry.recovery_epoch },
            .client => .{ .client = entry.recovery_epoch },
        };
        output.origin = entry.origin;
        output.recovery_epoch = entry.recovery_epoch;
        output.is_snapshot = entry.is_snapshot;
        output.start_absolute = entry.start_absolute;
        output.end_absolute = entry.end_absolute;
        output.lifecycle = .committed;
        output.digest = immutableRecoveryCommitOutputDigest(output);
        const binding = &aggregate.recovery_snapshot_binding;
        binding.* = .{
            .saved_self_addr = @intFromPtr(binding),
            .aggregate_addr = @intFromPtr(aggregate),
            .scratch_addr = prepared.scratch_addr,
            .storage_addr = @intFromPtr(self),
            .ledger_addr = @intFromPtr(&self.inbox_ledger),
            .lease_addr = prepared.lease_addr,
            .lease_digest = prepared.lease_digest,
            .owner_incarnation = prepared.owner_incarnation,
            .operation_generation = prepared.operation_generation,
            .turn_generation = prepared.turn_generation,
            .parser_generation = prepared.parser_seal.generation,
            .parser_seal = prepared.parser_seal,
            .authority_generation = prepared.authority_generation,
            .authority_seal_digest = prepared.authority_seal_digest,
            .awaiting_state = prepared.authority_state,
            .awaiting_state_digest = recoveryAuthorityStateDigest(
                prepared.authority_state,
            ),
            .ledger_authority_digest = self.inbox_ledger.projectionAuthorityDigest(),
            .token = output.token,
            .semantic_digest = output.semantic_digest,
            .recovery_intent = output.recovery_intent,
            .origin = output.origin,
            .recovery_epoch = output.recovery_epoch,
            .is_snapshot = output.is_snapshot,
            .start_absolute = output.start_absolute,
            .end_absolute = output.end_absolute,
            .source_output_addr = @intFromPtr(output),
            .source_output_digest = output.digest,
            .side_intent_addr = if (prepared.source_discriminator ==
                .same_drain_side_intent)
                @intFromPtr(&output.ledger_output)
            else
                0,
            .side_intent_digest = if (prepared.source_discriminator ==
                .same_drain_side_intent)
                output.ledger_output.digest
            else
                [_]u8{0} ** 32,
            .destination_pristine_digest = prepared.binding_destination_pristine_digest,
            .source_discriminator = prepared.source_discriminator,
            .source_provenance_digest = switch (prepared.source_discriminator) {
                .later_turn_commit => recoveryAuthorityStateDigest(
                    prepared.authority_state,
                ),
                .same_drain_side_intent => prepared.ack_transition_digest,
            },
            .ack_transition_addr = prepared.ack_transition_addr,
            .ack_transition_digest = prepared.ack_transition_digest,
            .lifecycle = .committed,
        };
        binding.digest = committedRecoverySnapshotBindingDigest(binding);
        self.semantic_state = .{ .active = prepared.binding_next_state };
        external_inbox_ledger.consumeClaimedCommittedLiveOutputUnchecked(
            ledger_output,
        );
        output.lifecycle = .consumed_tombstone;
        output.digest = immutableRecoveryCommitOutputDigest(output);
        binding.source_output_digest = output.digest;
        if (binding.source_discriminator == .same_drain_side_intent)
            binding.side_intent_digest = ledger_output.digest;
        binding.lifecycle = .consumed_tombstone;
        binding.digest = committedRecoverySnapshotBindingDigest(binding);
        consumeRecoveryDispositionAuthorityUnchecked(aggregate);
        prepared.lifecycle = .consumed_tombstone;
        prepared.digest = preparedRecoverySnapshotCommitDigest(prepared);
    }

    fn consumeRecoveryDispositionAuthorityUnchecked(
        aggregate: *PreparedRxAggregate,
    ) void {
        for (aggregate.recovery_dispositions.entries[0..aggregate.recovery_dispositions.count]) |
            *entry,
        | {
            entry.token_source = .consumed_tombstone;
            entry.digest = recoverySnapshotDispositionEntryDigest(entry);
        }
        aggregate.recovery_dispositions.root_digest =
            recoverySnapshotDispositionRootDigest(
                &aggregate.recovery_dispositions,
            );
        aggregate.recovery_snapshot_commit.dispositions_root_digest =
            aggregate.recovery_dispositions.root_digest;
    }

    fn committedRecoverySnapshotBindingCurrent(
        self: *const ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        aggregate: *const PreparedRxAggregate,
    ) bool {
        const prepared = &aggregate.recovery_snapshot_commit;
        const output = &aggregate.recovery_commit_output;
        const binding = &aggregate.recovery_snapshot_binding;
        if (binding.saved_self_addr != @intFromPtr(binding) or
            binding.aggregate_addr != @intFromPtr(aggregate) or
            binding.scratch_addr != lease.scratch_addr or
            binding.storage_addr != @intFromPtr(self) or
            binding.ledger_addr != @intFromPtr(&self.inbox_ledger) or
            binding.lease_addr != @intFromPtr(lease) or
            !std.mem.eql(u8, &binding.lease_digest, &lease.digest) or
            binding.owner_incarnation != self.owner_incarnation or
            binding.operation_generation != self.operation_generation or
            binding.turn_generation != aggregate.turn_generation or
            binding.parser_generation != binding.parser_seal.generation or
            !std.meta.eql(binding.parser_seal, prepared.parser_seal) or
            !std.meta.eql(binding.authority_generation, prepared.authority_generation) or
            !std.mem.eql(
                u8,
                &binding.authority_seal_digest,
                &prepared.authority_seal_digest,
            ) or !std.meta.eql(binding.awaiting_state, prepared.authority_state) or
            !std.mem.eql(
                u8,
                &binding.awaiting_state_digest,
                &recoveryAuthorityStateDigest(binding.awaiting_state),
            ) or !std.mem.eql(
            u8,
            &binding.ledger_authority_digest,
            &self.inbox_ledger.projectionAuthorityDigest(),
        ) or binding.source_output_addr != @intFromPtr(output) or
            !std.mem.eql(u8, &binding.source_output_digest, &output.digest) or
            !std.mem.eql(
                u8,
                &binding.destination_pristine_digest,
                &prepared.binding_destination_pristine_digest,
            ) or binding.source_discriminator != prepared.source_discriminator or
            binding.ack_transition_addr != prepared.ack_transition_addr or
            !std.mem.eql(
                u8,
                &binding.ack_transition_digest,
                &prepared.ack_transition_digest,
            ) or binding.lifecycle != .consumed_tombstone or
            !std.mem.eql(
                u8,
                &binding.digest,
                &committedRecoverySnapshotBindingDigest(binding),
            )) return false;
        if (!std.meta.eql(binding.token, output.token) or
            !std.mem.eql(u8, &binding.semantic_digest, &output.semantic_digest) or
            !std.meta.eql(binding.recovery_intent, output.recovery_intent) or
            binding.origin != output.origin or
            binding.recovery_epoch != output.recovery_epoch or
            binding.is_snapshot != output.is_snapshot or
            binding.start_absolute != output.start_absolute or
            binding.end_absolute != output.end_absolute)
            return false;
        return switch (binding.source_discriminator) {
            .later_turn_commit => binding.side_intent_addr == 0 and
                std.mem.allEqual(u8, &binding.side_intent_digest, 0) and
                binding.ack_transition_addr == 0 and
                std.mem.allEqual(u8, &binding.ack_transition_digest, 0) and
                std.mem.eql(
                    u8,
                    &binding.source_provenance_digest,
                    &binding.awaiting_state_digest,
                ),
            .same_drain_side_intent => binding.side_intent_addr ==
                @intFromPtr(&output.ledger_output) and std.mem.eql(
                u8,
                &binding.side_intent_digest,
                &output.ledger_output.digest,
            ) and binding.ack_transition_addr != 0 and std.mem.eql(
                u8,
                &binding.source_provenance_digest,
                &binding.ack_transition_digest,
            ),
        };
    }

    fn finishPublishedRxAggregateCommit(
        self: *ExternalPumpStorage,
        aggregate: *PreparedRxAggregate,
        event_cleanup: *FrozenAggregateCleanup,
        published: *const PublishedRxAggregateCommit,
        defer_scalar_drift_to_outer_owner: bool,
    ) RxAggregateCommitResult {
        const retire_result = if (published.proof_count == 0)
            external_inbox_ledger.RetireLiveResult.retired
        else
            aggregate.retirement.retire();
        const event_finish = finishFrozenAggregateCleanup(event_cleanup);
        const callback_state_valid =
            std.mem.eql(u8, &aggregate.digest, &published.callback_entry_digest) and
            std.meta.eql(
                aggregate.retirement,
                published.expected_after_callbacks.retirement,
            );
        aggregate.digest = published.expected_after_callbacks.digest;
        const aggregate_state_valid =
            std.meta.eql(aggregate.*, published.expected_after_callbacks);
        const ledger_state_valid = std.mem.eql(
            u8,
            &self.inbox_ledger.projectionAuthorityDigest(),
            &published.ledger_projection_digest,
        );
        const storage_scalar_state_valid =
            self.lifecycle == published.storage_lifecycle and
            std.meta.eql(self.semantic_state, published.semantic_state) and
            std.meta.eql(self.owner_authority, published.owner_authority) and
            std.meta.eql(self.owner_authority_seal, published.owner_authority_seal) and
            self.owner_incarnation == published.owner_incarnation and
            std.meta.eql(self.owner_incarnation_seal, published.owner_incarnation_seal) and
            self.operation_generation == published.operation_generation;
        const storage_state_valid =
            storage_scalar_state_valid and ledger_state_valid;
        if (!callback_state_valid or !aggregate_state_valid) {
            // Restore only the callback-hidden, precomputed canonical state. Never seal callback
            // mutations as new authority; retained teardown can now retire the committed graph.
            aggregate.* = published.expected_after_callbacks;
        }
        if (!storage_state_valid) {
            if (defer_scalar_drift_to_outer_owner and ledger_state_valid) {
                return .quarantined;
            }
            // Preserve only lease-release-critical scalars until the outer whole-turn owner drops
            // its TX/RX claims. Pointer-bearing owners (especially the ledger) remain untouched and
            // must not be dereferenced; releaseWholeTurnLease immediately converts this marker into
            // a dead bounded-quarantine tombstone after clearing the thread-local claims.
            self.lifecycle = published.storage_lifecycle;
            self.semantic_state = published.semantic_state;
            self.owner_authority = published.owner_authority;
            self.owner_authority_seal = published.owner_authority_seal;
            self.owner_incarnation = published.owner_incarnation;
            self.owner_incarnation_seal = published.owner_incarnation_seal;
            self.operation_generation = published.operation_generation;
            self.callback_quarantine_pending = true;
            return .quarantined;
        }
        if (retire_result == .quarantined or !event_finish or
            !callback_state_valid or !aggregate_state_valid)
        {
            latchCrossOwnerQuarantine();
            return .quarantined;
        }
        return .committed;
    }

    fn quarantinePublishedStorageAfterCallbackDrift(
        self: *ExternalPumpStorage,
    ) void {
        const quarantine_already_accounted = self.callback_quarantine_accounted;
        self.lifecycle = .dead;
        self.semantic_state = .{ .terminal = .{
            .reason = .invariant_failure,
            .fd_disposition = .owner_cleanup,
        } };
        self.owned_client = null;
        self.owned_evidence = null;
        self.client_transfer = .{};
        self.inbox_ledger = .{};
        self.prepared_adoption = .{ .lifecycle = .committed_tombstone };
        self.client_cleanup_take = .{};
        self.committed_screen = .{};
        self.live_partial = .terminal;
        self.live_screen = .{ .lifecycle = .cleaned_tombstone };
        self.completed_control = .terminal;
        self.owner_metadata = .{};
        self.owner_resize = .none;
        self.owner_authority = .empty;
        self.owner_authority_seal = .{};
        self.owner_request_ids = null;
        self.control_correlation = .{};
        self.owner_incarnation = 0;
        self.owner_incarnation_seal = .{};
        self.intent_scratch_reservation = .{
            .lifecycle = .poisoned_tombstone,
        };
        self.rx_aggregate_handle = .{ .lifecycle = .poisoned };
        self.rx_aggregate_reservation = .{
            .lifecycle = .poisoned_tombstone,
        };
        self.callback_quarantine_pending = false;
        self.callback_quarantine_accounted = false;
        if (!quarantine_already_accounted) latchCrossOwnerQuarantine();
        releaseActiveStorage(@intFromPtr(self));
    }

    fn commitRxAggregateUnchecked(
        self: *ExternalPumpStorage,
        aggregate: *PreparedRxAggregate,
        intent_handle: *external_rx_intent.ExternalRxIntentHandle,
        event_cleanup: *FrozenAggregateCleanup,
    ) RxAggregateCommitResult {
        var published: PublishedRxAggregateCommit = undefined;
        self.publishRxAggregateUnchecked(
            aggregate,
            intent_handle,
            event_cleanup,
            &published,
        );
        return self.finishPublishedRxAggregateCommit(
            aggregate,
            event_cleanup,
            &published,
            false,
        );
    }

    const RevokeCommitResult = enum {
        committed,
        protocol_terminal,
        invariant_terminal,
        protocol_terminal_cleaned,
        invariant_terminal_cleaned,
        quarantined,
    };

    // MARU_REVOKE_CONSUME_PUBLISH_BEGIN
    fn consumeAndPublishRevokedRxAggregate(
        self: *ExternalPumpStorage,
        scratch: *ExternalRxTurnScratch,
        intent_handle: *external_rx_intent.ExternalRxIntentHandle,
        external: *client_external_mode.State,
        binding: client_external_tx.OwnerBinding,
        aggregate: *PreparedRxAggregate,
        event_cleanup: *FrozenAggregateCleanup,
        response_take: *PreparedControlResponseTake,
        frozen_response: *FrozenControlResponse,
        frozen: *const FrozenRevokeCorrelation,
        cleanup_completed: bool,
        published: *PublishedRxAggregateCommit,
    ) bool {
        const projected_response = aggregate.response_destination.lifecycle == .prepared;
        // This is the single final checked boundary. Every operation after it is an infallible
        // scalar/owner publication; allocator callbacks are confined to the cleanup tail.
        if (!client_external_tx.consumePreparedCancellationUnderHeldLease(
            validateTxOwner,
            @ptrCast(self),
            &scratch.tx_cancellation,
            &scratch.tx_cancellation_permit,
            &scratch.tx_cancellation_cleanup,
            external,
            binding,
        )) return false;
        if (projected_response) {
            self.publishRxAggregateUnchecked(
                aggregate,
                intent_handle,
                event_cleanup,
                published,
            );
            // The checked prefix sealed the response destination and the aggregate's exact
            // destination program. Publication has just materialized that response as the sole
            // completed owner, so moving it into terminal cleanup is an infallible suffix.
            self.publishCompletedControlResponseUnchecked(frozen_response);
        } else {
            if (cleanup_completed)
                publishControlResponseTakeUnchecked(self, response_take, frozen_response);
            self.publishRxAggregateUnchecked(
                aggregate,
                intent_handle,
                event_cleanup,
                published,
            );
        }
        self.control_correlation.generation = frozen.generation + 1;
        self.control_correlation.state = .terminal;
        self.control_correlation.digest = controlCorrelationDigest(&self.control_correlation);
        return true;
    }
    // MARU_REVOKE_CONSUME_PUBLISH_END

    // MARU_REVOKE_PURE_VALIDATE_BEGIN
    fn validatePreparedRevokedRxAggregateGraph(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        intent_handle: *external_rx_intent.ExternalRxIntentHandle,
        external: *client_external_mode.State,
        graph_owner: *const PreparedRevokedCommitGraph,
    ) bool {
        const graph = graph_owner.storageConst();
        if (graph.saved_self_addr != @intFromPtr(graph_owner) or
            graph.storage_addr != @intFromPtr(self) or
            graph.lease_addr != @intFromPtr(lease) or
            graph.intent_handle_addr != @intFromPtr(intent_handle) or
            graph.external_addr != @intFromPtr(external) or
            graph.aggregate_addr == 0 or graph.lifecycle != .prepared or
            !std.mem.eql(u8, &graph.digest, &preparedRevokedCommitGraphDigest(graph)))
            return false;
        const aggregate: *PreparedRxAggregate = @ptrFromInt(graph.aggregate_addr);
        const cleanup_completed = graph.action == .cleanup_completed;
        const projected_response =
            aggregate.response_destination.lifecycle == .prepared;
        return client_external_tx.validateArmedCancellation(
            validateTxOwner,
            @ptrCast(self),
            &scratch.tx_cancellation,
            &scratch.tx_cancellation_permit,
            &scratch.tx_cancellation_cleanup,
            external,
            graph.binding,
        ) and graph.projected_response == projected_response and
            frozenRevokeCorrelationCurrent(self, &graph.correlation) and
            validateEventReduction(self, aggregate, intent_handle) and
            validateEventScalarDestinations(self, aggregate) and
            (!cleanup_completed or (projected_response and
                std.meta.eql(graph.response_take, PreparedControlResponseTake{}) and
                frozenControlResponsePristine(&graph.frozen_response)) or
                self.validateControlResponseTakeUnderHeldLease(
                    lease,
                    &graph.response_take,
                    &graph.frozen_response,
                ));
    }
    // MARU_REVOKE_PURE_VALIDATE_END

    fn cleanupFailedPreparedRevoke(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        intent_handle: *external_rx_intent.ExternalRxIntentHandle,
        external: *client_external_mode.State,
        graph_owner: *PreparedRevokedCommitGraph,
        tx_prepared: bool,
        failure: RevokeCommitResult,
    ) RevokeCommitResult {
        const graph = graph_owner.storage();
        var progress = revokedCleanupProgress(graph) orelse {
            return .quarantined;
        };
        if (progress == .empty) {
            progress = if (tx_prepared) .tx_abort_pending else .rx_abort_pending;
            graph.cleanup_progress = @intFromEnum(progress);
            graph.cleanup_failure = switch (failure) {
                .protocol_terminal, .protocol_terminal_cleaned => 1,
                else => 2,
            };
            graph.cleanup_digest = revokedCleanupProgressDigest(graph);
        } else if (graph.saved_self_addr != @intFromPtr(graph_owner) or
            graph.storage_addr != @intFromPtr(self) or
            graph.lease_addr != @intFromPtr(lease) or
            graph.intent_handle_addr != @intFromPtr(intent_handle) or
            graph.external_addr != @intFromPtr(external) or
            graph.aggregate_addr == 0 or
            (graph.cleanup_failure != 1 and graph.cleanup_failure != 2) or
            !std.mem.eql(u8, &graph.cleanup_digest, &revokedCleanupProgressDigest(graph)))
        {
            return .quarantined;
        }
        if (progress == .tx_abort_pending) {
            if (hitRevokeCleanupFailpoint(scratch, .before_tx_abort)) return .quarantined;
            if (!client_external_tx.abortPreparedCancellation(
                validateTxOwner,
                @ptrCast(self),
                &scratch.tx_cancellation,
                &scratch.tx_cancellation_permit,
                external,
                graph.binding,
            )) {
                return .quarantined;
            }
            progress = .tx_reset_pending;
            graph.cleanup_progress = @intFromEnum(progress);
            graph.cleanup_digest = revokedCleanupProgressDigest(graph);
        }
        if (progress == .tx_reset_pending) {
            if (hitRevokeCleanupFailpoint(scratch, .before_tx_reset)) return .quarantined;
            if (!client_external_tx.resetCancellationGraphForNextTurn(
                validateTxOwner,
                @ptrCast(self),
                &scratch.tx_cancellation,
                &scratch.tx_cancellation_permit,
                &scratch.tx_cancellation_cleanup,
                external,
                graph.binding,
            )) {
                return .quarantined;
            }
            progress = .rx_abort_pending;
            graph.cleanup_progress = @intFromEnum(progress);
            graph.cleanup_digest = revokedCleanupProgressDigest(graph);
        }
        if (progress != .rx_abort_pending) {
            return .quarantined;
        }
        if (hitRevokeCleanupFailpoint(scratch, .before_rx_abort)) return .quarantined;
        const cleanup_failure = graph.cleanup_failure;
        const cleanup_progress = graph.cleanup_progress;
        const cleanup_digest = graph.cleanup_digest;
        const rx_abort = self.abortRxAggregate(lease, intent_handle);
        if (rx_abort != .cleaned) {
            return .quarantined;
        }
        if (hitRevokeCleanupFailpoint(scratch, .after_rx_abort_graph_drift))
            graph.cleanup_failure = if (cleanup_failure == 1) 2 else 1;
        if (graph.cleanup_failure != cleanup_failure or
            graph.cleanup_progress != cleanup_progress or
            !std.mem.eql(u8, &graph.cleanup_digest, &cleanup_digest) or
            !std.mem.eql(
                u8,
                &graph.cleanup_digest,
                &revokedCleanupProgressDigest(graph),
            ))
        {
            // Both TX and RX owners are already closed. The callback-mutated graph is no longer a
            // cleanup capability, so erase it and report the drift through the quarantine latch.
            graph_owner.* = .{};
            latchCrossOwnerQuarantine();
            return .quarantined;
        }
        graph_owner.* = .{};
        return switch (cleanup_failure) {
            1 => .protocol_terminal_cleaned,
            else => .invariant_terminal_cleaned,
        };
    }

    fn resumeFailedPreparedRevokeCleanup(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
    ) bool {
        const graph_owner = &scratch.revoked_commit_graph;
        if (std.mem.allEqual(u8, &graph_owner.bytes, 0)) return true;
        const graph = graph_owner.storage();
        const progress = revokedCleanupProgress(graph) orelse {
            return false;
        };
        if (progress == .empty or
            graph.saved_self_addr != @intFromPtr(graph_owner) or
            graph.storage_addr != @intFromPtr(self) or
            graph.lease_addr != @intFromPtr(lease) or
            graph.aggregate_addr == 0 or
            (graph.cleanup_failure != 1 and graph.cleanup_failure != 2) or
            !std.mem.eql(
                u8,
                &graph.cleanup_digest,
                &revokedCleanupProgressDigest(graph),
            ))
        {
            return false;
        }
        const client = if (self.owned_client) |*owned| owned else {
            return false;
        };
        const external = switch (client.io_mode) {
            .external => |*state| state,
            .blocking => {
                return false;
            },
        };
        const intent_handle = &scratch.traversal.intent;
        const expected_binding = makeTxOwnerBinding(
            self,
            client,
            external,
            lease,
            @intFromPtr(scratch),
            @sizeOf(ExternalRxTurnScratch),
            @intFromPtr(&scratch.tx_cancellation),
            @sizeOf(client_external_tx.PreparedTxCancellation),
            .cancel_turn,
        );
        if (graph.external_addr != @intFromPtr(external) or
            graph.intent_handle_addr != @intFromPtr(intent_handle) or
            !std.meta.eql(graph.binding, expected_binding))
        {
            return false;
        }
        const failure: RevokeCommitResult = if (graph.cleanup_failure == 1)
            .protocol_terminal
        else
            .invariant_terminal;
        const replay_result = self.cleanupFailedPreparedRevoke(
            lease,
            scratch,
            intent_handle,
            external,
            graph_owner,
            progress == .tx_abort_pending,
            failure,
        );
        return switch (replay_result) {
            .protocol_terminal_cleaned, .invariant_terminal_cleaned => true,
            else => false,
        };
    }

    /// Converts an untrusted or repeatedly failing inline cleanup capability into the process-wide
    /// bounded quarantine contract. The retained RX/TX owners remain under canonical storage
    /// teardown authority; clearing only these caller-owned proofs prevents a later dereference or
    /// replay under a different whole-turn lease. This leaf is callback-free by construction.
    fn quarantineFailedPreparedRevokeCleanup(
        _: *ExternalPumpStorage,
        scratch: *ExternalRxTurnScratch,
    ) void {
        latchCrossOwnerQuarantine();
        scratch.tx_cancellation = .{};
        scratch.tx_cancellation_permit = .{};
        scratch.tx_cancellation_cleanup = .{};
        scratch.revoked_commit_graph = .{};
        scratch.post_cancellation_receipt = .{};
    }

    const ControlCleanupPublicationSnapshot = struct {
        lifecycle: StorageLifecycle,
        saved_self_addr: usize,
        owner_incarnation: u64,
        owner_incarnation_seal: OwnerIncarnationSeal,
        operation_generation: u64,
        operation_reentry_latched: bool,
        correlation: ControlCorrelationOwner,
        authority: OwnerAuthorityState,
        authority_seal: OwnerAuthoritySeal,
        completed_generation: u64,
        semantic: client_pump.ExternalPumpState,
        intent_reservation: IntentScratchReservation,
        aggregate_handle: PreparedRxAggregateHandle,
        aggregate_reservation: RxAggregateScratchReservation,
    };

    fn captureControlCleanupPublicationSnapshot(
        self: *const ExternalPumpStorage,
    ) ControlCleanupPublicationSnapshot {
        return .{
            .lifecycle = self.lifecycle,
            .saved_self_addr = self.saved_self_addr,
            .owner_incarnation = self.owner_incarnation,
            .owner_incarnation_seal = self.owner_incarnation_seal,
            .operation_generation = self.operation_generation,
            .operation_reentry_latched = self.operation_reentry_latched,
            .correlation = self.control_correlation,
            .authority = self.owner_authority,
            .authority_seal = self.owner_authority_seal,
            .completed_generation = self.completed_control_generation,
            .semantic = self.semantic_state,
            .intent_reservation = self.intent_scratch_reservation,
            .aggregate_handle = self.rx_aggregate_handle,
            .aggregate_reservation = self.rx_aggregate_reservation,
        };
    }

    // MARU_CLEANUP_CANONICAL_WRITER_BEGIN
    fn detectAndRestoreControlCleanupPublicationDrift(
        self: *ExternalPumpStorage,
        canonical: ControlCleanupPublicationSnapshot,
    ) bool {
        const drifted = self.lifecycle != canonical.lifecycle or
            self.saved_self_addr != canonical.saved_self_addr or
            self.owner_incarnation != canonical.owner_incarnation or
            !std.meta.eql(self.owner_incarnation_seal, canonical.owner_incarnation_seal) or
            self.operation_generation != canonical.operation_generation or
            self.operation_reentry_latched != canonical.operation_reentry_latched or
            !std.meta.eql(self.control_correlation, canonical.correlation) or
            !std.meta.eql(self.owner_authority, canonical.authority) or
            !std.meta.eql(self.owner_authority_seal, canonical.authority_seal) or
            self.completed_control != .none or
            self.completed_control_generation != canonical.completed_generation or
            !std.meta.eql(self.semantic_state, canonical.semantic) or
            !std.meta.eql(
                self.intent_scratch_reservation,
                canonical.intent_reservation,
            ) or !std.meta.eql(
            self.rx_aggregate_handle,
            canonical.aggregate_handle,
        ) or !std.meta.eql(
            self.rx_aggregate_reservation,
            canonical.aggregate_reservation,
        );
        if (!drifted) return false;
        self.lifecycle = canonical.lifecycle;
        self.saved_self_addr = canonical.saved_self_addr;
        self.owner_incarnation = canonical.owner_incarnation;
        self.owner_incarnation_seal = canonical.owner_incarnation_seal;
        self.operation_generation = canonical.operation_generation;
        self.operation_reentry_latched = canonical.operation_reentry_latched;
        self.control_correlation = canonical.correlation;
        self.owner_authority = canonical.authority;
        self.owner_authority_seal = canonical.authority_seal;
        self.completed_control = .none;
        self.completed_control_generation = canonical.completed_generation;
        self.semantic_state = canonical.semantic;
        self.intent_scratch_reservation = canonical.intent_reservation;
        self.rx_aggregate_handle = canonical.aggregate_handle;
        self.rx_aggregate_reservation = canonical.aggregate_reservation;
        return true;
    }

    const ControlSemanticTerminalCleanupSnapshot = struct {
        storage: ControlCleanupPublicationSnapshot,
        scratch_saved_self_addr: usize,
        scratch_lifecycle: ExternalRxTurnScratchLifecycle,
        turn_generation: u64,
        canonical_drain: RxDrainEvidence,
        terminal: PreparedControlSemanticTerminal,
        binding: PreparedControlSemanticTerminalBinding,
        take: PreparedControlResponseTake,
        frozen: FrozenControlResponse,
        parser_seal: client_external_mode.ParserAuthoritySeal,
        tx_queue_generation: u64,
    };

    const ResizeSemanticCleanupSnapshot = struct {
        storage: ControlCleanupPublicationSnapshot,
        owner_resize: OwnerResizeState,
        scratch_saved_self_addr: usize,
        scratch_lifecycle: ExternalRxTurnScratchLifecycle,
        turn_generation: u64,
        canonical_drain: RxDrainEvidence,
        permit: PreparedWholeDrainPermit,
        verdict: PreparedControlSemanticVerdict,
        wrapper: PreparedControlSemanticTake,
        receipt: PreparedResizeSemanticCommit,
        take: PreparedControlResponseTake,
        frozen: FrozenControlResponse,
        parser_seal: client_external_mode.ParserAuthoritySeal,
        tx_queue_generation: u64,
    };

    const ResyncSemanticCleanupSnapshot = struct {
        storage: ControlCleanupPublicationSnapshot,
        scratch_saved_self_addr: usize,
        scratch_lifecycle: ExternalRxTurnScratchLifecycle,
        turn_generation: u64,
        canonical_drain: RxDrainEvidence,
        permit: PreparedWholeDrainPermit,
        verdict: PreparedControlSemanticVerdict,
        transition: PreparedResyncAckTransition,
        projected: ProjectedRecoverySnapshotCommit,
        receipt: PreparedResyncSemanticCommit,
        wrapper: PreparedControlSemanticTake,
        take: PreparedControlResponseTake,
        frozen: FrozenControlResponse,
        parser_seal: client_external_mode.ParserAuthoritySeal,
        tx_queue_generation: u64,
        ledger_projection_digest: external_owner_seal.Digest,
        aggregate_present: bool,
        aggregate_addr: usize,
        aggregate_digest: external_owner_seal.Digest,
        aggregate_recovery_commit_digest: external_owner_seal.Digest,
        aggregate_recovery_output_digest: external_owner_seal.Digest,
        aggregate_recovery_binding_digest: external_owner_seal.Digest,
        aggregate_recovery_dispositions_digest: external_owner_seal.Digest,
    };

    comptime {
        if (@sizeOf(ProjectedRecoverySnapshotCommit) > 256 * 1024)
            @compileError("F3c2 projected commit exceeded its 256 KiB stack-object budget");
        // prepare -> validate -> ledger planning may keep three projected-sized values live.
        if (@sizeOf(ProjectedRecoverySnapshotCommit) * 3 > 1024 * 1024)
            @compileError("F3c2 projected validation exceeded its 1 MiB nested stack budget");
        if (@sizeOf(ResyncSemanticCleanupSnapshot) > 512 * 1024)
            @compileError("F3c2 cleanup snapshot exceeded its 512 KiB stack-object budget");
    }

    fn captureResizeSemanticCleanupSnapshot(
        self: *const ExternalPumpStorage,
        scratch: *const ExternalRxTurnScratch,
        frozen: *const FrozenControlResponse,
    ) ResizeSemanticCleanupSnapshot {
        const client = &self.owned_client.?;
        const external = switch (client.io_mode) {
            .external => |*state| state,
            .blocking => unreachable,
        };
        var expected_frozen = frozen.*;
        expected_frozen.payload = external_inbox_ledger.OwnedPayload.empty(
            frozen.payload.allocator,
        );
        expected_frozen.lifecycle = .cleaned_tombstone;
        expected_frozen.digest = frozenControlResponseDigest(&expected_frozen);
        return .{
            .storage = self.captureControlCleanupPublicationSnapshot(),
            .owner_resize = self.owner_resize,
            .scratch_saved_self_addr = scratch.saved_self_addr,
            .scratch_lifecycle = scratch.lifecycle,
            .turn_generation = scratch.turn_generation,
            .canonical_drain = scratch.drain_evidence,
            .permit = scratch.whole_drain_permit,
            .verdict = scratch.control_semantic_verdict,
            .wrapper = scratch.control_semantic_take,
            .receipt = scratch.resize_semantic_commit,
            .take = scratch.resize_semantic_response_take,
            .frozen = expected_frozen,
            .parser_seal = external.rx_provenance.parser_seal,
            .tx_queue_generation = external.tx_queue_generation,
        };
    }

    fn detectAndRestoreResizeSemanticCleanupDrift(
        self: *ExternalPumpStorage,
        scratch: *ExternalRxTurnScratch,
        canonical: ResizeSemanticCleanupSnapshot,
    ) bool {
        var drifted = self.detectAndRestoreControlCleanupPublicationDrift(
            canonical.storage,
        );
        if (!std.meta.eql(self.owner_resize, canonical.owner_resize)) {
            self.owner_resize = canonical.owner_resize;
            drifted = true;
        }
        const client = if (self.owned_client) |*owned| owned else {
            drifted = true;
            scratch.saved_self_addr = canonical.scratch_saved_self_addr;
            scratch.lifecycle = canonical.scratch_lifecycle;
            scratch.turn_generation = canonical.turn_generation;
            restoreTerminalCleanupDrainEvidenceUnchecked(
                &scratch.drain_evidence,
                canonical.canonical_drain,
            );
            scratch.whole_drain_permit = canonical.permit;
            scratch.control_semantic_verdict = canonical.verdict;
            scratch.control_semantic_take = canonical.wrapper;
            scratch.resize_semantic_commit = canonical.receipt;
            scratch.resize_semantic_response_take = canonical.take;
            scratch.resize_semantic_frozen_response = canonical.frozen;
            return drifted;
        };
        const external_current = switch (client.io_mode) {
            .external => |*state| blk: {
                const current = std.meta.eql(
                    state.rx_provenance.parser_seal,
                    canonical.parser_seal,
                ) and client_external_mode.parserSealValid(state, &client.parser) and
                    state.tx_queue_generation == canonical.tx_queue_generation;
                if (!current) {
                    state.rx_provenance.parser_seal = canonical.parser_seal;
                    state.tx_queue_generation = canonical.tx_queue_generation;
                }
                break :blk current;
            },
            .blocking => false,
        };
        if (!external_current or
            scratch.saved_self_addr != canonical.scratch_saved_self_addr or
            scratch.lifecycle != canonical.scratch_lifecycle or
            scratch.turn_generation != canonical.turn_generation or
            !std.meta.eql(scratch.drain_evidence, canonical.canonical_drain) or
            !std.meta.eql(scratch.whole_drain_permit, canonical.permit) or
            !std.meta.eql(scratch.control_semantic_verdict, canonical.verdict) or
            !std.meta.eql(scratch.control_semantic_take, canonical.wrapper) or
            !std.meta.eql(scratch.resize_semantic_commit, canonical.receipt) or
            !std.meta.eql(scratch.resize_semantic_response_take, canonical.take) or
            !frozenControlResponseMatchesExpectedCleaned(
                &scratch.resize_semantic_frozen_response,
                &canonical.frozen,
            )) drifted = true;
        if (drifted) {
            scratch.saved_self_addr = canonical.scratch_saved_self_addr;
            scratch.lifecycle = canonical.scratch_lifecycle;
            scratch.turn_generation = canonical.turn_generation;
            restoreTerminalCleanupDrainEvidenceUnchecked(
                &scratch.drain_evidence,
                canonical.canonical_drain,
            );
            scratch.whole_drain_permit = canonical.permit;
            scratch.control_semantic_verdict = canonical.verdict;
            scratch.control_semantic_take = canonical.wrapper;
            scratch.resize_semantic_commit = canonical.receipt;
            scratch.resize_semantic_response_take = canonical.take;
            scratch.resize_semantic_frozen_response = canonical.frozen;
        }
        return drifted;
    }

    fn captureResyncSemanticCleanupSnapshot(
        self: *const ExternalPumpStorage,
        scratch: *const ExternalRxTurnScratch,
        aggregate: ?*PreparedRxAggregate,
        frozen: *const FrozenControlResponse,
    ) ResyncSemanticCleanupSnapshot {
        const client = &self.owned_client.?;
        const external = switch (client.io_mode) {
            .external => |*state| state,
            .blocking => unreachable,
        };
        var expected_frozen = frozen.*;
        expected_frozen.payload = external_inbox_ledger.OwnedPayload.empty(
            frozen.payload.allocator,
        );
        expected_frozen.lifecycle = .cleaned_tombstone;
        expected_frozen.digest = frozenControlResponseDigest(&expected_frozen);
        var aggregate_digest = [_]u8{0} ** 32;
        var aggregate_recovery_commit_digest = [_]u8{0} ** 32;
        var aggregate_recovery_output_digest = [_]u8{0} ** 32;
        var aggregate_recovery_binding_digest = [_]u8{0} ** 32;
        var aggregate_recovery_dispositions_digest = [_]u8{0} ** 32;
        if (aggregate) |value| {
            // Predict the sole callback-owned mutation without copying the pointer-bearing
            // aggregate. The original retirement is restored before any allocator callback.
            const retirement = value.retirement;
            value.retirement = .{ .lifecycle = .retired };
            aggregate_digest = preparedRxAggregateDigest(value);
            value.retirement = retirement;
            // The aggregate seal contains the child seals, not every child field. Preserve
            // independently recomputed child digests so a callback cannot mutate a pointer and
            // leave its stale child seal looking canonical to the aggregate-level recomputation.
            aggregate_recovery_commit_digest = preparedRecoverySnapshotCommitDigest(
                &value.recovery_snapshot_commit,
            );
            aggregate_recovery_output_digest = immutableRecoveryCommitOutputDigest(
                &value.recovery_commit_output,
            );
            aggregate_recovery_binding_digest = committedRecoverySnapshotBindingDigest(
                &value.recovery_snapshot_binding,
            );
            aggregate_recovery_dispositions_digest = recoverySnapshotDispositionRootDigest(
                &value.recovery_dispositions,
            );
        }
        return .{
            .storage = self.captureControlCleanupPublicationSnapshot(),
            .scratch_saved_self_addr = scratch.saved_self_addr,
            .scratch_lifecycle = scratch.lifecycle,
            .turn_generation = scratch.turn_generation,
            .canonical_drain = scratch.drain_evidence,
            .permit = scratch.whole_drain_permit,
            .verdict = scratch.control_semantic_verdict,
            .transition = scratch.resync_ack_transition,
            .projected = scratch.projected_recovery_snapshot_commit,
            .receipt = scratch.resync_semantic_commit,
            .wrapper = scratch.control_semantic_take,
            .take = scratch.resync_ack_response_take,
            .frozen = expected_frozen,
            .parser_seal = external.rx_provenance.parser_seal,
            .tx_queue_generation = external.tx_queue_generation,
            .ledger_projection_digest = self.inbox_ledger.projectionAuthorityDigest(),
            .aggregate_present = aggregate != null,
            .aggregate_addr = if (aggregate) |value| @intFromPtr(value) else 0,
            .aggregate_digest = aggregate_digest,
            .aggregate_recovery_commit_digest = aggregate_recovery_commit_digest,
            .aggregate_recovery_output_digest = aggregate_recovery_output_digest,
            .aggregate_recovery_binding_digest = aggregate_recovery_binding_digest,
            .aggregate_recovery_dispositions_digest = aggregate_recovery_dispositions_digest,
        };
    }

    /// The allocator callback is untrusted.  Scalar storage authority can use the existing
    /// canonical restorer, but a changed ledger or aggregate is never copied back: those values
    /// contain ownership-bearing pointers and are handed to bounded quarantine instead.
    fn detectResyncSemanticCleanupDrift(
        self: *ExternalPumpStorage,
        scratch: *ExternalRxTurnScratch,
        aggregate: ?*PreparedRxAggregate,
        canonical: ResyncSemanticCleanupSnapshot,
    ) bool {
        var drifted = self.detectAndRestoreControlCleanupPublicationDrift(
            canonical.storage,
        );
        const client = if (self.owned_client) |*owned| owned else return true;
        const external_current = switch (client.io_mode) {
            .external => |*state| std.meta.eql(
                state.rx_provenance.parser_seal,
                canonical.parser_seal,
            ) and client_external_mode.parserSealValid(state, &client.parser) and
                state.tx_queue_generation == canonical.tx_queue_generation,
            .blocking => false,
        };
        const aggregate_current = canonical.aggregate_present == (aggregate != null) and
            canonical.aggregate_addr == (if (aggregate) |value| @intFromPtr(value) else 0) and
            (if (aggregate) |value|
                value.lifecycle == .side_intent_consumed and
                    value.retirement.lifecycle == .retired and
                    std.mem.eql(
                        u8,
                        &canonical.aggregate_digest,
                        &preparedRxAggregateDigest(value),
                    ) and std.mem.eql(
                    u8,
                    &canonical.aggregate_recovery_commit_digest,
                    &preparedRecoverySnapshotCommitDigest(&value.recovery_snapshot_commit),
                ) and std.mem.eql(
                    u8,
                    &canonical.aggregate_recovery_output_digest,
                    &immutableRecoveryCommitOutputDigest(&value.recovery_commit_output),
                ) and std.mem.eql(
                    u8,
                    &canonical.aggregate_recovery_binding_digest,
                    &committedRecoverySnapshotBindingDigest(&value.recovery_snapshot_binding),
                ) and std.mem.eql(
                    u8,
                    &canonical.aggregate_recovery_dispositions_digest,
                    &recoverySnapshotDispositionRootDigest(&value.recovery_dispositions),
                )
            else
                std.mem.allEqual(u8, &canonical.aggregate_digest, 0) and
                    std.mem.allEqual(u8, &canonical.aggregate_recovery_commit_digest, 0) and
                    std.mem.allEqual(u8, &canonical.aggregate_recovery_output_digest, 0) and
                    std.mem.allEqual(u8, &canonical.aggregate_recovery_binding_digest, 0) and
                    std.mem.allEqual(u8, &canonical.aggregate_recovery_dispositions_digest, 0));
        if (!external_current or !aggregate_current or
            !std.mem.eql(
                u8,
                &self.inbox_ledger.projectionAuthorityDigest(),
                &canonical.ledger_projection_digest,
            ) or scratch.saved_self_addr != canonical.scratch_saved_self_addr or
            scratch.lifecycle != canonical.scratch_lifecycle or
            scratch.turn_generation != canonical.turn_generation or
            !std.meta.eql(scratch.drain_evidence, canonical.canonical_drain) or
            !std.meta.eql(scratch.whole_drain_permit, canonical.permit) or
            !std.meta.eql(scratch.control_semantic_verdict, canonical.verdict) or
            !std.meta.eql(scratch.resync_ack_transition, canonical.transition) or
            !std.meta.eql(scratch.projected_recovery_snapshot_commit, canonical.projected) or
            !std.meta.eql(scratch.resync_semantic_commit, canonical.receipt) or
            !std.meta.eql(scratch.control_semantic_take, canonical.wrapper) or
            !std.meta.eql(scratch.resync_ack_response_take, canonical.take) or
            !frozenControlResponseMatchesExpectedCleaned(
                &scratch.resync_ack_frozen_response,
                &canonical.frozen,
            )) drifted = true;
        if (!drifted) if (aggregate) |value| {
            // Only seal the precomputed canonical state. Never authenticate callback mutations.
            value.digest = canonical.aggregate_digest;
        };
        return drifted;
    }

    fn captureControlSemanticTerminalCleanupSnapshot(
        self: *const ExternalPumpStorage,
        scratch: *const ExternalRxTurnScratch,
        frozen: *const FrozenControlResponse,
    ) ControlSemanticTerminalCleanupSnapshot {
        const client = &self.owned_client.?;
        const external = switch (client.io_mode) {
            .external => |*state| state,
            .blocking => unreachable,
        };
        var expected_frozen = frozen.*;
        expected_frozen.payload = external_inbox_ledger.OwnedPayload.empty(
            frozen.payload.allocator,
        );
        expected_frozen.lifecycle = .cleaned_tombstone;
        expected_frozen.digest = frozenControlResponseDigest(&expected_frozen);
        return .{
            .storage = self.captureControlCleanupPublicationSnapshot(),
            .scratch_saved_self_addr = scratch.saved_self_addr,
            .scratch_lifecycle = scratch.lifecycle,
            .turn_generation = scratch.turn_generation,
            .canonical_drain = scratch.drain_evidence,
            .terminal = scratch.control_semantic_terminal,
            .binding = scratch.control_semantic_terminal_binding,
            .take = scratch.control_terminal_response_take,
            .frozen = expected_frozen,
            .parser_seal = external.rx_provenance.parser_seal,
            .tx_queue_generation = external.tx_queue_generation,
        };
    }

    fn frozenControlResponseMatchesExpectedCleaned(
        actual: *const FrozenControlResponse,
        expected: *const FrozenControlResponse,
    ) bool {
        return actual.saved_self_addr == expected.saved_self_addr and
            actual.storage_addr == expected.storage_addr and
            actual.owner_incarnation == expected.owner_incarnation and
            actual.correlation_generation == expected.correlation_generation and
            actual.kind == expected.kind and
            std.meta.eql(actual.expectation, expected.expectation) and
            actual.target_stream_id == expected.target_stream_id and
            actual.expected_controller_generation == expected.expected_controller_generation and
            actual.request_id == expected.request_id and
            actual.wire_len == expected.wire_len and
            actual.payload.allocation_ptr == null and actual.payload.logical_len == 0 and
            actual.payload.allocator.ptr == expected.payload.allocator.ptr and
            actual.payload.allocator.vtable == expected.payload.allocator.vtable and
            std.meta.eql(actual.payload_seal, expected.payload_seal) and
            actual.lifecycle == .cleaned_tombstone and
            std.mem.eql(u8, &actual.digest, &expected.digest);
    }

    fn detectAndRestoreControlSemanticTerminalCleanupDrift(
        self: *ExternalPumpStorage,
        scratch: *ExternalRxTurnScratch,
        canonical: ControlSemanticTerminalCleanupSnapshot,
    ) bool {
        var drifted = self.detectAndRestoreControlCleanupPublicationDrift(
            canonical.storage,
        );
        const client = if (self.owned_client) |*owned| owned else {
            drifted = true;
            scratch.saved_self_addr = canonical.scratch_saved_self_addr;
            scratch.lifecycle = canonical.scratch_lifecycle;
            scratch.turn_generation = canonical.turn_generation;
            restoreTerminalCleanupDrainEvidenceUnchecked(
                &scratch.drain_evidence,
                canonical.canonical_drain,
            );
            scratch.control_semantic_terminal = canonical.terminal;
            scratch.control_semantic_terminal_binding = canonical.binding;
            scratch.control_terminal_response_take = canonical.take;
            scratch.control_terminal_frozen_response = canonical.frozen;
            return drifted;
        };
        const external_current = switch (client.io_mode) {
            .external => |*state| blk: {
                const current = std.meta.eql(
                    state.rx_provenance.parser_seal,
                    canonical.parser_seal,
                ) and client_external_mode.parserSealValid(state, &client.parser) and
                    state.tx_queue_generation == canonical.tx_queue_generation;
                if (!current) {
                    state.rx_provenance.parser_seal = canonical.parser_seal;
                    state.tx_queue_generation = canonical.tx_queue_generation;
                }
                break :blk current;
            },
            .blocking => false,
        };
        if (!external_current or
            scratch.saved_self_addr != canonical.scratch_saved_self_addr or
            scratch.lifecycle != canonical.scratch_lifecycle or
            scratch.turn_generation != canonical.turn_generation or
            !std.meta.eql(scratch.drain_evidence, canonical.canonical_drain) or
            !std.meta.eql(scratch.control_semantic_terminal, canonical.terminal) or
            !std.meta.eql(scratch.control_semantic_terminal_binding, canonical.binding) or
            !std.meta.eql(scratch.control_terminal_response_take, canonical.take) or
            !frozenControlResponseMatchesExpectedCleaned(
                &scratch.control_terminal_frozen_response,
                &canonical.frozen,
            ))
            drifted = true;
        if (drifted) {
            scratch.saved_self_addr = canonical.scratch_saved_self_addr;
            scratch.lifecycle = canonical.scratch_lifecycle;
            scratch.turn_generation = canonical.turn_generation;
            restoreTerminalCleanupDrainEvidenceUnchecked(
                &scratch.drain_evidence,
                canonical.canonical_drain,
            );
            scratch.control_semantic_terminal = canonical.terminal;
            scratch.control_semantic_terminal_binding = canonical.binding;
            scratch.control_terminal_response_take = canonical.take;
            scratch.control_terminal_frozen_response = canonical.frozen;
        }
        return drifted;
    }

    /// Cleanup callbacks run after the terminal publication point, so an allocator can corrupt the
    /// already-consumed proof even though normal lifecycle reset is no longer legal. This private
    /// recovery writer restores only the previously authenticated byte-for-byte snapshot and is
    /// followed by process-wide quarantine; it cannot manufacture a new drain capability.
    fn restoreTerminalCleanupDrainEvidenceUnchecked(
        destination: *RxDrainEvidence,
        canonical: RxDrainEvidence,
    ) void {
        destination.* = canonical;
    }
    // MARU_CLEANUP_CANONICAL_WRITER_END

    // MARU_REVOKE_CALLBACK_TAIL_BEGIN
    fn finishRevokedRxAggregateCallbacks(
        self: *ExternalPumpStorage,
        scratch: *ExternalRxTurnScratch,
        graph_owner: *PreparedRevokedCommitGraph,
        external: *client_external_mode.State,
        binding: client_external_tx.OwnerBinding,
        aggregate: *PreparedRxAggregate,
        event_cleanup: *FrozenAggregateCleanup,
        frozen_response: *FrozenControlResponse,
        cleanup_completed: bool,
        published: *const PublishedRxAggregateCommit,
    ) RevokeCommitResult {
        defer graph_owner.* = .{};
        const canonical = self.captureControlCleanupPublicationSnapshot();
        const tx_cleanup = client_external_tx.finishCancellationCleanup(
            validateTxOwner,
            @ptrCast(self),
            &scratch.tx_cancellation,
            &scratch.tx_cancellation_permit,
            &scratch.tx_cancellation_cleanup,
            external,
            binding,
        );
        const tx_reset = tx_cleanup == .cleaned and
            client_external_tx.resetCancellationGraphForNextTurn(
                validateTxOwner,
                @ptrCast(self),
                &scratch.tx_cancellation,
                &scratch.tx_cancellation_permit,
                &scratch.tx_cancellation_cleanup,
                external,
                binding,
            );
        const tx_receipt_captured = tx_reset and
            client_external_tx.capturePostCancellationReceipt(
                &scratch.post_cancellation_receipt,
                &scratch.tx_cancellation,
                &scratch.tx_cancellation_permit,
                &scratch.tx_cancellation_cleanup,
                external,
            );
        if (cleanup_completed)
            finishControlResponsePayloadCleanupUnchecked(frozen_response);
        var publication_drift = self.detectAndRestoreControlCleanupPublicationDrift(canonical);
        const rx_result = self.finishPublishedRxAggregateCommit(
            aggregate,
            event_cleanup,
            published,
            true,
        );
        const tx_post_callback = if (tx_receipt_captured)
            client_external_tx.consumePostCancellationReceipt(
                &scratch.post_cancellation_receipt,
                &scratch.tx_cancellation,
                &scratch.tx_cancellation_permit,
                &scratch.tx_cancellation_cleanup,
                external,
            )
        else
            .invalid;
        if (self.detectAndRestoreControlCleanupPublicationDrift(canonical))
            publication_drift = true;
        scratch.post_cancellation_receipt = .{};
        if (tx_post_callback != .valid) publication_drift = true;
        if (rx_result == .quarantined or tx_cleanup == .quarantined or publication_drift) {
            latchCrossOwnerQuarantine();
            return .quarantined;
        }
        if (rx_result != .committed or tx_cleanup != .cleaned or !tx_reset)
            return .invariant_terminal;
        return .committed;
    }
    // MARU_REVOKE_CALLBACK_TAIL_END

    fn prepareRevokedCommitGraph(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        intent_handle: *external_rx_intent.ExternalRxIntentHandle,
        now_ns: i128,
    ) ?RevokeCommitResult {
        const graph_owner = &scratch.revoked_commit_graph;
        if (!std.mem.allEqual(u8, &graph_owner.bytes, 0)) return .invariant_terminal;
        var graph_prepared = false;
        var aggregate_prepared = false;
        defer {
            if (!graph_prepared and !aggregate_prepared) graph_owner.* = .{};
        }
        const graph = graph_owner.storage();
        graph.* = .{};
        graph.saved_self_addr = @intFromPtr(graph_owner);
        graph.storage_addr = @intFromPtr(self);
        graph.lease_addr = @intFromPtr(lease);
        graph.intent_handle_addr = @intFromPtr(intent_handle);
        const client = if (self.owned_client) |*owned| owned else return .invariant_terminal;
        const external = switch (client.io_mode) {
            .external => |*state| state,
            .blocking => return .invariant_terminal,
        };
        var cleanup_owner_proof = RevokedCleanupOwnerProof{
            .saved_self_addr = undefined,
            .scratch_addr = @intFromPtr(scratch),
            .scratch_len = @sizeOf(ExternalRxTurnScratch),
            .graph_addr = @intFromPtr(graph_owner),
            .graph_len = @sizeOf(PreparedRevokedCommitGraph),
            .cleanup_addr = @intFromPtr(&graph.event_cleanup),
            .lease_addr = @intFromPtr(lease),
            .storage_addr = @intFromPtr(self),
            .owner_incarnation = self.owner_incarnation,
            .digest = undefined,
        };
        cleanup_owner_proof.saved_self_addr = @intFromPtr(&cleanup_owner_proof);
        cleanup_owner_proof.digest = revokedCleanupOwnerProofDigest(&cleanup_owner_proof);
        const aggregate = self.validateAndPrepareRxAggregateCommit(
            lease,
            intent_handle,
            &graph.event_cleanup,
            &cleanup_owner_proof,
        ) orelse return .invariant_terminal;
        aggregate_prepared = true;
        graph.aggregate_addr = @intFromPtr(aggregate);
        graph.projected_response =
            aggregate.response_destination.lifecycle == .prepared;
        if (hitRevokePrepareFailpoint(scratch, .after_aggregate))
            return self.cleanupFailedPreparedRevoke(lease, scratch, intent_handle, external, graph_owner, false, .invariant_terminal);
        const cancellation_graph_pristine =
            std.mem.allEqual(u8, &scratch.tx_cancellation.bytes, 0) and
            std.mem.allEqual(u8, &scratch.tx_cancellation_permit.bytes, 0) and
            std.mem.allEqual(u8, &scratch.tx_cancellation_cleanup.bytes, 0);
        const correlation_valid = controlCorrelationValid(self);
        const correlation_generation_valid =
            self.control_correlation.generation != std.math.maxInt(u64);

        const correlation_completed = graph.projected_response or
            self.completed_control != .none or switch (self.control_correlation.state) {
            .completed => true,
            else => false,
        };
        const actual_control_progress: client_pump.F3ControlProgress = if (!correlation_valid)
            .invalid
        else switch (self.control_correlation.state) {
            .idle => .none,
            .in_flight => |control| switch (control.progress) {
                .partial => .partial,
                .response_wait => .response_wait,
                .queued => switch (client_external_tx.requestFrameProgress(
                    external,
                    control.request_id,
                    control.wire_len,
                )) {
                    .queued => .queued,
                    .partial => .partial,
                    .missing => .missing,
                    .invalid => .invalid,
                },
            },
            .completed => if (self.completed_control != .none) .none else .fully_sent,
            .terminal => .invalid,
        };
        const control_progress: client_pump.F3ControlProgress =
            if (graph.projected_response) .none else actual_control_progress;
        const revoke_plan = client_pump.planRevokeIntegration(.{
            .causes = .{
                .invariant_or_corruption = !cancellation_graph_pristine or
                    !correlation_valid or !correlation_generation_valid,
                .exact_revoke = true,
            },
            .completed_present = correlation_completed,
            .control = control_progress,
        });
        const cleanup_completed = revoke_plan.action == .cleanup_completed;
        if ((!cleanup_completed and revoke_plan.action != .cancel_queued) or
            !revoke_plan.suppress_tx or
            revoke_plan.bounded_rx_required or
            revoke_plan.terminal == null or
            revoke_plan.terminal.?.reason != .revoked)
        {
            const failure: RevokeCommitResult = if (revoke_plan.terminal != null and
                revoke_plan.terminal.?.reason == .invariant_failure)
                .invariant_terminal
            else
                .protocol_terminal;
            return self.cleanupFailedPreparedRevoke(
                lease,
                scratch,
                intent_handle,
                external,
                graph_owner,
                false,
                failure,
            );
        }
        const reduced = switch (aggregate.event_reduction.outcome) {
            .revoked => |state| state,
            else => return self.cleanupFailedPreparedRevoke(
                lease,
                scratch,
                intent_handle,
                external,
                graph_owner,
                false,
                .invariant_terminal,
            ),
        };
        if (aggregate.event_reduction.authority.role != .controller or
            aggregate.authority_destination.lifecycle != .prepared)
            return self.cleanupFailedPreparedRevoke(lease, scratch, intent_handle, external, graph_owner, false, .invariant_terminal);
        const controller_generation = switch (aggregate.event_reduction.authority.generation) {
            .tracked => |generation| generation,
            .untracked => {
                return self.cleanupFailedPreparedRevoke(lease, scratch, intent_handle, external, graph_owner, false, .protocol_terminal);
            },
        };
        if (reduced.authority.role != .observer) {
            return self.cleanupFailedPreparedRevoke(lease, scratch, intent_handle, external, graph_owner, false, .protocol_terminal);
        }

        if (cleanup_completed and !graph.projected_response) {
            if (!self.prepareControlResponseTakeUnderHeldLease(
                lease,
                &graph.response_take,
            )) {
                return self.cleanupFailedPreparedRevoke(lease, scratch, intent_handle, external, graph_owner, false, .invariant_terminal);
            }
            if (!self.validateControlResponseTakeUnderHeldLease(
                lease,
                &graph.response_take,
                &graph.frozen_response,
            )) {
                return self.cleanupFailedPreparedRevoke(lease, scratch, intent_handle, external, graph_owner, false, .invariant_terminal);
            }
        }

        const frozen = &graph.correlation;
        frozen.saved_self_addr = @intFromPtr(frozen);
        frozen.storage_addr = @intFromPtr(self);
        frozen.generation = self.control_correlation.generation;
        frozen.owner_digest = self.control_correlation.digest;
        frozen.projected_response = graph.projected_response;
        const cancellation_spec: client_external_tx.CancellationSpec = switch (self.control_correlation.state) {
            .idle => .{ .stream_id = self.evidence_snapshot.stream_id },
            .in_flight => |control| blk: {
                if (control.target.stream_id != self.evidence_snapshot.stream_id or
                    control.target.controller_generation != controller_generation or
                    (if (graph.projected_response)
                        actual_control_progress != .response_wait
                    else
                        actual_control_progress != .queued))
                    return self.cleanupFailedPreparedRevoke(lease, scratch, intent_handle, external, graph_owner, false, .protocol_terminal);
                frozen.present = true;
                frozen.kind = control.kind;
                frozen.expectation = control.expectation;
                frozen.target = control.target;
                frozen.request_id = control.request_id;
                frozen.wire_len = control.wire_len;
                break :blk if (graph.projected_response) .{
                    .stream_id = self.evidence_snapshot.stream_id,
                } else .{
                    .stream_id = self.evidence_snapshot.stream_id,
                    .control = .{
                        .request_id = control.request_id,
                        .wire_len = control.wire_len,
                    },
                };
            },
            .completed => |control| if (cleanup_completed) blk: {
                const completed_payload = self.completed_control.completed.payload;
                frozen.present = true;
                frozen.completed = true;
                frozen.kind = control.kind;
                frozen.expectation = control.expectation;
                frozen.target = control.target;
                frozen.request_id = control.request_id;
                frozen.wire_len = control.wire_len;
                break :blk .{
                    .stream_id = self.evidence_snapshot.stream_id,
                    .protected_payload_addr = if (completed_payload.logical_len == 0)
                        0
                    else
                        @intFromPtr(completed_payload.allocation_ptr.?),
                    .protected_payload_len = completed_payload.logical_len,
                };
            } else return self.cleanupFailedPreparedRevoke(lease, scratch, intent_handle, external, graph_owner, false, .protocol_terminal),
            .terminal => return self.cleanupFailedPreparedRevoke(lease, scratch, intent_handle, external, graph_owner, false, .protocol_terminal),
        };
        frozen.digest = frozenRevokeCorrelationDigest(frozen);
        const binding = makeTxOwnerBinding(
            self,
            client,
            external,
            lease,
            @intFromPtr(scratch),
            @sizeOf(ExternalRxTurnScratch),
            @intFromPtr(&scratch.tx_cancellation),
            @sizeOf(client_external_tx.PreparedTxCancellation),
            .cancel_turn,
        );
        graph.external_addr = @intFromPtr(external);
        graph.action = if (cleanup_completed) .cleanup_completed else .cancel_queued;
        graph.binding = binding;
        if (client_external_tx.prepareCancellationFromExternalPump(
            validateTxOwner,
            @ptrCast(self),
            &scratch.tx_cancellation,
            &scratch.tx_cancellation_permit,
            &scratch.tx_cancellation_cleanup,
            external,
            binding,
            cancellation_spec,
            now_ns,
        ) != .prepared) {
            return self.cleanupFailedPreparedRevoke(lease, scratch, intent_handle, external, graph_owner, false, .protocol_terminal);
        }
        if (!client_external_tx.validatePreparedCancellation(
            validateTxOwner,
            @ptrCast(self),
            &scratch.tx_cancellation,
            &scratch.tx_cancellation_permit,
            external,
            binding,
        ))
            return self.cleanupFailedPreparedRevoke(lease, scratch, intent_handle, external, graph_owner, true, .invariant_terminal);
        if (hitRevokePrepareFailpoint(scratch, .after_tx_prepare))
            return self.cleanupFailedPreparedRevoke(lease, scratch, intent_handle, external, graph_owner, true, .invariant_terminal);
        graph.lifecycle = .prepared;
        graph.digest = preparedRevokedCommitGraphDigest(graph);
        if (!self.validatePreparedRevokedRxAggregateGraph(
            lease,
            scratch,
            intent_handle,
            external,
            graph_owner,
        )) {
            return self.cleanupFailedPreparedRevoke(lease, scratch, intent_handle, external, graph_owner, true, .invariant_terminal);
        }
        graph_prepared = true;

        return null;
    }

    fn commitRevokedRxAggregateWithTx(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        intent_handle: *external_rx_intent.ExternalRxIntentHandle,
        now_ns: i128,
    ) RevokeCommitResult {
        if (self.prepareRevokedCommitGraph(
            lease,
            scratch,
            intent_handle,
            now_ns,
        )) |failure| return failure;
        const graph_owner = &scratch.revoked_commit_graph;
        const graph = graph_owner.storage();
        const external: *client_external_mode.State = @ptrFromInt(graph.external_addr);
        const aggregate: *PreparedRxAggregate = @ptrFromInt(graph.aggregate_addr);
        const cleanup_completed = graph.action == .cleanup_completed;
        var published: PublishedRxAggregateCommit = undefined;
        if (!self.consumeAndPublishRevokedRxAggregate(
            scratch,
            intent_handle,
            external,
            graph.binding,
            aggregate,
            &graph.event_cleanup,
            &graph.response_take,
            &graph.frozen_response,
            &graph.correlation,
            cleanup_completed,
            &published,
        )) {
            return self.cleanupFailedPreparedRevoke(
                lease,
                scratch,
                intent_handle,
                external,
                graph_owner,
                true,
                .invariant_terminal,
            );
        }
        graph.lifecycle = .consumed;
        graph.digest = preparedRevokedCommitGraphDigest(graph);
        const result = self.finishRevokedRxAggregateCallbacks(
            scratch,
            graph_owner,
            external,
            graph.binding,
            aggregate,
            &graph.event_cleanup,
            &graph.frozen_response,
            cleanup_completed,
            &published,
        );
        return result;
    }

    fn abortRxAggregate(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        intent_handle: *external_rx_intent.ExternalRxIntentHandle,
    ) RxAggregateAbortResult {
        const aggregate = self.validateReadyRxAggregate(lease) orelse
            return .invalid_state;
        if (aggregate.intent_handle_addr != @intFromPtr(intent_handle) or
            (aggregate.lifecycle != .ready and
                aggregate.lifecycle != .preparing and
                aggregate.lifecycle != .finalized))
            return .invalid_state;
        if (!validateRxAggregateScreenGraph(
            self,
            aggregate,
            intent_handle,
        ))
            return .invalid_state;

        var ledger_abort: external_inbox_ledger.FrozenLiveBatchAbort = .{};
        const has_live_batch = aggregate.live_batch.saved_self_addr != 0;
        if (has_live_batch) {
            self.inbox_ledger.prepareLiveBatchAbort(
                &aggregate.live_batch,
                &ledger_abort,
            ) catch return .invalid_state;
            if (!self.inbox_ledger.validatePreparedLiveBatchAbort(
                &aggregate.live_batch,
                &ledger_abort,
            ))
                return .invalid_state;
        }
        var intent_abort: external_rx_intent.FrozenIntentAbort = .{};
        external_rx_intent.prepareIntentAbort(
            intent_handle,
            @intFromPtr(aggregate),
            &intent_abort,
        ) catch return .invalid_state;
        if (!external_rx_intent.validatePreparedIntentAbort(
            intent_handle,
            &intent_abort,
        ))
            return .invalid_state;
        const has_metadata_abort =
            aggregate.metadata_destination.abort.saved_self_addr != 0;
        if (has_metadata_abort and
            !external_event_materialization.validateLiveMetadataAbort(
                &aggregate.metadata_destination.staged,
                &aggregate.metadata_destination.abort_cleanup,
                &aggregate.metadata_destination.abort,
            ))
            return .invalid_state;

        var transfer_cleanup =
            [_]external_owner_cleanup.FrozenOwnerCleanupDescriptor{.{}} **
            external_rx_intent.max_intents;
        var transfer_cleanup_count: usize = 0;
        for (&aggregate.screen_transfers) |*transfer| {
            switch (transfer.lifecycle) {
                .empty, .batch_owned, .mutation_bound, .committed, .aborted => {},
                .neutral_owned => {
                    const borrowed =
                        external_rx_intent.borrowMovedIntentPayload(
                            &transfer.neutral,
                            @intFromPtr(aggregate),
                        ) orelse return .invalid_state;
                    if (borrowed.allocation_len != 0) {
                        const bytes = @as(
                            [*]u8,
                            @ptrFromInt(borrowed.allocation_addr),
                        )[0..borrowed.allocation_len];
                        external_owner_cleanup.freezeOwnedSlice(
                            &transfer_cleanup[transfer_cleanup_count],
                            borrowed.allocator,
                            bytes,
                        ) catch return .invalid_state;
                        if (!std.mem.eql(
                            u8,
                            &transfer_cleanup[transfer_cleanup_count].content_digest,
                            &transfer.payload_digest,
                        ))
                            return .invalid_state;
                        transfer_cleanup_count += 1;
                    }
                },
                .ledger_owned => {
                    const bytes = transfer.ledger_payload.bytes();
                    if (bytes.len != 0) {
                        external_owner_cleanup.freezeOwnedSlice(
                            &transfer_cleanup[transfer_cleanup_count],
                            transfer.ledger_payload.allocator,
                            @constCast(bytes),
                        ) catch return .invalid_state;
                        if (!std.mem.eql(
                            u8,
                            &transfer_cleanup[transfer_cleanup_count].content_digest,
                            &transfer.payload_digest,
                        ))
                            return .invalid_state;
                        transfer_cleanup_count += 1;
                    }
                },
                .poisoned => return .quarantined,
            }
        }

        var descriptors =
            [_]*const external_owner_cleanup.FrozenOwnerCleanupDescriptor{
                undefined,
            } ** max_rx_aggregate_cleanup_owners;
        var descriptor_count: usize = 0;
        for (ledger_abort.cleanup[0..ledger_abort.cleanup_count]) |*descriptor| {
            descriptors[descriptor_count] = descriptor;
            descriptor_count += 1;
        }
        for (intent_abort.cleanup[0..intent_abort.cleanup_count]) |*descriptor| {
            descriptors[descriptor_count] = descriptor;
            descriptor_count += 1;
        }
        for (transfer_cleanup[0..transfer_cleanup_count]) |*descriptor| {
            descriptors[descriptor_count] = descriptor;
            descriptor_count += 1;
        }
        if (has_metadata_abort) {
            const metadata = &aggregate.metadata_destination.abort;
            for (descriptors[0..descriptor_count]) |prior| {
                if (rangesOverlap(
                    metadata.backing_addr,
                    metadata.backing_len,
                    prior.allocation_addr,
                    prior.allocation_len,
                ))
                    return .quarantined;
            }
        }
        const total_descriptor_count =
            descriptor_count + @intFromBool(has_metadata_abort);
        if (!aggregateCleanupCountFits(total_descriptor_count))
            return .quarantined;
        for (descriptors[0..descriptor_count], 0..) |descriptor, index| {
            if (!external_owner_cleanup.validate(descriptor))
                return .invalid_state;
            for (descriptors[0..index]) |prior| {
                if (rangesOverlap(
                    descriptor.allocation_addr,
                    descriptor.allocation_len,
                    prior.allocation_addr,
                    prior.allocation_len,
                ))
                    return .quarantined;
            }
        }
        var cleanup: FrozenAggregateCleanup = .{};
        var expected_cleanup_bytes: usize = 0;
        for (descriptors[0..descriptor_count]) |descriptor|
            expected_cleanup_bytes = std.math.add(
                usize,
                expected_cleanup_bytes,
                descriptor.allocation_len,
            ) catch return .quarantined;
        if (has_metadata_abort)
            expected_cleanup_bytes = std.math.add(
                usize,
                expected_cleanup_bytes,
                aggregate.metadata_destination.abort.backing_len,
            ) catch return .quarantined;
        cleanup = .{
            .saved_self_addr = @intFromPtr(&cleanup),
            .expected_count = @intCast(total_descriptor_count),
            .expected_total_bytes = expected_cleanup_bytes,
            .lifecycle = .prepared,
            .digest = undefined,
        };
        cleanup.digest = frozenAggregateCleanupDigest(&cleanup);
        if (rangesOverlap(
            @intFromPtr(aggregate),
            @sizeOf(PreparedRxAggregate),
            @intFromPtr(&cleanup),
            @sizeOf(FrozenAggregateCleanup),
        ))
            return .quarantined;
        for (descriptors[0..descriptor_count]) |descriptor| {
            if (rangesOverlap(
                descriptor.allocation_addr,
                descriptor.allocation_len,
                @intFromPtr(&cleanup),
                @sizeOf(FrozenAggregateCleanup),
            ) or rangesOverlap(
                descriptor.allocation_addr,
                descriptor.allocation_len,
                @intFromPtr(aggregate),
                @sizeOf(PreparedRxAggregate),
            ))
                return .quarantined;
        }
        if (has_metadata_abort) {
            const metadata = &aggregate.metadata_destination.abort;
            if (rangesOverlap(
                metadata.backing_addr,
                metadata.backing_len,
                @intFromPtr(&cleanup),
                @sizeOf(FrozenAggregateCleanup),
            ) or rangesOverlap(
                metadata.backing_addr,
                metadata.backing_len,
                @intFromPtr(aggregate),
                @sizeOf(PreparedRxAggregate),
            ))
                return .quarantined;
        }
        var cleanup_count: usize = 0;
        if (has_live_batch) {
            const count = ledger_abort.cleanup_count;
            if (!external_inbox_ledger.ExternalInboxLedger
                .validateLiveBatchAbortCleanupMove(
                &ledger_abort,
                cleanup.cleanup[cleanup_count..][0..count],
            ))
                return .invalid_state;
            cleanup_count += count;
        }
        {
            const count = intent_abort.cleanup_count;
            if (!external_rx_intent.validateIntentAbortCleanupMove(
                &intent_abort,
                cleanup.cleanup[cleanup_count..][0..count],
            ))
                return .invalid_state;
            cleanup_count += count;
        }
        for (transfer_cleanup[0..transfer_cleanup_count], 0..) |*descriptor, index| {
            external_owner_cleanup.validateMoveFrozen(
                descriptor,
                &cleanup.cleanup[cleanup_count + index],
            ) catch return .invalid_state;
        }
        cleanup_count += transfer_cleanup_count;
        if (cleanup_count != descriptor_count)
            return .invalid_state;
        if (aggregate.lifecycle == .finalized) {
            if (has_live_batch and self.inbox_ledger.abortPreparedLiveCommit(
                &aggregate.live_batch,
                &aggregate.retirement,
                &aggregate.dispositions,
                &aggregate.live_commit,
            ) != .aborted) {
                latchCrossOwnerQuarantine();
                return .quarantined;
            }
            if (!external_rx_intent.abortPreparedIntentCommit(
                intent_handle,
                &aggregate.screen_proofs,
                &aggregate.neutral_payloads,
                &aggregate.intent_commit,
            )) {
                latchCrossOwnerQuarantine();
                return .quarantined;
            }
            aggregate.digest = preparedRxAggregateDigest(aggregate);
        }
        aggregate.lifecycle = .aborting;
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        if (has_live_batch)
            self.inbox_ledger.commitLiveBatchAbortUnchecked(
                &aggregate.live_batch,
                &ledger_abort,
            );
        external_rx_intent.commitIntentAbortUnchecked(
            intent_handle,
            &intent_abort,
        );
        if (has_metadata_abort) {
            aggregate.metadata_destination.replacement.abort();
            external_event_materialization.commitLiveMetadataAbortUnchecked(
                &aggregate.metadata_destination.staged,
                &aggregate.metadata_destination.abort_cleanup,
                &aggregate.metadata_destination.abort,
            );
        }
        for (&aggregate.screen_transfers) |*transfer| {
            switch (transfer.lifecycle) {
                .neutral_owned => tombstoneMovedIntentPayloadUnchecked(&transfer.neutral),
                .ledger_owned => transfer.ledger_payload =
                    external_inbox_ledger.OwnedPayload.empty(
                        transfer.ledger_payload.allocator,
                    ),
                else => {},
            }
            if (transfer.lifecycle != .empty) {
                transfer.lifecycle = .aborted;
                transfer.digest = screenTransferDigest(transfer);
            }
        }

        cleanup_count = 0;
        if (has_live_batch) {
            const count = ledger_abort.cleanup_count;
            external_inbox_ledger.ExternalInboxLedger
                .moveCommittedLiveBatchAbortCleanupUnchecked(
                &ledger_abort,
                cleanup.cleanup[cleanup_count..][0..count],
            );
            cleanup_count += count;
        }
        {
            const count = intent_abort.cleanup_count;
            external_rx_intent.moveCommittedIntentAbortCleanupUnchecked(
                &intent_abort,
                cleanup.cleanup[cleanup_count..][0..count],
            );
            cleanup_count += count;
        }
        for (transfer_cleanup[0..transfer_cleanup_count]) |*descriptor| {
            external_owner_cleanup.moveFrozenUnchecked(
                descriptor,
                &cleanup.cleanup[cleanup_count],
            );
            cleanup_count += 1;
        }
        if (has_metadata_abort) {
            external_owner_cleanup.moveFrozenUnchecked(
                &aggregate.metadata_destination.abort_cleanup,
                &cleanup.cleanup[cleanup_count],
            );
            cleanup_count += 1;
        }
        cleanup.cleanup_count = @intCast(cleanup_count);
        cleanup.total_bytes = expected_cleanup_bytes;
        cleanup.lifecycle = .frozen;
        cleanup.digest = frozenAggregateCleanupDigest(&cleanup);
        aggregate.lifecycle = .aborted;
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        self.retainRxAggregateAllocation(aggregate);

        const result: RxAggregateAbortResult =
            if (finishFrozenAggregateCleanup(&cleanup))
                .cleaned
            else
                .quarantined;
        if (result == .quarantined)
            latchCrossOwnerQuarantine();
        return result;
    }

    fn destroyReadyRxAggregate(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
    ) RxAggregateDestroyResult {
        const aggregate = self.validateReadyRxAggregate(lease) orelse
            return .invalid_state;
        if (aggregate.lifecycle != .ready)
            return .invalid_state;
        const allocator = self.rx_aggregate_handle.allocator;
        var aggregate_cleanup: external_owner_cleanup.FrozenOwnerCleanupDescriptor = .{};
        external_owner_cleanup.validateFreezeOwnedSliceAligned(
            &aggregate_cleanup,
            std.mem.asBytes(aggregate),
            .of(PreparedRxAggregate),
        ) catch return .quarantined;
        aggregate.lifecycle = .destroying;
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        external_owner_cleanup.freezeOwnedSliceAlignedUnchecked(
            &aggregate_cleanup,
            allocator,
            std.mem.asBytes(aggregate),
            .of(PreparedRxAggregate),
        );
        self.rx_aggregate_handle = .{};
        self.rx_aggregate_reservation = .{};
        return if (external_owner_cleanup.finishCallbackHidden(
            &aggregate_cleanup,
        ) == .cleaned)
            .destroyed
        else
            .quarantined;
    }

    /// Prepares the single retained-aggregate destruction authority shared by full owner teardown
    /// and narrow transaction cleanup.  The allocator callback must see a tombstoned handle, never
    /// a live pointer-bearing owner.
    fn prepareRetainedRxAggregateDestroy(
        self: *ExternalPumpStorage,
        cleanup: *external_owner_cleanup.FrozenOwnerCleanupDescriptor,
        execution: *?RetainedRxAggregateDestroyExecution,
    ) bool {
        if (!retainedRxAggregateValid(self) or cleanup.saved_self_addr != 0 or
            execution.* != null)
            return false;
        const aggregate: *PreparedRxAggregate =
            @ptrFromInt(self.rx_aggregate_handle.aggregate_addr);
        external_owner_cleanup.validateFreezeOwnedSliceAligned(
            cleanup,
            std.mem.asBytes(aggregate),
            .of(PreparedRxAggregate),
        ) catch return false;
        execution.* = .{
            .aggregate = aggregate,
            .allocator = self.rx_aggregate_handle.allocator,
        };
        return true;
    }

    // MARU_F3C2_RETAINED_CLEANUP_UNCHECKED_BEGIN
    fn commitRetainedRxAggregateDestroyUnchecked(
        self: *ExternalPumpStorage,
        cleanup: *external_owner_cleanup.FrozenOwnerCleanupDescriptor,
        execution: RetainedRxAggregateDestroyExecution,
    ) void {
        const aggregate = execution.aggregate;
        aggregate.lifecycle = .destroying;
        aggregate.digest = preparedRxAggregateDigest(aggregate);
        external_owner_cleanup.freezeOwnedSliceAlignedUnchecked(
            cleanup,
            execution.allocator,
            std.mem.asBytes(aggregate),
            .of(PreparedRxAggregate),
        );
        self.rx_aggregate_handle = .{};
        self.rx_aggregate_reservation = .{};
    }
    // MARU_F3C2_RETAINED_CLEANUP_UNCHECKED_END

    fn prepareCompletedResponseOwnerCleanup(
        self: *ExternalPumpStorage,
        aggregate_cleanup: *external_owner_cleanup.FrozenOwnerCleanupDescriptor,
        aggregate_execution: *?RetainedRxAggregateDestroyExecution,
        intent_destroy: *external_rx_intent.PreparedDestroy,
        intent_out: *?*external_rx_intent.ExternalRxIntentHandle,
        intent_scratch_out: *?*anyopaque,
    ) bool {
        if (!self.prepareRetainedRxAggregateDestroy(
            aggregate_cleanup,
            aggregate_execution,
        ) or
            !self.intentScratchReservationValid() or
            self.intent_scratch_reservation.lifecycle != .active or
            intent_scratch_out.* != null)
            return false;
        const intent: *external_rx_intent.ExternalRxIntentHandle =
            @ptrFromInt(self.intent_scratch_reservation.handle_addr);
        if (!external_rx_intent.prepareDestroy(
            intent,
            @intFromPtr(self),
            self.intent_scratch_reservation.generation,
            intent_destroy,
        )) return false;
        intent_out.* = intent;
        intent_scratch_out.* = @ptrFromInt(intent_destroy.scratch_addr);
        return true;
    }

    // MARU_F3C2_COMBINED_CLEANUP_UNCHECKED_BEGIN
    fn commitCompletedResponseOwnerCleanupUnchecked(
        self: *ExternalPumpStorage,
        aggregate_cleanup: *external_owner_cleanup.FrozenOwnerCleanupDescriptor,
        aggregate_execution: RetainedRxAggregateDestroyExecution,
        intent: *external_rx_intent.ExternalRxIntentHandle,
        intent_scratch: *anyopaque,
        intent_destroy: *external_rx_intent.PreparedDestroy,
        frozen_intent: *external_rx_intent.FrozenDestroy,
    ) void {
        self.commitRetainedRxAggregateDestroyUnchecked(
            aggregate_cleanup,
            aggregate_execution,
        );
        external_rx_intent.commitPreparedDestroyUnchecked(
            intent,
            intent_scratch,
            intent_destroy,
            frozen_intent,
        );
        self.intent_scratch_reservation = .{};
    }
    // MARU_F3C2_COMBINED_CLEANUP_UNCHECKED_END

    fn poisonRxAggregateReservation(self: *ExternalPumpStorage) void {
        self.rx_aggregate_handle = .{ .lifecycle = .poisoned };
        self.rx_aggregate_reservation = .{
            .lifecycle = .poisoned_tombstone,
        };
        self.intent_scratch_reservation = .{
            .lifecycle = .poisoned_tombstone,
        };
        self.semantic_state = .{ .terminal = .{
            .reason = .invariant_failure,
            .fd_disposition = .owner_cleanup,
        } };
        latchCrossOwnerQuarantine();
    }

    fn rejectForgedRxAggregateAllocation(self: *ExternalPumpStorage) void {
        // No aggregate authority was ever acquired, so keep both reservation owners canonical.
        // This lets terminal teardown destroy the already-bound intent scratch and Client while
        // the process-wide latch prevents any future adoption after the hostile allocator event.
        self.semantic_state = .{ .terminal = .{
            .reason = .invariant_failure,
            .fd_disposition = .owner_cleanup,
        } };
        latchCrossOwnerQuarantine();
    }

    fn livePartialPending(self: *const ExternalPumpStorage) bool {
        return switch (self.live_partial) {
            .assembling => true,
            else => false,
        };
    }

    fn validatedPartialContinuation(
        self: *const ExternalPumpStorage,
    ) ?external_rx_demux.ValidatedPartialView {
        const assembling = switch (self.live_partial) {
            .assembling => |assembling| assembling,
            else => return null,
        };
        if (!self.livePartialValid()) return null;
        const semantic = self.inbox_ledger.partialSnapshot(
            assembling.ledger_token,
        ) catch return null;
        const range = switch (semantic.provenance) {
            .external => |range| range,
            .untracked => return null,
        };
        return .{
            .stream_id = semantic.stream_id,
            .is_snapshot = semantic.is_snapshot,
            .identity = range.identity,
            .start_absolute = range.start_absolute,
            .end_absolute = range.end_absolute,
            .chunk_count = semantic.chunk_count,
        };
    }

    fn liveScreenPending(self: *const ExternalPumpStorage) bool {
        return self.live_screen.lifecycle == .active and
            self.live_screen.len != 0;
    }

    fn controlResponsePending(self: *const ExternalPumpStorage) bool {
        return switch (self.completed_control) {
            .completed => true,
            else => false,
        };
    }

    /// Snapshot construction and teardown tests share this projection so blocker truth has one
    /// source even after the storage lifecycle no longer permits issuing a public snapshot.
    fn liveOwnerBlockerProjection(
        self: *const ExternalPumpStorage,
    ) ?LiveOwnerBlockerProjection {
        if (!self.liveOwnersValid()) return null;
        return .{
            .partial_pending = self.livePartialPending(),
            .screen_pending = self.liveScreenPending(),
            .response_pending = self.controlResponsePending(),
        };
    }

    fn tombstonePendingSummaries(self: *ExternalPumpStorage) void {
        self.screen_pending_summary = .{ .lifecycle = .tombstone };
        self.metadata_pending_summary = .{ .lifecycle = .tombstone };
    }

    fn wholeTurnScratchDisjoint(
        self: *const ExternalPumpStorage,
        scratch_addr: usize,
        scratch_len: usize,
    ) bool {
        if (scratch_addr == 0 or scratch_len == 0) return false;
        _ = std.math.add(usize, scratch_addr, scratch_len) catch return false;
        if (self.inbox_ledger.overlapsOwnedRange(scratch_addr, scratch_len) or
            self.committed_screen.overlapsOwnedBacking(scratch_addr, scratch_len))
            return false;
        if (self.owner_metadata.metadata == .current) {
            const current = &self.owner_metadata.metadata.current;
            if (current.logical.backing) |backing|
                if (rangesOverlap(
                    scratch_addr,
                    scratch_len,
                    @intFromPtr(backing.ptr),
                    backing.len,
                )) return false;
            if (current.cleanup.backing) |backing|
                if (rangesOverlap(
                    scratch_addr,
                    scratch_len,
                    @intFromPtr(backing.ptr),
                    backing.len,
                )) return false;
        }
        const take_overlap = self.client_cleanup_take.overlapsCommittedOwnedRange(
            scratch_addr,
            scratch_len,
        ) orelse return false;
        if (take_overlap) return false;
        if (self.owned_client) |*owned| {
            var source_ranges: client_mod.ExternalSourceOwnerRangeScratch = .{};
            owned.preflightExternalAdoptionDestinationWithScratch(
                @ptrFromInt(scratch_addr),
                scratch_len,
                &source_ranges,
            ) catch return false;
        }
        return true;
    }

    pub fn initInPlace(
        out: *ExternalPumpStorage,
        source: *client_mod.Client,
        evidence: *PreparedAdoptionEvidence,
    ) InitResult {
        return initInPlaceWithOptions(out, source, evidence, .{});
    }

    fn initInPlaceWithOptions(
        out: *ExternalPumpStorage,
        source: *client_mod.Client,
        evidence: *PreparedAdoptionEvidence,
        options: InitOptions,
    ) InitResult {
        if (options.test_skip_process_owner_reservation and !builtin.is_test)
            unreachable;
        // Pointer arithmetic and overlap rejection happen before interpreting destination fields:
        // a malicious alias must not let an `out.* = ...` overwrite the source Client.
        if (rangesOverlap(
            @intFromPtr(out),
            @sizeOf(ExternalPumpStorage),
            @intFromPtr(source),
            @sizeOf(client_mod.Client),
        ) or rangesOverlap(
            @intFromPtr(out),
            @sizeOf(ExternalPumpStorage),
            @intFromPtr(evidence),
            @sizeOf(PreparedAdoptionEvidence),
        )) {
            return failed(.overlapping_storage, .preserved);
        }
        // The cap becomes parser-allocation authority. Reject invalid policy before reserving the
        // process owner or invoking any source allocator so failure is observably pre-mutation.
        if (options.resident_cap == 0 or
            options.resident_cap > max_rx_resident_bytes)
            return failed(.resident_too_large, .preserved);
        const expected_rx_resident_cap = options.resident_cap;
        const expected_rx_resident_cap_digest = rxResidentCapDigest(
            @intFromPtr(out),
            expected_rx_resident_cap,
        );
        if (cross_owner_quarantine_events.load(.acquire) != 0)
            return failed(.process_quarantined, .preserved);
        const out_addr = @intFromPtr(out);
        if (initializing_storage_addr != 0)
            return failed(.destination_not_empty, .preserved);
        initializing_storage_addr = out_addr;
        defer initializing_storage_addr = 0;
        const reserve_process_owner = !options.test_skip_process_owner_reservation;
        if (reserve_process_owner) {
            if (active_storage_addr.cmpxchgStrong(
                0,
                out_addr,
                .acq_rel,
                .acquire,
            ) != null)
                return failed(.process_owner_busy, .preserved);
        }
        var retain_active_reservation = false;
        defer if (reserve_process_owner and !retain_active_reservation)
            releaseActiveStorage(out_addr);
        source.preflightExternalAdoptionDestination(
            evidence,
            @sizeOf(PreparedAdoptionEvidence),
        ) catch |err| {
            return switch (err) {
                error.OutOfMemory => failed(.out_of_memory, .preserved),
                else => failed(.overlapping_storage, .preserved),
            };
        };
        const evidence_seed_seal = evidence.seed_seal orelse {
            return failed(.invalid_evidence, .preserved);
        };
        if (evidence_seed_seal.backing_len != 0 and rangesOverlap(
            @intFromPtr(out),
            @sizeOf(ExternalPumpStorage),
            evidence_seed_seal.backing_addr,
            evidence_seed_seal.backing_len,
        )) {
            return failed(.overlapping_storage, .preserved);
        }
        source.preflightExternalAdoptionDestination(
            out,
            @sizeOf(ExternalPumpStorage),
        ) catch |err| {
            return switch (err) {
                error.OutOfMemory => failed(.out_of_memory, .preserved),
                error.InvalidAlias => failed(.overlapping_storage, .preserved),
                else => failed(.invariant_failure, .preserved),
            };
        };
        if (out.lifecycle != .empty)
            return failed(.destination_not_empty, .preserved);
        if (!evidence.validate(source)) {
            return failed(.invalid_evidence, .preserved);
        }

        out.* = .{
            .lifecycle = .constructing,
            .saved_self_addr = @intFromPtr(out),
            .rx_resident_cap = options.resident_cap,
            .rx_resident_cap_digest = rxResidentCapDigest(
                @intFromPtr(out),
                options.resident_cap,
            ),
            .semantic_state = .constructing,
            .evidence_snapshot = evidence.attachment,
            .operation_generation = 0,
        };

        source.prepareExternalPumpTransfer(
            &out.client_transfer,
            &out.owned_client,
            options.resident_cap,
        ) catch |err| {
            out.client_transfer.deinit();
            out.* = .{};
            return switch (err) {
                error.ConnectionClosed => failed(.connection_closed, .preserved),
                error.NotExternal => failed(.source_not_external, .preserved),
                error.DestinationOccupied => failed(.destination_not_empty, .preserved),
                error.AlreadyBound => failed(.source_already_bound, .preserved),
                error.ResidentTooLarge => failed(.resident_too_large, .preserved),
                error.MalformedParser => failed(.malformed_parser, .preserved),
                error.OutOfMemory => failed(.out_of_memory, .preserved),
            };
        };
        // The allocations above run arbitrary allocator code. Re-prove that this transaction still
        // owns the destination before trusting any field it published.
        if (out.lifecycle != .constructing or
            out.rx_resident_cap != expected_rx_resident_cap or
            !std.mem.eql(
                u8,
                &out.rx_resident_cap_digest,
                &expected_rx_resident_cap_digest,
            ) or !rxResidentCapValid(out))
        {
            out.client_transfer.deinit();
            out.* = .{};
            return failed(.invariant_failure, .preserved);
        }
        if (!out.client_transfer.validate(source, &out.owned_client) or
            !evidence.validate(source))
        {
            out.client_transfer.deinit();
            out.* = .{};
            return failed(.invalid_evidence, .preserved);
        }
        var owner_proof: client_mod.PreparedExternalOwnerRangeProof = .{};
        var owner_proof_live = false;
        defer if (owner_proof_live) owner_proof.deinit();
        source.prepareExternalOwnerRangeProof(
            &owner_proof,
            out,
            @sizeOf(ExternalPumpStorage),
            evidence,
            @sizeOf(PreparedAdoptionEvidence),
        ) catch |err| {
            out.client_transfer.deinit();
            out.* = .{};
            return switch (err) {
                error.OutOfMemory => failed(.out_of_memory, .preserved),
                else => failed(.invariant_failure, .preserved),
            };
        };
        owner_proof_live = true;
        if (out.lifecycle != .constructing or
            out.rx_resident_cap != expected_rx_resident_cap or
            !std.mem.eql(
                u8,
                &out.rx_resident_cap_digest,
                &expected_rx_resident_cap_digest,
            ) or !rxResidentCapValid(out))
        {
            out.client_transfer.deinit();
            out.* = .{};
            return failed(.invariant_failure, .preserved);
        }
        if (!owner_proof.validate(
            source,
            out,
            @sizeOf(ExternalPumpStorage),
            evidence,
            @sizeOf(PreparedAdoptionEvidence),
        ) or
            !out.client_transfer.validate(source, &out.owned_client) or
            !evidence.validate(source))
        {
            out.client_transfer.deinit();
            out.* = .{};
            return failed(.invalid_evidence, .preserved);
        }

        // No allocation, callback or error is permitted between these two ownership takes.
        source.commitExternalPumpTransfer(
            &out.client_transfer,
            &out.owned_client,
        ) catch {
            out.client_transfer.deinit();
            out.* = .{};
            return failed(.invalid_evidence, .preserved);
        };
        out.owned_evidence = .{};
        evidence.moveInto(&out.owned_evidence.?, &out.owned_client.?);
        out.lifecycle = .normalizing;
        out.semantic_state = .constructing;
        // The final owner-range proof deliberately frees only after both owners moved and the
        // source became a tombstone. Its allocator callback therefore cannot mutate a live source
        // descriptor between validation and the paired take. Public re-entry sees `.normalizing`.
        owner_proof.deinit();
        owner_proof_live = false;
        if (out.lifecycle != .normalizing or
            out.rx_resident_cap != expected_rx_resident_cap or
            !std.mem.eql(
                u8,
                &out.rx_resident_cap_digest,
                &expected_rx_resident_cap_digest,
            ) or !rxResidentCapValid(out))
        {
            _ = out.closeUncommittedOwned(.invariant_failure);
            return failed(.invariant_failure, .consumed_and_closed);
        }
        if (options.failpoint == .after_paired_take) {
            _ = out.closeUncommittedOwned(.invariant_failure);
            return failed(.invariant_failure, .consumed_and_closed);
        }
        const finish_outcome = client_mod.Client.finishExternalPumpTransfer(
            &out.client_transfer,
            &out.owned_client,
        );
        if (finish_outcome == .quarantined) {
            _ = out.closeUncommittedOwned(.invariant_failure);
            return failed(.invariant_failure, .consumed_and_closed);
        }
        if (!rxResidentCapOwnerValid(out)) {
            _ = out.closeUncommittedOwned(.invariant_failure);
            return failed(.invariant_failure, .consumed_and_closed);
        }
        out.lifecycle = .adopting;
        out.semantic_state = .adopting;
        retain_active_reservation = reserve_process_owner;
        return .initialized;
    }

    /// 2b2b never reaches active; this gate prevents a caller from treating successful storage
    /// construction as authority adoption.
    pub fn requireActive(self: *ExternalPumpStorage) AccessError!void {
        try self.requireAddress();
        if ((self.lifecycle == .adopting or self.lifecycle == .live) and
            !rxResidentCapOwnerValid(self))
            return error.InvalidDescriptor;
        return switch (self.lifecycle) {
            .empty => error.Empty,
            .adopting, .adoption_preparing, .constructing, .normalizing => error.NotActive,
            .live => switch (self.semantic_state) {
                .active => {},
                .terminal => error.Terminal,
                else => error.NotActive,
            },
            .tearing_down, .dead => error.Terminal,
        };
    }

    /// Atomically admits one immutable TX frame under the same operation reservation as a pump
    /// turn. Encoding allocation is allowed before the final suffix; queue bytes, generation, and
    /// request-ID state publish together only after every callback-facing authority is revalidated.
    pub fn admitTx(
        self: *ExternalPumpStorage,
        spec: TxAdmissionSpec,
        now_ns: i128,
    ) TxAdmissionResult {
        var lease: ExternalWholeTurnLease = .{};
        var admission_scratch: client_external_tx.PreparedTxAdmission = .{};
        self.acquireWholeTurnLease(
            &lease,
            @intFromPtr(&admission_scratch),
            @sizeOf(client_external_tx.PreparedTxAdmission),
        ) catch |err| return switch (err) {
            error.TransactionBusy => .busy,
            error.Terminal => .{
                .terminal = self.snapshotTerminalReason(),
            },
            else => .{ .terminal = .invariant_failure },
        };

        var result: TxAdmissionResult = blk: {
            const client = if (self.owned_client) |*owned| owned else break :blk .{ .terminal = .invariant_failure };
            const state = switch (client.io_mode) {
                .external => |*external| external,
                .blocking => break :blk .{ .terminal = .invariant_failure },
            };
            const request_ids = if (self.owner_request_ids) |*ids| ids else break :blk .{ .terminal = .invariant_failure };
            break :blk client_external_tx.admitFromExternalPump(
                validateTxOwner,
                @ptrCast(self),
                &admission_scratch,
                state.tx_allocator,
                state,
                request_ids,
                makeTxOwnerBinding(
                    self,
                    client,
                    state,
                    &lease,
                    @intFromPtr(&admission_scratch),
                    @sizeOf(client_external_tx.PreparedTxAdmission),
                    @intFromPtr(&admission_scratch),
                    @sizeOf(client_external_tx.PreparedTxAdmission),
                    .admission,
                ),
                spec,
                now_ns,
            );
        };
        switch (result) {
            .terminal => |reason| self.semantic_state = .{ .terminal = .{
                .reason = reason,
                .fd_disposition = .owner_cleanup,
            } },
            else => {},
        }
        const release_result = self.releaseWholeTurnLease(&lease);
        if (release_result != .released) {
            result = .{ .terminal = .invariant_failure };
        }
        return result;
    }

    /// Admits the only outstanding control request. The request-ID preview and semantic plan are
    /// sealed before f1 runs; after f1 commits, the remaining scalar publication cannot allocate,
    /// call out, or fail.
    pub fn admitControl(
        self: *ExternalPumpStorage,
        spec: ControlAdmissionSpec,
        now_ns: i128,
    ) ControlAdmissionResult {
        var lease: ExternalWholeTurnLease = .{};
        var admission_scratch: client_external_tx.PreparedTxAdmission = .{};
        self.acquireWholeTurnLease(
            &lease,
            @intFromPtr(&admission_scratch),
            @sizeOf(client_external_tx.PreparedTxAdmission),
        ) catch |err| return switch (err) {
            error.TransactionBusy => .busy,
            error.Terminal => .{
                .terminal = self.snapshotTerminalReason(),
            },
            else => .{ .terminal = .invariant_failure },
        };

        var result: ControlAdmissionResult = .{ .terminal = .invariant_failure };
        var terminal_reason: ?client_pump.TerminalReason = null;
        var control_wire_buffer: [protocol.max_control_json]u8 = undefined;
        control: {
            if (!controlCorrelationValid(self)) break :control;
            if (self.control_correlation.state != .idle) {
                result = .backpressure;
                break :control;
            }
            if (self.control_correlation.generation == std.math.maxInt(u64)) {
                terminal_reason = .resource_exhausted;
                break :control;
            }
            const authority = switch (self.owner_authority) {
                .current => |authority| authority,
                .empty => break :control,
            };
            const control_kind: client_pump.ControlKind = switch (spec.request) {
                .resize => .resize,
                .resync => .resync,
                .detach => .detach,
            };
            const target_stream_id = switch (spec.request) {
                .resize => |request| request.stream_id,
                .resync => |request| request.stream_id,
                .detach => |request| request.stream_id,
            };
            if ((control_kind != .detach and authority.role != .controller) or
                authority.flow != .clear or
                target_stream_id != self.evidence_snapshot.stream_id or
                !controlGenerationMatches(
                    control_kind,
                    authority.generation,
                    spec.expected_controller_generation,
                ))
            {
                terminal_reason = .protocol_error;
                break :control;
            }
            const active = switch (self.semantic_state) {
                .active => |active| active,
                else => break :control,
            };
            var next_semantic = active;
            switch (control_kind) {
                .resize => if (active != .valid) {
                    result = .backpressure;
                    break :control;
                },
                .resync => switch (active) {
                    .client_recovery => |phase| switch (phase) {
                        .control_wait => |context| {
                            const recovery_authority =
                                spec.request.resync.recovery_authority;
                            if (recovery_authority.owner_incarnation != self.owner_incarnation or
                                recovery_authority.origin != .client or
                                recovery_authority.recovery_epoch != context.epoch)
                            {
                                terminal_reason = .protocol_error;
                                break :control;
                            }
                            next_semantic = .{ .client_recovery = .{
                                .control_in_flight = context,
                            } };
                        },
                        else => {
                            result = .backpressure;
                            break :control;
                        },
                    },
                    else => {
                        result = .backpressure;
                        break :control;
                    },
                },
                .detach => if (active != .valid) {
                    result = .backpressure;
                    break :control;
                },
            }
            const client = if (self.owned_client) |*owned| owned else break :control;
            const state = switch (client.io_mode) {
                .external => |*external| external,
                .blocking => break :control,
            };
            const request_ids = if (self.owner_request_ids) |*ids| ids else break :control;
            const encoded = control_response_wire.encodeRequest(
                &control_wire_buffer,
                spec.request,
            ) catch |err| {
                terminal_reason = switch (err) {
                    error.InvalidRequest => .protocol_error,
                    error.BufferTooSmall => .resource_exhausted,
                };
                break :control;
            };
            const prepared_request = request_ids.prepare() catch |err| {
                terminal_reason = switch (err) {
                    error.Exhausted => .request_id_exhausted,
                    error.InvalidState => .invariant_failure,
                };
                break :control;
            };
            const target = client_control_correlation.Target{
                .stream_id = target_stream_id,
                .controller_generation = spec.expected_controller_generation,
            };
            const expected_wire_len = std.math.add(
                usize,
                protocol.header_size,
                encoded.payload.len,
            ) catch {
                terminal_reason = .resource_exhausted;
                break :control;
            };
            const prepared_correlation =
                client_control_correlation.prepareAdmission(
                    .idle,
                    control_kind,
                    encoded.expectation,
                    target,
                    prepared_request.id,
                    expected_wire_len,
                    now_ns,
                );
            const in_flight = switch (prepared_correlation) {
                .admitted => |value| value,
                .deadline_overflow => {
                    terminal_reason = .deadline_exceeded;
                    break :control;
                },
                .backpressure => {
                    result = .backpressure;
                    break :control;
                },
                .invalid => break :control,
            };
            const admitted = client_external_tx.admitFromExternalPump(
                validateTxOwner,
                @ptrCast(self),
                &admission_scratch,
                state.tx_allocator,
                state,
                request_ids,
                makeTxOwnerBinding(
                    self,
                    client,
                    state,
                    &lease,
                    @intFromPtr(&admission_scratch),
                    @sizeOf(client_external_tx.PreparedTxAdmission),
                    @intFromPtr(&admission_scratch),
                    @sizeOf(client_external_tx.PreparedTxAdmission),
                    .admission,
                ),
                .{
                    .kind = .request,
                    .stream_id = 0,
                    .payload = encoded.payload,
                    .request_policy = .reserve,
                },
                now_ns,
            );
            switch (admitted) {
                .admitted => |value| {
                    if (value.request_id != in_flight.request_id or
                        value.wire_len != in_flight.wire_len)
                    {
                        terminal_reason = .invariant_failure;
                        break :control;
                    }
                    // All fallible/callback-capable work ended above. The generation was checked
                    // before f1 and the held lease prevents any competing mutation.
                    self.control_correlation.generation += 1;
                    self.control_correlation.state = .{
                        .in_flight = in_flight,
                    };
                    self.control_correlation.digest =
                        controlCorrelationDigest(&self.control_correlation);
                    self.semantic_state = .{ .active = next_semantic };
                    result = .{ .admitted = value };
                },
                .backpressure => result = .backpressure,
                .busy => result = .busy,
                .terminal => |reason| terminal_reason = reason,
            }
        }
        if (terminal_reason) |reason| {
            self.semantic_state = .{ .terminal = .{
                .reason = reason,
                .fd_disposition = .owner_cleanup,
            } };
            result = .{ .terminal = reason };
        }
        if (self.releaseWholeTurnLease(&lease) != .released) {
            self.semantic_state = .{ .terminal = .{
                .reason = .invariant_failure,
                .fd_disposition = .owner_cleanup,
            } };
            result = .{ .terminal = .invariant_failure };
        }
        return result;
    }

    fn snapshotTerminalReason(self: *ExternalPumpStorage) client_pump.TerminalReason {
        if (self.access_claim.cmpxchgStrong(
            @intFromEnum(StorageClaim.idle),
            @intFromEnum(StorageClaim.operation),
            .acq_rel,
            .acquire,
        ) != null)
            return .invariant_failure;
        defer self.access_claim.store(
            @intFromEnum(StorageClaim.idle),
            .release,
        );
        if (self.lifecycle != .live) return .invariant_failure;
        return switch (self.semantic_state) {
            .terminal => |terminal| terminal.reason,
            else => .invariant_failure,
        };
    }

    /// Hold the process-thread operation reservation across the complete RX policy turn.
    pub fn acquireWholeTurnLease(
        self: *ExternalPumpStorage,
        out: *ExternalWholeTurnLease,
        scratch_addr: usize,
        scratch_len: usize,
    ) AccessError!void {
        if (active_external_operation_addr != 0) {
            if (active_external_operation_addr == @intFromPtr(self))
                self.operation_reentry_latched = true;
            return error.TransactionBusy;
        }
        if (self.access_claim.cmpxchgStrong(
            @intFromEnum(StorageClaim.idle),
            @intFromEnum(StorageClaim.operation),
            .acq_rel,
            .acquire,
        )) |observed|
            return if (observed == @intFromEnum(StorageClaim.dead))
                error.Terminal
            else
                error.TransactionBusy;
        var storage_claim_owned = true;
        errdefer if (storage_claim_owned)
            self.access_claim.store(
                @intFromEnum(StorageClaim.idle),
                .release,
            );
        const tx_state = blk: {
            const client = if (self.owned_client) |*owned|
                owned
            else
                return error.NotActive;
            break :blk switch (client.io_mode) {
                .external => |*external| external,
                .blocking => return error.NotActive,
            };
        };
        if (!tx_state.acquireTxOperation())
            return error.TransactionBusy;
        var tx_claim_owned = true;
        errdefer if (tx_claim_owned) {
            if (!tx_state.releaseTxOperation())
                @panic("external whole-turn TX claim release failed");
        };
        try self.requireActive();
        if (!std.meta.eql(out.*, ExternalWholeTurnLease{}))
            return error.InvalidDescriptor;
        const out_addr = @intFromPtr(out);
        _ = std.math.add(usize, out_addr, @sizeOf(ExternalWholeTurnLease)) catch
            return error.InvalidDescriptor;
        _ = std.math.add(usize, scratch_addr, scratch_len) catch
            return error.InvalidDescriptor;
        if (rangesOverlap(
            out_addr,
            @sizeOf(ExternalWholeTurnLease),
            @intFromPtr(self),
            @sizeOf(ExternalPumpStorage),
        ) or rangesOverlap(
            out_addr,
            @sizeOf(ExternalWholeTurnLease),
            scratch_addr,
            scratch_len,
        ) or rangesOverlap(
            scratch_addr,
            scratch_len,
            @intFromPtr(self),
            @sizeOf(ExternalPumpStorage),
        ))
            return error.InvalidDescriptor;
        if (!self.wholeTurnScratchDisjoint(scratch_addr, scratch_len))
            return error.InvalidDescriptor;
        if (!self.wholeTurnScratchDisjoint(
            out_addr,
            @sizeOf(ExternalWholeTurnLease),
        ))
            return error.InvalidDescriptor;
        if (self.operation_generation == std.math.maxInt(u64))
            return error.GenerationExhausted;
        const rx_authority = snapshotRxResidentCapAuthority(self) orelse
            return error.InvalidDescriptor;
        const rx_authority_digest = rxAuthorityDigest(
            rx_authority.client_addr,
            rx_authority.parser_addr,
            rx_authority.provenance,
        );
        active_external_operation_addr = @intFromPtr(self);
        active_external_tx_state_addr = @intFromPtr(tx_state);
        self.operation_reentry_latched = false;
        self.operation_generation += 1;
        out.* = .{
            .saved_self_addr = out_addr,
            .storage_addr = @intFromPtr(self),
            .scratch_addr = scratch_addr,
            .scratch_len = scratch_len,
            .operation_generation = self.operation_generation,
            .rx_resident_cap = self.rx_resident_cap,
            .rx_resident_cap_digest = self.rx_resident_cap_digest,
            .rx_client_addr = rx_authority.client_addr,
            .rx_parser_addr = rx_authority.parser_addr,
            .rx_provenance = rx_authority.provenance,
            .rx_authority_digest = rx_authority_digest,
            .lifecycle = .acquired,
        };
        out.digest = wholeTurnLeaseDigest(out.*);
        active_external_lease_addr = out_addr;
        active_external_lease_generation = self.operation_generation;
        active_external_rx_resident_cap = self.rx_resident_cap;
        active_external_rx_resident_cap_digest = self.rx_resident_cap_digest;
        active_external_rx_client_addr = rx_authority.client_addr;
        active_external_rx_parser_addr = rx_authority.parser_addr;
        active_external_rx_provenance = rx_authority.provenance;
        active_external_rx_authority_digest = rx_authority_digest;
        tx_claim_owned = false;
        storage_claim_owned = false;
    }

    pub fn validateWholeTurnLease(
        self: *const ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
    ) bool {
        return self.wholeTurnLeaseIdentityValid(lease) and
            self.lifecycle == .live and
            self.semantic_state == .active;
    }

    fn wholeTurnLeaseIdentityValid(
        self: *const ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
    ) bool {
        return active_external_operation_addr == @intFromPtr(self) and
            active_external_tx_state_addr != 0 and
            (@as(*const client_external_mode.State, @ptrFromInt(
                active_external_tx_state_addr,
            ))).txOperationHeldByCurrentThread() and
            self.saved_self_addr == @intFromPtr(self) and
            active_external_lease_addr == @intFromPtr(lease) and
            active_external_lease_generation == self.operation_generation and
            active_external_rx_resident_cap == self.rx_resident_cap and
            std.mem.eql(
                u8,
                &active_external_rx_resident_cap_digest,
                &self.rx_resident_cap_digest,
            ) and
            activeWholeTurnRxAuthorityMatches(self) and
            lease.saved_self_addr == @intFromPtr(lease) and
            lease.storage_addr == @intFromPtr(self) and
            lease.operation_generation == self.operation_generation and
            lease.rx_resident_cap == self.rx_resident_cap and
            std.mem.eql(
                u8,
                &lease.rx_resident_cap_digest,
                &self.rx_resident_cap_digest,
            ) and
            lease.rx_client_addr == active_external_rx_client_addr and
            lease.rx_parser_addr == active_external_rx_parser_addr and
            std.meta.eql(
                lease.rx_provenance,
                active_external_rx_provenance,
            ) and
            std.mem.eql(
                u8,
                &lease.rx_authority_digest,
                &active_external_rx_authority_digest,
            ) and
            lease.lifecycle == .acquired and
            std.mem.eql(u8, &lease.digest, &wholeTurnLeaseDigest(lease.*));
    }

    fn activeWholeTurnRxAuthorityMatches(
        self: *const ExternalPumpStorage,
    ) bool {
        if (!std.mem.eql(
            u8,
            &active_external_rx_authority_digest,
            &rxAuthorityDigest(
                active_external_rx_client_addr,
                active_external_rx_parser_addr,
                active_external_rx_provenance,
            ),
        )) return false;
        const client = if (self.owned_client) |*owned| owned else return false;
        if (@intFromPtr(client) != active_external_rx_client_addr or
            @intFromPtr(&client.parser) != active_external_rx_parser_addr)
            return false;
        const state = switch (client.io_mode) {
            .external => |*external| external,
            .blocking => return false,
        };
        return std.meta.eql(
            state.rx_provenance,
            active_external_rx_provenance,
        ) and rxResidentCapOwnerValid(self);
    }

    fn restoreActiveWholeTurnRxAuthority(
        self: *ExternalPumpStorage,
    ) bool {
        const client = if (self.owned_client) |*owned| owned else return false;
        if (@intFromPtr(client) != active_external_rx_client_addr or
            @intFromPtr(&client.parser) != active_external_rx_parser_addr or
            !std.mem.eql(
                u8,
                &active_external_rx_authority_digest,
                &rxAuthorityDigest(
                    active_external_rx_client_addr,
                    active_external_rx_parser_addr,
                    active_external_rx_provenance,
                ),
            ))
            return false;
        const state = switch (client.io_mode) {
            .external => |*external| external,
            .blocking => return false,
        };
        const current_provenance = state.rx_provenance;
        self.saved_self_addr = @intFromPtr(self);
        self.rx_resident_cap = active_external_rx_resident_cap;
        self.rx_resident_cap_digest =
            active_external_rx_resident_cap_digest;
        state.rx_provenance = active_external_rx_provenance;
        if (self.activeWholeTurnRxAuthorityMatches()) return true;
        state.rx_provenance = current_provenance;
        return false;
    }

    fn refreshWholeTurnRxAuthorityAfterParserProgress(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
    ) bool {
        if (active_external_operation_addr != @intFromPtr(self) or
            active_external_lease_addr != @intFromPtr(lease) or
            lease.saved_self_addr != @intFromPtr(lease) or
            lease.lifecycle != .acquired or
            !std.mem.eql(u8, &lease.digest, &wholeTurnLeaseDigest(lease.*)) or
            lease.rx_client_addr != active_external_rx_client_addr or
            lease.rx_parser_addr != active_external_rx_parser_addr or
            !std.meta.eql(
                lease.rx_provenance,
                active_external_rx_provenance,
            ))
            return false;
        const client = if (self.owned_client) |*owned| owned else return false;
        if (@intFromPtr(client) != active_external_rx_client_addr or
            @intFromPtr(&client.parser) != active_external_rx_parser_addr)
            return false;
        const state = switch (client.io_mode) {
            .external => |*external| external,
            .blocking => return false,
        };
        const before = active_external_rx_provenance;
        const after = state.rx_provenance;
        const before_unread = std.math.sub(
            usize,
            before.parser_seal.items_len,
            before.parser_seal.head,
        ) catch return false;
        const after_unread = std.math.sub(
            usize,
            after.parser_seal.items_len,
            after.parser_seal.head,
        ) catch return false;
        const consumed = std.math.sub(
            u64,
            after.buffer_start_absolute,
            before.buffer_start_absolute,
        ) catch return false;
        const consumed_usize = std.math.cast(usize, consumed) orelse return false;
        if (!client_external_mode.parserSealValid(state, &client.parser) or
            before.identity == null or
            !std.meta.eql(before.identity, after.identity) or
            before.destination_slot_len != after.destination_slot_len or
            before.rx_absolute_next != after.rx_absolute_next or
            before.resident_cap != after.resident_cap or
            before.lifecycle != after.lifecycle or
            consumed == 0 or
            consumed_usize > before_unread or
            after_unread != before_unread - consumed_usize or
            before.parser_seal.generation == std.math.maxInt(u64) or
            after.parser_seal.generation != before.parser_seal.generation + 1 or
            self.rx_resident_cap != after.resident_cap or
            !rxResidentCapValid(self))
            return false;
        const authority_digest = rxAuthorityDigest(
            active_external_rx_client_addr,
            active_external_rx_parser_addr,
            after,
        );
        active_external_rx_provenance = after;
        active_external_rx_authority_digest = authority_digest;
        lease.rx_provenance = after;
        lease.rx_authority_digest = authority_digest;
        lease.digest = wholeTurnLeaseDigest(lease.*);
        return self.activeWholeTurnRxAuthorityMatches();
    }

    fn refreshWholeTurnRxAuthorityAfterAdmit(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        admitted: usize,
    ) bool {
        if (admitted == 0 or
            active_external_operation_addr != @intFromPtr(self) or
            active_external_lease_addr != @intFromPtr(lease) or
            lease.saved_self_addr != @intFromPtr(lease) or
            lease.lifecycle != .acquired or
            !std.mem.eql(u8, &lease.digest, &wholeTurnLeaseDigest(lease.*)) or
            lease.rx_client_addr != active_external_rx_client_addr or
            lease.rx_parser_addr != active_external_rx_parser_addr or
            !std.meta.eql(
                lease.rx_provenance,
                active_external_rx_provenance,
            ))
            return false;
        const client = if (self.owned_client) |*owned| owned else return false;
        const state = switch (client.io_mode) {
            .external => |*external| external,
            .blocking => return false,
        };
        const before = active_external_rx_provenance;
        const after = state.rx_provenance;
        const before_unread = std.math.sub(
            usize,
            before.parser_seal.items_len,
            before.parser_seal.head,
        ) catch return false;
        const after_unread = std.math.sub(
            usize,
            after.parser_seal.items_len,
            after.parser_seal.head,
        ) catch return false;
        const next_absolute = std.math.add(
            u64,
            before.rx_absolute_next,
            admitted,
        ) catch return false;
        const next_unread = std.math.add(
            usize,
            before_unread,
            admitted,
        ) catch return false;
        if (!client_external_mode.parserSealValid(state, &client.parser) or
            !std.meta.eql(before.identity, after.identity) or
            before.destination_slot_len != after.destination_slot_len or
            before.buffer_start_absolute != after.buffer_start_absolute or
            after.rx_absolute_next != next_absolute or
            after_unread != next_unread or
            before.resident_cap != after.resident_cap or
            before.lifecycle != after.lifecycle or
            before.parser_seal.generation == std.math.maxInt(u64) or
            after.parser_seal.generation != before.parser_seal.generation + 1 or
            self.rx_resident_cap != after.resident_cap or
            !rxResidentCapValid(self))
            return false;
        const authority_digest = rxAuthorityDigest(
            active_external_rx_client_addr,
            active_external_rx_parser_addr,
            after,
        );
        active_external_rx_provenance = after;
        active_external_rx_authority_digest = authority_digest;
        lease.rx_provenance = after;
        lease.rx_authority_digest = authority_digest;
        lease.digest = wholeTurnLeaseDigest(lease.*);
        return self.activeWholeTurnRxAuthorityMatches();
    }

    fn clearActiveWholeTurnRxAuthority() void {
        active_external_rx_resident_cap = 0;
        active_external_rx_resident_cap_digest = [_]u8{0} ** 32;
        active_external_rx_client_addr = 0;
        active_external_rx_parser_addr = 0;
        active_external_rx_provenance = .{};
        active_external_rx_authority_digest = [_]u8{0} ** 32;
    }

    fn releaseActiveWholeTurnTxClaim() ?bool {
        if (active_external_tx_state_addr == 0) return null;
        const state: *client_external_mode.State =
            @ptrFromInt(active_external_tx_state_addr);
        active_external_tx_state_addr = 0;
        return state.releaseTxOperationAndObserveClose();
    }

    pub fn releaseWholeTurnLease(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
    ) WholeTurnReleaseResult {
        if (active_external_operation_addr != @intFromPtr(self) or
            active_external_lease_addr != @intFromPtr(lease) or
            active_external_lease_generation == 0)
            return .ignored_untrusted;
        const intact_identity = self.wholeTurnLeaseIdentityValid(lease);
        if (intact_identity and
            self.lifecycle == .live and
            (self.semantic_state == .active or self.semantic_state == .terminal))
        {
            const close_for_callback_quarantine =
                self.callback_quarantine_pending;
            lease.* = .{ .lifecycle = .released };
            active_external_lease_addr = 0;
            active_external_lease_generation = 0;
            clearActiveWholeTurnRxAuthority();
            active_external_operation_addr = 0;
            const close_requested = releaseActiveWholeTurnTxClaim() orelse
                @panic("external whole-turn TX claim release failed");
            if (close_for_callback_quarantine) {
                self.quarantinePublishedStorageAfterCallbackDrift();
                self.access_claim.store(
                    @intFromEnum(StorageClaim.dead),
                    .release,
                );
                return .aborted_terminal;
            }
            if (close_requested)
                self.semantic_state = .{ .terminal = .{
                    .reason = .invariant_failure,
                    .fd_disposition = .owner_cleanup,
                } };
            self.access_claim.store(
                @intFromEnum(StorageClaim.idle),
                .release,
            );
            return if (close_requested) .aborted_terminal else .released;
        }
        if (intact_identity)
            lease.* = .{ .lifecycle = .aborted };
        // The thread-local final address is the private outer-owner authority. A copied or foreign
        // lease cannot reach this branch. Restore the lifecycle proven at acquire so a hostile
        // storage-header drift cannot forge moved/dead and bypass cleanup. If the lease descriptor
        // drifted, do not dereference it again after the identity verdict.
        if (!self.restoreActiveWholeTurnRxAuthority())
            latchCrossOwnerQuarantine();
        self.lifecycle = .live;
        self.semantic_state = .{ .terminal = .{
            .reason = .invariant_failure,
            .fd_disposition = .owner_cleanup,
        } };
        active_external_lease_addr = 0;
        active_external_lease_generation = 0;
        clearActiveWholeTurnRxAuthority();
        active_external_operation_addr = 0;
        _ = releaseActiveWholeTurnTxClaim() orelse
            @panic("external whole-turn TX claim release failed");
        self.access_claim.store(
            @intFromEnum(StorageClaim.idle),
            .release,
        );
        return .aborted_terminal;
    }

    pub fn snapshotInheritedRxBlockersUnderHeldLease(
        self: *const ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        out: *InheritedRxBlockerSnapshot,
    ) AccessError!void {
        if (!self.validateWholeTurnLease(lease))
            return error.TransactionBusy;
        if (!std.meta.eql(out.*, InheritedRxBlockerSnapshot{}))
            return error.InvalidSnapshot;
        if (rangesOverlap(
            @intFromPtr(out),
            @sizeOf(InheritedRxBlockerSnapshot),
            @intFromPtr(self),
            @sizeOf(ExternalPumpStorage),
        ) or rangesOverlap(
            @intFromPtr(out),
            @sizeOf(InheritedRxBlockerSnapshot),
            @intFromPtr(lease),
            @sizeOf(ExternalWholeTurnLease),
        ))
            return error.InvalidDescriptor;
        if (!rangeContains(
            lease.scratch_addr,
            lease.scratch_len,
            @intFromPtr(out),
            @sizeOf(InheritedRxBlockerSnapshot),
        ))
            return error.InvalidDescriptor;
        const snapshot = try self.expectedInheritedSnapshot(lease, out);
        out.* = snapshot;
    }

    pub fn validateAndConsumeInheritedSnapshot(
        self: *const ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        snapshot: *InheritedRxBlockerSnapshot,
    ) AccessError!bool {
        if (!self.validateWholeTurnLease(lease))
            return error.TransactionBusy;
        if (snapshot.lifecycle != .prepared or
            snapshot.saved_self_addr != @intFromPtr(snapshot))
            return error.InvalidSnapshot;
        const expected = try self.expectedInheritedSnapshot(lease, snapshot);
        if (!std.meta.eql(snapshot.*, expected))
            return error.InvalidSnapshot;
        const blocked = snapshot.hasBlocker();
        snapshot.* = .{ .lifecycle = .consumed };
        return blocked;
    }

    fn validateLiveScreenConsumePermit(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        permit: *const LiveScreenConsumePermit,
    ) bool {
        if (!self.validateWholeTurnLease(lease) or
            self.operation_reentry_latched or
            permit.saved_self_addr != @intFromPtr(permit) or
            permit.storage_addr != @intFromPtr(self) or
            permit.lease_addr != @intFromPtr(lease) or
            permit.operation_generation != self.operation_generation or
            permit.lifecycle != .prepared or
            !std.mem.eql(
                u8,
                &permit.digest,
                &liveScreenConsumePermitDigest(permit),
            ) or !self.liveScreenValid())
            return false;
        const backlog = &self.live_screen;
        if (backlog.lifecycle != .active or backlog.len == 0 or
            permit.fifo_generation != backlog.generation or
            permit.fifo_head != backlog.head or
            permit.fifo_len != backlog.len or
            !std.meta.eql(permit.token, backlog.tokens[backlog.head]) or
            !self.inbox_ledger.validatePreparedLiveCommit(
                &permit.live_batch,
                &permit.retirement,
                &permit.dispositions,
                &permit.live_commit,
                @intFromPtr(permit),
                @intFromPtr(self),
                self.operation_generation,
            ))
            return false;
        const view = self.inbox_ledger.borrow(
            permit.token,
            .completed,
        ) catch return false;
        return std.meta.eql(view.semantic.completed, permit.semantic) and
            std.mem.eql(
                u8,
                &external_owner_cleanup.contentDigest(view.bytes),
                &permit.payload_digest,
            );
    }

    /// Applies exactly one completed live-screen FIFO head. The callback executes while the
    /// whole-turn lease excludes teardown and sibling mutation. Its success is only advisory until
    /// every owner seal and the checked ledger retirement are revalidated after it returns.
    fn consumeLiveScreenHeadUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        ops: *const BufferedRxOps,
        permit: *LiveScreenConsumePermit,
    ) LiveScreenConsumeResult {
        if (!self.validateWholeTurnLease(lease) or
            !std.meta.eql(permit.*, LiveScreenConsumePermit{}) or
            !rangeContains(
                lease.scratch_addr,
                lease.scratch_len,
                @intFromPtr(permit),
                @sizeOf(LiveScreenConsumePermit),
            ) or !self.liveScreenValid())
            return .invalid_state;
        const backlog = &self.live_screen;
        if (backlog.lifecycle == .empty and backlog.len == 0)
            return .no_work;
        if (backlog.lifecycle != .active or backlog.len == 0 or
            backlog.generation == std.math.maxInt(u64))
            return .invalid_state;
        const token = backlog.tokens[backlog.head];
        const view = self.inbox_ledger.borrow(
            token,
            .completed,
        ) catch return .invalid_state;
        const semantic = switch (view.semantic) {
            .completed => |completed| completed,
            else => return .invalid_state,
        };
        const identity = switch (semantic.provenance) {
            .external => |range| range.identity,
            .untracked => return .invalid_state,
        };
        self.inbox_ledger.beginLiveBatch(
            &permit.live_batch,
            if (self.owned_client) |*owned|
                owned.parser.allocator
            else
                return .invalid_state,
            identity,
        ) catch return .invalid_state;
        self.inbox_ledger.prepareLiveRelease(
            &permit.live_batch,
            .{ .existing = token },
            .completed,
        ) catch return .invalid_state;
        self.inbox_ledger.finishLiveBatch(
            &permit.live_batch,
        ) catch return .invalid_state;
        self.inbox_ledger.prepareLiveCommit(
            &permit.live_batch,
            &permit.retirement,
            &permit.dispositions,
            @intFromPtr(permit),
            @intFromPtr(self),
            self.operation_generation,
            &permit.live_commit,
        ) catch return .invalid_state;
        permit.saved_self_addr = @intFromPtr(permit);
        permit.storage_addr = @intFromPtr(self);
        permit.lease_addr = @intFromPtr(lease);
        permit.operation_generation = self.operation_generation;
        permit.fifo_generation = backlog.generation;
        permit.fifo_head = backlog.head;
        permit.fifo_len = backlog.len;
        permit.token = token;
        permit.semantic = semantic;
        permit.payload_digest = external_owner_cleanup.contentDigest(view.bytes);
        permit.lifecycle = .prepared;
        permit.digest = liveScreenConsumePermitDigest(permit);
        const callback_entry_permit = permit.*;

        const callback_result = ops.apply_live_screen(ops.context, view);
        const callback_authority_valid =
            self.validateLiveScreenConsumePermit(lease, permit);
        self.operation_reentry_latched = false;
        if (!callback_authority_valid) {
            permit.* = callback_entry_permit;
            if (!self.abortLiveScreenConsumePermit(permit))
                latchCrossOwnerQuarantine();
            return .invalid_state;
        }
        if (callback_result == .retry) {
            if (!self.abortLiveScreenConsumePermit(permit)) {
                latchCrossOwnerQuarantine();
                return .invalid_state;
            }
            return .retry;
        }

        const next_len = backlog.len - 1;
        const next_generation = backlog.generation + 1;
        const next_head: u8 = @intCast(
            (@as(usize, backlog.head) + 1) %
                external_inbox_ledger.max_live_mutations,
        );
        backlog.tokens[backlog.head] = .{ .slot = 0, .generation = 0 };
        if (next_len == 0) {
            backlog.* = .{};
        } else {
            backlog.head = next_head;
            backlog.len = next_len;
            backlog.generation = next_generation;
            backlog.owner_digest = liveScreenDigest(self, backlog);
        }
        self.inbox_ledger.consumePreparedLiveCommitUnchecked(
            &permit.live_batch,
            &permit.retirement,
            &permit.dispositions,
            &permit.live_commit,
        );
        const retire_result = permit.retirement.retire();
        permit.* = .{ .lifecycle = .consumed };
        if (retire_result != .retired)
            return .invalid_state;
        return .consumed;
    }

    fn abortLiveScreenConsumePermit(
        self: *ExternalPumpStorage,
        permit: *LiveScreenConsumePermit,
    ) bool {
        if (self.inbox_ledger.abortPreparedLiveCommit(
            &permit.live_batch,
            &permit.retirement,
            &permit.dispositions,
            &permit.live_commit,
        ) != .aborted)
            return false;
        if (!external_inbox_ledger.ExternalInboxLedger
            .resetPreparedLiveCommit(&permit.live_commit))
            return false;
        if (self.inbox_ledger.abortPreparedLiveBatch(
            &permit.live_batch,
        ) != .aborted)
            return false;
        permit.* = .{ .lifecycle = .aborted };
        return true;
    }

    fn terminalRxTurn(
        self: *ExternalPumpStorage,
        reason: client_pump.TerminalReason,
        rx_bytes: usize,
        rx_frames: usize,
    ) client_pump.TurnResult {
        const terminal = client_pump.ExternalPumpTerminal{
            .reason = reason,
            .fd_disposition = .owner_cleanup,
        };
        self.semantic_state = .{ .terminal = terminal };
        return terminalRxResult(terminal, rx_bytes, rx_frames);
    }

    fn terminalRxResult(
        terminal: client_pump.ExternalPumpTerminal,
        rx_bytes: usize,
        rx_frames: usize,
    ) client_pump.TurnResult {
        var result = client_pump.decide(.{
            .turn = .{
                .readable = false,
                .writable = false,
                .now_ns = 0,
            },
            .parser = .empty,
            .socket_rx_drained = false,
            .terminal = terminal,
        });
        result.rx_bytes = rx_bytes;
        result.rx_frames = rx_frames;
        return result;
    }

    const BufferedTraversalCommitSummary = struct {
        rx_bytes: usize,
        rx_frames: usize,
        final_readiness: client_external_mode.RxParserReadiness,
        budget_exhausted: bool,
    };

    const BufferedTraversalCommitTerminal = struct {
        reason: client_pump.TerminalReason,
        rx_bytes: usize,
        rx_frames: usize,
    };

    const BufferedTraversalCommitResult = union(enum) {
        completed: BufferedTraversalCommitSummary,
        terminal: BufferedTraversalCommitTerminal,
    };

    const RxPolicyFacts = struct {
        turn: client_pump.TurnInput,
        parser: client_pump.ParserReadiness = .empty,
        inherited_blocker: bool = false,
        rx_frame_budget_exhausted: bool = false,
        rx_read_budget_exhausted: bool = false,
        work_budget_exhausted: bool = false,
        terminal: ?client_pump.ExternalPumpTerminal = null,
        deadlines: [5]?i128 = .{null} ** 5,
    };

    const RxPreparedSummary = struct {
        policy: RxPolicyFacts,
        rx_read_bytes: usize = 0,
        rx_bytes: usize = 0,
        rx_frames: usize = 0,
    };

    const RxPreparation = union(enum) {
        terminal: RxPreparedSummary,
        without_drain: RxPreparedSummary,
        drained: RxPreparedSummary,
    };

    fn terminalRxPreparation(
        _: *ExternalPumpStorage,
        turn: client_pump.TurnInput,
        reason: client_pump.TerminalReason,
        rx_read_bytes: usize,
        rx_bytes: usize,
        rx_frames: usize,
    ) RxPreparation {
        const terminal = client_pump.ExternalPumpTerminal{
            .reason = reason,
            .fd_disposition = .owner_cleanup,
        };
        return .{ .terminal = .{
            .policy = .{
                .turn = turn,
                .terminal = terminal,
            },
            .rx_read_bytes = rx_read_bytes,
            .rx_bytes = rx_bytes,
            .rx_frames = rx_frames,
        } };
    }

    fn terminalInjectedRxTurn(
        self: *ExternalPumpStorage,
        reason: client_pump.TerminalReason,
        rx_read_bytes: usize,
        rx_bytes: usize,
        rx_frames: usize,
    ) client_pump.TurnResult {
        var result = self.terminalRxTurn(reason, rx_bytes, rx_frames);
        result.rx_read_bytes = rx_read_bytes;
        return result;
    }

    /// Closes the callback-free RX ownership graph before the outer turn releases its lease.
    ///
    /// This is deliberately the only terminal epilogue for the injected product path.  It must
    /// never invoke transport, allocator, projection, or retirement callbacks: callback-bearing
    /// mechanics have already returned, and their hidden TLS authority must be gone before any
    /// terminal evidence is interpreted.
    fn finalizeInjectedRxTerminalUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        result: client_pump.TurnResult,
    ) client_pump.TurnResult {
        var terminal = result;
        if (terminal.terminal == null) {
            terminal = self.terminalInjectedRxTurn(
                .invariant_failure,
                result.rx_read_bytes,
                result.rx_bytes,
                result.rx_frames,
            );
        }
        if (active_callback_region_addr != 0 or
            active_callback_release_addr != 0 or
            active_callback_storage_addr != 0 or
            active_callback_lease_addr != 0 or
            active_callback_scratch_addr != 0 or
            active_callback_permit_addr != 0)
        {
            scratch.lifecycle = .terminal;
            return self.terminalInjectedRxTurn(
                .invariant_failure,
                terminal.rx_read_bytes,
                terminal.rx_bytes,
                terminal.rx_frames,
            );
        }

        switch (scratch.callback_region.lifecycle) {
            .empty => {
                if (!callbackRegionTokenPristine(&scratch.callback_region))
                    scratch.lifecycle = .terminal;
            },
            .consumed => {
                if (!resetConsumedCallbackRegion(
                    scratch,
                    &scratch.callback_region,
                )) scratch.lifecycle = .terminal;
            },
            .active, .quarantined => scratch.lifecycle = .terminal,
        }

        const client = if (self.owned_client) |*owned| owned else {
            scratch.lifecycle = .terminal;
            return self.terminalInjectedRxTurn(
                .invariant_failure,
                terminal.rx_read_bytes,
                terminal.rx_bytes,
                terminal.rx_frames,
            );
        };
        const rx_state = switch (client.io_mode) {
            .external => |*state| state,
            .blocking => {
                scratch.lifecycle = .terminal;
                return self.terminalInjectedRxTurn(
                    .invariant_failure,
                    terminal.rx_read_bytes,
                    terminal.rx_bytes,
                    terminal.rx_frames,
                );
            },
        };

        const prepared_result =
            client_external_mode.terminalizePreparedAdmitNoCallback(
                rx_state,
                &client.parser,
                &scratch.read.prepared_admit,
            );
        var prepared_closed = true;
        switch (prepared_result) {
            .pristine => {},
            .ordinary_finished => {
                prepared_closed = resetCompletedPreparedAdmit(
                    &scratch.read.prepared_admit,
                );
            },
            .quarantine_pending => |pending| {
                prepared_closed = completeGuardedAdmitQuarantine(
                    &scratch.read.prepared_admit,
                    pending.outcome_tag,
                    pending.quarantine,
                    &scratch.quarantine_receipt,
                );
            },
            .quarantine_accounted => |accounted| {
                prepared_closed = finalizeGuardedAdmitQuarantine(
                    &scratch.read.prepared_admit,
                    accounted.outcome_tag,
                    accounted.quarantine,
                    &scratch.quarantine_receipt,
                );
            },
            .terminalized => |pending| {
                prepared_closed = completeGuardedAdmitQuarantine(
                    &scratch.read.prepared_admit,
                    pending.outcome_tag,
                    pending.quarantine,
                    &scratch.quarantine_receipt,
                );
            },
            .unrecoverable => prepared_closed = false,
        }

        // A stopped graph exists only after the receipt has been published. Include every public
        // edge in the predicate so a corrupted primary edge cannot hide a still-live mirror.
        const stopped_graph_present =
            scratch.stopped_borrow.saved_self_addr != 0 or
            scratch.borrow_use_permit.saved_self_addr != 0 or
            scratch.would_block_seed.saved_self_addr != 0 or
            scratch.prepared_admit_use_permit.saved_self_addr != 0 or
            scratch.read.active_borrow_addr != 0 or
            scratch.read.active_use_permit_addr != 0 or
            scratch.read.active_prepared_use_permit_addr != 0;
        if (prepared_closed and stopped_graph_present) {
            const graph_result = client_external_rx_read.terminalizeStoppedGraphNoCallback(
                &scratch.read,
                &scratch.collect_receipt,
                &scratch.stopped_borrow,
                &scratch.borrow_use_permit,
                &scratch.would_block_seed,
                &scratch.prepared_admit_use_permit,
            );
            prepared_closed = switch (graph_result) {
                .closed, .already_closed => true,
                .unrecoverable => blk: {
                    // `endStoppedUse` has already removed the active permit edge at the
                    // before-settle seam.  That graph is no longer eligible for the active-graph
                    // closer, but its frozen disposition is sufficient for the ordinary
                    // callback-free settle+teardown path.
                    if (scratch.borrow_use_permit.lifecycle != .released or
                        scratch.stopped_borrow.lifecycle != .borrowed or
                        scratch.read.active_use_permit_addr != 0 or
                        scratch.read.active_prepared_use_permit_addr != 0)
                        break :blk false;
                    var disposition =
                        client_external_rx_read.StoppedDisposition{
                            .staged = if (terminal.rx_read_bytes != 0)
                                .consumed
                            else
                                .discarded,
                            .would_block = .not_present,
                        };
                    if (scratch.collect_receipt.stop == .would_block) {
                        disposition.would_block =
                            switch (scratch.would_block_seed.lifecycle) {
                                .consumed => .consumed,
                                .aborted => .aborted,
                                else => break :blk false,
                            };
                    }
                    if (!client_external_rx_read.settleStopped(
                        &scratch.read,
                        &scratch.collect_receipt,
                        &scratch.stopped_borrow,
                        disposition,
                    )) break :blk false;
                    break :blk client_external_rx_read.teardown(
                        &scratch.read,
                    ) == .closed;
                },
            };
        }

        switch (scratch.drain_evidence.lifecycle) {
            .empty => {
                if (!rxDrainEvidencePristine(&scratch.drain_evidence))
                    prepared_closed = false;
            },
            .prepared, .armed => {
                if (!self.abortRxDrainEvidence(
                    lease,
                    scratch,
                ) or !finishRxDrainEvidence(scratch))
                    prepared_closed = false;
            },
            .consumed, .aborted => {
                const evidence = &scratch.drain_evidence;
                if (!self.rxDrainEvidenceCurrentForCleanup(
                    lease,
                    scratch,
                    evidence,
                ) or !finishRxDrainEvidence(scratch))
                    prepared_closed = false;
            },
            .finished => {
                const evidence = &scratch.drain_evidence;
                if (!self.rxDrainEvidenceCurrentForCleanup(
                    lease,
                    scratch,
                    evidence,
                ))
                    prepared_closed = false;
            },
        }
        // Traversal may leave its heap scratch reserved by the storage for reuse, but it may not
        // leave a movable aggregate or an in-progress traversal behind.  Do not destroy either
        // here: destruction owns allocator callbacks and belongs to the later storage teardown.
        const traversal_closed = switch (scratch.traversal.lifecycle) {
            .ready, .closed => true,
            .empty, .busy => false,
        };
        // A revoke rollback may have completed only a prefix before the terminal path was chosen.
        // Replay the sealed cleanup graph while the original whole-turn lease is still held; the
        // progress typestate makes already-aborted TX ownership a no-op instead of a double abort.
        const revoked_cleanup_closed = self.resumeFailedPreparedRevokeCleanup(
            lease,
            scratch,
        );
        if (!revoked_cleanup_closed)
            self.quarantineFailedPreparedRevokeCleanup(scratch);
        const aggregate_retained =
            self.intentScratchReservationValid() and
            self.rxAggregateReservationValid() and
            self.rx_aggregate_reservation.lifecycle != .active and
            self.rx_aggregate_reservation.lifecycle != .destroying;
        prepared_closed = prepared_closed and traversal_closed and
            revoked_cleanup_closed and aggregate_retained;
        if (!prepared_closed)
            terminal = self.terminalInjectedRxTurn(
                .invariant_failure,
                terminal.rx_read_bytes,
                terminal.rx_bytes,
                terminal.rx_frames,
            );
        scratch.lifecycle = .terminal;
        if (terminal.terminal) |reason|
            self.semantic_state = .{ .terminal = reason };
        return terminal;
    }

    fn completeGuardedAdmitQuarantine(
        prepared: *client_external_mode.PreparedRxAppend,
        outcome_tag: client_external_mode.GuardedQuarantineOutcomeTag,
        quarantine: client_external_mode.GuardedAdmitQuarantine,
        receipt: *client_external_mode.GuardedQuarantineAccountingReceipt,
    ) bool {
        return accountGuardedAdmitQuarantine(
            prepared,
            outcome_tag,
            quarantine,
            receipt,
        ) and finalizeGuardedAdmitQuarantine(
            prepared,
            outcome_tag,
            quarantine,
            receipt,
        );
    }

    fn resetCompletedPreparedAdmit(
        prepared: *client_external_mode.PreparedRxAppend,
    ) bool {
        return client_external_mode.resetFinishedPreparedAdmit(prepared);
    }

    fn finalizeGuardedAdmitQuarantine(
        prepared: *client_external_mode.PreparedRxAppend,
        outcome_tag: client_external_mode.GuardedQuarantineOutcomeTag,
        quarantine: client_external_mode.GuardedAdmitQuarantine,
        receipt: *client_external_mode.GuardedQuarantineAccountingReceipt,
    ) bool {
        return client_external_mode.finalizeQuarantinedPreparedAdmit(
            prepared,
            outcome_tag,
            quarantine,
            receipt,
        );
    }

    fn drainEvidenceDigest(
        evidence: *const RxDrainEvidence,
    ) external_owner_seal.Digest {
        var writer = external_owner_seal.Writer.init("MARURDE3");
        writer.writeBytes(&evidence.domain);
        writer.writeU16(evidence.version);
        writer.writeUsize(evidence.saved_self_addr);
        writer.writeUsize(evidence.storage_addr);
        writer.writeU64(evidence.owner_incarnation);
        writer.writeBytes(&evidence.owner_incarnation_digest);
        writer.writeUsize(evidence.lease_addr);
        writer.writeU64(evidence.lease_generation);
        writer.writeU64(evidence.operation_generation);
        writer.writeUsize(evidence.read_scratch_addr);
        writer.writeU64(evidence.pre_settle_scratch_generation);
        writer.writeU64(evidence.expected_post_settle_generation);
        writer.writeUsize(evidence.receipt_addr);
        writer.writeUsize(evidence.borrow_addr);
        writer.writeUsize(evidence.permit_addr);
        writer.writeUsize(evidence.seed_addr);
        writer.writeBytes(&evidence.seed_authority_continuity_digest);
        writer.writeBytes(&evidence.prepared_seed_authority_digest);
        writer.writeBytes(&evidence.consumed_seed_authority_digest);
        writer.writeU64(evidence.read_attempt_generation);
        writer.writeUsize(evidence.parser_addr);
        client_external_rx_read.writeParserSeal(
            &writer,
            &evidence.parser_seal,
        );
        writer.writeU8(@intFromEnum(evidence.final_readiness));
        writer.writeBool(evidence.rx_frame_budget_exhausted);
        writer.writeBool(evidence.rx_read_budget_exhausted);
        writer.writeBool(evidence.work_budget_exhausted);
        writer.writeU8(@intFromEnum(evidence.mode));
        writer.writeBytes(&evidence.completed_exception_digest);
        writer.writeU64(evidence.owner_inventory_generation);
        writer.writeBytes(&evidence.owner_snapshot_digest);
        writer.writeBytes(&evidence.initial_inherited_snapshot_digest);
        writer.writeBytes(&evidence.inherited_blocker_snapshot_digest);
        writer.writeBool(evidence.final_owner_blockers_clear);
        writer.writeU8(@intFromEnum(evidence.lifecycle));
        return writer.finish();
    }

    fn rxDrainEvidenceSealed(evidence: *const RxDrainEvidence) bool {
        const mode_canonical = switch (evidence.mode) {
            .general => std.mem.allEqual(u8, &evidence.completed_exception_digest, 0),
            .completed_control => !std.mem.allEqual(u8, &evidence.completed_exception_digest, 0),
        };
        return std.mem.eql(u8, &evidence.domain, "MARURDE3") and
            evidence.version == 2 and mode_canonical and
            evidence.saved_self_addr == @intFromPtr(evidence) and
            !std.mem.allEqual(u8, &evidence.digest, 0) and
            std.mem.eql(
                u8,
                &evidence.digest,
                &drainEvidenceDigest(evidence),
            );
    }

    const DrainBlockerProjection = struct {
        digest: external_owner_seal.Digest,
        all_clear: bool,
        mode: RxDrainEvidenceMode = .general,
        completed_exception_digest: external_owner_seal.Digest = [_]u8{0} ** 32,
    };

    const RxDrainFinalState = struct {
        parser_readiness: client_external_mode.RxParserReadiness,
        policy_parser: client_pump.ParserReadiness,
        parser_seal: client_external_mode.ParserAuthoritySeal,
        allowance_stop: client_external_rx_read.AcceptedAllowanceStop,
        frame_budget_exhausted: bool,
        read_budget_exhausted: bool,
        work_budget_exhausted: bool,
        terminal: bool,
        blockers: DrainBlockerProjection,
        owner_inventory_generation: u64,
        owner_snapshot_digest: external_owner_seal.Digest,

        fn eligible(self: @This()) bool {
            return !self.terminal and
                self.parser_readiness == .empty and
                self.policy_parser == .empty and
                self.allowance_stop == .continue_collecting and
                !self.frame_budget_exhausted and
                !self.read_budget_exhausted and
                !self.work_budget_exhausted and
                self.blockers.all_clear;
        }
    };

    fn currentDrainBlockerProjection(
        self: *const ExternalPumpStorage,
    ) ?DrainBlockerProjection {
        return self.currentDrainBlockerProjectionForMode(.general);
    }

    fn currentCompletedExceptionDigest(
        self: *const ExternalPumpStorage,
    ) ?external_owner_seal.Digest {
        if (!self.completedControlValid()) return null;
        const completed = switch (self.completed_control) {
            .completed => |*value| value,
            .none, .terminal => return null,
        };
        var exception = external_owner_seal.Writer.init("MARUCDE1");
        exception.writeBytes(&completed.owner_digest);
        exception.writeBytes(&self.control_correlation.digest);
        return exception.finish();
    }

    /// F3 keeps the general D2 projection strict and grants one sealed exception only when the
    /// canonical completed owner and its correlation still agree exactly.
    fn currentDrainBlockerProjectionForMode(
        self: *const ExternalPumpStorage,
        mode: RxDrainEvidenceMode,
    ) ?DrainBlockerProjection {
        const live = self.liveOwnerBlockerProjection() orelse return null;
        const resize_pending = switch (self.owner_resize) {
            .none => false,
            .current => |current| current.pending,
        };
        var completed_exception_digest: external_owner_seal.Digest = [_]u8{0} ** 32;
        const response_clear = switch (mode) {
            .general => !live.response_pending,
            .completed_control => blk: {
                if (!live.response_pending) break :blk false;
                completed_exception_digest = self.currentCompletedExceptionDigest() orelse
                    break :blk false;
                break :blk true;
            },
        };
        const all_clear =
            self.screen_pending_summary.retained_count == 0 and
            !self.metadata_pending_summary.pending and
            !live.partial_pending and !live.screen_pending and
            response_clear and !resize_pending;
        var writer = external_owner_seal.Writer.init("MARUDBP1");
        writer.writeU64(self.operation_generation);
        writer.writeUsize(self.screen_pending_summary.retained_count);
        writer.writeU64(self.screen_pending_summary.generation);
        writer.writeBool(self.metadata_pending_summary.pending);
        writer.writeU64(self.metadata_pending_summary.revision);
        writer.writeBool(live.partial_pending);
        writer.writeBool(live.screen_pending);
        writer.writeBool(live.response_pending);
        writer.writeBool(resize_pending);
        writer.writeBytes(&self.inheritedOwnerDigest());
        writer.writeU8(@intFromEnum(mode));
        writer.writeBytes(&completed_exception_digest);
        return .{
            .digest = writer.finish(),
            .all_clear = all_clear,
            .mode = mode,
            .completed_exception_digest = completed_exception_digest,
        };
    }

    fn rxDrainEvidenceCurrentForCleanup(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        evidence: *const RxDrainEvidence,
    ) bool {
        const read_generation_current = switch (evidence.lifecycle) {
            .prepared, .armed => scratch.read.generation ==
                evidence.pre_settle_scratch_generation or
                scratch.read.generation ==
                    evidence.expected_post_settle_generation,
            .consumed, .aborted, .finished => scratch.read.generation ==
                evidence.expected_post_settle_generation,
            .empty => false,
        };
        return active_callback_region_addr == 0 and
            active_callback_release_addr == 0 and
            ownerIncarnationValid(self) and
            self.validateWholeTurnLease(lease) and
            rxDrainEvidenceSealed(evidence) and
            evidence.storage_addr == @intFromPtr(self) and
            evidence.owner_incarnation == self.owner_incarnation and
            std.mem.eql(
                u8,
                &evidence.owner_incarnation_digest,
                &self.owner_incarnation_seal.digest,
            ) and
            evidence.lease_addr == @intFromPtr(lease) and
            evidence.lease_generation == lease.operation_generation and
            evidence.operation_generation == self.operation_generation and
            evidence.read_scratch_addr == @intFromPtr(&scratch.read) and
            read_generation_current;
    }

    fn prepareRxDrainEvidence(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        final: RxDrainFinalState,
        initial_inherited_snapshot_digest: external_owner_seal.Digest,
    ) bool {
        const client = if (self.owned_client) |*owned| owned else return false;
        const state = switch (client.io_mode) {
            .external => |*external| external,
            .blocking => return false,
        };
        const readiness = client_external_mode.parserReadiness(
            state,
            &client.parser,
        ) catch return false;
        const seed_authority = client_external_rx_read
            .snapshotDrainSeedAuthority(
            &scratch.read,
            &scratch.collect_receipt,
            &scratch.stopped_borrow,
            &scratch.borrow_use_permit,
            &scratch.would_block_seed,
            .prepared,
        ) orelse return false;
        if (active_callback_region_addr != 0 or
            active_callback_release_addr != 0 or
            !ownerIncarnationValid(self) or
            !self.validateWholeTurnLease(lease) or
            readiness != final.parser_readiness or !final.eligible())
            return false;
        const snapshot = buildRxOwnerAuthoritySnapshot(
            self,
            lease,
            scratch,
        ) orelse return false;
        const blocker = self.currentDrainBlockerProjectionForMode(final.blockers.mode) orelse return false;
        if (!blocker.all_clear or
            !std.mem.eql(u8, &blocker.digest, &final.blockers.digest) or
            !std.meta.eql(
                state.rx_provenance.parser_seal,
                final.parser_seal,
            ) or snapshot.inventory_generation !=
            final.owner_inventory_generation or
            !std.mem.eql(
                u8,
                &snapshot.digest,
                &final.owner_snapshot_digest,
            ))
            return false;
        const evidence = &scratch.drain_evidence;
        if (evidence.saved_self_addr != 0 or evidence.lifecycle != .empty)
            return false;
        evidence.* = .{
            .domain = "MARURDE3".*,
            .version = 2,
            .saved_self_addr = @intFromPtr(evidence),
            .storage_addr = @intFromPtr(self),
            .owner_incarnation = self.owner_incarnation,
            .owner_incarnation_digest = self.owner_incarnation_seal.digest,
            .lease_addr = @intFromPtr(lease),
            .lease_generation = lease.operation_generation,
            .operation_generation = self.operation_generation,
            .read_scratch_addr = @intFromPtr(&scratch.read),
            .pre_settle_scratch_generation = scratch.read.generation,
            .expected_post_settle_generation = std.math.add(u64, scratch.read.generation, 1) catch return false,
            .receipt_addr = seed_authority.receipt_addr,
            .borrow_addr = seed_authority.borrow_addr,
            .permit_addr = seed_authority.permit_addr,
            .seed_addr = seed_authority.seed_addr,
            .seed_authority_continuity_digest = seed_authority.continuity_digest,
            .prepared_seed_authority_digest = seed_authority.digest,
            .read_attempt_generation = seed_authority.attempt_generation,
            .parser_addr = @intFromPtr(&client.parser),
            .parser_seal = state.rx_provenance.parser_seal,
            .final_readiness = readiness,
            .rx_frame_budget_exhausted = final.frame_budget_exhausted,
            .rx_read_budget_exhausted = final.read_budget_exhausted,
            .work_budget_exhausted = final.work_budget_exhausted,
            .mode = blocker.mode,
            .completed_exception_digest = blocker.completed_exception_digest,
            .owner_inventory_generation = snapshot.inventory_generation,
            .owner_snapshot_digest = snapshot.digest,
            .initial_inherited_snapshot_digest = initial_inherited_snapshot_digest,
            .inherited_blocker_snapshot_digest = blocker.digest,
            .final_owner_blockers_clear = blocker.all_clear,
            .lifecycle = .prepared,
        };
        evidence.digest = drainEvidenceDigest(evidence);
        if (!rxDrainEvidenceSealed(evidence) or
            evidence.storage_addr != @intFromPtr(self) or
            evidence.owner_incarnation != self.owner_incarnation or
            !std.mem.eql(
                u8,
                &evidence.owner_incarnation_digest,
                &self.owner_incarnation_seal.digest,
            ) or
            evidence.lease_addr != @intFromPtr(lease) or
            evidence.read_scratch_addr != @intFromPtr(&scratch.read) or
            evidence.pre_settle_scratch_generation != scratch.read.generation or
            evidence.parser_addr != @intFromPtr(&client.parser) or
            !std.meta.eql(
                evidence.parser_seal,
                state.rx_provenance.parser_seal,
            ))
            return false;
        return true;
    }

    fn armRxDrainEvidence(
        scratch: *ExternalRxTurnScratch,
        consumed_attempt_generation: u64,
    ) bool {
        if (active_callback_region_addr != 0 or
            active_callback_release_addr != 0)
            return false;
        const evidence = &scratch.drain_evidence;
        const seed_authority = client_external_rx_read
            .snapshotDrainSeedAuthority(
            &scratch.read,
            &scratch.collect_receipt,
            &scratch.stopped_borrow,
            &scratch.borrow_use_permit,
            &scratch.would_block_seed,
            .consumed,
        ) orelse return false;
        if (evidence.lifecycle != .prepared or
            !rxDrainEvidenceSealed(evidence) or
            evidence.read_scratch_addr != @intFromPtr(&scratch.read) or
            evidence.permit_addr != @intFromPtr(&scratch.borrow_use_permit) or
            evidence.seed_addr != @intFromPtr(&scratch.would_block_seed) or
            evidence.read_attempt_generation != consumed_attempt_generation or
            evidence.receipt_addr != seed_authority.receipt_addr or
            evidence.borrow_addr != seed_authority.borrow_addr or
            evidence.permit_addr != seed_authority.permit_addr or
            evidence.seed_addr != seed_authority.seed_addr or
            !std.mem.eql(
                u8,
                &evidence.seed_authority_continuity_digest,
                &seed_authority.continuity_digest,
            ) or
            evidence.read_attempt_generation !=
                seed_authority.attempt_generation)
            return false;
        evidence.consumed_seed_authority_digest = seed_authority.digest;
        evidence.lifecycle = .armed;
        evidence.digest = drainEvidenceDigest(evidence);
        return true;
    }

    fn consumeRxDrainEvidence(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        settlement: client_external_rx_read.StoppedDisposition,
    ) bool {
        const evidence = &scratch.drain_evidence;
        const client = if (self.owned_client) |*owned| owned else return false;
        const state = switch (client.io_mode) {
            .external => |*external| external,
            .blocking => return false,
        };
        const readiness = client_external_mode.parserReadiness(
            state,
            &client.parser,
        ) catch return false;
        const expected_staged: @TypeOf(settlement.staged) =
            if (scratch.collect_receipt.accepted_bytes == 0)
                .discarded
            else
                .consumed;
        if (evidence.lifecycle != .armed or
            active_callback_region_addr != 0 or
            active_callback_release_addr != 0 or
            !ownerIncarnationValid(self) or
            !self.validateWholeTurnLease(lease) or
            !rxDrainEvidenceSealed(evidence) or
            evidence.storage_addr != @intFromPtr(self) or
            evidence.owner_incarnation != self.owner_incarnation or
            !std.mem.eql(
                u8,
                &evidence.owner_incarnation_digest,
                &self.owner_incarnation_seal.digest,
            ) or
            evidence.lease_addr != @intFromPtr(lease) or
            evidence.lease_generation != lease.operation_generation or
            evidence.operation_generation != self.operation_generation or
            evidence.read_scratch_addr != @intFromPtr(&scratch.read) or
            evidence.receipt_addr != @intFromPtr(&scratch.collect_receipt) or
            evidence.borrow_addr != @intFromPtr(&scratch.stopped_borrow) or
            evidence.permit_addr != @intFromPtr(&scratch.borrow_use_permit) or
            evidence.seed_addr != @intFromPtr(&scratch.would_block_seed) or
            scratch.read.generation !=
                evidence.expected_post_settle_generation or
            settlement.staged != expected_staged or
            settlement.would_block != .consumed or
            evidence.parser_addr != @intFromPtr(&client.parser) or
            !std.meta.eql(evidence.parser_seal, state.rx_provenance.parser_seal) or
            readiness != evidence.final_readiness or readiness != .empty or
            evidence.rx_frame_budget_exhausted or
            evidence.rx_read_budget_exhausted or
            evidence.work_budget_exhausted)
            return false;
        const snapshot = buildRxOwnerAuthoritySnapshot(
            self,
            lease,
            scratch,
        ) orelse return false;
        const blocker = self.currentDrainBlockerProjectionForMode(evidence.mode) orelse return false;
        if (snapshot.inventory_generation !=
            evidence.owner_inventory_generation or
            !std.mem.eql(
                u8,
                &snapshot.digest,
                &evidence.owner_snapshot_digest,
            ) or !blocker.all_clear or !evidence.final_owner_blockers_clear or
            blocker.mode != evidence.mode or
            !std.mem.eql(
                u8,
                &blocker.completed_exception_digest,
                &evidence.completed_exception_digest,
            ) or
            !std.mem.eql(
                u8,
                &blocker.digest,
                &evidence.inherited_blocker_snapshot_digest,
            ))
            return false;
        evidence.lifecycle = .consumed;
        evidence.digest = drainEvidenceDigest(evidence);
        recordRxDrainTestEvent(.consumed);
        return true;
    }

    fn consumedRxDrainEvidenceCurrent(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
    ) bool {
        const evidence = &scratch.drain_evidence;
        const client = if (self.owned_client) |*owned| owned else return false;
        const state = switch (client.io_mode) {
            .external => |*external| external,
            .blocking => return false,
        };
        const readiness = client_external_mode.parserReadiness(
            state,
            &client.parser,
        ) catch return false;
        if (evidence.lifecycle != .consumed or
            !self.rxDrainEvidenceCurrentForCleanup(
                lease,
                scratch,
                evidence,
            ) or
            evidence.parser_addr != @intFromPtr(&client.parser) or
            !std.meta.eql(evidence.parser_seal, state.rx_provenance.parser_seal) or
            readiness != evidence.final_readiness or readiness != .empty or
            evidence.rx_frame_budget_exhausted or
            evidence.rx_read_budget_exhausted or
            evidence.work_budget_exhausted or
            !evidence.final_owner_blockers_clear)
            return false;
        const snapshot = buildRxOwnerAuthoritySnapshot(
            self,
            lease,
            scratch,
        ) orelse return false;
        const blocker = self.currentDrainBlockerProjectionForMode(evidence.mode) orelse return false;
        return snapshot.inventory_generation ==
            evidence.owner_inventory_generation and
            std.mem.eql(
                u8,
                &snapshot.digest,
                &evidence.owner_snapshot_digest,
            ) and blocker.all_clear and blocker.mode == evidence.mode and
            std.mem.eql(
                u8,
                &blocker.completed_exception_digest,
                &evidence.completed_exception_digest,
            ) and
            std.mem.eql(
                u8,
                &blocker.digest,
                &evidence.inherited_blocker_snapshot_digest,
            );
    }

    fn finishedRxDrainEvidenceCurrentUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        required_mode: RxDrainEvidenceMode,
    ) bool {
        const evidence = &scratch.drain_evidence;
        const client = if (self.owned_client) |*owned| owned else return false;
        const state = switch (client.io_mode) {
            .external => |*external| external,
            .blocking => return false,
        };
        const readiness = client_external_mode.parserReadiness(
            state,
            &client.parser,
        ) catch return false;
        if (evidence.lifecycle != .finished or evidence.mode != required_mode or
            !self.rxDrainEvidenceCurrentForCleanup(lease, scratch, evidence) or
            evidence.parser_addr != @intFromPtr(&client.parser) or
            !std.meta.eql(evidence.parser_seal, state.rx_provenance.parser_seal) or
            readiness != .empty or evidence.final_readiness != .empty or
            evidence.rx_frame_budget_exhausted or
            evidence.rx_read_budget_exhausted or
            evidence.work_budget_exhausted or
            !evidence.final_owner_blockers_clear)
            return false;
        const snapshot = buildRxOwnerAuthoritySnapshot(
            self,
            lease,
            scratch,
        ) orelse return false;
        const blocker = self.currentDrainBlockerProjectionForMode(
            required_mode,
        ) orelse return false;
        return snapshot.inventory_generation == evidence.owner_inventory_generation and
            std.mem.eql(u8, &snapshot.digest, &evidence.owner_snapshot_digest) and
            blocker.all_clear and blocker.mode == required_mode and
            std.mem.eql(
                u8,
                &blocker.completed_exception_digest,
                &evidence.completed_exception_digest,
            ) and std.mem.eql(
            u8,
            &blocker.digest,
            &evidence.inherited_blocker_snapshot_digest,
        );
    }

    fn finishRxDrainEvidence(
        scratch: *ExternalRxTurnScratch,
    ) bool {
        const evidence = &scratch.drain_evidence;
        if (active_callback_region_addr != 0 or
            active_callback_release_addr != 0 or
            (evidence.lifecycle != .consumed and
                evidence.lifecycle != .aborted) or
            !rxDrainEvidenceSealed(evidence))
            return false;
        evidence.lifecycle = .finished;
        evidence.digest = drainEvidenceDigest(evidence);
        return true;
    }

    fn abortRxDrainEvidence(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
    ) bool {
        const evidence = &scratch.drain_evidence;
        if ((evidence.lifecycle != .prepared and
            evidence.lifecycle != .armed) or
            active_callback_region_addr != 0 or
            active_callback_release_addr != 0 or
            !self.rxDrainEvidenceCurrentForCleanup(
                lease,
                scratch,
                evidence,
            ))
            return false;
        evidence.lifecycle = .aborted;
        evidence.digest = drainEvidenceDigest(evidence);
        return true;
    }

    fn resetFinishedRxDrainEvidence(
        self: *ExternalPumpStorage,
        scratch: *ExternalRxTurnScratch,
    ) bool {
        if (!self.finishedRxDrainEvidenceResettable(scratch))
            return false;
        const evidence = &scratch.drain_evidence;
        evidence.* = .{};
        return true;
    }

    fn finishedRxDrainEvidenceResettable(
        self: *ExternalPumpStorage,
        scratch: *const ExternalRxTurnScratch,
    ) bool {
        const evidence = &scratch.drain_evidence;
        const snapshot = &scratch.authority_snapshot;
        const mode_current = switch (evidence.mode) {
            .general => !self.controlResponsePending() and
                std.mem.allEqual(u8, &evidence.completed_exception_digest, 0),
            .completed_control => if (self.currentCompletedExceptionDigest()) |digest|
                std.mem.eql(u8, &digest, &evidence.completed_exception_digest)
            else
                false,
        };
        return scratch.saved_self_addr == @intFromPtr(scratch) and
            scratch.lifecycle == .ready and
            active_callback_region_addr == 0 and
            active_callback_release_addr == 0 and
            evidence.lifecycle == .finished and
            mode_current and
            rxDrainEvidenceSealed(evidence) and
            evidence.storage_addr == @intFromPtr(self) and
            ownerIncarnationValid(self) and
            evidence.owner_incarnation == self.owner_incarnation and
            std.mem.eql(
                u8,
                &evidence.owner_incarnation_digest,
                &self.owner_incarnation_seal.digest,
            ) and
            evidence.operation_generation == self.operation_generation and
            evidence.read_scratch_addr == @intFromPtr(&scratch.read) and
            scratch.read.generation ==
                evidence.expected_post_settle_generation and
            snapshot.saved_self_addr == @intFromPtr(snapshot) and
            snapshot.storage_addr == @intFromPtr(self) and
            snapshot.scratch_addr == @intFromPtr(scratch) and
            snapshot.operation_generation == self.operation_generation and
            snapshot.inventory_generation ==
                evidence.owner_inventory_generation and
            std.mem.eql(
                u8,
                &snapshot.digest,
                &rxOwnerAuthoritySnapshotDigest(snapshot),
            ) and
            std.mem.eql(
                u8,
                &snapshot.digest,
                &evidence.owner_snapshot_digest,
            );
    }

    /// Retires the previous pump turn before a sibling public operation advances the operation
    /// generation. A finished drain proves the state at the end of that turn, but it is not a
    /// capability that may survive a later TX admission or even a read-only leased projection.
    /// Keeping this transition beside the evidence validator prevents each outer caller from
    /// inventing a weaker way to clear the scratch.
    pub fn settleRxTurnForSiblingOperation(
        self: *ExternalPumpStorage,
        scratch: *ExternalRxTurnScratch,
    ) bool {
        if (active_external_operation_addr != 0 or
            active_callback_region_addr != 0 or
            active_callback_release_addr != 0 or
            scratch.saved_self_addr != @intFromPtr(scratch) or
            scratch.lifecycle != .ready)
            return false;
        return switch (scratch.drain_evidence.lifecycle) {
            .empty => rxDrainEvidencePristine(&scratch.drain_evidence),
            .finished => self.resetFinishedRxDrainEvidence(scratch),
            else => false,
        };
    }

    /// Runs only the closed buffered parser and aggregate mechanics. The caller retains inherited
    /// blocker ordering, readiness policy, terminal publication, and scheduling.
    fn traverseAndCommitBufferedUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        client: *client_mod.Client,
        rx_state: *client_external_mode.State,
        live_partial_pending: bool,
        now_ns: i128,
        scratch: *ExternalRxTurnScratch,
    ) BufferedTraversalCommitResult {
        var authority = ProductIntentAuthority{
            .storage = self,
            .lease = lease,
            .scratch = scratch,
        };
        const authority_ops = authority.ops();
        var parser_progress = ProductParserProgress{
            .storage = self,
            .lease = lease,
        };
        const parser_progress_ops = parser_progress.ops();
        var payload_guard_owner = ProductPayloadAllocationGuard{
            .authority = &authority,
        };
        const payload_guard = payload_guard_owner.ops();
        const intent_result = if (scratch.traversal.intent.lifecycle == .empty)
            if (client_external_rx_turn.Scratch.prepareForIntentCreation(
                &scratch.traversal,
            ))
                self.createIntentScratch(
                    &scratch.traversal.intent,
                    client.parser.allocator,
                    authority_ops,
                )
            else
                external_rx_intent.CreateResult.authority_drift
        else switch (external_rx_intent.resetForNextTurn(
            &scratch.traversal.intent,
            authority_ops,
        )) {
            .ready => if (client_external_rx_turn.Scratch.resetForNextTurn(
                &scratch.traversal,
            ))
                external_rx_intent.CreateResult.allocated
            else
                external_rx_intent.CreateResult.authority_drift,
            .invalid_state => external_rx_intent.CreateResult.authority_drift,
        };
        if (intent_result != .allocated) {
            return .{ .terminal = .{
                .reason = if (intent_result == .out_of_memory)
                    .resource_exhausted
                else
                    .invariant_failure,
                .rx_bytes = 0,
                .rx_frames = 0,
            } };
        }

        const partial = if (live_partial_pending)
            self.validatedPartialContinuation() orelse {
                _ = external_rx_intent.abortAll(&scratch.traversal.intent);
                return .{ .terminal = .{
                    .reason = .invariant_failure,
                    .rx_bytes = 0,
                    .rx_frames = 0,
                } };
            }
        else
            null;
        const traversal = client_external_rx_turn.traverseBuffered(.{
            .state = rx_state,
            .parser = &client.parser,
            .scratch = &scratch.traversal,
            .authority = authority_ops,
            .payload_guard = &payload_guard,
            .target_stream_id = self.evidence_snapshot.stream_id,
            .partial = partial,
            .parser_progress = parser_progress_ops,
        });
        const summary = switch (traversal) {
            .terminal => |failure| {
                if (failure.reason == .allocation_quarantined)
                    latchCrossOwnerQuarantine();
                return .{ .terminal = .{
                    .reason = switch (failure.reason) {
                        .protocol_error => .protocol_error,
                        .resource_exhausted => .resource_exhausted,
                        .invariant_failure, .allocation_quarantined => .invariant_failure,
                    },
                    .rx_bytes = failure.rx_bytes,
                    .rx_frames = failure.rx_frames,
                } };
            },
            .no_intents => |empty| return .{ .completed = .{
                .rx_bytes = empty.rx_bytes,
                .rx_frames = empty.rx_frames,
                .final_readiness = empty.final_readiness,
                .budget_exhausted = empty.budget_exhausted,
            } },
            .staged => |staged| staged,
        };
        const rx_bytes = summary.rx_bytes;
        const rx_frames = summary.rx_frames;

        switch (self.createRxAggregateWithAuthority(
            lease,
            &scratch.traversal.intent,
            client.parser.allocator,
            authority_ops,
            now_ns,
            &scratch.aggregate_ranges,
        )) {
            .allocated => {},
            .out_of_memory => {
                const reason: client_pump.TerminalReason =
                    if (external_rx_intent.abortAll(
                        &scratch.traversal.intent,
                    ) == .cleaned)
                        .resource_exhausted
                    else
                        .invariant_failure;
                return .{ .terminal = .{
                    .reason = reason,
                    .rx_bytes = rx_bytes,
                    .rx_frames = rx_frames,
                } };
            },
            .invalid_state, .authority_drift, .quarantined => {
                _ = external_rx_intent.abortAll(&scratch.traversal.intent);
                return .{ .terminal = .{
                    .reason = .invariant_failure,
                    .rx_bytes = rx_bytes,
                    .rx_frames = rx_frames,
                } };
            },
        }
        for (0..summary.classified_count) |intent_index| {
            const move_result = self.moveScreenIntoRxAggregate(
                lease,
                &scratch.traversal.intent,
                @intCast(intent_index),
                authority_ops,
            );
            switch (move_result) {
                .wrong_intent => continue,
                .staged => {},
                else => {
                    _ = self.abortRxAggregate(lease, &scratch.traversal.intent);
                    return .{ .terminal = .{
                        .reason = .invariant_failure,
                        .rx_bytes = rx_bytes,
                        .rx_frames = rx_frames,
                    } };
                },
            }
            const transfer_result = self.transferScreenToLedger(
                lease,
                &scratch.traversal.intent,
                @intCast(intent_index),
            );
            const admit_result = if (transfer_result == .staged)
                self.admitScreenToLiveBatch(
                    lease,
                    @intCast(intent_index),
                )
            else
                RxAggregateTransferResult.invalid_state;
            if (transfer_result != .staged or admit_result != .staged) {
                _ = self.abortRxAggregate(lease, &scratch.traversal.intent);
                return .{ .terminal = .{
                    .reason = .resource_exhausted,
                    .rx_bytes = rx_bytes,
                    .rx_frames = rx_frames,
                } };
            }
        }
        const finalize_result = self.finalizeRxAggregate(
            lease,
            &scratch.traversal.intent,
        );
        switch (finalize_result) {
            .finalized => {},
            .terminal_deadline => {
                const abort_result =
                    self.abortRxAggregate(lease, &scratch.traversal.intent);
                return .{ .terminal = .{
                    .reason = if (abort_result == .cleaned)
                        .deadline_exceeded
                    else
                        .invariant_failure,
                    .rx_bytes = rx_bytes,
                    .rx_frames = rx_frames,
                } };
            },
            .terminal_runtime_ended => {
                const actual_abort_result =
                    self.abortRxAggregate(lease, &scratch.traversal.intent);
                const abort_result = if (hitInjectedRxFailpoint(
                    scratch,
                    .after_terminal_abort_result_failure,
                ))
                    RxAggregateAbortResult.invalid_state
                else
                    actual_abort_result;
                return .{ .terminal = .{
                    .reason = if (abort_result == .cleaned)
                        .runtime_ended
                    else
                        .invariant_failure,
                    .rx_bytes = rx_bytes,
                    .rx_frames = rx_frames,
                } };
            },
            .invalid_state, .rejected => {
                _ = self.abortRxAggregate(lease, &scratch.traversal.intent);
                return .{ .terminal = .{
                    .reason = .protocol_error,
                    .rx_bytes = rx_bytes,
                    .rx_frames = rx_frames,
                } };
            },
        }
        const aggregate = self.validateReadyRxAggregate(lease) orelse {
            _ = self.abortRxAggregate(lease, &scratch.traversal.intent);
            return .{ .terminal = .{
                .reason = .invariant_failure,
                .rx_bytes = rx_bytes,
                .rx_frames = rx_frames,
            } };
        };
        if (aggregate.event_reduction.outcome == .revoked) {
            const revoke_result = self.commitRevokedRxAggregateWithTx(
                lease,
                scratch,
                &scratch.traversal.intent,
                now_ns,
            );
            const reason: client_pump.TerminalReason = switch (revoke_result) {
                .committed => .revoked,
                .protocol_terminal => blk: {
                    const aborted = self.abortRxAggregate(
                        lease,
                        &scratch.traversal.intent,
                    );
                    break :blk if (aborted == .cleaned)
                        .protocol_error
                    else
                        .invariant_failure;
                },
                .invariant_terminal => blk: {
                    const aborted = self.abortRxAggregate(
                        lease,
                        &scratch.traversal.intent,
                    );
                    if (aborted != .cleaned) break :blk .invariant_failure;
                    break :blk .invariant_failure;
                },
                .protocol_terminal_cleaned => .protocol_error,
                .invariant_terminal_cleaned => .invariant_failure,
                .quarantined => .invariant_failure,
            };
            return .{ .terminal = .{
                .reason = reason,
                .rx_bytes = rx_bytes,
                .rx_frames = rx_frames,
            } };
        }
        const commit_result = self.commitRxAggregate(
            lease,
            &scratch.traversal.intent,
        );
        if (commit_result != .committed) {
            if (commit_result == .invalid_state)
                _ = self.abortRxAggregate(lease, &scratch.traversal.intent);
            return .{ .terminal = .{
                .reason = .invariant_failure,
                .rx_bytes = rx_bytes,
                .rx_frames = rx_frames,
            } };
        }
        return .{ .completed = .{
            .rx_bytes = rx_bytes,
            .rx_frames = rx_frames,
            .final_readiness = summary.final_readiness,
            .budget_exhausted = summary.budget_exhausted,
        } };
    }

    fn prepareRxTurn(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        turn: client_pump.TurnInput,
        original_ops: *const RxTurnOps,
        scratch: *ExternalRxTurnScratch,
    ) RxPreparation {
        if (active_callback_region_addr != 0) {
            return .{ .without_drain = .{
                .policy = .{
                    .turn = turn,
                    .inherited_blocker = true,
                },
            } };
        }
        var frozen_ops: FrozenRxTurnOps = .{};
        if (!freezeRxTurnOps(
            self,
            lease,
            scratch,
            original_ops,
            &frozen_ops,
        ))
            return self.terminalRxPreparation(
                turn,
                .invariant_failure,
                0,
                0,
                0,
            );
        const ops = &frozen_ops.ops;
        self.snapshotInheritedRxBlockersUnderHeldLease(
            lease,
            &scratch.snapshot,
        ) catch return self.terminalRxPreparation(
            turn,
            .invariant_failure,
            0,
            0,
            0,
        );
        const snapshot = scratch.snapshot;
        _ = self.validateAndConsumeInheritedSnapshot(
            lease,
            &scratch.snapshot,
        ) catch return self.terminalRxPreparation(
            turn,
            .invariant_failure,
            0,
            0,
            0,
        );
        const completed_terminal_probe = snapshot.response_correlation_pending and
            self.completed_control == .completed and
            self.control_correlation.state == .completed and
            self.completedControlValid();
        const existing_consumer_blocker =
            snapshot.committed_screen_pending or
            snapshot.metadata_projection_pending or
            snapshot.resize_projection_pending or
            (snapshot.response_correlation_pending and
                !completed_terminal_probe);
        if (existing_consumer_blocker) {
            return .{ .without_drain = .{
                .policy = .{
                    .turn = turn,
                    .inherited_blocker = true,
                },
            } };
        }
        if (snapshot.live_screen_pending) {
            var callback_release: CallbackReleaseAuthority = .{};
            if (!beginPumpCallbackRegion(
                self,
                lease,
                scratch,
                &callback_release,
            ))
                return self.terminalRxPreparation(
                    turn,
                    .invariant_failure,
                    0,
                    0,
                    0,
                );
            const consume = self.consumeLiveScreenHeadUnderHeldLease(
                lease,
                &ops.buffered,
                &scratch.live_consume,
            );
            if (!finishAndValidateRxTurnCallback(
                self,
                lease,
                scratch,
                original_ops,
                &frozen_ops,
                &callback_release,
            ))
                return self.terminalRxPreparation(
                    turn,
                    .invariant_failure,
                    0,
                    0,
                    0,
                );
            return switch (consume) {
                .consumed, .retry => .{ .without_drain = .{
                    .policy = .{
                        .turn = turn,
                        .inherited_blocker = true,
                    },
                } },
                .no_work, .invalid_state => self.terminalRxPreparation(
                    turn,
                    .invariant_failure,
                    0,
                    0,
                    0,
                ),
            };
        }

        const client = if (self.owned_client) |*owned|
            owned
        else
            return self.terminalRxPreparation(
                turn,
                .invariant_failure,
                0,
                0,
                0,
            );
        const rx_state = switch (client.io_mode) {
            .external => |*state| state,
            .blocking => return self.terminalRxPreparation(
                turn,
                .invariant_failure,
                0,
                0,
                0,
            ),
        };
        const initial_readiness = client_external_mode.parserReadiness(
            rx_state,
            &client.parser,
        ) catch return self.terminalRxPreparation(
            turn,
            .invariant_failure,
            0,
            0,
            0,
        );
        if (initial_readiness == .complete_or_error) {
            var callback_release: CallbackReleaseAuthority = .{};
            if (!beginPumpCallbackRegion(
                self,
                lease,
                scratch,
                &callback_release,
            ))
                return self.terminalRxPreparation(
                    turn,
                    .invariant_failure,
                    0,
                    0,
                    0,
                );
            const mechanics = self.traverseAndCommitBufferedUnderHeldLease(
                lease,
                client,
                rx_state,
                snapshot.live_partial_pending,
                turn.now_ns,
                scratch,
            );
            if (!finishAndValidateRxTurnCallback(
                self,
                lease,
                scratch,
                original_ops,
                &frozen_ops,
                &callback_release,
            ))
                return self.terminalRxPreparation(
                    turn,
                    .invariant_failure,
                    0,
                    0,
                    0,
                );
            return switch (mechanics) {
                .terminal => |terminal| self.terminalRxPreparation(
                    turn,
                    terminal.reason,
                    0,
                    terminal.rx_bytes,
                    terminal.rx_frames,
                ),
                .completed => |completed| .{ .without_drain = .{
                    .policy = .{
                        .turn = turn,
                        .parser = switch (completed.final_readiness) {
                            .empty => .empty,
                            .incomplete => .incomplete,
                            .complete_or_error => .complete_or_error,
                        },
                        .rx_frame_budget_exhausted = completed.budget_exhausted,
                        .work_budget_exhausted = completed.rx_frames >= external_rx_intent.max_intents,
                    },
                    .rx_bytes = completed.rx_bytes,
                    .rx_frames = completed.rx_frames,
                } },
            };
        }
        if (!turn.readable) {
            return .{ .without_drain = .{
                .policy = .{
                    .turn = turn,
                    .parser = switch (initial_readiness) {
                        .empty => .empty,
                        .incomplete => .incomplete,
                        .complete_or_error => unreachable,
                    },
                },
            } };
        }

        const allowance = switch (client_external_mode.maxReadable(
            rx_state,
            &client.parser,
            self.rx_resident_cap,
            client_external_rx_read.max_rx_read_bytes_per_turn,
        )) {
            .invalid, .counter_exhausted => return self.terminalRxPreparation(
                turn,
                .invariant_failure,
                0,
                0,
                0,
            ),
            .resident_exhausted => {
                if (initial_readiness == .incomplete)
                    return self.terminalRxPreparation(
                        turn,
                        .resource_exhausted,
                        0,
                        0,
                        0,
                    );
                return .{ .without_drain = .{
                    .policy = .{
                        .turn = turn,
                        .rx_read_budget_exhausted = true,
                    },
                } };
            },
            .turn_exhausted => return .{ .without_drain = .{
                .policy = .{
                    .turn = turn,
                    .parser = switch (initial_readiness) {
                        .empty => .empty,
                        .incomplete => .incomplete,
                        .complete_or_error => unreachable,
                    },
                    .rx_read_budget_exhausted = true,
                },
            } },
            .bytes => |positive| positive,
        };
        var read_authority = ProductRxReadAuthority{
            .storage = self,
            .lease = lease,
            .scratch = scratch,
            .read_ops = &ops.transport,
            .original_ops = original_ops,
            .frozen_ops = &frozen_ops,
        };
        const authority_ops = read_authority.ops();
        var read_callback_release: CallbackReleaseAuthority = .{};
        if (!beginPumpCallbackRegion(
            self,
            lease,
            scratch,
            &read_callback_release,
        ))
            return self.terminalRxPreparation(
                turn,
                .invariant_failure,
                0,
                0,
                0,
            );
        const collected = client_external_rx_read.collectInjected(
            &scratch.read,
            .{
                .allowance = allowance,
                .read_ops = &ops.transport,
                .authority_ops = &authority_ops,
            },
        );
        if (!finishAndValidateRxTurnCallback(
            self,
            lease,
            scratch,
            original_ops,
            &frozen_ops,
            &read_callback_release,
        ))
            return self.terminalRxPreparation(
                turn,
                .invariant_failure,
                0,
                0,
                0,
            );
        const receipt = switch (collected) {
            .rejected => return self.terminalRxPreparation(
                turn,
                .invariant_failure,
                0,
                0,
                0,
            ),
            .terminal => |terminal| return self.terminalRxPreparation(
                turn,
                switch (terminal.reason) {
                    .eof => .eof,
                    .socket_error => .socket_error,
                    else => .invariant_failure,
                },
                0,
                0,
                0,
            ),
            .stopped => |stopped| stopped,
        };
        scratch.collect_receipt = receipt;
        if (!client_external_rx_read.borrowStopped(
            &scratch.read,
            &scratch.collect_receipt,
            &scratch.stopped_borrow,
        ))
            return self.terminalRxPreparation(
                turn,
                .invariant_failure,
                0,
                0,
                0,
            );
        const guard_ops = client_external_rx_read.BorrowUseGuardOps{
            .context = &scratch.callback_region,
            .context_len = @sizeOf(CallbackRegionToken),
            .current = callbackRegionCurrent,
        };
        if (!client_external_rx_read.beginStoppedUse(
            &scratch.read,
            &scratch.collect_receipt,
            &scratch.stopped_borrow,
            &guard_ops,
            &scratch.would_block_seed,
            &scratch.borrow_use_permit,
        ))
            return self.terminalRxPreparation(
                turn,
                .invariant_failure,
                0,
                0,
                0,
            );
        if (hitInjectedRxFailpoint(scratch, .after_stopped_begin))
            return self.terminalRxPreparation(
                turn,
                .invariant_failure,
                0,
                0,
                0,
            );
        const stopped_bytes = client_external_rx_read.stoppedBytes(
            &scratch.read,
            &scratch.collect_receipt,
            &scratch.stopped_borrow,
        ) orelse return self.terminalRxPreparation(
            turn,
            .invariant_failure,
            0,
            0,
            0,
        );
        var admitted = false;
        var mechanics: ?BufferedTraversalCommitResult = null;
        var terminal_reason: ?client_pump.TerminalReason = null;

        if (stopped_bytes.len != 0) {
            const prepared_use_started =
                client_external_rx_read.beginPreparedAdmitUse(
                    &scratch.read,
                    &scratch.collect_receipt,
                    &scratch.stopped_borrow,
                    &scratch.borrow_use_permit,
                    &scratch.would_block_seed,
                    &scratch.prepared_admit_use_permit,
                );
            if (!prepared_use_started) {
                terminal_reason = .invariant_failure;
            } else if (hitInjectedRxFailpoint(
                scratch,
                .after_prepared_begin,
            )) {
                return self.terminalRxPreparation(
                    turn,
                    .invariant_failure,
                    0,
                    0,
                    0,
                );
            } else {
                var replacement_guard_owner = ProductReplacementAllocationGuard{
                    .storage = self,
                    .lease = lease,
                    .scratch = scratch,
                    .admitted_len = stopped_bytes.len,
                };
                const replacement_guard = replacement_guard_owner.ops();
                var admit_callback_release: CallbackReleaseAuthority = .{};
                if (!beginPumpCallbackRegion(
                    self,
                    lease,
                    scratch,
                    &admit_callback_release,
                ))
                    terminal_reason = .invariant_failure
                else {
                    const prepare = client_external_mode.prepareAdmitGuarded(
                        rx_state,
                        &client.parser,
                        stopped_bytes,
                        rx_state.rx_provenance.rx_absolute_next,
                        self.rx_resident_cap,
                        &replacement_guard,
                        &scratch.read.prepared_admit,
                    );
                    if (hitInjectedRxFailpoint(scratch, .after_prepare)) {
                        _ = finishAndValidateRxTurnCallback(
                            self,
                            lease,
                            scratch,
                            original_ops,
                            &frozen_ops,
                            &admit_callback_release,
                        );
                        return self.terminalRxPreparation(
                            turn,
                            .invariant_failure,
                            0,
                            0,
                            0,
                        );
                    }
                    switch (prepare) {
                        .ordinary_failure => {
                            if (!finishAndValidateRxTurnCallback(
                                self,
                                lease,
                                scratch,
                                original_ops,
                                &frozen_ops,
                                &admit_callback_release,
                            ))
                                terminal_reason = .invariant_failure
                            else
                                terminal_reason = .resource_exhausted;
                        },
                        .allocation_quarantined => |quarantine| {
                            if (!finishAndValidateRxTurnCallback(
                                self,
                                lease,
                                scratch,
                                original_ops,
                                &frozen_ops,
                                &admit_callback_release,
                            ) or
                                !completeGuardedAdmitQuarantine(
                                    &scratch.read.prepared_admit,
                                    .allocation_quarantined,
                                    quarantine,
                                    &scratch.quarantine_receipt,
                                ))
                                terminal_reason = .invariant_failure
                            else
                                terminal_reason = .invariant_failure;
                        },
                        .prepared => {
                            const commit =
                                client_external_mode.commitPreparedAdmitGuarded(
                                    rx_state,
                                    &client.parser,
                                    stopped_bytes,
                                    &scratch.read.prepared_admit,
                                );
                            if (hitInjectedRxFailpoint(
                                scratch,
                                .after_commit,
                            )) {
                                _ = finishPumpCallbackRegion(
                                    scratch,
                                    &admit_callback_release,
                                );
                                return self.terminalRxPreparation(
                                    turn,
                                    .invariant_failure,
                                    0,
                                    0,
                                    0,
                                );
                            }
                            if (!finishPumpCallbackRegion(
                                scratch,
                                &admit_callback_release,
                            )) {
                                terminal_reason = .invariant_failure;
                            } else switch (commit) {
                                .committed => {
                                    const reset = resetCompletedPreparedAdmit(
                                        &scratch.read.prepared_admit,
                                    );
                                    const refreshed = reset and self
                                        .refreshWholeTurnRxAuthorityAfterAdmit(
                                        lease,
                                        stopped_bytes.len,
                                    );
                                    admitted = reset and refreshed and
                                        validateFrozenRxTurnOps(
                                            self,
                                            lease,
                                            scratch,
                                            original_ops,
                                            &frozen_ops,
                                        );
                                    if (!admitted)
                                        terminal_reason = .invariant_failure;
                                },
                                .ordinary_failure => {
                                    if (!validateFrozenRxTurnOps(
                                        self,
                                        lease,
                                        scratch,
                                        original_ops,
                                        &frozen_ops,
                                    )) {
                                        terminal_reason = .invariant_failure;
                                    } else {
                                        var abort_callback_release: CallbackReleaseAuthority = .{};
                                        if (!beginPumpCallbackRegion(
                                            self,
                                            lease,
                                            scratch,
                                            &abort_callback_release,
                                        )) {
                                            terminal_reason = .invariant_failure;
                                        } else {
                                            const aborted = client_external_mode
                                                .abortPreparedAdmitGuarded(
                                                rx_state,
                                                &client.parser,
                                                &scratch.read.prepared_admit,
                                            );
                                            if (!finishAndValidateRxTurnCallback(
                                                self,
                                                lease,
                                                scratch,
                                                original_ops,
                                                &frozen_ops,
                                                &abort_callback_release,
                                            )) {
                                                terminal_reason = .invariant_failure;
                                            } else switch (aborted) {
                                                .aborted => {
                                                    if (!resetCompletedPreparedAdmit(
                                                        &scratch.read.prepared_admit,
                                                    ))
                                                        terminal_reason =
                                                            .invariant_failure
                                                    else
                                                        terminal_reason =
                                                            .invariant_failure;
                                                },
                                                .ordinary_failure => terminal_reason = .invariant_failure,
                                                .allocation_quarantined => |quarantine| {
                                                    if (!completeGuardedAdmitQuarantine(
                                                        &scratch.read.prepared_admit,
                                                        .allocation_quarantined,
                                                        quarantine,
                                                        &scratch.quarantine_receipt,
                                                    ))
                                                        terminal_reason =
                                                            .invariant_failure
                                                    else
                                                        terminal_reason =
                                                            .invariant_failure;
                                                },
                                            }
                                        }
                                    }
                                },
                                .allocation_quarantined => |quarantine| {
                                    if (!completeGuardedAdmitQuarantine(
                                        &scratch.read.prepared_admit,
                                        .allocation_quarantined,
                                        quarantine,
                                        &scratch.quarantine_receipt,
                                    ))
                                        terminal_reason = .invariant_failure
                                    else
                                        terminal_reason = .invariant_failure;
                                },
                                .post_commit_quarantined => |quarantine| {
                                    if (!completeGuardedAdmitQuarantine(
                                        &scratch.read.prepared_admit,
                                        .post_commit_quarantined,
                                        quarantine,
                                        &scratch.quarantine_receipt,
                                    ))
                                        terminal_reason = .invariant_failure
                                    else
                                        terminal_reason = .invariant_failure;
                                },
                            }
                        },
                    }
                }
                if (!client_external_rx_read.finishPreparedAdmitUse(
                    &scratch.read,
                    &scratch.collect_receipt,
                    &scratch.stopped_borrow,
                    &scratch.borrow_use_permit,
                    &scratch.would_block_seed,
                    &scratch.prepared_admit_use_permit,
                ) or !client_external_rx_read.resetFinishedPreparedAdmitUse(
                    &scratch.read,
                    &scratch.prepared_admit_use_permit,
                ))
                    terminal_reason = .invariant_failure;
            }
            if (admitted and terminal_reason == null) {
                var traversal_callback_release: CallbackReleaseAuthority = .{};
                if (!beginPumpCallbackRegion(
                    self,
                    lease,
                    scratch,
                    &traversal_callback_release,
                )) {
                    terminal_reason = .invariant_failure;
                } else {
                    mechanics = self.traverseAndCommitBufferedUnderHeldLease(
                        lease,
                        client,
                        rx_state,
                        snapshot.live_partial_pending,
                        turn.now_ns,
                        scratch,
                    );
                    if (!finishAndValidateRxTurnCallback(
                        self,
                        lease,
                        scratch,
                        original_ops,
                        &frozen_ops,
                        &traversal_callback_release,
                    ))
                        terminal_reason = .invariant_failure;
                    if (hitInjectedRxFailpoint(
                        scratch,
                        .after_traversal,
                    ))
                        return self.terminalRxPreparation(
                            turn,
                            .invariant_failure,
                            stopped_bytes.len,
                            0,
                            0,
                        );
                }
            }
        }

        const read_bytes = if (admitted) stopped_bytes.len else 0;
        var mechanics_terminal: ?BufferedTraversalCommitTerminal = null;
        const completed = if (mechanics) |value| switch (value) {
            .terminal => |terminal| blk: {
                mechanics_terminal = terminal;
                break :blk BufferedTraversalCommitSummary{
                    .rx_bytes = terminal.rx_bytes,
                    .rx_frames = terminal.rx_frames,
                    .final_readiness = .complete_or_error,
                    .budget_exhausted = false,
                };
            },
            .completed => |summary| summary,
        } else BufferedTraversalCommitSummary{
            .rx_bytes = 0,
            .rx_frames = 0,
            .final_readiness = initial_readiness,
            .budget_exhausted = false,
        };
        const final_parser: client_pump.ParserReadiness =
            switch (completed.final_readiness) {
                .empty => .empty,
                .incomplete => .incomplete,
                .complete_or_error => .complete_or_error,
            };
        const trailing_transport_reason: ?client_pump.TerminalReason =
            switch (scratch.collect_receipt.stop) {
                .eof_after_prefix => .eof,
                .socket_error_after_prefix => .socket_error,
                .would_block, .allowance_reached, .attempt_budget_exhausted => null,
            };
        if (trailing_transport_reason != null) {
            // A positive prefix is parser-owned before the trailing transport
            // observation is interpreted. An incomplete frame is a protocol
            // violation, and an already reduced revoke/other terminal remains
            // stronger than EOF/socket error. Only a clean parsed prefix may
            // inherit the trailing transport reason.
            if (final_parser == .incomplete) {
                terminal_reason = .protocol_error;
            } else if (mechanics_terminal == null and terminal_reason == null) {
                terminal_reason = trailing_transport_reason;
            }
        }
        const allowance_stop =
            client_external_rx_read.classifyAcceptedAllowanceStop(
                scratch.collect_receipt.allowance,
                scratch.collect_receipt.accepted_bytes,
                if (final_parser == .empty) .empty else .incomplete,
            );
        const drain_mode: RxDrainEvidenceMode = if (self.controlResponsePending() and
            self.completedControlValid())
            .completed_control
        else
            .general;
        const final_blockers = self.currentDrainBlockerProjectionForMode(drain_mode) orelse
            return self.terminalRxPreparation(
                turn,
                .invariant_failure,
                read_bytes,
                completed.rx_bytes,
                completed.rx_frames,
            );
        const final_owner_snapshot = buildRxOwnerAuthoritySnapshot(
            self,
            lease,
            scratch,
        ) orelse return self.terminalRxPreparation(
            turn,
            .invariant_failure,
            read_bytes,
            completed.rx_bytes,
            completed.rx_frames,
        );
        if (!client_external_mode.parserSealValid(
            rx_state,
            &client.parser,
        ))
            return self.terminalRxPreparation(
                turn,
                .invariant_failure,
                read_bytes,
                completed.rx_bytes,
                completed.rx_frames,
            );
        const read_budget_exhausted =
            scratch.collect_receipt.stop == .attempt_budget_exhausted or
            allowance_stop == .immediate;
        const allowance_terminal =
            allowance_stop == .counter_terminal or
            allowance_stop == .resident_incomplete_terminal or
            allowance_stop == .invalid;
        const drain_final = RxDrainFinalState{
            .parser_readiness = completed.final_readiness,
            .policy_parser = final_parser,
            .parser_seal = rx_state.rx_provenance.parser_seal,
            .allowance_stop = allowance_stop,
            .frame_budget_exhausted = completed.budget_exhausted,
            .read_budget_exhausted = read_budget_exhausted,
            .work_budget_exhausted = completed.rx_frames >= external_rx_intent.max_intents,
            .terminal = terminal_reason != null or
                mechanics_terminal != null or allowance_terminal,
            .blockers = final_blockers,
            .owner_inventory_generation = final_owner_snapshot.inventory_generation,
            .owner_snapshot_digest = final_owner_snapshot.digest,
        };
        var socket_rx_drained = false;
        var drain_prepared = false;
        var would_block_disposition: client_external_rx_read.StoppedDisposition =
            .{
                .staged = if (admitted) .consumed else .discarded,
                .would_block = .not_present,
            };
        if (scratch.collect_receipt.stop == .would_block) {
            if (!client_external_rx_read.mintBorrowedWouldBlockSeed(
                &scratch.read,
                &scratch.collect_receipt,
                &scratch.stopped_borrow,
                &scratch.borrow_use_permit,
                &scratch.would_block_seed,
            )) {
                terminal_reason = .invariant_failure;
            } else {
                if (hitInjectedRxFailpoint(scratch, .after_seed_mint))
                    return self.terminalRxPreparation(
                        turn,
                        .invariant_failure,
                        if (admitted) stopped_bytes.len else 0,
                        0,
                        0,
                    );
                if (drain_final.eligible()) {
                    drain_prepared = self.prepareRxDrainEvidence(
                        lease,
                        scratch,
                        drain_final,
                        snapshot.digest,
                    );
                    if (!drain_prepared) {
                        terminal_reason = .invariant_failure;
                    }
                }
                if (drain_prepared) {
                    const generation =
                        client_external_rx_read.consumeWouldBlockSeed(
                            &scratch.read,
                            &scratch.borrow_use_permit,
                            &scratch.would_block_seed,
                        );
                    if (hitInjectedRxFailpoint(
                        scratch,
                        .after_seed_consume,
                    ))
                        return self.terminalRxPreparation(
                            turn,
                            .invariant_failure,
                            if (admitted) stopped_bytes.len else 0,
                            0,
                            0,
                        );
                    if (generation) |attempt_generation| {
                        if (drain_prepared and !armRxDrainEvidence(
                            scratch,
                            attempt_generation,
                        )) terminal_reason = .invariant_failure;
                    }
                    if (generation == null)
                        terminal_reason = .invariant_failure;
                    would_block_disposition.would_block = .consumed;
                } else {
                    if (!client_external_rx_read.abortWouldBlockSeed(
                        &scratch.read,
                        &scratch.borrow_use_permit,
                        &scratch.would_block_seed,
                    ))
                        terminal_reason = .invariant_failure;
                    would_block_disposition.would_block = .aborted;
                }
            }
        }
        if (hitInjectedRxFailpoint(scratch, .before_end))
            return self.terminalRxPreparation(
                turn,
                .invariant_failure,
                if (admitted) stopped_bytes.len else 0,
                0,
                0,
            );
        if (!client_external_rx_read.endStoppedUse(
            &scratch.read,
            &scratch.collect_receipt,
            &scratch.stopped_borrow,
            &scratch.borrow_use_permit,
        ))
            terminal_reason = .invariant_failure;
        if (hitInjectedRxFailpoint(scratch, .before_settle))
            return self.terminalRxPreparation(
                turn,
                .invariant_failure,
                if (admitted) stopped_bytes.len else 0,
                0,
                0,
            );
        if (!client_external_rx_read.settleStopped(
            &scratch.read,
            &scratch.collect_receipt,
            &scratch.stopped_borrow,
            would_block_disposition,
        ))
            terminal_reason = .invariant_failure;

        if (terminal_reason) |reason| {
            if (drain_prepared and
                self.abortRxDrainEvidence(lease, scratch))
                _ = finishRxDrainEvidence(scratch);
            return self.terminalRxPreparation(
                turn,
                reason,
                read_bytes,
                completed.rx_bytes,
                completed.rx_frames,
            );
        }
        if (mechanics_terminal) |terminal|
            return self.terminalRxPreparation(
                turn,
                terminal.reason,
                read_bytes,
                terminal.rx_bytes,
                terminal.rx_frames,
            );
        if (allowance_stop == .counter_terminal or allowance_stop == .invalid)
            return self.terminalRxPreparation(
                turn,
                .invariant_failure,
                read_bytes,
                completed.rx_bytes,
                completed.rx_frames,
            );
        if (allowance_stop == .resident_incomplete_terminal)
            return self.terminalRxPreparation(
                turn,
                .resource_exhausted,
                read_bytes,
                completed.rx_bytes,
                completed.rx_frames,
            );

        if (drain_prepared) {
            socket_rx_drained = self.consumeRxDrainEvidence(
                lease,
                scratch,
                would_block_disposition,
            );
        }
        if (drain_prepared and !socket_rx_drained)
            return self.terminalRxPreparation(
                turn,
                .invariant_failure,
                read_bytes,
                completed.rx_bytes,
                completed.rx_frames,
            );
        const summary = RxPreparedSummary{
            .policy = .{
                .turn = turn,
                .parser = final_parser,
                .inherited_blocker = !drain_final.blockers.all_clear,
                .rx_frame_budget_exhausted = completed.budget_exhausted,
                .rx_read_budget_exhausted = read_budget_exhausted,
                .work_budget_exhausted = completed.rx_frames >= external_rx_intent.max_intents,
            },
            .rx_read_bytes = read_bytes,
            .rx_bytes = completed.rx_bytes,
            .rx_frames = completed.rx_frames,
        };
        return if (socket_rx_drained)
            .{ .drained = summary }
        else
            .{ .without_drain = summary };
    }

    fn publishRxPreparationUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        preparation: RxPreparation,
    ) client_pump.TurnResult {
        if (!rxPreparationCoherent(preparation)) {
            const summary = switch (preparation) {
                inline else => |value| value,
            };
            return self.invalidRxPreparationResult(summary);
        }
        return switch (preparation) {
            .terminal => |summary| self.policyResultFromRxSummary(summary, false),
            .without_drain => |summary| self.policyResultFromRxSummary(
                summary,
                false,
            ),
            .drained => |summary| blk: {
                if (!self.consumedRxDrainEvidenceCurrent(
                    lease,
                    scratch,
                )) {
                    break :blk self.invalidRxPreparationResult(summary);
                }
                recordRxDrainTestEvent(.published);
                recordRxDrainTestEvent(.decide);
                const result = self.policyResultFromRxSummary(summary, true);
                if (!finishRxDrainEvidence(scratch)) {
                    break :blk self.terminalizePublishedRxResult(
                        result,
                        .invariant_failure,
                    );
                }
                break :blk result;
            },
        };
    }

    fn rxPreparationCoherent(preparation: RxPreparation) bool {
        return switch (preparation) {
            .terminal => |summary| summary.policy.terminal != null,
            .without_drain, .drained => |summary| summary.policy.terminal == null,
        };
    }

    fn invalidRxPreparationResult(
        self: *ExternalPumpStorage,
        summary: RxPreparedSummary,
    ) client_pump.TurnResult {
        var invalid = summary;
        invalid.policy.terminal = .{
            .reason = .invariant_failure,
            .fd_disposition = .owner_cleanup,
        };
        return self.policyResultFromRxSummary(invalid, false);
    }

    fn terminalizePublishedRxResult(
        _: *ExternalPumpStorage,
        published: client_pump.TurnResult,
        reason: client_pump.TerminalReason,
    ) client_pump.TurnResult {
        const terminal = client_pump.ExternalPumpTerminal{
            .reason = reason,
            .fd_disposition = .owner_cleanup,
        };
        return .{
            .rx_bytes = published.rx_bytes,
            .rx_read_bytes = published.rx_read_bytes,
            .rx_frames = published.rx_frames,
            .tx_bytes = published.tx_bytes,
            .tx_frames = published.tx_frames,
            .terminal = terminal,
            .next_deadline_ns = published.next_deadline_ns,
        };
    }

    fn policyResultFromRxSummary(
        _: *ExternalPumpStorage,
        summary: RxPreparedSummary,
        socket_rx_drained: bool,
    ) client_pump.TurnResult {
        const facts = summary.policy;
        var result = client_pump.decide(.{
            .turn = facts.turn,
            .parser = facts.parser,
            .socket_rx_drained = socket_rx_drained,
            .inherited_blocker = facts.inherited_blocker,
            .rx_frame_budget_exhausted = facts.rx_frame_budget_exhausted or
                facts.work_budget_exhausted,
            .rx_read_budget_exhausted = facts.rx_read_budget_exhausted,
            .terminal = facts.terminal,
            .deadlines = facts.deadlines,
        });
        result.rx_read_bytes = summary.rx_read_bytes;
        result.rx_bytes = summary.rx_bytes;
        result.rx_frames = summary.rx_frames;
        return result;
    }

    fn pumpBufferedRxUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        turn: client_pump.TurnInput,
        ops: *const BufferedRxOps,
        scratch: *ExternalRxTurnScratch,
    ) client_pump.TurnResult {
        self.snapshotInheritedRxBlockersUnderHeldLease(
            lease,
            &scratch.snapshot,
        ) catch return self.terminalRxTurn(
            .invariant_failure,
            0,
            0,
        );
        const snapshot = scratch.snapshot;
        _ = self.validateAndConsumeInheritedSnapshot(
            lease,
            &scratch.snapshot,
        ) catch return self.terminalRxTurn(
            .invariant_failure,
            0,
            0,
        );
        const existing_consumer_blocker =
            snapshot.committed_screen_pending or
            snapshot.metadata_projection_pending or
            snapshot.resize_projection_pending or
            snapshot.response_correlation_pending;
        if (existing_consumer_blocker) {
            return client_pump.decide(.{
                .turn = turn,
                .parser = .empty,
                .socket_rx_drained = false,
                .inherited_blocker = true,
            });
        }
        if (snapshot.live_screen_pending) {
            const consume = self.consumeLiveScreenHeadUnderHeldLease(
                lease,
                ops,
                &scratch.live_consume,
            );
            return switch (consume) {
                .consumed, .retry => client_pump.decide(.{
                    .turn = turn,
                    .parser = .empty,
                    .socket_rx_drained = false,
                    .inherited_blocker = true,
                }),
                .no_work, .invalid_state => self.terminalRxTurn(
                    .invariant_failure,
                    0,
                    0,
                ),
            };
        }

        const client = if (self.owned_client) |*owned|
            owned
        else
            return self.terminalRxTurn(.invariant_failure, 0, 0);
        const rx_state = switch (client.io_mode) {
            .external => |*state| state,
            .blocking => return self.terminalRxTurn(
                .invariant_failure,
                0,
                0,
            ),
        };
        const initial_readiness = client_external_mode.parserReadiness(
            rx_state,
            &client.parser,
        ) catch return self.terminalRxTurn(.invariant_failure, 0, 0);
        if (initial_readiness != .complete_or_error) {
            return client_pump.decide(.{
                .turn = turn,
                .parser = switch (initial_readiness) {
                    .empty => .empty,
                    .incomplete => .incomplete,
                    .complete_or_error => unreachable,
                },
                .socket_rx_drained = false,
            });
        }

        const mechanics = self.traverseAndCommitBufferedUnderHeldLease(
            lease,
            client,
            rx_state,
            snapshot.live_partial_pending,
            turn.now_ns,
            scratch,
        );
        const summary = switch (mechanics) {
            .terminal => |terminal| return if (!std.mem.allEqual(
                u8,
                &scratch.revoked_commit_graph.bytes,
                0,
            )) terminalRxResult(
                .{
                    .reason = terminal.reason,
                    .fd_disposition = .owner_cleanup,
                },
                terminal.rx_bytes,
                terminal.rx_frames,
            ) else self.terminalRxTurn(
                terminal.reason,
                terminal.rx_bytes,
                terminal.rx_frames,
            ),
            .completed => |completed| completed,
        };
        var result = client_pump.decide(.{
            .turn = turn,
            .parser = switch (summary.final_readiness) {
                .empty => .empty,
                .incomplete => .incomplete,
                .complete_or_error => .complete_or_error,
            },
            .socket_rx_drained = false,
            .rx_frame_budget_exhausted = summary.budget_exhausted,
        });
        result.rx_bytes = summary.rx_bytes;
        result.rx_frames = summary.rx_frames;
        return result;
    }

    /// Module-local buffered mechanics fixture. Product code must enter through the full
    /// `RxTurnOps` transaction below so readiness can never bypass the transport authority.
    fn pumpBufferedRxForTest(
        self: *ExternalPumpStorage,
        turn: client_pump.TurnInput,
        ops: *const BufferedRxOps,
        scratch: *ExternalRxTurnScratch,
    ) client_pump.TurnResult {
        if (scratch.saved_self_addr != @intFromPtr(scratch) or
            scratch.lifecycle != .ready)
            return self.terminalRxTurn(.invariant_failure, 0, 0);
        var lease: ExternalWholeTurnLease = .{};
        self.acquireWholeTurnLease(
            &lease,
            @intFromPtr(scratch),
            @sizeOf(ExternalRxTurnScratch),
        ) catch |err| return switch (err) {
            error.TransactionBusy => client_pump.decide(.{
                .turn = turn,
                .parser = .empty,
                .socket_rx_drained = false,
                .inherited_blocker = true,
            }),
            else => self.terminalRxTurn(.invariant_failure, 0, 0),
        };
        // TX and RX share one caller-sampled monotonic clock. Validate and publish it immediately
        // after acquiring the whole-turn lease, before recovery, parser, transport, or consumer
        // callbacks can observe a backwards/deadline-expired turn.
        const tx_clock_terminal: ?client_pump.TerminalReason = tx_clock: {
            const client = if (self.owned_client) |*owned| owned else break :tx_clock .invariant_failure;
            const external = switch (client.io_mode) {
                .external => |*state| state,
                .blocking => break :tx_clock .invariant_failure,
            };
            break :tx_clock client_external_tx.observeClock(
                external,
                turn.now_ns,
            );
        };
        if (tx_clock_terminal) |reason| {
            scratch.lifecycle = .terminal;
            self.semantic_state = .{ .terminal = .{
                .reason = reason,
                .fd_disposition = .owner_cleanup,
            } };
            var terminal = self.finalizeInjectedRxTerminalUnderHeldLease(
                &lease,
                scratch,
                self.terminalInjectedRxTurn(reason, 0, 0, 0),
            );
            if (self.releaseWholeTurnLease(&lease) != .released)
                terminal = self.terminalInjectedRxTurn(
                    .invariant_failure,
                    0,
                    0,
                    0,
                );
            return terminal;
        }
        const control_clock_terminal: ?client_pump.TerminalReason = control_clock: {
            if (!controlCorrelationValid(self))
                break :control_clock .invariant_failure;
            const expired = switch (self.control_correlation.state) {
                .in_flight => |control| client_control_correlation.deadlineExpired(
                    control,
                    turn.now_ns,
                ),
                .idle, .completed => false,
                .terminal => break :control_clock .invariant_failure,
            };
            if (!expired) break :control_clock null;
            if (!publishControlCorrelation(self, .terminal))
                break :control_clock .invariant_failure;
            break :control_clock .deadline_exceeded;
        };
        if (control_clock_terminal) |reason| {
            scratch.lifecycle = .terminal;
            self.semantic_state = .{ .terminal = .{
                .reason = reason,
                .fd_disposition = .owner_cleanup,
            } };
            var terminal = self.finalizeInjectedRxTerminalUnderHeldLease(
                &lease,
                scratch,
                self.terminalInjectedRxTurn(reason, 0, 0, 0),
            );
            if (self.releaseWholeTurnLease(&lease) != .released)
                terminal = self.terminalInjectedRxTurn(
                    .invariant_failure,
                    0,
                    0,
                    0,
                );
            return terminal;
        }
        scratch.lifecycle = .busy;
        scratch.snapshot = .{};
        scratch.live_consume = .{};
        scratch.authority_ranges_generation = self.operation_generation;
        var result = self.pumpBufferedRxUnderHeldLease(
            &lease,
            turn,
            ops,
            scratch,
        );
        if (result.terminal != null and
            !std.mem.allEqual(u8, &scratch.revoked_commit_graph.bytes, 0))
        {
            result = self.finalizeInjectedRxTerminalUnderHeldLease(
                &lease,
                scratch,
                result,
            );
        }
        scratch.snapshot = .{};
        scratch.live_consume = .{};
        scratch.lifecycle = .ready;
        if (self.releaseWholeTurnLease(&lease) != .released) {
            result = self.terminalRxTurn(
                .invariant_failure,
                result.rx_bytes,
                result.rx_frames,
            );
        }
        return result;
    }

    const AuthorityAdapterResult = enum {
        pristine,
        prepared,
        aborted_and_reset,
        terminal_closed,
        terminal_poisoned,
    };

    fn authorityDestinationsPristine(scratch: *const ExternalRxTurnScratch) bool {
        return std.meta.eql(
            scratch.authority_permit,
            client_external_turn_authority.PreparedAuthorityPermit{},
        ) and std.meta.eql(
            scratch.authority_cleanup_seed,
            client_external_turn_authority.FrozenCleanupSeed{},
        );
    }

    fn controlSemanticDestinationsPristine(
        scratch: *const ExternalRxTurnScratch,
    ) bool {
        return std.meta.eql(
            scratch.whole_drain_permit,
            PreparedWholeDrainPermit{},
        ) and std.meta.eql(
            scratch.control_semantic_verdict,
            PreparedControlSemanticVerdict{},
        ) and std.meta.eql(
            scratch.control_semantic_take,
            PreparedControlSemanticTake{},
        ) and std.meta.eql(
            scratch.resize_semantic_commit,
            PreparedResizeSemanticCommit{},
        ) and std.meta.eql(
            scratch.resize_semantic_response_take,
            PreparedControlResponseTake{},
        ) and frozenControlResponsePristine(
            &scratch.resize_semantic_frozen_response,
        ) and std.meta.eql(
            scratch.resync_ack_transition,
            PreparedResyncAckTransition{},
        ) and std.meta.eql(
            scratch.resync_ack_response_take,
            PreparedControlResponseTake{},
        ) and frozenControlResponsePristine(
            &scratch.resync_ack_frozen_response,
        ) and std.meta.eql(
            scratch.resync_semantic_commit,
            PreparedResyncSemanticCommit{},
        ) and std.meta.eql(
            scratch.projected_recovery_snapshot_commit,
            ProjectedRecoverySnapshotCommit{},
        ) and std.meta.eql(
            scratch.control_semantic_terminal,
            PreparedControlSemanticTerminal{},
        ) and std.meta.eql(
            scratch.control_semantic_terminal_binding,
            PreparedControlSemanticTerminalBinding{},
        ) and std.meta.eql(
            scratch.control_terminal_response_take,
            PreparedControlResponseTake{},
        ) and frozenControlResponsePristine(&scratch.control_terminal_frozen_response);
    }

    fn resetConsumedControlSemanticDestinations(
        scratch: *ExternalRxTurnScratch,
    ) void {
        scratch.whole_drain_permit = .{};
        scratch.control_semantic_verdict = .{};
        scratch.control_semantic_take = .{};
        scratch.resize_semantic_commit = .{};
        scratch.resize_semantic_response_take = .{};
        scratch.resize_semantic_frozen_response = .{};
        scratch.resync_ack_transition = .{};
        scratch.resync_ack_response_take = .{};
        scratch.resync_ack_frozen_response = .{};
        scratch.resync_semantic_commit = .{};
        scratch.projected_recovery_snapshot_commit = .{};
        scratch.control_semantic_terminal = .{};
        scratch.control_semantic_terminal_binding = .{};
        scratch.control_terminal_response_take = .{};
        scratch.control_terminal_frozen_response = .{};
    }

    fn controlSemanticAuthorityClear(self: *const ExternalPumpStorage) bool {
        const authority = switch (self.owner_authority) {
            .current => |value| value,
            .empty => return false,
        };
        const completed_clear = switch (self.completed_control) {
            .none => true,
            .completed, .terminal => false,
        };
        return completed_clear and
            self.control_correlation.state == .idle and
            authority.role == .controller and authority.flow == .clear and
            self.semantic_state == .active and self.semantic_state.active == .valid;
    }

    fn retireCommittedControlDrainEvidence(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
    ) bool {
        const evidence = &scratch.drain_evidence;
        if (!self.wholeTurnLeaseIdentityValid(lease) or
            evidence.lifecycle != .finished or
            evidence.mode != .completed_control or
            !rxDrainEvidenceSealed(evidence) or
            evidence.storage_addr != @intFromPtr(self) or
            evidence.owner_incarnation != self.owner_incarnation or
            !std.mem.eql(
                u8,
                &evidence.owner_incarnation_digest,
                &self.owner_incarnation_seal.digest,
            ) or
            evidence.lease_addr != @intFromPtr(lease) or
            evidence.lease_generation != lease.operation_generation or
            evidence.operation_generation != self.operation_generation or
            evidence.read_scratch_addr != @intFromPtr(&scratch.read) or
            scratch.read.generation != evidence.expected_post_settle_generation)
        {
            return false;
        }
        evidence.* = .{};
        return true;
    }

    fn retireConsumedControlTraversal(scratch: *ExternalRxTurnScratch) bool {
        if (client_external_rx_turn.Scratch.closedForOuterTurn(&scratch.traversal))
            return true;
        return client_external_rx_turn.Scratch.retireDestroyedIntent(
            &scratch.traversal,
        );
    }

    fn orchestrateCompletedControlUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        summary: RxPreparedSummary,
        result: *client_pump.TurnResult,
    ) bool {
        const prepared = self.prepareCompletedControlSemanticUnderHeldLease(
            lease,
            scratch,
            summary,
        );
        switch (prepared) {
            .not_ready => return false,
            .terminal_prepared => {
                if (!self.prepareControlSemanticTerminalBindingUnderHeldLease(
                    lease,
                    scratch,
                )) return false;
                const terminal_consume = self.consumeControlSemanticTerminalUnderHeldLease(
                    lease,
                    scratch,
                );
                if (terminal_consume != .consumed_cleaned) return false;
                const terminal = switch (self.semantic_state) {
                    .terminal => |value| value,
                    else => return false,
                };
                if (!self.retireCommittedControlDrainEvidence(lease, scratch))
                    return false;
                if (!retireConsumedControlTraversal(scratch)) return false;
                resetConsumedControlSemanticDestinations(scratch);
                scratch.lifecycle = .terminal;
                result.* = self.terminalInjectedRxTurn(
                    terminal.reason,
                    result.rx_read_bytes,
                    result.rx_bytes,
                    result.rx_frames,
                );
                return true;
            },
            .prepared_pair => switch (scratch.control_semantic_verdict.control_kind) {
                .resize => {
                    if (!self.prepareResizeSemanticCommitUnderHeldLease(lease, scratch))
                        return false;
                    const resize_consume = self.consumeResizeSemanticCommitUnderHeldLease(
                        lease,
                        scratch,
                    );
                    if (resize_consume != .consumed_resize_cleaned) return false;
                },
                .resync => {
                    const aggregate = self.validateReadyRxAggregate(lease);
                    if (!self.prepareResyncSemanticCommitUnderHeldLease(
                        lease,
                        scratch,
                        aggregate,
                    )) return false;
                    if (self.consumeResyncSemanticCommitUnderHeldLease(
                        lease,
                        scratch,
                        aggregate,
                    ) != .consumed_resync_cleaned) return false;
                },
                .detach => return false,
            },
        }
        if (!self.retireCommittedControlDrainEvidence(lease, scratch))
            return false;
        if (!retireConsumedControlTraversal(scratch)) return false;
        resetConsumedControlSemanticDestinations(scratch);
        result.authority_clear = self.controlSemanticAuthorityClear();
        return controlSemanticDestinationsPristine(scratch);
    }

    /// Rebuilds the permit projection from live owners while the whole-turn lease excludes every
    /// sibling mutation. The caller deliberately invokes this again at each lifecycle edge:
    /// reusing the original seed would turn an immutable record into a stale capability.
    fn currentAuthorityViewUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        summary: RxPreparedSummary,
    ) ?client_external_turn_authority.CurrentView {
        if (scratch.saved_self_addr != @intFromPtr(scratch) or
            scratch.lifecycle != .busy or scratch.turn_generation == 0 or
            scratch.turn_generation == std.math.maxInt(u64) or
            active_callback_region_addr != 0 or
            active_callback_release_addr != 0 or
            self.operation_reentry_latched or
            !ownerIncarnationValid(self) or !ownerAuthorityValid(self) or
            !self.validateWholeTurnLease(lease))
            return null;
        const evidence = &scratch.drain_evidence;
        if (evidence.lifecycle != .finished or evidence.mode != .general or
            !self.rxDrainEvidenceCurrentForCleanup(lease, scratch, evidence) or
            !evidence.final_owner_blockers_clear or
            std.mem.allEqual(u8, &evidence.initial_inherited_snapshot_digest, 0))
            return null;
        const client = if (self.owned_client) |*owned| owned else return null;
        const state = switch (client.io_mode) {
            .external => |*external| external,
            .blocking => return null,
        };
        if (@intFromPtr(client) != lease.rx_client_addr or
            @intFromPtr(&client.parser) != lease.rx_parser_addr or
            !client_external_mode.parserSealValid(state, &client.parser) or
            !std.meta.eql(state.rx_provenance, lease.rx_provenance))
            return null;
        const readiness = client_external_mode.parserReadiness(
            state,
            &client.parser,
        ) catch return null;
        if (readiness != evidence.final_readiness)
            return null;
        const owner_snapshot = buildRxOwnerAuthoritySnapshot(
            self,
            lease,
            scratch,
        ) orelse return null;
        const blockers = self.currentDrainBlockerProjection() orelse return null;
        if (owner_snapshot.inventory_generation !=
            evidence.owner_inventory_generation or
            !std.mem.eql(
                u8,
                &owner_snapshot.digest,
                &evidence.owner_snapshot_digest,
            ) or !blockers.all_clear or
            !std.mem.eql(
                u8,
                &blockers.digest,
                &evidence.inherited_blocker_snapshot_digest,
            ))
            return null;
        const authority = switch (self.owner_authority) {
            .current => |current| current,
            .empty => return null,
        };
        const terminal_detach_only = authority.role == .observer and
            self.observerDetachTxIsSoleFrame(state);
        const semantic_active = switch (self.semantic_state) {
            .active => true,
            else => false,
        };
        return .{
            .permit_addr = @intFromPtr(&scratch.authority_permit),
            .cleanup_seed_addr = @intFromPtr(&scratch.authority_cleanup_seed),
            .storage_addr = @intFromPtr(self),
            .owner_incarnation = self.owner_incarnation,
            .owner_incarnation_digest = self.owner_incarnation_seal.digest,
            .scratch_addr = @intFromPtr(scratch),
            .scratch_turn_generation = scratch.turn_generation,
            .lease_addr = @intFromPtr(lease),
            .operation_generation = lease.operation_generation,
            .lease_digest = lease.digest,
            .client_addr = @intFromPtr(client),
            .parser_addr = @intFromPtr(&client.parser),
            .parser_generation = state.rx_provenance.parser_seal.generation,
            .parser_seal_digest = state.rx_provenance.parser_seal.digest,
            .rx_provenance_digest = lease.rx_authority_digest,
            .rx_absolute_next = state.rx_provenance.rx_absolute_next,
            .drain_evidence_addr = @intFromPtr(evidence),
            .drain_read_attempt_generation = evidence.read_attempt_generation,
            .drain_evidence_digest = evidence.digest,
            .inherited_blocker_snapshot_digest = evidence.initial_inherited_snapshot_digest,
            .final_owner_snapshot_digest = evidence.owner_snapshot_digest,
            .final_parser_readiness = switch (readiness) {
                .empty => .empty,
                .incomplete => .incomplete,
                .complete_or_error => .complete_or_error,
            },
            .drain_evidence_lifecycle = .finished,
            .final_blockers_clear = blockers.all_clear,
            .read_budget_remaining = !summary.policy.rx_read_budget_exhausted,
            .frame_budget_remaining = !summary.policy.rx_frame_budget_exhausted,
            .work_budget_remaining = !summary.policy.work_budget_exhausted,
            .terminal_or_revoke = summary.policy.terminal != null,
            .semantic_active = semantic_active,
            .reentry_clear = !self.operation_reentry_latched,
            .attachment_role = authority.role,
            .terminal_detach_only = terminal_detach_only,
            .authority_flow = authority.flow,
            .owner_authority_seal_digest = self.owner_authority_seal.digest,
            .authority_generation = authority.generation,
        };
    }

    /// Observer authority remains read-only except for its own terminal detach. The exception is
    /// minted only when the sealed correlation and the entire TX queue agree that exactly one
    /// canonical detach request is queued or partially written.
    fn observerDetachTxIsSoleFrame(
        self: *const ExternalPumpStorage,
        state: *const client_external_mode.State,
    ) bool {
        if (state.external_tx.items.len != 1 or !controlCorrelationValid(self))
            return false;
        const control = switch (self.control_correlation.state) {
            .in_flight => |value| value,
            .idle, .completed, .terminal => return false,
        };
        if (control.kind != .detach or control.expectation != .detach)
            return false;
        return switch (client_external_tx.requestFrameProgress(
            state,
            control.request_id,
            control.wire_len,
        )) {
            .queued => control.progress == .queued,
            .partial => control.progress == .partial,
            .missing, .invalid => false,
        };
    }

    fn abortPreparedAuthorityForCleanup(
        scratch: *ExternalRxTurnScratch,
    ) bool {
        if (client_external_turn_authority.abortForCleanup(
            &scratch.authority_permit,
            &scratch.authority_cleanup_seed,
        ) == .aborted) return true;
        return client_external_turn_authority.poisonPreparedForTerminal(
            &scratch.authority_permit,
        );
    }

    fn currentAuthorityViewFromPermitUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
    ) ?client_external_turn_authority.CurrentView {
        const seed = scratch.authority_permit.seed;
        return self.currentAuthorityViewUnderHeldLease(
            lease,
            scratch,
            .{ .policy = .{
                .turn = .{
                    .readable = false,
                    .writable = false,
                    .now_ns = 0,
                },
                .parser = switch (seed.final_parser_readiness) {
                    .empty => .empty,
                    .incomplete => .incomplete,
                    .complete_or_error => .complete_or_error,
                },
                .inherited_blocker = !seed.final_blockers_clear,
                .rx_frame_budget_exhausted = !seed.frame_budget_remaining,
                .rx_read_budget_exhausted = !seed.read_budget_remaining,
                .work_budget_exhausted = !seed.work_budget_remaining,
                .terminal = if (seed.terminal_or_revoke) .{
                    .reason = .invariant_failure,
                    .fd_disposition = .owner_cleanup,
                } else null,
            } },
        );
    }

    /// Validates the RX authority fields that TX is never allowed to mutate. The broader owner
    /// inventory intentionally contains TX frame ranges and therefore changes on legitimate
    /// retire; the write leaf separately seals that queue, while this projection keeps parser,
    /// drain, inherited blockers, semantic authority, and the consumed permit immutable.
    fn txConsumedAuthorityStable(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
    ) bool {
        const permit = &scratch.authority_permit;
        const seed = permit.seed;
        if (!client_external_turn_authority.validateConsumed(permit, seed) or
            !self.validateWholeTurnLease(lease) or
            !ownerIncarnationValid(self) or !ownerAuthorityValid(self) or
            self.operation_reentry_latched or
            self.semantic_state != .active)
        {
            return false;
        }
        const client = if (self.owned_client) |*owned| owned else return false;
        const state = switch (client.io_mode) {
            .external => |*external| external,
            .blocking => return false,
        };
        const evidence = &scratch.drain_evidence;
        if (evidence.mode != .general or
            @intFromPtr(client) != seed.client_addr or
            @intFromPtr(&client.parser) != seed.parser_addr or
            !client_external_mode.parserSealValid(state, &client.parser) or
            state.rx_provenance.parser_seal.generation !=
                seed.parser_generation or
            !std.mem.eql(
                u8,
                &state.rx_provenance.parser_seal.digest,
                &seed.parser_seal_digest,
            ) or
            !std.mem.eql(
                u8,
                &lease.rx_authority_digest,
                &seed.rx_provenance_digest,
            ) or
            state.rx_provenance.rx_absolute_next != seed.rx_absolute_next or
            @intFromPtr(evidence) != seed.drain_evidence_addr or
            evidence.read_attempt_generation !=
                seed.drain_read_attempt_generation or
            !std.mem.eql(
                u8,
                &evidence.digest,
                &seed.drain_evidence_digest,
            ))
        {
            return false;
        }
        const blockers = self.currentDrainBlockerProjection() orelse
            return false;
        const authority = switch (self.owner_authority) {
            .current => |current| current,
            .empty => return false,
        };
        const stable = blockers.all_clear and
            std.mem.eql(
                u8,
                &blockers.digest,
                &evidence.inherited_blocker_snapshot_digest,
            ) and
            authority.role == seed.attachment_role and
            authority.flow == seed.authority_flow and
            std.meta.eql(authority.generation, seed.authority_generation) and
            std.mem.eql(
                u8,
                &self.owner_authority_seal.digest,
                &seed.owner_authority_seal_digest,
            );
        return stable;
    }

    /// Prepares the D2 authority and leaves it sealed for the f1 TX suffix. The caller either
    /// consumes it immediately before the first write syscall or aborts it when no TX is eligible.
    fn prepareAuthorityUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
        summary: RxPreparedSummary,
    ) AuthorityAdapterResult {
        const seed = self.currentAuthorityViewUnderHeldLease(
            lease,
            scratch,
            summary,
        ) orelse return .terminal_poisoned;
        switch (client_external_turn_authority.prepare(
            &scratch.authority_permit,
            &scratch.authority_cleanup_seed,
            seed,
        )) {
            .ineligible => return if (authorityDestinationsPristine(scratch))
                .pristine
            else
                .terminal_poisoned,
            .invalid_seed, .destination_not_empty => return .terminal_poisoned,
            .prepared => recordAuthorityAdapterTestEvent(.prepared),
        }
        if (hitAuthorityAdapterFailpoint(scratch, .after_prepare)) {
            scratch.turn_generation += 1;
        } else if (hitAuthorityAdapterFailpoint(
            scratch,
            .after_prepare_cleanup_corrupt,
        )) {
            scratch.turn_generation += 1;
            scratch.authority_cleanup_seed.digest[0] ^= 1;
        } else if (hitAuthorityAdapterFailpoint(
            scratch,
            .after_prepare_owner_drift,
        )) {
            self.owner_authority_seal.digest[0] ^= 1;
        } else if (hitAuthorityAdapterFailpoint(
            scratch,
            .after_prepare_parser_drift,
        )) {
            const client = if (self.owned_client) |*owned| owned else return .terminal_poisoned;
            const state = switch (client.io_mode) {
                .external => |*external| external,
                .blocking => return .terminal_poisoned,
            };
            state.rx_provenance.parser_seal.digest[0] ^= 1;
        } else if (hitAuthorityAdapterFailpoint(
            scratch,
            .after_prepare_drain_drift,
        )) {
            scratch.drain_evidence.digest[0] ^= 1;
        } else if (hitAuthorityAdapterFailpoint(
            scratch,
            .after_prepare_reentry,
        )) {
            self.operation_reentry_latched = true;
        }
        const validate_view = self.currentAuthorityViewUnderHeldLease(
            lease,
            scratch,
            summary,
        ) orelse {
            return if (abortPreparedAuthorityForCleanup(scratch))
                .terminal_closed
            else
                .terminal_poisoned;
        };
        if (!client_external_turn_authority.validate(
            &scratch.authority_permit,
            validate_view,
        )) {
            return if (abortPreparedAuthorityForCleanup(scratch))
                .terminal_closed
            else
                .terminal_poisoned;
        }
        recordAuthorityAdapterTestEvent(.validated);
        return .prepared;
    }

    fn consumePreparedAuthorityForTxUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
    ) bool {
        const current = self.currentAuthorityViewFromPermitUnderHeldLease(
            lease,
            scratch,
        ) orelse return false;
        if (client_external_turn_authority.consume(
            &scratch.authority_permit,
            current,
        ) != .consumed)
            return false;
        recordAuthorityAdapterTestEvent(.consumed);
        return true;
    }

    fn resetConsumedAuthorityUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
    ) bool {
        if (!self.validateWholeTurnLease(lease) or
            !client_external_turn_authority.resetConsumedAfterTx(
                &scratch.authority_permit,
                &scratch.authority_cleanup_seed,
            ) or !authorityDestinationsPristine(scratch))
            return false;
        recordAuthorityAdapterTestEvent(.reset);
        return true;
    }

    fn abortPreparedAuthorityUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
    ) AuthorityAdapterResult {
        const abort_view = self.currentAuthorityViewFromPermitUnderHeldLease(
            lease,
            scratch,
        ) orelse {
            return if (abortPreparedAuthorityForCleanup(scratch))
                .terminal_closed
            else
                .terminal_poisoned;
        };
        if (client_external_turn_authority.abort(
            &scratch.authority_permit,
            abort_view,
        ) != .aborted) {
            return if (abortPreparedAuthorityForCleanup(scratch))
                .terminal_closed
            else
                .terminal_poisoned;
        }
        recordAuthorityAdapterTestEvent(.aborted);
        const reset_view = self.currentAuthorityViewFromPermitUnderHeldLease(
            lease,
            scratch,
        ) orelse return .terminal_poisoned;
        if (!client_external_turn_authority.resetSpent(
            &scratch.authority_permit,
            &scratch.authority_cleanup_seed,
            reset_view,
        ) or !authorityDestinationsPristine(scratch))
            return .terminal_poisoned;
        recordAuthorityAdapterTestEvent(.reset);
        return .aborted_and_reset;
    }

    fn prepareRxTurnForNextTurn(
        self: *ExternalPumpStorage,
        lease: *ExternalWholeTurnLease,
        scratch: *ExternalRxTurnScratch,
    ) bool {
        if (scratch.lifecycle != .busy or
            !authorityDestinationsPristine(scratch) or
            !controlSemanticDestinationsPristine(scratch) or
            !callbackRegionTokenPristine(&scratch.callback_region) or
            active_callback_region_addr != 0 or
            active_callback_release_addr != 0 or
            active_callback_storage_addr != 0 or
            active_callback_lease_addr != 0 or
            active_callback_scratch_addr != 0 or
            active_callback_permit_addr != 0 or
            scratch.turn_generation == 0 or
            scratch.turn_generation == std.math.maxInt(u64) or
            !self.validateWholeTurnLease(lease) or
            !std.meta.eql(scratch.snapshot, InheritedRxBlockerSnapshot{}) or
            !std.meta.eql(scratch.live_consume, LiveScreenConsumePermit{}) or
            !client_external_mode.guardedQuarantineReceiptPristine(
                &scratch.quarantine_receipt,
            ) or
            !client_external_rx_turn.Scratch.closedForOuterTurn(
                &scratch.traversal,
            ))
            return false;

        const graph_pristine = client_external_rx_read.stoppedGraphPristine(
            &scratch.stopped_borrow,
            &scratch.borrow_use_permit,
            &scratch.would_block_seed,
            &scratch.prepared_admit_use_permit,
        );
        if (!graph_pristine and
            !client_external_rx_read.settledStoppedGraphValid(
                &scratch.read,
                &scratch.collect_receipt,
                &scratch.stopped_borrow,
                &scratch.borrow_use_permit,
                &scratch.would_block_seed,
                &scratch.prepared_admit_use_permit,
            ))
            return false;
        if (!scratch.read.isReady())
            return false;
        switch (scratch.drain_evidence.lifecycle) {
            .empty => if (!rxDrainEvidencePristine(&scratch.drain_evidence))
                return false,
            .finished => if (!self.rxDrainEvidenceCurrentForCleanup(
                lease,
                scratch,
                &scratch.drain_evidence,
            ))
                return false,
            else => return false,
        }
        return true;
    }

    fn commitRxTurnForNextTurn(
        scratch: *ExternalRxTurnScratch,
        expected_generation: u64,
    ) bool {
        if (scratch.lifecycle != .busy or
            scratch.turn_generation != expected_generation or
            expected_generation == 0 or
            expected_generation == std.math.maxInt(u64) or
            !authorityDestinationsPristine(scratch) or
            !controlSemanticDestinationsPristine(scratch) or
            !callbackRegionTokenPristine(&scratch.callback_region) or
            !scratch.read.isReady() or
            !client_external_mode.guardedQuarantineReceiptPristine(
                &scratch.quarantine_receipt,
            ) or
            (!client_external_rx_read.stoppedGraphPristine(
                &scratch.stopped_borrow,
                &scratch.borrow_use_permit,
                &scratch.would_block_seed,
                &scratch.prepared_admit_use_permit,
            ) and !client_external_rx_read.settledStoppedGraphValid(
                &scratch.read,
                &scratch.collect_receipt,
                &scratch.stopped_borrow,
                &scratch.borrow_use_permit,
                &scratch.would_block_seed,
                &scratch.prepared_admit_use_permit,
            )) or active_callback_region_addr != 0 or
            active_callback_release_addr != 0 or
            active_callback_storage_addr != 0 or
            active_callback_lease_addr != 0 or
            active_callback_scratch_addr != 0 or
            active_callback_permit_addr != 0)
            return false;
        scratch.turn_generation = expected_generation + 1;
        scratch.lifecycle = .ready;
        return true;
    }

    /// Runs one complete RX transaction. The product owner supplies the sole POSIX transport;
    /// module-local hostile fixtures use the same entry with injected read outcomes.
    pub fn pumpRxTurn(
        self: *ExternalPumpStorage,
        turn: client_pump.TurnInput,
        ops: *const RxTurnOps,
        scratch: *ExternalRxTurnScratch,
    ) client_pump.TurnResult {
        if (active_callback_region_addr != 0 or
            active_callback_release_addr != 0)
            return client_pump.decide(.{
                .turn = turn,
                .parser = .empty,
                .socket_rx_drained = false,
                .inherited_blocker = true,
            });
        if (scratch.saved_self_addr != @intFromPtr(scratch) or
            scratch.lifecycle != .ready or
            scratch.turn_generation == 0 or
            scratch.turn_generation == std.math.maxInt(u64) or
            !authorityDestinationsPristine(scratch) or
            !controlSemanticDestinationsPristine(scratch) or
            !callbackRegionTokenPristine(&scratch.callback_region) or
            !scratch.read.isReady() or
            !client_external_rx_turn.Scratch.closedForOuterTurn(
                &scratch.traversal,
            ) or !std.meta.eql(
            scratch.snapshot,
            InheritedRxBlockerSnapshot{},
        ) or !std.meta.eql(
            scratch.live_consume,
            LiveScreenConsumePermit{},
        ) or !client_external_mode.guardedQuarantineReceiptPristine(
            &scratch.quarantine_receipt,
        ) or active_callback_region_addr != 0 or
            active_callback_release_addr != 0 or
            active_callback_storage_addr != 0 or
            active_callback_lease_addr != 0 or
            active_callback_scratch_addr != 0 or
            active_callback_permit_addr != 0)
            return self.terminalRxTurn(.invariant_failure, 0, 0);
        const stopped_graph_pristine =
            client_external_rx_read.stoppedGraphPristine(
                &scratch.stopped_borrow,
                &scratch.borrow_use_permit,
                &scratch.would_block_seed,
                &scratch.prepared_admit_use_permit,
            );
        if (!stopped_graph_pristine and
            !client_external_rx_read.settledStoppedGraphValid(
                &scratch.read,
                &scratch.collect_receipt,
                &scratch.stopped_borrow,
                &scratch.borrow_use_permit,
                &scratch.would_block_seed,
                &scratch.prepared_admit_use_permit,
            ))
            return self.terminalRxTurn(.invariant_failure, 0, 0);
        const finished_drain = switch (scratch.drain_evidence.lifecycle) {
            .empty => if (rxDrainEvidencePristine(&scratch.drain_evidence))
                false
            else
                return self.terminalRxTurn(.invariant_failure, 0, 0),
            .finished => if (self.finishedRxDrainEvidenceResettable(scratch))
                true
            else
                return self.terminalRxTurn(.invariant_failure, 0, 0),
            else => return self.terminalRxTurn(.invariant_failure, 0, 0),
        };
        if (!stopped_graph_pristine and
            !client_external_rx_read.resetSettledStoppedGraphForNextTurn(
                &scratch.read,
                &scratch.collect_receipt,
                &scratch.stopped_borrow,
                &scratch.borrow_use_permit,
                &scratch.would_block_seed,
                &scratch.prepared_admit_use_permit,
            ))
            return self.terminalRxTurn(.invariant_failure, 0, 0);
        if (!client_external_rx_read.stoppedGraphPristine(
            &scratch.stopped_borrow,
            &scratch.borrow_use_permit,
            &scratch.would_block_seed,
            &scratch.prepared_admit_use_permit,
        ))
            return self.terminalRxTurn(.invariant_failure, 0, 0);
        if (finished_drain and !self.resetFinishedRxDrainEvidence(scratch))
            return self.terminalRxTurn(.invariant_failure, 0, 0);
        var lease: ExternalWholeTurnLease = .{};
        self.acquireWholeTurnLease(
            &lease,
            @intFromPtr(scratch),
            @sizeOf(ExternalRxTurnScratch),
        ) catch |err| return switch (err) {
            error.TransactionBusy => client_pump.decide(.{
                .turn = turn,
                .parser = .empty,
                .socket_rx_drained = false,
                .inherited_blocker = true,
            }),
            else => self.terminalRxTurn(.invariant_failure, 0, 0),
        };
        // TX and RX share one caller-sampled monotonic clock. Validate and publish it immediately
        // after acquiring the whole-turn lease, before recovery, parser, transport, or consumer
        // callbacks can observe a backwards/deadline-expired turn.
        const tx_clock_terminal: ?client_pump.TerminalReason = tx_clock: {
            const client = if (self.owned_client) |*owned| owned else break :tx_clock .invariant_failure;
            const external = switch (client.io_mode) {
                .external => |*state| state,
                .blocking => break :tx_clock .invariant_failure,
            };
            break :tx_clock client_external_tx.observeClock(
                external,
                turn.now_ns,
            );
        };
        if (tx_clock_terminal) |reason| {
            scratch.lifecycle = .terminal;
            self.semantic_state = .{ .terminal = .{
                .reason = reason,
                .fd_disposition = .owner_cleanup,
            } };
            var terminal = self.finalizeInjectedRxTerminalUnderHeldLease(
                &lease,
                scratch,
                self.terminalInjectedRxTurn(reason, 0, 0, 0),
            );
            if (self.releaseWholeTurnLease(&lease) != .released)
                terminal = self.terminalInjectedRxTurn(
                    .invariant_failure,
                    0,
                    0,
                    0,
                );
            return terminal;
        }
        scratch.lifecycle = .busy;
        scratch.snapshot = .{};
        scratch.live_consume = .{};
        scratch.stopped_borrow = .{};
        scratch.borrow_use_permit = .{};
        scratch.would_block_seed = .{};
        scratch.quarantine_receipt = .{};
        scratch.authority_ranges_generation = self.operation_generation;
        switch (self.commitAppliedRecoveryFreshUnderHeldLease(
            &lease,
            turn.now_ns,
        )) {
            .not_pending, .committed => {},
            .terminal => {
                scratch.lifecycle = .terminal;
                const reason = switch (self.semantic_state) {
                    .terminal => |terminal| terminal.reason,
                    else => client_pump.TerminalReason.invariant_failure,
                };
                var terminal = self.finalizeInjectedRxTerminalUnderHeldLease(
                    &lease,
                    scratch,
                    self.terminalInjectedRxTurn(reason, 0, 0, 0),
                );
                if (self.releaseWholeTurnLease(&lease) != .released) {
                    terminal = self.terminalInjectedRxTurn(
                        .invariant_failure,
                        0,
                        0,
                        0,
                    );
                    if (self.lifecycle == .live)
                        self.semantic_state = .{ .terminal = terminal.terminal.? };
                }
                return terminal;
            },
        }
        const preparation = self.prepareRxTurn(
            &lease,
            turn,
            ops,
            scratch,
        );
        var result = self.publishRxPreparationUnderHeldLease(
            &lease,
            scratch,
            preparation,
        );
        var completed_control_orchestrated = false;
        // MARU_F3D_PRODUCT_ORCHESTRATION_BEGIN
        if (result.terminal == null and scratch.lifecycle != .terminal) {
            switch (preparation) {
                .drained => |summary| {
                    if (scratch.drain_evidence.mode == .completed_control) {
                        if (!self.orchestrateCompletedControlUnderHeldLease(
                            &lease,
                            scratch,
                            summary,
                            &result,
                        )) {
                            scratch.lifecycle = .terminal;
                            result = self.terminalInjectedRxTurn(
                                .invariant_failure,
                                result.rx_read_bytes,
                                result.rx_bytes,
                                result.rx_frames,
                            );
                        } else {
                            completed_control_orchestrated = true;
                        }
                    }
                },
                .terminal, .without_drain => {},
            }
        }
        // MARU_F3D_PRODUCT_ORCHESTRATION_END
        var tx_authority_prepared = false;
        if (result.terminal == null and scratch.lifecycle != .terminal) {
            switch (preparation) {
                .drained => |summary| if (completed_control_orchestrated) {
                    // The completed-aware drain belongs exclusively to F3 semantic preparation.
                    // Until that consumer runs, it remains backpressure and must never mint D2 TX
                    // authority from a projection that intentionally forgave the response owner.
                    result.authority_clear = self.controlSemanticAuthorityClear();
                    const tx_pending = if (self.owned_client) |*owned| switch (owned.io_mode) {
                        .external => |*state| state.external_tx.items.len != 0,
                        .blocking => false,
                    } else false;
                    if (result.authority_clear and tx_pending) {
                        // This completed-control evidence has been retired and cannot mint a D2
                        // TX permit. Preserve the frame and self-wake a fresh general drain turn;
                        // only that turn may issue write authority.
                        result.authority_clear = false;
                        result.immediate_rx = true;
                    }
                } else switch (self.prepareAuthorityUnderHeldLease(
                    &lease,
                    scratch,
                    summary,
                )) {
                    .pristine, .aborted_and_reset => {},
                    .prepared => tx_authority_prepared = true,
                    .terminal_closed, .terminal_poisoned => {
                        scratch.lifecycle = .terminal;
                        result = self.terminalInjectedRxTurn(
                            .invariant_failure,
                            result.rx_read_bytes,
                            result.rx_bytes,
                            result.rx_frames,
                        );
                    },
                },
                .terminal, .without_drain => {},
            }
        }
        if (result.terminal == null and scratch.lifecycle != .terminal) tx_suffix: {
            const client = if (self.owned_client) |*owned| owned else {
                scratch.lifecycle = .terminal;
                result = self.terminalInjectedRxTurn(
                    .invariant_failure,
                    result.rx_read_bytes,
                    result.rx_bytes,
                    result.rx_frames,
                );
                break :tx_suffix;
            };
            const external = switch (client.io_mode) {
                .external => |*state| state,
                .blocking => {
                    scratch.lifecycle = .terminal;
                    result = self.terminalInjectedRxTurn(
                        .invariant_failure,
                        result.rx_read_bytes,
                        result.rx_bytes,
                        result.rx_frames,
                    );
                    break :tx_suffix;
                },
            };
            const tx_pending = external.external_tx.items.len != 0;
            result.write_interest = tx_pending and result.authority_clear;
            if (tx_pending and result.authority_clear and
                !result.immediate_rx and turn.writable)
            {
                if (!tx_authority_prepared or
                    !self.consumePreparedAuthorityForTxUnderHeldLease(
                        &lease,
                        scratch,
                    ))
                {
                    scratch.lifecycle = .terminal;
                    result = self.terminalInjectedRxTurn(
                        .invariant_failure,
                        result.rx_read_bytes,
                        result.rx_bytes,
                        result.rx_frames,
                    );
                    break :tx_suffix;
                }
                var tx_context = PosixTxContext{ .fd = client.fd };
                var tx_write_scratch: client_external_tx.PreparedTxWrite = .{};
                var tx_completion_context = ControlCompletionContext{
                    .storage = self,
                };
                const tx_binding = makeTxOwnerBinding(
                    self,
                    client,
                    external,
                    &lease,
                    @intFromPtr(scratch),
                    @sizeOf(ExternalRxTurnScratch),
                    @intFromPtr(&tx_write_scratch),
                    @sizeOf(client_external_tx.PreparedTxWrite),
                    .write_turn,
                );
                const tx_result =
                    client_external_tx.writeTurnPreparedFromExternalPump(
                        validateTxOwner,
                        @ptrCast(self),
                        &tx_write_scratch,
                        .{
                            .context = &tx_completion_context,
                            .consume = correlateExternalTxCompletions,
                        },
                        external.tx_allocator,
                        external,
                        tx_binding,
                        .{
                            .context = &tx_context,
                            .write = writeExternalTxPosix,
                        },
                        turn.now_ns,
                    );
                if (!self.resetConsumedAuthorityUnderHeldLease(
                    &lease,
                    scratch,
                )) {
                    scratch.lifecycle = .terminal;
                    result = self.terminalInjectedRxTurn(
                        .invariant_failure,
                        result.rx_read_bytes,
                        result.rx_bytes,
                        result.rx_frames,
                    );
                    break :tx_suffix;
                }
                tx_authority_prepared = false;
                result.tx_bytes = tx_result.accepted_bytes;
                result.tx_frames = tx_result.completed_frames;
                result.immediate_tx = tx_result.immediate_tx;
                if (tx_result.terminal) |reason| {
                    scratch.lifecycle = .terminal;
                    result = self.terminalInjectedRxTurn(
                        reason,
                        result.rx_read_bytes,
                        result.rx_bytes,
                        result.rx_frames,
                    );
                    self.semantic_state = .{ .terminal = result.terminal.? };
                } else {
                    if (!reconcileControlTxProgress(self, external)) {
                        scratch.lifecycle = .terminal;
                        result = self.terminalInjectedRxTurn(
                            .invariant_failure,
                            result.rx_read_bytes,
                            result.rx_bytes,
                            result.rx_frames,
                        );
                        self.semantic_state = .{ .terminal = result.terminal.? };
                    } else {
                        result.write_interest =
                            external.external_tx.items.len != 0;
                    }
                }
            }
        }
        if (tx_authority_prepared and result.terminal == null and
            scratch.lifecycle != .terminal)
        {
            switch (self.abortPreparedAuthorityUnderHeldLease(
                &lease,
                scratch,
            )) {
                .aborted_and_reset => tx_authority_prepared = false,
                else => {
                    scratch.lifecycle = .terminal;
                    result = self.terminalInjectedRxTurn(
                        .invariant_failure,
                        result.rx_read_bytes,
                        result.rx_bytes,
                        result.rx_frames,
                    );
                },
            }
        }
        scratch.snapshot = .{};
        scratch.live_consume = .{};
        if (result.terminal != null or scratch.lifecycle == .terminal) {
            result = self.finalizeInjectedRxTerminalUnderHeldLease(
                &lease,
                scratch,
                result,
            );
        } else if (scratch.callback_region.lifecycle == .consumed and
            !resetConsumedCallbackRegion(
                scratch,
                &scratch.callback_region,
            ))
            scratch.lifecycle = .terminal;

        var reusable_generation: ?u64 = null;
        if (scratch.lifecycle != .terminal and result.terminal == null) {
            const generation = scratch.turn_generation;
            if (self.prepareRxTurnForNextTurn(
                &lease,
                scratch,
            )) {
                reusable_generation = generation;
            } else {
                scratch.lifecycle = .terminal;
                result = self.terminalInjectedRxTurn(
                    .invariant_failure,
                    result.rx_read_bytes,
                    result.rx_bytes,
                    result.rx_frames,
                );
            }
        }
        if (scratch.lifecycle == .terminal and
            result.terminal != null and reusable_generation == null and
            self.semantic_state == .active)
        {
            result = self.finalizeInjectedRxTerminalUnderHeldLease(
                &lease,
                scratch,
                result,
            );
        }

        if (hitAuthorityAdapterFailpoint(
            scratch,
            .before_release_lease_digest_corrupt,
        )) lease.digest[0] ^= 1;
        const release_result = self.releaseWholeTurnLease(&lease);
        if (release_result != .released) {
            scratch.lifecycle = .terminal;
            result = self.terminalInjectedRxTurn(
                .invariant_failure,
                result.rx_read_bytes,
                result.rx_bytes,
                result.rx_frames,
            );
            if (self.lifecycle == .live)
                self.semantic_state = .{ .terminal = result.terminal.? };
            reusable_generation = null;
        } else if (reusable_generation) |generation| {
            if (!commitRxTurnForNextTurn(scratch, generation)) {
                scratch.lifecycle = .terminal;
                result = self.terminalInjectedRxTurn(
                    .invariant_failure,
                    result.rx_read_bytes,
                    result.rx_bytes,
                    result.rx_frames,
                );
                if (self.lifecycle == .live)
                    self.semantic_state = .{ .terminal = result.terminal.? };
            }
        } else if (result.terminal == null) {
            scratch.lifecycle = .terminal;
            result = self.terminalInjectedRxTurn(
                .invariant_failure,
                result.rx_read_bytes,
                result.rx_bytes,
                result.rx_frames,
            );
            if (self.lifecycle == .live)
                self.semantic_state = .{ .terminal = result.terminal.? };
        }
        return result;
    }

    fn expectedInheritedSnapshot(
        self: *const ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        out: *const InheritedRxBlockerSnapshot,
    ) AccessError!InheritedRxBlockerSnapshot {
        if (!ownerIncarnationValid(self) or !ownerAuthorityValid(self) or
            !ownerResizeValid(self) or !self.screenPendingSummaryValid() or
            !self.metadataPendingSummaryValid() or !self.liveOwnersValid())
            return error.InvalidSnapshot;
        const live_blockers = self.liveOwnerBlockerProjection() orelse
            return error.InvalidSnapshot;
        const authority_generation = self.owner_authority.current.generation;
        var result = InheritedRxBlockerSnapshot{
            .saved_self_addr = @intFromPtr(out),
            .storage_addr = @intFromPtr(self),
            .lease_addr = @intFromPtr(lease),
            .operation_generation = self.operation_generation,
            .committed_screen_pending = self.screen_pending_summary.retained_count != 0,
            .live_partial_pending = live_blockers.partial_pending,
            .live_screen_pending = live_blockers.screen_pending,
            .metadata_projection_pending = self.metadata_pending_summary.pending,
            .resize_projection_pending = switch (self.owner_resize) {
                .none => false,
                .current => |current| current.pending,
            },
            .response_correlation_pending = live_blockers.response_pending,
            .authority_generation = authority_generation,
            .generation = self.operation_generation,
            .lifecycle = .prepared,
            .owner_digest = self.inheritedOwnerDigest(),
        };
        result.digest = inheritedSnapshotDigest(result);
        return result;
    }

    fn inheritedOwnerDigest(
        self: *const ExternalPumpStorage,
    ) external_owner_seal.Digest {
        var writer = external_owner_seal.Writer.init("MARUIRX1");
        writer.writeBytes(&self.owner_incarnation_seal.digest);
        writer.writeBytes(&self.screen_pending_summary.digest);
        writer.writeBytes(&self.metadata_pending_summary.digest);
        switch (self.live_partial) {
            .none => writer.writeU8(0),
            .assembling => |assembling| {
                writer.writeU8(1);
                writer.writeBytes(&assembling.owner_digest);
            },
            .terminal => writer.writeU8(2),
        }
        writer.writeU8(@intFromEnum(self.live_screen.lifecycle));
        writer.writeBytes(&self.live_screen.owner_digest);
        switch (self.completed_control) {
            .none => writer.writeU8(0),
            .completed => |pending| {
                writer.writeU8(1);
                writer.writeBytes(&pending.owner_digest);
            },
            .terminal => writer.writeU8(2),
        }
        switch (self.owner_resize) {
            .none => writer.writeBool(false),
            .current => |current| {
                writer.writeBool(true);
                writer.writeBytes(&current.seal.digest);
            },
        }
        writer.writeBytes(&self.owner_authority_seal.digest);
        writer.writeUsize(self.rx_resident_cap);
        writer.writeBytes(&self.rx_resident_cap_digest);
        writer.writeU64(self.operation_generation);
        return writer.finish();
    }

    fn latchRecoveryInvariantTerminal(
        self: *ExternalPumpStorage,
    ) client_pump.RecoveryMarkResult {
        if (self.lifecycle == .live) {
            self.semantic_state = .{ .terminal = .{
                .reason = .invariant_failure,
                .fd_disposition = .owner_cleanup,
            } };
        }
        return .stale_invariant;
    }

    /// Allocation-free authority check that runs before a recovery snapshot can mutate the GUI
    /// screen. It does not consume or publish state; the exact same key is checked again by
    /// `markResyncApplied` after apply and lease release.
    pub fn preflightBatchAuthority(
        self: *const ExternalPumpStorage,
        stream_id: u64,
        is_snapshot: bool,
        maybe_key: ?client_pump.RecoveryKey,
    ) external_recovery_types.BatchAuthority {
        if (self.saved_self_addr != @intFromPtr(self) or
            self.lifecycle != .live or
            active_external_operation_addr != 0 or
            !ownerIncarnationValid(self) or
            stream_id != self.evidence_snapshot.stream_id)
            return .stale_invariant;
        const active = switch (self.semantic_state) {
            .active => |value| value,
            else => return .stale_invariant,
        };
        const key = maybe_key orelse return switch (active) {
            .valid => .ordinary,
            .host_recovery, .client_recovery => .stale_invariant,
        };
        if (!key.isCanonical() or !is_snapshot or
            key.owner_incarnation != self.owner_incarnation)
            return .stale_invariant;
        return switch (active) {
            .host_recovery => |phase| switch (phase) {
                .snapshot_in_flight => |waiting| if (key.origin == .host and
                    key.recovery_epoch == waiting.context.epoch and
                    key.expected_token_generation ==
                        waiting.expected_token_generation)
                    .recovery_exact
                else
                    .stale_invariant,
                else => .stale_invariant,
            },
            .client_recovery => |phase| switch (phase) {
                .snapshot_in_flight => |waiting| if (key.origin == .client and
                    key.recovery_epoch == waiting.context.epoch and
                    key.expected_token_generation ==
                        waiting.expected_token_generation)
                    .recovery_exact
                else
                    .stale_invariant,
                else => .stale_invariant,
            },
            .valid => .stale_invariant,
        };
    }

    /// Completes only the post-release authority transition. The consumer has already applied the
    /// screen and retired its ledger token, so stale evidence cannot be retried or repaired here.
    /// No allocator callback, clock read, or recursive pump is permitted in this suffix.
    pub fn markResyncApplied(
        self: *ExternalPumpStorage,
        stream_id: u64,
        key: client_pump.RecoveryKey,
    ) client_pump.RecoveryMarkResult {
        if (self.saved_self_addr != @intFromPtr(self) or
            self.lifecycle != .live or
            active_external_operation_addr != 0 or
            !ownerIncarnationValid(self) or
            !key.isCanonical() or
            stream_id != self.evidence_snapshot.stream_id or
            key.owner_incarnation != self.owner_incarnation)
            return self.latchRecoveryInvariantTerminal();

        const next: client_pump.AuthorityState = switch (self.semantic_state) {
            .active => |active| switch (active) {
                .host_recovery => |phase| switch (phase) {
                    .snapshot_in_flight => |waiting| blk: {
                        if (key.origin != .host or
                            key.recovery_epoch != waiting.context.epoch or
                            key.expected_token_generation !=
                                waiting.expected_token_generation)
                            return self.latchRecoveryInvariantTerminal();
                        break :blk .{ .host_recovery = .{
                            .applied_pending = waiting,
                        } };
                    },
                    else => return self.latchRecoveryInvariantTerminal(),
                },
                .client_recovery => |phase| switch (phase) {
                    .snapshot_in_flight => |waiting| blk: {
                        if (key.origin != .client or
                            key.recovery_epoch != waiting.context.epoch or
                            key.expected_token_generation !=
                                waiting.expected_token_generation)
                            return self.latchRecoveryInvariantTerminal();
                        break :blk .{ .client_recovery = .{
                            .applied_pending = waiting,
                        } };
                    },
                    else => return self.latchRecoveryInvariantTerminal(),
                },
                .valid => return self.latchRecoveryInvariantTerminal(),
            },
            else => return self.latchRecoveryInvariantTerminal(),
        };
        // `applied_pending` is the durable immediate-turn latch. Publishing a second bool would
        // create two wake authorities; pollHint derives both values from this single state.
        self.semantic_state = .{ .active = next };
        return .commit_pending;
    }

    /// Projects only the dependency-neutral recovery state. Keeping this leaf separate lets the
    /// e-core tests prove the recovery clock contract without manufacturing a partially adopted
    /// product owner; the public projection below additionally requires the sealed Client/TX
    /// state and fails closed when that product graph is incomplete.
    fn recoveryPollHint(
        semantic_state: client_pump.ExternalPumpState,
    ) client_pump.PollHint {
        return switch (semantic_state) {
            .active => |active| switch (active) {
                .host_recovery => |phase| switch (phase) {
                    .ack_unadmitted => |context| .{
                        .immediate = false,
                        .next_deadline_ns = context.deadline_ns,
                    },
                    .ack_queued => |context| .{
                        .immediate = false,
                        .next_deadline_ns = context.deadline_ns,
                    },
                    .awaiting_snapshot => |waiting| .{
                        .immediate = false,
                        .next_deadline_ns = waiting.context.deadline_ns,
                    },
                    .snapshot_in_flight => |in_flight| .{
                        .immediate = false,
                        .next_deadline_ns = in_flight.context.deadline_ns,
                    },
                    .applied_pending => |waiting| .{
                        .immediate = true,
                        .next_deadline_ns = waiting.context.deadline_ns,
                    },
                },
                .client_recovery => |phase| switch (phase) {
                    .control_wait => |context| .{
                        .immediate = false,
                        .next_deadline_ns = context.deadline_ns,
                    },
                    .control_in_flight => |context| .{
                        .immediate = false,
                        .next_deadline_ns = context.deadline_ns,
                    },
                    .awaiting_snapshot => |waiting| .{
                        .immediate = false,
                        .next_deadline_ns = waiting.context.deadline_ns,
                    },
                    .snapshot_in_flight => |in_flight| .{
                        .immediate = false,
                        .next_deadline_ns = in_flight.context.deadline_ns,
                    },
                    .applied_pending => |waiting| .{
                        .immediate = true,
                        .next_deadline_ns = waiting.context.deadline_ns,
                    },
                },
                .valid => .{
                    .immediate = false,
                    .next_deadline_ns = null,
                },
            },
            .terminal => .{ .immediate = false, .next_deadline_ns = null },
            else => .{ .immediate = true, .next_deadline_ns = null },
        };
    }

    fn controlPollHint(
        self: *const ExternalPumpStorage,
    ) ?client_pump.PollHint {
        if (!controlCorrelationValid(self)) return null;
        return switch (self.control_correlation.state) {
            .idle => .{ .immediate = false, .next_deadline_ns = null },
            .in_flight => |control| .{
                .immediate = false,
                .next_deadline_ns = control.deadline_ns,
            },
            // The private take/apply suffix owns this wake. f3 will expose that suffix to the
            // product caller without creating a second readiness authority.
            .completed => .{ .immediate = true, .next_deadline_ns = null },
            .terminal => .{ .immediate = true, .next_deadline_ns = null },
        };
    }

    /// Read-only descriptor projection for the final external-mode owner. Raw Client storage never
    /// escapes the mechanics module.
    pub fn pollSocketFd(self: *const ExternalPumpStorage) ?c.fd_t {
        if (self.saved_self_addr != @intFromPtr(self) or
            self.lifecycle != .live or
            !ownerIncarnationValid(self)) return null;
        const client = if (self.owned_client) |*owned| owned else return null;
        return switch (client.io_mode) {
            .external => if (client.fd >= 0) client.fd else null,
            .blocking => null,
        };
    }

    /// Read-only wake/deadline projection. Recovery, TX, and control expose one immediate bit and the
    /// earliest absolute deadline, while an incomplete product owner fails closed.
    pub fn pollHint(self: *const ExternalPumpStorage) client_pump.PollHint {
        if (self.saved_self_addr != @intFromPtr(self) or
            self.lifecycle != .live or
            !ownerIncarnationValid(self))
            return .{ .immediate = true, .next_deadline_ns = null };
        const recovery = recoveryPollHint(self.semantic_state);
        const client = if (self.owned_client) |*owned| owned else return .{ .immediate = true, .next_deadline_ns = null };
        const external = switch (client.io_mode) {
            .external => |*state| state,
            .blocking => return .{ .immediate = true, .next_deadline_ns = null },
        };
        const tx = client_external_tx.pollHint(external);
        if (!tx.valid)
            return .{ .immediate = true, .next_deadline_ns = null };
        const control = self.controlPollHint() orelse
            return .{ .immediate = true, .next_deadline_ns = null };
        const recovery_tx_deadline = if (recovery.next_deadline_ns) |recovery_deadline|
            if (tx.deadline_ns) |tx_deadline|
                @min(recovery_deadline, tx_deadline)
            else
                recovery_deadline
        else
            tx.deadline_ns;
        return .{
            .immediate = recovery.immediate or tx.immediate or control.immediate,
            .next_deadline_ns = if (recovery_tx_deadline) |current|
                if (control.next_deadline_ns) |control_deadline|
                    @min(current, control_deadline)
                else
                    current
            else
                control.next_deadline_ns,
        };
    }

    pub const CleanupWireAuthority = enum {
        none,
        offset_zero,
        control_in_flight,
        partial_frame,
        response_wait,
    };

    pub const CleanupWireProjection = union(enum) {
        authority: CleanupWireAuthority,
        busy,
        terminal: client_pump.TerminalReason,
        invalid,
    };

    /// Projects only the wire fact required by the outer cleanup policy while holding the same
    /// whole-turn lease as RX/TX. Queue descriptors, Client storage, and request correlation never
    /// escape this mechanics owner.
    pub fn projectCleanupWireAuthority(
        self: *ExternalPumpStorage,
    ) CleanupWireProjection {
        var lease: ExternalWholeTurnLease = .{};
        var scratch: [1]u8 = undefined;
        self.acquireWholeTurnLease(
            &lease,
            @intFromPtr(&scratch),
            scratch.len,
        ) catch |err| return switch (err) {
            error.TransactionBusy => .busy,
            error.Terminal => .{ .terminal = self.snapshotTerminalReason() },
            else => .invalid,
        };

        var result: CleanupWireProjection = blk: {
            if (!controlCorrelationValid(self)) break :blk .invalid;
            const client = if (self.owned_client) |*owned| owned else break :blk .invalid;
            const external = switch (client.io_mode) {
                .external => |*state| state,
                .blocking => break :blk .invalid,
            };
            if (!client_external_tx.pollHint(external).valid) break :blk .invalid;

            switch (self.control_correlation.state) {
                .in_flight => |control| switch (control.progress) {
                    .response_wait => break :blk .{ .authority = .response_wait },
                    // A control remains semantically in flight whether the kernel has accepted
                    // zero or some bytes. Cleanup must never append detach behind it.
                    .queued, .partial => break :blk .{ .authority = .control_in_flight },
                },
                .terminal => break :blk .invalid,
                .idle, .completed => {},
            }

            var has_zero = false;
            for (external.external_tx.items) |frame| {
                if (frame.offset >= frame.bytes.len) break :blk .invalid;
                if (frame.offset != 0) break :blk .{ .authority = .partial_frame };
                has_zero = true;
            }
            break :blk .{ .authority = if (has_zero) .offset_zero else .none };
        };
        if (self.releaseWholeTurnLease(&lease) != .released)
            result = .invalid;
        return result;
    }

    pub const CleanupCancelResult = enum {
        cancelled,
        busy,
        uncancellable,
        terminal,
        invalid,
        quarantined,
    };

    /// Cancels only offset-zero input frames for this attachment. Control frames and any frame
    /// with a kernel-visible prefix are deliberately uncancellable, matching the 3b fail-close
    /// rule. The full prepared/commit/cleanup graph stays behind the mechanics boundary.
    pub fn cancelOffsetZeroInputForCleanup(
        self: *ExternalPumpStorage,
        scratch: *ExternalRxTurnScratch,
        now_ns: i128,
    ) CleanupCancelResult {
        if (scratch.saved_self_addr != @intFromPtr(scratch) or
            scratch.lifecycle != .ready or scratch.turn_generation == 0 or
            !std.mem.allEqual(u8, &scratch.tx_cancellation.bytes, 0) or
            !std.mem.allEqual(u8, &scratch.tx_cancellation_permit.bytes, 0) or
            !std.mem.allEqual(u8, &scratch.tx_cancellation_cleanup.bytes, 0))
            return .busy;
        var lease: ExternalWholeTurnLease = .{};
        self.acquireWholeTurnLease(
            &lease,
            @intFromPtr(scratch),
            @sizeOf(ExternalRxTurnScratch),
        ) catch |err| return switch (err) {
            error.TransactionBusy => .busy,
            error.Terminal => .terminal,
            else => .invalid,
        };
        scratch.lifecycle = .busy;

        var result: CleanupCancelResult = blk: {
            if (!controlCorrelationValid(self) or self.control_correlation.state != .idle)
                break :blk .uncancellable;
            const client = if (self.owned_client) |*owned| owned else break :blk .invalid;
            const external = switch (client.io_mode) {
                .external => |*state| state,
                .blocking => break :blk .invalid,
            };
            const binding = makeTxOwnerBinding(
                self,
                client,
                external,
                &lease,
                @intFromPtr(scratch),
                @sizeOf(ExternalRxTurnScratch),
                @intFromPtr(&scratch.tx_cancellation),
                @sizeOf(client_external_tx.PreparedTxCancellation),
                .cancel_turn,
            );
            switch (client_external_tx.prepareCancellationFromExternalPump(
                validateTxOwner,
                @ptrCast(self),
                &scratch.tx_cancellation,
                &scratch.tx_cancellation_permit,
                &scratch.tx_cancellation_cleanup,
                external,
                binding,
                .{ .stream_id = self.evidence_snapshot.stream_id },
                now_ns,
            )) {
                .prepared => {},
                .uncancellable => break :blk .uncancellable,
                .invalid => break :blk .invalid,
            }
            if (!client_external_tx.validatePreparedCancellation(
                validateTxOwner,
                @ptrCast(self),
                &scratch.tx_cancellation,
                &scratch.tx_cancellation_permit,
                external,
                binding,
            )) break :blk .invalid;
            if (!client_external_tx.consumePreparedCancellationUnderHeldLease(
                validateTxOwner,
                @ptrCast(self),
                &scratch.tx_cancellation,
                &scratch.tx_cancellation_permit,
                &scratch.tx_cancellation_cleanup,
                external,
                binding,
            )) break :blk .invalid;
            switch (client_external_tx.finishCancellationCleanup(
                validateTxOwner,
                @ptrCast(self),
                &scratch.tx_cancellation,
                &scratch.tx_cancellation_permit,
                &scratch.tx_cancellation_cleanup,
                external,
                binding,
            )) {
                .cleaned => {},
                .invalid => break :blk .invalid,
                .quarantined => break :blk .quarantined,
            }
            if (!client_external_tx.resetCancellationGraphForNextTurn(
                validateTxOwner,
                @ptrCast(self),
                &scratch.tx_cancellation,
                &scratch.tx_cancellation_permit,
                &scratch.tx_cancellation_cleanup,
                external,
                binding,
            )) break :blk .invalid;
            break :blk .cancelled;
        };
        scratch.lifecycle = .ready;
        if (self.releaseWholeTurnLease(&lease) != .released)
            result = .quarantined;
        return result;
    }

    /// Runs the semantic prefix of the mandatory fresh-clock zero-readiness turn. RX remains a
    /// separate suffix so the owner can commit first and then classify bytes already ready on the
    /// same turn without reopening input/TX in between.
    fn commitAppliedRecoveryFreshSemantic(
        self: *ExternalPumpStorage,
        now_ns: i128,
    ) enum { committed, terminal } {
        if (self.saved_self_addr != @intFromPtr(self) or
            self.lifecycle != .live or
            !ownerIncarnationValid(self))
        {
            _ = self.latchRecoveryInvariantTerminal();
            return .terminal;
        }
        const active = switch (self.semantic_state) {
            .active => |value| value,
            else => {
                _ = self.latchRecoveryInvariantTerminal();
                return .terminal;
            },
        };
        const plan = client_pump.planRecoveryTransition(.{
            .state = active,
            .trigger = .fresh_commit,
            .now_ns = now_ns,
        });
        if (plan.disposition != .committed) {
            const reason: client_pump.TerminalReason =
                if (client_pump.recoveryDeadline(active)) |deadline|
                    if (now_ns >= deadline) .deadline_exceeded else .invariant_failure
                else
                    .invariant_failure;
            self.semantic_state = .{ .terminal = .{
                .reason = reason,
                .fd_disposition = .owner_cleanup,
            } };
            return .terminal;
        }
        self.semantic_state = .{ .active = plan.next };
        return .committed;
    }

    fn commitAppliedRecoveryFreshUnderHeldLease(
        self: *ExternalPumpStorage,
        lease: *const ExternalWholeTurnLease,
        now_ns: i128,
    ) enum { not_pending, committed, terminal } {
        if (!self.validateWholeTurnLease(lease)) {
            _ = self.latchRecoveryInvariantTerminal();
            return .terminal;
        }
        const pending = switch (self.semantic_state.active) {
            .host_recovery => |phase| phase == .applied_pending,
            .client_recovery => |phase| phase == .applied_pending,
            .valid => false,
        };
        if (!pending) return .not_pending;
        return switch (self.commitAppliedRecoveryFreshSemantic(now_ns)) {
            .committed => .committed,
            .terminal => .terminal,
        };
    }

    /// Pointer-free metadata query. Invalid committed authority stays distinguishable from ordinary
    /// lifecycle states; this read-only operation never attempts cleanup without caller scratch.
    pub fn metadataState(self: *const ExternalPumpStorage) MetadataStateResult {
        if (self.saved_self_addr != 0 and self.saved_self_addr != @intFromPtr(self))
            return .moved;
        if (active_external_operation_addr != 0)
            return .transaction_busy;
        active_external_operation_addr = @intFromPtr(self);
        defer active_external_operation_addr = 0;
        switch (self.lifecycle) {
            .empty, .constructing, .normalizing, .adopting, .adoption_preparing => return .not_active,
            .tearing_down, .dead => return .dead,
            .live => {},
        }
        switch (self.semantic_state) {
            .active => {},
            .terminal => return .dead,
            else => return .not_active,
        }
        const summary = self.owner_metadata.metadataStateSummary(self) orelse
            return .invalid_owner;
        return .{ .state = summary };
    }

    fn projectOwnerEventInternal(
        self: *ExternalPumpStorage,
        projector: OwnerEventProjector,
        cleanup_scratch: *ExternalPumpCleanupScratch,
    ) ProjectOwnerEventResult {
        if (self.saved_self_addr != 0 and self.saved_self_addr != @intFromPtr(self))
            return .moved;
        if (active_external_operation_addr != 0)
            return .transaction_busy;
        switch (self.lifecycle) {
            .empty, .constructing, .normalizing, .adopting, .adoption_preparing => return .not_active,
            .tearing_down, .dead => return .dead,
            .live => {},
        }
        switch (self.semantic_state) {
            .active => {},
            .terminal => return .dead,
            else => return .not_active,
        }
        active_external_operation_addr = @intFromPtr(self);
        defer active_external_operation_addr = 0;
        if (!ownerIncarnationValid(self) or !ownerAuthorityValid(self))
            return self.quarantineProjection(cleanup_scratch, false);
        const authority = self.owner_authority.current;
        if (authority.flow == .initial_fence) return .fenced;
        if (cleanupScratchOverlapsStorage(self, cleanup_scratch) or
            !cleanup_scratch.isReady())
            return self.quarantineProjection(cleanup_scratch, false);

        const metadata_summary = self.owner_metadata.metadataStateSummary(self) orelse
            return self.quarantineProjection(cleanup_scratch, true);
        if (!ownerResizeValid(self) or !self.inbox_ledger.accountingView().valid)
            return self.quarantineProjection(cleanup_scratch, true);
        if (!self.projectionScratchDisjoint(cleanup_scratch))
            return self.quarantineProjection(cleanup_scratch, false);
        if (self.owner_event_projection_generation == std.math.maxInt(u64)) {
            switch (self.teardownUnderHeldOperationLease(cleanup_scratch)) {
                .cleaned, .cleaned_with_invariant, .already_dead, .quarantined => {},
                .moved_storage, .transaction_busy => {
                    _ = self.quarantineOwnerTeardown(cleanup_scratch, true);
                },
            }
            return .terminal_latched;
        }
        const next_generation = self.owner_event_projection_generation + 1;

        const selected: SelectedOwnerEvent = switch (self.owner_resize) {
            .current => |current| if (current.pending)
                .{
                    .key = .{ .resized = .{
                        .generation = current.event.resize_generation,
                        .cols = current.event.cols,
                        .rows = current.event.rows,
                    } },
                    .view = .{ .resized = current.event },
                }
            else
                self.selectMetadataEvent(metadata_summary) orelse return .none,
            .none => self.selectMetadataEvent(metadata_summary) orelse return .none,
        };

        var permit: OwnerEventPermit = .{};
        if (!prepareOwnerEventPermit(self, selected.key, next_generation, &permit))
            return self.quarantineProjection(cleanup_scratch, true);
        defer if (permit.lifecycle == .prepared) consumeOwnerEventPermit(&permit);
        if (!self.projectorContextDisjoint(projector, cleanup_scratch, &permit))
            return self.finishProjectionWithTrustedTeardown(cleanup_scratch, &permit);

        const ledger_authority = self.inbox_ledger.projectionAuthorityDigest();
        const screen_authority =
            self.committed_screen.projectionAuthorityDigest(self) orelse
            return self.quarantineProjection(cleanup_scratch, true);
        const take_authority =
            self.client_cleanup_take.projectionAuthorityDigest() orelse
            return self.quarantineProjection(cleanup_scratch, true);
        const operation_generation = self.operation_generation;
        const teardown_generation = self.owner_teardown_generation;
        // Exact-copy the complete outer Client before traversing any owned backing. The post
        // callback path must compare this descriptor-only snapshot first; otherwise a forged list
        // pointer could be dereferenced while trying to compute the deep digest that detects it.
        const client_outer_authority = self.owned_client;
        const client_authority = if (self.owned_client) |*client|
            client.clientProjectionAuthorityDigest()
        else
            null;
        const evidence_authority = self.owned_evidence;
        self.owner_event_projection_generation = next_generation;
        const decision = projector.project(projector.context, selected.view);

        if (!cleanup_scratch.isReady())
            return self.quarantineProjection(cleanup_scratch, false);
        const semantic_active = switch (self.semantic_state) {
            .active => true,
            else => false,
        };
        if (self.saved_self_addr != @intFromPtr(self) or self.lifecycle != .live or
            !semantic_active or !ownerIncarnationValid(self) or
            !ownerAuthorityValid(self) or
            self.operation_generation != operation_generation or
            self.owner_teardown_generation != teardown_generation)
            return self.quarantineProjection(cleanup_scratch, true);
        const post_ledger_authority = self.inbox_ledger.projectionAuthorityDigest();
        const post_screen_authority =
            self.committed_screen.projectionAuthorityDigest(self) orelse
            return self.quarantineProjection(cleanup_scratch, true);
        const post_take_authority =
            self.client_cleanup_take.projectionAuthorityDigest() orelse
            return self.quarantineProjection(cleanup_scratch, true);
        if (!std.mem.eql(
            u8,
            &ledger_authority,
            &post_ledger_authority,
        ) or !std.mem.eql(u8, &screen_authority, &post_screen_authority) or
            !std.mem.eql(u8, &take_authority, &post_take_authority) or
            !std.meta.eql(client_outer_authority, self.owned_client) or
            !std.meta.eql(evidence_authority, self.owned_evidence))
            return self.quarantineProjection(cleanup_scratch, true);
        // The shallow equality above is the descriptor-first memory-safety gate. Only now may the
        // deep transcript traverse list elements through those exact pre-callback pointers.
        const post_client_authority = if (self.owned_client) |*client|
            client.clientProjectionAuthorityDigest()
        else
            null;
        if (!std.meta.eql(client_authority, post_client_authority))
            return self.quarantineProjection(cleanup_scratch, true);
        const post_summary = self.owner_metadata.metadataStateSummary(self) orelse
            return self.quarantineProjection(cleanup_scratch, true);
        if (!ownerResizeValid(self) or !self.selectedEventStillMatches(selected, post_summary))
            return self.quarantineProjection(cleanup_scratch, true);
        if (!ownerEventPermitValid(self, selected.key, &permit))
            return self.finishProjectionWithTrustedTeardown(cleanup_scratch, &permit);

        consumeOwnerEventPermit(&permit);
        switch (decision) {
            .retry_preserved => return .retry_preserved,
            .applied => {
                switch (selected.key) {
                    .resized => {
                        self.owner_resize.current.pending = false;
                        self.resealOwnerResize();
                    },
                    .metadata => {
                        if (!self.metadataPendingSummaryValid() or
                            self.metadata_pending_summary.generation ==
                                std.math.maxInt(u64))
                            return self.quarantineProjection(
                                cleanup_scratch,
                                true,
                            );
                        self.owner_metadata.metadata.current.pending = false;
                        self.metadata_pending_summary.pending = false;
                        self.metadata_pending_summary.generation += 1;
                        self.metadata_pending_summary.digest =
                            metadataPendingSummaryDigest(
                                self.metadata_pending_summary,
                            );
                    },
                }
                return .applied;
            },
        }
    }

    /// The raw attach CLI renders only screen batches. Metadata and host-side resize notifications
    /// still have to be consumed, otherwise they remain inherited pump blockers and can starve
    /// stdin/TX forever. This product adapter acknowledges exactly one already-validated owner
    /// event without exposing its borrowed backing or inventing a second event representation.
    pub fn consumeCliOwnerProjection(
        self: *ExternalPumpStorage,
        cleanup_scratch: *ExternalPumpCleanupScratch,
    ) CliOwnerProjectionResult {
        const Context = struct {
            fn project(_: *anyopaque, view: OwnerEventView) ProjectionDecision {
                std.mem.doNotOptimizeAway(view);
                return .applied;
            }
        };
        var context: u8 = 0;
        return switch (self.projectOwnerEventInternal(.{
            .context = &context,
            .context_len = @sizeOf(u8),
            .project = Context.project,
        }, cleanup_scratch)) {
            .applied => .applied,
            .none => .none,
            .retry_preserved, .transaction_busy => .retry,
            .fenced, .moved, .not_active, .dead, .terminal_latched => .terminal,
        };
    }

    /// Chooses the one sibling projection that may run after an RX turn. Committed/partial screen
    /// authority cannot be crossed; an already-materialized metadata/resize event precedes an
    /// adjacent live-screen FIFO head; a screen-only or response-only owner returns to the pump.
    pub fn cliOwnerProjectionReadiness(
        self: *const ExternalPumpStorage,
    ) CliOwnerProjectionReadiness {
        if (self.saved_self_addr != 0 and self.saved_self_addr != @intFromPtr(self))
            return .terminal;
        if (active_external_operation_addr != 0) return .retry;
        if (self.lifecycle != .live or self.semantic_state != .active or
            self.semantic_state.active != .valid or
            !ownerIncarnationValid(self) or !ownerAuthorityValid(self) or
            !ownerResizeValid(self) or !self.metadataPendingSummaryValid())
            return .terminal;
        if (self.owner_authority.current.flow == .initial_fence) return .retry;
        const live = self.liveOwnerBlockerProjection() orelse return .terminal;
        const resize_pending = switch (self.owner_resize) {
            .none => false,
            .current => |current| current.pending,
        };
        // A control response and its owner event can arrive in either wire order. The event is
        // itself the inherited blocker that prevents the response drain, so response_pending may
        // not veto this adjacent owner transaction or the pair deadlocks forever.
        return selectCliOwnerProjectionReadiness(
            self.screen_pending_summary.retained_count,
            live.partial_pending,
            resize_pending or self.metadata_pending_summary.pending,
            live.screen_pending,
            live.response_pending,
        );
    }

    fn selectMetadataEvent(
        self: *ExternalPumpStorage,
        summary: external_event_materialization.MetadataStateSummary,
    ) ?SelectedOwnerEvent {
        const scalar = switch (summary) {
            .unsupported, .unavailable => return null,
            .current => |current| current,
        };
        if (!scalar.pending) return null;
        const current = &self.owner_metadata.metadata.current;
        const dto = &current.logical;
        return .{
            .key = .{ .metadata = .{
                .revision = scalar.revision,
                .raw_digest = current.logical_seal.raw_digest,
                .semantic_digest = current.logical_seal.semantic_digest,
            } },
            .view = .{ .metadata = .{
                .revision = dto.revision,
                .observer_generation = dto.observer_generation,
                .title_generation = dto.title_generation,
                .cols = dto.cols,
                .rows = dto.rows,
                .semantic_state = dto.semantic_state,
                .alt_active = dto.alt_active,
                .app_cursor_keys = dto.app_cursor_keys,
                .app_keypad = dto.app_keypad,
                .kitty_flags = dto.kitty_flags,
                .alternate_scroll = dto.alternate_scroll,
                .mouse_tracking = dto.mouse_tracking,
                .mouse_tracking_mode = dto.mouse_tracking_mode,
                .bracketed_paste = dto.bracketed_paste,
                .bell_count = dto.bell_count,
                .clipboard_write_seq = dto.clipboard_write_seq,
                .clipboard_read_seq = dto.clipboard_read_seq,
                .foreground_available = dto.foreground_available,
                .foreground_pgid = dto.foreground_pgid,
                .cwd = dto.cwd(),
                .window_title = dto.windowTitle(),
                .ssh_remote_dest = dto.sshRemoteDest(),
                .clipboard_read_target = dto.clipboardReadTarget(),
                .processes = dto.foregroundProcesses(),
            } },
        };
    }

    fn projectorContextDisjoint(
        self: *const ExternalPumpStorage,
        projector: OwnerEventProjector,
        cleanup_scratch: *const ExternalPumpCleanupScratch,
        permit: *const OwnerEventPermit,
    ) bool {
        const context_addr = @intFromPtr(projector.context);
        if (context_addr == 0 or projector.context_len == 0)
            return false;
        _ = std.math.add(usize, context_addr, projector.context_len) catch return false;
        if (rangesOverlap(context_addr, projector.context_len, @intFromPtr(self), @sizeOf(ExternalPumpStorage)) or
            rangesOverlap(context_addr, projector.context_len, @intFromPtr(cleanup_scratch), @sizeOf(ExternalPumpCleanupScratch)) or
            rangesOverlap(context_addr, projector.context_len, @intFromPtr(permit), @sizeOf(OwnerEventPermit)))
            return false;
        if (self.owner_metadata.metadata == .current) {
            const current = &self.owner_metadata.metadata.current;
            if (current.logical.backing) |backing|
                if (rangesOverlap(
                    context_addr,
                    projector.context_len,
                    @intFromPtr(backing.ptr),
                    backing.len,
                )) return false;
            if (current.cleanup.backing) |backing|
                if (rangesOverlap(
                    context_addr,
                    projector.context_len,
                    @intFromPtr(backing.ptr),
                    backing.len,
                )) return false;
        }
        return true;
    }

    fn projectionScratchDisjoint(
        self: *const ExternalPumpStorage,
        cleanup_scratch: *const ExternalPumpCleanupScratch,
    ) bool {
        const scratch_addr = @intFromPtr(cleanup_scratch);
        const scratch_len = @sizeOf(ExternalPumpCleanupScratch);
        if (self.inbox_ledger.overlapsOwnedRange(scratch_addr, scratch_len))
            return false;
        if (self.owner_metadata.metadata == .current) {
            const current = &self.owner_metadata.metadata.current;
            if (current.logical.backing) |backing|
                if (rangesOverlap(
                    scratch_addr,
                    scratch_len,
                    @intFromPtr(backing.ptr),
                    backing.len,
                )) return false;
            if (current.cleanup.backing) |backing|
                if (rangesOverlap(
                    scratch_addr,
                    scratch_len,
                    @intFromPtr(backing.ptr),
                    backing.len,
                )) return false;
        }
        if (self.owned_client) |*owned| {
            var source_ranges: client_mod.ExternalSourceOwnerRangeScratch = .{};
            owned.preflightExternalAdoptionDestinationWithScratch(
                @constCast(cleanup_scratch),
                scratch_len,
                &source_ranges,
            ) catch return false;
        }
        return true;
    }

    fn selectedEventStillMatches(
        self: *const ExternalPumpStorage,
        selected: SelectedOwnerEvent,
        metadata_summary: external_event_materialization.MetadataStateSummary,
    ) bool {
        return switch (selected.key) {
            .resized => |key| self.owner_resize == .current and
                self.owner_resize.current.pending and
                self.owner_resize.current.event.resize_generation == key.generation and
                self.owner_resize.current.event.cols == key.cols and
                self.owner_resize.current.event.rows == key.rows,
            .metadata => |key| metadata_summary == .current and
                metadata_summary.current.pending and
                metadata_summary.current.revision == key.revision and
                std.mem.eql(
                    u8,
                    &self.owner_metadata.metadata.current.logical_seal.raw_digest,
                    &key.raw_digest,
                ) and std.mem.eql(
                u8,
                &self.owner_metadata.metadata.current.logical_seal.semantic_digest,
                &key.semantic_digest,
            ),
        };
    }

    fn resealOwnerResize(self: *ExternalPumpStorage) void {
        const current = &self.owner_resize.current;
        current.seal.pending = current.pending;
        current.seal.digest = ownerResizeDigest(current.seal);
    }

    fn finishProjectionWithTrustedTeardown(
        self: *ExternalPumpStorage,
        cleanup_scratch: *ExternalPumpCleanupScratch,
        permit: *OwnerEventPermit,
    ) ProjectOwnerEventResult {
        consumeOwnerEventPermit(permit);
        switch (self.teardownUnderHeldOperationLease(cleanup_scratch)) {
            .cleaned, .cleaned_with_invariant, .already_dead, .quarantined => {},
            .moved_storage, .transaction_busy => {
                _ = self.quarantineOwnerTeardown(cleanup_scratch, true);
            },
        }
        return .terminal_latched;
    }

    fn quarantineProjection(
        self: *ExternalPumpStorage,
        cleanup_scratch: *ExternalPumpCleanupScratch,
        scratch_trusted: bool,
    ) ProjectOwnerEventResult {
        _ = self.quarantineOwnerTeardown(cleanup_scratch, scratch_trusted);
        return .terminal_latched;
    }

    /// The sole product entry point for partial screen consumption. The process-thread lease
    /// prevents this no-callback two-owner commit from crossing adoption or teardown prepare.
    pub fn consumeScreenRetained(
        self: *ExternalPumpStorage,
        ordinal: usize,
    ) ScreenConsumeError!void {
        return self.consumeScreenRetainedBound(ordinal, false);
    }

    fn consumeScreenRetainedBound(
        self: *ExternalPumpStorage,
        ordinal: usize,
        allow_terminal_attachment_cleanup: bool,
    ) ScreenConsumeError!void {
        if (active_external_operation_addr != 0) return error.TransactionBusy;
        active_external_operation_addr = @intFromPtr(self);
        defer active_external_operation_addr = 0;
        if (allow_terminal_attachment_cleanup) {
            if (self.saved_self_addr != @intFromPtr(self)) return error.MovedStorage;
            if (self.lifecycle != .live) return error.NotActive;
            switch (self.semantic_state) {
                .active, .terminal => {},
                else => return error.NotActive,
            }
        } else try self.requireActive();
        const screen = &self.committed_screen;
        const ledger = &self.inbox_ledger;
        if (!screen.isCommitted(self) or
            screen.ledger_addr != @intFromPtr(ledger) or
            ordinal >= screen.tokens_len or screen.released.isSet(ordinal) or
            screen.retained_count == 0 or
            !self.screenPendingSummaryValid() or
            self.screen_pending_summary.generation == std.math.maxInt(u64))
            return error.InvalidRetirement;
        const transfer = screen.primary.transfer;
        const phase: external_inbox_ledger.PayloadPhase =
            switch (transfer.copies[ordinal].semantic) {
                .frame => .frame,
                .partial => .partial,
                .completed => .completed,
            };
        var prepared: external_inbox_ledger.PreparedScreenRetirement = .{};
        try ledger.prepareScreenRetirement(
            transfer.tokens[ordinal],
            phase,
            &prepared,
        );
        ledger.commitScreenRetirementUnchecked(&prepared);
        screen.released.set(ordinal);
        screen.retained_count -= 1;
        self.screen_pending_summary.retained_count = screen.retained_count;
        self.screen_pending_summary.generation += 1;
        self.screen_pending_summary.digest =
            screenPendingSummaryDigest(self.screen_pending_summary);
    }

    /// Returns the first complete inherited screen batch still charged to the stable ledger.
    /// Partial parser state deliberately stays pump-owned until the ordinary RX transaction turns
    /// it into a complete batch; it is never exposed as an attachment lease.
    pub fn nextAttachmentBatch(
        self: *ExternalPumpStorage,
        stream_id: u64,
    ) client_mod.ClientError!?external_inbox_ledger.Token {
        self.requireActive() catch |err| return switch (err) {
            error.TransactionBusy => error.AdminBusy,
            error.Terminal, error.Empty, error.NotActive, error.MovedStorage => error.ConnectionClosed,
            else => error.ProtocolError,
        };
        if (stream_id == 0 or stream_id != self.evidence_snapshot.stream_id or
            !self.screenPendingSummaryValid() or
            !self.committed_screen.isCommitted(self))
            return error.ProtocolError;
        if (self.attachment_lease != null) return error.AdminBusy;
        const screen = &self.committed_screen;
        const transfer = screen.primary.transfer;
        for (transfer.tokens, transfer.copies, 0..) |token, copy, ordinal| {
            if (screen.released.isSet(ordinal)) continue;
            switch (copy.semantic) {
                .completed => |semantic| {
                    if (semantic.stream_id != stream_id) return error.ProtocolError;
                    self.attachment_lease = token;
                    return token;
                },
                .frame, .partial => {},
            }
        }
        return null;
    }

    /// Borrows bytes behind a charged token without exposing the ledger itself.
    pub fn borrowAttachmentBatch(
        self: *ExternalPumpStorage,
        token: external_inbox_ledger.Token,
    ) external_inbox_ledger.InvariantError!ExternalAttachmentBatchView {
        self.requireActive() catch return error.InvariantFailure;
        if (self.attachment_lease == null or
            !std.meta.eql(self.attachment_lease.?, token))
            return error.InvariantFailure;
        if (!self.screenPendingSummaryValid() or
            !self.committed_screen.isCommitted(self))
            return error.InvariantFailure;
        const screen = &self.committed_screen;
        const transfer = screen.primary.transfer;
        for (transfer.tokens, transfer.copies, 0..) |candidate, copy, ordinal| {
            if (!std.meta.eql(candidate, token)) continue;
            if (screen.released.isSet(ordinal)) return error.InvariantFailure;
            const completed = switch (copy.semantic) {
                .completed => |semantic| semantic,
                .frame, .partial => return error.InvariantFailure,
            };
            const borrowed = try self.inbox_ledger.borrow(token, .completed);
            const observed = switch (borrowed.semantic) {
                .completed => |semantic| semantic,
                else => return error.InvariantFailure,
            };
            if (completed.stream_id != observed.stream_id or
                completed.is_snapshot != observed.is_snapshot)
                return error.InvariantFailure;
            const recovery_key = switch (observed.recovery_intent) {
                .none => null,
                .host, .client => blk: {
                    const identity = switch (observed.provenance) {
                        .untracked => return error.InvariantFailure,
                        .external => |range| range.identity,
                    };
                    break :blk observed.recovery_intent.key(
                        identity.attach_instance_id,
                        token.generation,
                    ) orelse return error.InvariantFailure;
                },
            };
            return .{
                .is_snapshot = observed.is_snapshot,
                .stream_id = observed.stream_id,
                .recovery_key = recovery_key,
                .bytes = borrowed.bytes,
            };
        }
        return error.InvariantFailure;
    }

    /// Retires exactly the charged token selected by `nextAttachmentBatch` through the existing
    /// screen-retirement transaction; no second ledger release implementation is introduced.
    pub fn releaseAttachmentBatch(
        self: *ExternalPumpStorage,
        token: external_inbox_ledger.Token,
    ) external_inbox_ledger.InvariantError!void {
        if (self.attachment_lease == null or
            !std.meta.eql(self.attachment_lease.?, token))
            return error.InvariantFailure;
        if (!self.committed_screen.isCommitted(self)) return error.InvariantFailure;
        for (self.committed_screen.primary.transfer.tokens, 0..) |candidate, ordinal| {
            if (!std.meta.eql(candidate, token)) continue;
            self.consumeScreenRetainedBound(ordinal, true) catch
                return error.InvariantFailure;
            self.attachment_lease = null;
            return;
        }
        return error.InvariantFailure;
    }

    pub fn dropAttachmentStream(self: *ExternalPumpStorage, stream_id: u64) void {
        while (self.nextAttachmentBatch(stream_id) catch null) |token| {
            self.releaseAttachmentBatch(token) catch {
                self.failAttachment(.attachment_cleanup_failed);
                return;
            };
        }
    }

    pub fn failAttachment(
        self: *ExternalPumpStorage,
        reason: @import("client_poison.zig").ConnectionReason,
    ) void {
        if (self.saved_self_addr != @intFromPtr(self) or self.lifecycle != .live) return;
        // The external owner, not `Client.poison`, owns final cleanup after adoption. Mutating the
        // committed Client independently would invalidate the sealed cleanup take and quarantine
        // otherwise recoverable storage. Latch the connection-fatal semantic here; teardown closes
        // the same Client only after the attachment returns its charged token.
        _ = reason;
        self.semantic_state = .{ .terminal = .{
            .reason = .invariant_failure,
            .fd_disposition = .owner_cleanup,
        } };
    }

    pub fn prepareAdoption(
        self: *ExternalPumpStorage,
        now_ns: i128,
        cleanup_scratch: *ExternalPumpCleanupScratch,
    ) AdoptionPrepareStatus {
        const cap_authority = snapshotRxResidentCapAuthority(self) orelse {
            if (!restoreRxResidentCapFromClient(self))
                return self.quarantineImmediateTerminal();
            return self.finishImmediateTerminal(
                .invariant_failure,
                cleanup_scratch,
            );
        };
        const result = self.prepareAdoptionInner(now_ns, cleanup_scratch);
        if (result == .terminal_latched or
            rxResidentCapAuthorityMatches(self, cap_authority))
            return result;
        if (!restoreRxResidentCapAuthority(self, cap_authority))
            return self.quarantineImmediateTerminal();
        if (result == .prepared_adopted)
            self.resetPreparedAdoption();
        return self.finishImmediateTerminal(
            .invariant_failure,
            cleanup_scratch,
        );
    }

    fn prepareAdoptionInner(
        self: *ExternalPumpStorage,
        now_ns: i128,
        cleanup_scratch: *ExternalPumpCleanupScratch,
    ) AdoptionPrepareStatus {
        if (cross_owner_quarantine_events.load(.acquire) != 0)
            return .terminal_latched;
        if (self.saved_self_addr != @intFromPtr(self))
            return .terminal_latched;
        if (active_external_operation_addr != 0)
            return .{ .retryable_preserved = .transaction_busy };
        if (cleanupScratchOverlapsStorage(self, cleanup_scratch))
            return self.quarantineImmediateTerminal();
        if (!cleanup_scratch.isReady())
            return self.quarantineImmediateTerminal();
        if (self.lifecycle != .adopting or self.semantic_state != .adopting or
            self.prepared_adoption.lifecycle != .empty)
            return self.quarantineImmediateTerminal();
        self.lifecycle = .adoption_preparing;
        active_external_operation_addr = @intFromPtr(self);
        defer {
            active_external_operation_addr = 0;
            if (self.lifecycle == .adoption_preparing)
                self.lifecycle = .adopting;
        }
        const client = if (self.owned_client) |*owned| owned else return self.finishImmediateTerminal(
            .invariant_failure,
            cleanup_scratch,
        );
        const owned_evidence = if (self.owned_evidence) |*owned| owned else return self.finishImmediateTerminal(
            .invariant_failure,
            cleanup_scratch,
        );
        if (!owned_evidence.validate(client) or
            !std.meta.eql(owned_evidence.attachment, self.evidence_snapshot))
            return self.quarantineImmediateTerminal();
        const seed_seal = owned_evidence.seed_seal orelse
            return self.quarantineImmediateTerminal();
        const cleanup_seed_seal = owned_evidence.cleanup_seed_seal orelse
            return self.quarantineImmediateTerminal();
        if ((seed_seal.backing_len != 0 and rangesOverlap(
            @intFromPtr(cleanup_scratch),
            @sizeOf(ExternalPumpCleanupScratch),
            seed_seal.backing_addr,
            seed_seal.backing_len,
        )) or (cleanup_seed_seal.backing_len != 0 and rangesOverlap(
            @intFromPtr(cleanup_scratch),
            @sizeOf(ExternalPumpCleanupScratch),
            cleanup_seed_seal.backing_addr,
            cleanup_seed_seal.backing_len,
        )))
            return self.quarantineImmediateTerminal();
        if (self.evidence_snapshot.runtime_id == 0 or
            self.evidence_snapshot.stream_id == 0)
            return self.finishImmediateTerminal(
                .protocol_error,
                cleanup_scratch,
            );
        const ledger_view = self.inbox_ledger.accountingView();
        if (!ledger_view.valid or !ledger_view.pristine_zero)
            return self.quarantineImmediateTerminal();
        const authority = prepareAuthority(client, self.evidence_snapshot) catch |err|
            return self.finishImmediateTerminal(
                terminalReasonForAuthorityError(err),
                cleanup_scratch,
            );
        const input = adoptionFoldInput(owned_evidence, authority) orelse
            return self.finishImmediateTerminal(
                .invariant_failure,
                cleanup_scratch,
            );
        var scratch: client_mod.ExternalSourceOwnerRangeScratch = .{};
        const fold = client.foldExternalAdoptionSource(
            input,
            &scratch,
        ) catch return self.finishImmediateTerminal(
            .invariant_failure,
            cleanup_scratch,
        );
        const decision = external_source_decision.decide(
            client,
            input,
            fold,
            &scratch,
        );
        var aggregate_source_ranges: client_mod.ExternalSourceOwnerRangeScratch = .{};
        client.preflightExternalAdoptionDestinationWithScratch(
            cleanup_scratch,
            @sizeOf(ExternalPumpCleanupScratch),
            &aggregate_source_ranges,
        ) catch |err| return switch (err) {
            error.InvalidAlias => self.quarantineImmediateTerminal(),
            else => self.finishImmediateTerminal(
                terminalReasonForDecision(decision),
                cleanup_scratch,
            ),
        };
        aggregate_source_ranges = .{};
        client.preflightExternalAdoptionDestinationWithScratch(
            &self.prepared_adoption,
            @sizeOf(PreparedExternalAdoption),
            &aggregate_source_ranges,
        ) catch |err| return switch (err) {
            error.InvalidAlias => self.quarantineImmediateTerminal(),
            else => self.finishImmediateTerminal(
                terminalReasonForDecision(decision),
                cleanup_scratch,
            ),
        };
        switch (decision.verdict) {
            .adopted => {},
            else => return self.finishNonAdopted(
                now_ns,
                input,
                decision,
                cleanup_scratch,
            ),
        }
        if (self.operation_generation == std.math.maxInt(u64))
            return self.finishImmediateTerminal(
                .invariant_failure,
                cleanup_scratch,
            );
        self.operation_generation += 1;
        // Only adopted owns this destination. Capture the source decision before the allocating
        // proof: an OOM callback may execute arbitrary code, and retry is permitted only if the
        // exact decision/evidence still match.
        client.preflightExternalAdoptionDestination(
            &self.prepared_adoption,
            @sizeOf(PreparedExternalAdoption),
        ) catch |err| return switch (err) {
            error.OutOfMemory => blk: {
                var retry_scratch: client_mod.ExternalSourceOwnerRangeScratch = .{};
                if (owned_evidence.validate(client) and
                    std.meta.eql(
                        owned_evidence.attachment,
                        self.evidence_snapshot,
                    ) and external_source_decision.decisionMatches(
                    client,
                    input,
                    decision,
                    &retry_scratch,
                ))
                    break :blk .{
                        .retryable_preserved = .out_of_memory,
                    };
                break :blk self.quarantineImmediateTerminal();
            },
            else => self.quarantineImmediateTerminal(),
        };
        self.prepared_adoption = .{
            .saved_self_addr = @intFromPtr(&self.prepared_adoption),
            .storage_addr = @intFromPtr(self),
            .client_addr = @intFromPtr(client),
            .ledger_addr = @intFromPtr(&self.inbox_ledger),
            .evidence = self.evidence_snapshot,
            .source_decision = decision,
            .branch = .adopted,
        };
        const metadata_status = external_event_materialization.prepareInPlace(
            &self.prepared_adoption.metadata,
            client.allocator,
            client,
            input,
            decision,
            &scratch,
        );
        const metadata_footprint = switch (metadata_status) {
            .prepared => |footprint| footprint,
            .retryable_preserved => {
                self.resetPreparedAdoption();
                return .{ .retryable_preserved = .out_of_memory };
            },
            .terminal => |reason| {
                self.resetPreparedAdoption();
                return self.finishImmediateTerminal(
                    switch (reason) {
                        .resource_exhausted => .resource_exhausted,
                        .inconsistent_source => .protocol_error,
                        .internal_invariant => .invariant_failure,
                    },
                    cleanup_scratch,
                );
            },
        };
        client_external_adoption.PreparedScreenBacklog.initInPlace(
            &self.prepared_adoption.backlog,
            client.allocator,
            client,
            &self.inbox_ledger,
            self.evidence_snapshot.stream_id,
        ) catch |err| {
            self.resetPreparedAdoption();
            return switch (err) {
                error.OutOfMemory => .{
                    .retryable_preserved = .out_of_memory,
                },
                else => self.finishImmediateTerminal(
                    terminalReasonForPrepareError(err),
                    cleanup_scratch,
                ),
            };
        };
        const aggregate = aggregateAdoptionFootprint(
            .{
                .resident = self.prepared_adoption.backlog.adoption_metadata_resident_bytes,
                .prepare_peak = self.prepared_adoption.backlog.adoption_metadata_prepare_peak_bytes,
            },
            metadata_footprint,
        ) catch {
            self.resetPreparedAdoption();
            return self.finishImmediateTerminal(
                .resource_exhausted,
                cleanup_scratch,
            );
        };
        client.sealExternalAdoption(
            &self.prepared_adoption.backlog.client_disarm,
        ) catch {
            self.resetPreparedAdoption();
            return self.finishImmediateTerminal(
                .invariant_failure,
                cleanup_scratch,
            );
        };
        self.prepared_adoption.aggregate_resident_bytes = aggregate.resident;
        self.prepared_adoption.aggregate_prepare_peak_bytes =
            aggregate.prepare_peak;
        self.prepared_adoption.lifecycle = .prepared;
        self.prepareOwnerScalarTakeAt(
            &self.prepared_adoption.scalar_take,
            .adoption_preparing,
            true,
        ) catch {
            self.resetPreparedAdoption();
            return self.finishImmediateTerminal(
                .invariant_failure,
                cleanup_scratch,
            );
        };
        self.prepared_adoption.backlog.prepareCommittedTake(
            &self.prepared_adoption.screen_take,
            &self.committed_screen,
            client,
            &self.inbox_ledger,
            self,
        ) catch {
            self.resetPreparedAdoption();
            return .terminal_latched;
        };
        external_event_materialization.prepareOwnerMetadataTake(
            &self.prepared_adoption.metadata_take,
            &self.prepared_adoption.metadata,
            &owned_evidence.seed,
            &owned_evidence.cleanup_seed,
            &self.owner_metadata,
            @intFromPtr(self),
        ) catch {
            self.resetPreparedAdoption();
            return .terminal_latched;
        };
        client.prepareExternalAdoptionTake(
            &self.prepared_adoption.backlog.client_disarm,
            &self.prepared_adoption.backlog.inventory,
            &self.prepared_adoption.backlog.cleanup_inventory,
            &self.client_cleanup_take,
        ) catch |err| {
            const source_unchanged =
                self.validatePreparedSources(.adoption_preparing);
            self.resetPreparedAdoption();
            return switch (err) {
                error.OutOfMemory => if (source_unchanged)
                    .{ .retryable_preserved = .out_of_memory }
                else
                    self.finishImmediateTerminal(
                        .invariant_failure,
                        cleanup_scratch,
                    ),
                error.InvalidPlan, error.StaleClient => self.finishImmediateTerminal(
                    .invariant_failure,
                    cleanup_scratch,
                ),
            };
        };
        self.prepareFinalSeal() catch {
            self.resetPreparedAdoption();
            return self.finishImmediateTerminal(
                .invariant_failure,
                cleanup_scratch,
            );
        };
        if (!self.prepared_adoption.validateWhilePreparing(self)) {
            self.resetPreparedAdoption();
            return self.finishImmediateTerminal(
                .invariant_failure,
                cleanup_scratch,
            );
        }
        self.lifecycle = .adopting;
        return .prepared_adopted;
    }

    fn finishNonAdopted(
        self: *ExternalPumpStorage,
        now_ns: i128,
        input: client_mod.ExternalAdoptionFoldInput,
        decision: external_source_decision.PreparedSourceDecision,
        cleanup_scratch: *ExternalPumpCleanupScratch,
    ) AdoptionPrepareStatus {
        const client = if (self.owned_client) |*owned| owned else return self.finishImmediateTerminal(.invariant_failure, cleanup_scratch);
        cleanup_scratch.range_scratch.source = .{};
        client.prepareExternalRecoveryDiscard(
            self.evidence_snapshot.stream_id,
            &cleanup_scratch.client,
            &cleanup_scratch.range_scratch.source,
            &cleanup_scratch.recovery_discard,
        ) catch {
            return self.finishImmediateTerminal(
                terminalReasonForDecision(decision),
                cleanup_scratch,
            );
        };
        cleanup_scratch.range_scratch.source = .{};
        if (!external_source_decision.decisionMatches(
            client,
            input,
            decision,
            &cleanup_scratch.range_scratch.source,
        ) or !client.validateExternalRecoveryDiscard(
            &cleanup_scratch.recovery_discard,
            &cleanup_scratch.client,
        )) {
            cleanup_scratch.resetReady();
            return self.quarantineImmediateTerminal();
        }

        return switch (decision.verdict) {
            .host_recovery => self.commitImmediateRecovery(
                now_ns,
                input.authority,
                decision,
                .host,
                cleanup_scratch,
            ),
            .client_recovery => self.commitImmediateRecovery(
                now_ns,
                input.authority,
                decision,
                .client,
                cleanup_scratch,
            ),
            .terminal, .ended, .revoked => self.finishImmediateTerminal(
                terminalReasonForDecision(decision),
                cleanup_scratch,
            ),
            .adopted => self.finishImmediateTerminal(
                .invariant_failure,
                cleanup_scratch,
            ),
        };
    }

    fn commitImmediateRecovery(
        self: *ExternalPumpStorage,
        now_ns: i128,
        authority: client_mod.FoldAuthority,
        decision: external_source_decision.PreparedSourceDecision,
        origin: client_pump.RecoveryOrigin,
        cleanup_scratch: *ExternalPumpCleanupScratch,
    ) AdoptionPrepareStatus {
        const deadline_ns = std.math.add(
            i128,
            now_ns,
            30 * @as(i128, std.time.ns_per_s),
        ) catch {
            return self.finishImmediateTerminal(
                .invariant_failure,
                cleanup_scratch,
            );
        };
        const request_state = decision.request_state orelse {
            return self.finishImmediateTerminal(
                .request_id_exhausted,
                cleanup_scratch,
            );
        };
        const client = if (self.owned_client) |*owned| owned else {
            return self.finishImmediateTerminal(
                .invariant_failure,
                cleanup_scratch,
            );
        };
        const metadata_support = client.metadata_support;
        const storage_addr = @intFromPtr(self);
        const evidence_snapshot = self.evidence_snapshot;
        const ledger_snapshot = self.inbox_ledger;
        var evidence: PreparedAdoptionEvidence = .{};
        const owned_evidence = if (self.owned_evidence) |*owned| owned else return self.finishImmediateTerminal(.invariant_failure, cleanup_scratch);
        const owner_incarnation = owned_evidence.attach_instance_id;
        owned_evidence.moveInto(&evidence, client);
        self.owned_evidence = null;
        var frozen_client = client.*;
        self.owned_client = null;
        var frozen_transfer = self.client_transfer;
        self.client_transfer = .{};
        cleanup_scratch.lifecycle = .frozen;
        self.semantic_state = .{ .active = switch (origin) {
            .host => .{ .host_recovery = .{ .ack_unadmitted = .{
                .epoch = 1,
                .deadline_ns = deadline_ns,
            } } },
            .client => .{ .client_recovery = .{ .control_wait = .{
                .epoch = 1,
                .deadline_ns = deadline_ns,
            } } },
        } };
        self.owner_resize = .none;
        self.owner_authority = .{ .current = .{
            .role = switch (authority.role) {
                .observer => .observer,
                .controller => .controller,
            },
            .generation = switch (authority.generation) {
                .untracked => .untracked,
                .tracked => |generation| .{ .tracked = generation },
            },
            .flow = .initial_fence,
        } };
        self.owner_request_ids = request_state;
        self.prepared_adoption = .{ .lifecycle = .committed_tombstone };

        consumeFrozenClientQueues(&frozen_client, cleanup_scratch);
        evidence.deinit();
        frozen_transfer.deinit();
        // Allocator callbacks may mutate the published storage directly. Restore every scalar and
        // owner header from callback-hidden locals before making the recovered transport live.
        self.saved_self_addr = storage_addr;
        self.evidence_snapshot = evidence_snapshot;
        self.inbox_ledger = ledger_snapshot;
        self.owned_client = frozen_client;
        self.owned_evidence = null;
        self.client_transfer = .{};
        self.prepared_adoption = .{ .lifecycle = .committed_tombstone };
        self.client_cleanup_take = .{};
        self.committed_screen = .{};
        self.live_partial = .none;
        self.live_screen = .{};
        self.completed_control = .none;
        self.owner_metadata = .{};
        if (!external_event_materialization.commitRecoveryBaseline(
            &self.owner_metadata,
            storage_addr,
            @intFromPtr(&self.evidence_snapshot),
            metadata_support,
        ))
            return self.quarantineImmediateTerminal();
        self.semantic_state = .{ .active = switch (origin) {
            .host => .{ .host_recovery = .{ .ack_unadmitted = .{
                .epoch = 1,
                .deadline_ns = deadline_ns,
            } } },
            .client => .{ .client_recovery = .{ .control_wait = .{
                .epoch = 1,
                .deadline_ns = deadline_ns,
            } } },
        } };
        self.owner_resize = .none;
        self.owner_authority = .{ .current = .{
            .role = switch (authority.role) {
                .observer => .observer,
                .controller => .controller,
            },
            .generation = switch (authority.generation) {
                .untracked => .untracked,
                .tracked => |generation| .{ .tracked = generation },
            },
            .flow = .initial_fence,
        } };
        self.owner_request_ids = request_state;
        bindOwnerIncarnation(self, owner_incarnation);
        bindOwnerAuthority(self);
        self.owner_event_projection_generation = 0;
        self.lifecycle = .live;
        cleanup_scratch.resetReady();
        return .recovery_committed;
    }

    fn finishImmediateTerminal(
        self: *ExternalPumpStorage,
        reason: client_pump.TerminalReason,
        cleanup_scratch: *ExternalPumpCleanupScratch,
    ) AdoptionPrepareStatus {
        if (cleanup_scratch.recovery_discard.isEmpty()) {
            const client = if (self.owned_client) |*owned| owned else return self.quarantineImmediateTerminal();
            cleanup_scratch.range_scratch.source = .{};
            client.prepareExternalRecoveryDiscard(
                self.evidence_snapshot.stream_id,
                &cleanup_scratch.client,
                &cleanup_scratch.range_scratch.source,
                &cleanup_scratch.recovery_discard,
            ) catch return self.quarantineImmediateTerminal();
        }
        const terminal_client = if (self.owned_client) |*client| client else return self.quarantineImmediateTerminalReason(reason);
        if (cleanup_scratch.recovery_discard.lifecycle != .prepared or
            !terminal_client.validateExternalRecoveryDiscard(
                &cleanup_scratch.recovery_discard,
                &cleanup_scratch.client,
            ))
            return self.quarantineImmediateTerminalReason(reason);
        self.lifecycle = .tearing_down;
        self.semantic_state = .{ .terminal = .{
            .reason = reason,
            .fd_disposition = .owner_cleanup,
        } };
        const storage_addr = @intFromPtr(self);
        const evidence_snapshot = self.evidence_snapshot;
        const ledger_snapshot = self.inbox_ledger;
        var evidence: PreparedAdoptionEvidence = .{};
        const owned_evidence = if (self.owned_evidence) |*owned| owned else return self.quarantineImmediateTerminalReason(reason);
        owned_evidence.moveInto(&evidence, terminal_client);
        self.owned_evidence = null;
        var frozen_client = terminal_client.*;
        self.owned_client = null;
        var frozen_transfer = self.client_transfer;
        self.client_transfer = .{};
        self.prepared_adoption = .{};
        self.client_cleanup_take = .{ .lifecycle = .aborted };
        cleanup_scratch.lifecycle = .frozen;
        consumeFrozenClientQueues(&frozen_client, cleanup_scratch);
        frozen_client.deinit();
        evidence.deinit();
        frozen_transfer.deinit();
        // Nothing below invokes an allocator callback. Overwrite any direct callback mutation
        // before publishing the terminal lifecycle.
        self.saved_self_addr = storage_addr;
        self.evidence_snapshot = evidence_snapshot;
        self.inbox_ledger = ledger_snapshot;
        self.owned_client = null;
        self.owned_evidence = null;
        self.client_transfer = .{};
        self.prepared_adoption = .{};
        self.client_cleanup_take = .{ .lifecycle = .aborted };
        self.committed_screen = .{};
        self.live_partial = .terminal;
        self.live_screen = .{ .lifecycle = .cleaned_tombstone };
        self.completed_control = .terminal;
        self.intent_scratch_reservation = .{
            .lifecycle = .poisoned_tombstone,
        };
        self.owner_metadata = .{};
        self.owner_resize = .none;
        self.owner_authority = .empty;
        self.owner_request_ids = null;
        self.owner_incarnation = 0;
        self.owner_incarnation_seal = .{};
        self.owner_event_projection_generation = 0;
        self.semantic_state = .{ .terminal = .{
            .reason = reason,
            .fd_disposition = .owner_cleanup,
        } };
        _ = self.inbox_ledger.finish() catch {};
        self.lifecycle = .dead;
        releaseActiveStorage(@intFromPtr(self));
        cleanup_scratch.resetReady();
        return .terminal_latched;
    }

    fn quarantineImmediateTerminal(
        self: *ExternalPumpStorage,
    ) AdoptionPrepareStatus {
        return self.quarantineImmediateTerminalReason(.invariant_failure);
    }

    fn quarantineImmediateTerminalReason(
        self: *ExternalPumpStorage,
        reason: client_pump.TerminalReason,
    ) AdoptionPrepareStatus {
        self.lifecycle = .tearing_down;
        self.semantic_state = .{ .terminal = .{
            .reason = reason,
            .fd_disposition = .owner_cleanup,
        } };
        latchCrossOwnerQuarantine();
        self.prepared_adoption = .{ .lifecycle = .aborted_tombstone };
        self.client_cleanup_take = .{ .lifecycle = .aborted };
        self.owned_client = null;
        self.owned_evidence = null;
        self.owner_resize = .none;
        self.owner_authority = .empty;
        self.owner_request_ids = null;
        self.owner_incarnation = 0;
        self.owner_incarnation_seal = .{};
        self.owner_event_projection_generation = 0;
        self.lifecycle = .dead;
        releaseActiveStorage(@intFromPtr(self));
        return .terminal_latched;
    }

    pub fn prepareOwnerScalarTake(
        self: *ExternalPumpStorage,
        out: *PreparedOwnerScalarTake,
    ) error{InvalidOwnerTake}!void {
        return self.prepareOwnerScalarTakeAt(out, .adopting, false);
    }

    fn prepareOwnerScalarTakeAt(
        self: *ExternalPumpStorage,
        out: *PreparedOwnerScalarTake,
        expected_lifecycle: StorageLifecycle,
        embedded: bool,
    ) error{InvalidOwnerTake}!void {
        const pre_take_valid = self.prepared_adoption.validateForStorageLifecycle(
            self,
            expected_lifecycle,
            .before_takes,
        );
        if (!std.meta.eql(out.*, PreparedOwnerScalarTake{}) or
            (!embedded and rangesOverlap(
                @intFromPtr(out),
                @sizeOf(PreparedOwnerScalarTake),
                @intFromPtr(self),
                @sizeOf(ExternalPumpStorage),
            )) or
            (embedded and
                @intFromPtr(out) !=
                    @intFromPtr(&self.prepared_adoption.scalar_take)) or
            self.owner_authority != .empty or self.owner_request_ids != null or
            !pre_take_valid)
            return error.InvalidOwnerTake;
        const decision = self.prepared_adoption.source_decision orelse
            return error.InvalidOwnerTake;
        const live = switch (decision.verdict) {
            .adopted => |adopted| adopted,
            else => return error.InvalidOwnerTake,
        };
        out.* = .{
            .saved_self_addr = @intFromPtr(out),
            .prepared_addr = @intFromPtr(&self.prepared_adoption),
            .storage_addr = @intFromPtr(self),
            .resize_addr = @intFromPtr(&self.owner_resize),
            .authority_addr = @intFromPtr(&self.owner_authority),
            .request_addr = @intFromPtr(&self.owner_request_ids),
            .resize = if (live.resize) |candidate| candidate.event else null,
            .authority = .{ .current = .{
                .role = switch (live.authority.role) {
                    .observer => .observer,
                    .controller => .controller,
                },
                .generation = switch (live.authority.generation) {
                    .untracked => .untracked,
                    .tracked => |generation| .{ .tracked = generation },
                },
                .flow = .initial_fence,
            } },
            .request_ids = decision.request_state orelse return error.InvalidOwnerTake,
            .lifecycle = .prepared,
        };
        if (!out.validate(self)) {
            out.* = .{ .lifecycle = .aborted_tombstone };
            return error.InvalidOwnerTake;
        }
    }

    fn validatePreparedSources(
        self: *const ExternalPumpStorage,
        expected_lifecycle: StorageLifecycle,
    ) bool {
        const plan = &self.prepared_adoption;
        if (self.saved_self_addr != @intFromPtr(self) or
            self.lifecycle != expected_lifecycle or
            self.semantic_state != .adopting or
            plan.lifecycle != .prepared or
            plan.saved_self_addr != @intFromPtr(plan) or
            plan.storage_addr != @intFromPtr(self) or
            plan.ledger_addr != @intFromPtr(&self.inbox_ledger) or
            plan.branch != .adopted)
            return false;
        const client = if (self.owned_client) |*owned| owned else return false;
        const evidence = if (self.owned_evidence) |*owned| owned else return false;
        if (plan.client_addr != @intFromPtr(client) or
            !evidence.validate(client) or
            !std.meta.eql(plan.evidence, self.evidence_snapshot))
            return false;
        const authority = prepareAuthority(client, self.evidence_snapshot) catch
            return false;
        const input = adoptionFoldInput(evidence, authority) orelse return false;
        const decision = plan.source_decision orelse return false;
        var scratch: client_mod.ExternalSourceOwnerRangeScratch = .{};
        if (!external_source_decision.decisionMatches(
            client,
            input,
            decision,
            &scratch,
        ) or decision.verdict != .adopted or
            !plan.backlog.validate(client, &self.inbox_ledger))
            return false;
        const metadata_footprint = plan.metadata.footprint(
            client,
            input,
            decision,
            &scratch,
        ) orelse return false;
        const aggregate = aggregateAdoptionFootprint(
            .{
                .resident = plan.backlog.adoption_metadata_resident_bytes,
                .prepare_peak = plan.backlog.adoption_metadata_prepare_peak_bytes,
            },
            metadata_footprint,
        ) catch return false;
        return plan.aggregate_resident_bytes == aggregate.resident and
            plan.aggregate_prepare_peak_bytes == aggregate.prepare_peak;
    }

    fn prepareFinalSeal(
        self: *ExternalPumpStorage,
    ) error{InvalidCommitPermit}!void {
        const final_seal = &self.prepared_adoption.final_seal;
        if (!std.meta.eql(final_seal.*, PreparedAdoptionFinalSeal{}))
            return error.InvalidCommitPermit;
        final_seal.* = self.expectedFinalSeal();
        if (!self.validateFinalSeal()) {
            final_seal.abort();
            return error.InvalidCommitPermit;
        }
    }

    fn expectedFinalSeal(
        self: *const ExternalPumpStorage,
    ) PreparedAdoptionFinalSeal {
        const plan = &self.prepared_adoption;
        var result = PreparedAdoptionFinalSeal{
            .saved_self_addr = @intFromPtr(&plan.final_seal),
            .storage_addr = @intFromPtr(self),
            .plan_addr = @intFromPtr(plan),
            .client_addr = if (self.owned_client) |*client|
                @intFromPtr(client)
            else
                0,
            .ledger_addr = @intFromPtr(&self.inbox_ledger),
            .evidence_addr = if (self.owned_evidence) |*evidence|
                @intFromPtr(evidence)
            else
                0,
            .client_cleanup_take_addr = @intFromPtr(&self.client_cleanup_take),
            .screen_take_addr = @intFromPtr(&plan.screen_take),
            .metadata_take_addr = @intFromPtr(&plan.metadata_take),
            .scalar_take_addr = @intFromPtr(&plan.scalar_take),
            .committed_screen_addr = @intFromPtr(&self.committed_screen),
            .screen_pending_summary_addr = @intFromPtr(&self.screen_pending_summary),
            .owner_metadata_addr = @intFromPtr(&self.owner_metadata),
            .metadata_pending_summary_addr = @intFromPtr(&self.metadata_pending_summary),
            .owner_resize_addr = @intFromPtr(&self.owner_resize),
            .owner_authority_addr = @intFromPtr(&self.owner_authority),
            .owner_request_ids_addr = @intFromPtr(&self.owner_request_ids),
            .operation_generation = self.operation_generation,
            .lifecycle = .prepared,
        };
        result.digest = adoptionFinalSealDigest(self, &result);
        return result;
    }

    fn validateFinalSeal(self: *const ExternalPumpStorage) bool {
        const plan = &self.prepared_adoption;
        const final_seal = &plan.final_seal;
        if (!self.validatePreparedSources(self.lifecycle)) {
            return false;
        }
        const expected_final_seal = self.expectedFinalSeal();
        if (!std.meta.eql(final_seal.*, expected_final_seal)) {
            return false;
        }
        if (self.operation_generation == 0 or
            !self.committed_screen.isEmpty() or
            self.live_partial != .none or
            !std.meta.eql(self.live_screen, LiveScreenBacklog{}) or
            self.completed_control != .none or
            !std.meta.eql(self.screen_pending_summary, ScreenPendingSummarySeal{}) or
            !self.owner_metadata.isEmpty() or
            !std.meta.eql(self.metadata_pending_summary, MetadataPendingSummarySeal{}) or
            self.owner_resize != .none or
            self.owner_authority != .empty or
            !std.meta.eql(self.owner_authority_seal, OwnerAuthoritySeal{}) or
            self.owner_request_ids != null or
            self.owner_incarnation != 0 or
            !std.meta.eql(self.owner_incarnation_seal, OwnerIncarnationSeal{}) or
            self.owner_event_projection_generation != 0)
            return false;
        const client = if (self.owned_client) |*owned| owned else return false;
        const evidence = if (self.owned_evidence) |*owned| owned else return false;
        if (!commitHeadersPairwiseDisjoint(self)) return false;
        const ranges = commitHeaderRanges(self, client, evidence);
        var source_ranges: client_mod.ExternalSourceOwnerRangeScratch = .{};
        for (ranges) |range| {
            if (range.addr != @intFromPtr(client))
                client.preflightExternalAdoptionDestinationWithScratch(
                    @ptrFromInt(range.addr),
                    range.len,
                    &source_ranges,
                ) catch return false;
            if (plan.backlog.overlapsOwnedBacking(range.addr, range.len) or
                external_event_materialization.preparedMetadataOverlapsOwnedBacking(
                    &plan.metadata,
                    &evidence.seed,
                    &evidence.cleanup_seed,
                    range.addr,
                    range.len,
                ))
                return false;
        }
        if (plan.metadata_take.primary_seal) |seal| {
            if (seal.backing_len != 0 and
                plan.backlog.overlapsOwnedBacking(
                    seal.backing_addr,
                    seal.backing_len,
                ))
                return false;
            if (seal.backing_len != 0)
                client.preflightExternalAdoptionDestinationWithScratch(
                    @ptrFromInt(seal.backing_addr),
                    seal.backing_len,
                    &source_ranges,
                ) catch return false;
        }
        if (!plan.screen_take.validate(
            &plan.backlog,
            &self.committed_screen,
            client,
            &self.inbox_ledger,
            self,
        ) or !plan.metadata_take.validate(
            &plan.metadata,
            &evidence.seed,
            &evidence.cleanup_seed,
            &self.owner_metadata,
            @intFromPtr(self),
        ) or !plan.scalar_take.validate(self) or
            !self.client_cleanup_take.validate(
                client,
                &plan.backlog.client_disarm,
                &plan.backlog.inventory,
                &plan.backlog.cleanup_inventory,
            ))
            return false;
        if (!adoptionOwnerBackingsPairwiseDisjoint(
            plan,
            client,
            evidence,
            &source_ranges,
        ))
            return false;
        return commitHeadersPairwiseDisjoint(self);
    }

    fn mintAdoptedCommitPermit(
        self: *const ExternalPumpStorage,
        out: *AdoptedCommitPermit,
    ) bool {
        if (!std.meta.eql(out.*, AdoptedCommitPermit{}) or
            rangesOverlap(
                @intFromPtr(out),
                @sizeOf(AdoptedCommitPermit),
                @intFromPtr(self),
                @sizeOf(ExternalPumpStorage),
            ) or !self.validateFinalSeal())
            return false;
        out.* = .{
            .saved_self_addr = @intFromPtr(out),
            .storage_addr = @intFromPtr(self),
            .operation_generation = self.operation_generation,
            .final_seal_digest = self.prepared_adoption.final_seal.digest,
        };
        return true;
    }

    fn commitOwnerScalarTakeUnchecked(
        self: *ExternalPumpStorage,
        take: *PreparedOwnerScalarTake,
    ) void {
        if (take.resize) |event|
            bindOwnerResize(self, event)
        else
            self.owner_resize = .none;
        self.owner_authority = take.authority;
        self.owner_request_ids = take.request_ids;
        take.* = .{ .lifecycle = .committed_tombstone };
    }

    pub fn commitAdoption(
        self: *ExternalPumpStorage,
    ) CommitAdoptionResult {
        var recorder: NoopCommitRecorder = .{};
        return self.commitAdoptionWithRecorder(NoopCommitRecorder, &recorder);
    }

    /// Completes the final-address adoption fence after the already-decoded initial snapshot and
    /// its `RemoteAttachment` have both moved into the same product owner. Until this exact point,
    /// input and control admission remain forbidden even though storage adoption is committed.
    pub fn commitBoundInitialAttachment(self: *ExternalPumpStorage, stream_id: u64) bool {
        if (active_external_operation_addr != 0 or
            self.saved_self_addr != @intFromPtr(self) or
            self.lifecycle != .live or
            self.semantic_state != .active or
            self.semantic_state.active != .valid or
            stream_id == 0 or stream_id != self.evidence_snapshot.stream_id or
            !ownerAuthorityValid(self))
            return false;
        active_external_operation_addr = @intFromPtr(self);
        defer active_external_operation_addr = 0;
        const authority = switch (self.owner_authority) {
            .current => |*value| value,
            .empty => return false,
        };
        if (authority.flow != .initial_fence) return false;
        authority.flow = .clear;
        bindOwnerAuthority(self);
        return ownerAuthorityValid(self);
    }

    fn commitAdoptionWithRecorder(
        self: *ExternalPumpStorage,
        comptime Recorder: type,
        recorder: *Recorder,
    ) CommitAdoptionResult {
        if (active_external_operation_addr != 0)
            return .transaction_busy;
        if (self.saved_self_addr != @intFromPtr(self) or
            self.lifecycle == .empty or self.lifecycle == .dead or
            self.lifecycle == .live)
            return .dead;
        if (self.lifecycle != .adopting or self.semantic_state != .adopting)
            return self.latchCommitTerminal();
        if (!rxResidentCapOwnerValid(self)) {
            _ = restoreRxResidentCapFromClient(self);
            return self.latchCommitTerminal();
        }
        const cap_authority =
            snapshotRxResidentCapAuthority(self) orelse
            return self.latchCommitTerminal();

        active_external_operation_addr = @intFromPtr(self);
        defer active_external_operation_addr = 0;
        if (cross_owner_quarantine_events.load(.acquire) != 0)
            return self.latchCommitTerminal();
        const client = if (self.owned_client) |*owned| owned else return self.latchCommitTerminal();
        const evidence = if (self.owned_evidence) |*owned| owned else return self.latchCommitTerminal();
        const plan = &self.prepared_adoption;
        // Failure injection is test-only and runs before the final validation/permit mint. Once
        // the permit exists, no generic recorder receives a mutable sealed owner graph.
        recorder.beforePermit(&plan.backlog, &self.inbox_ledger);
        if (!rxResidentCapAuthorityMatches(self, cap_authority)) {
            if (!restoreRxResidentCapAuthority(self, cap_authority))
                latchCrossOwnerQuarantine();
            return self.latchCommitTerminal();
        }
        var source_ranges: client_mod.ExternalSourceOwnerRangeScratch = .{};
        const owner_backings_disjoint = self.validatedOwnerBackingDisjointness(
            client,
            evidence,
            &source_ranges,
        ) orelse return self.latchCommitTerminal();
        if (!owner_backings_disjoint)
            return self.latchCrossOwnerAliasTerminal();
        var permit: AdoptedCommitPermit = .{};
        if (!self.mintAdoptedCommitPermit(&permit))
            return self.latchCommitTerminal();
        // This is the final fallible precommit. The thread-wide lease stays published through any
        // terminal cleanup. Seed-plan retirement is deferred so the ledger-to-live suffix itself
        // contains no allocator callback.
        var seed_retirement: external_inbox_ledger.PreparedSeedRetirement = .{};
        plan.backlog.commitScreenSeeds(
            client,
            &self.inbox_ledger,
            &seed_retirement,
        ) catch return self.latchCommitTerminal();
        recorder.record(.ledger_seed);

        self.commitAdoptionUnchecked(
            Recorder,
            recorder,
            &permit,
            client,
            evidence,
            plan,
        );
        seed_retirement.retire();
        if (!rxResidentCapAuthorityMatches(self, cap_authority)) {
            if (!restoreRxResidentCapAuthority(self, cap_authority))
                latchCrossOwnerQuarantine();
            self.saved_self_addr = @intFromPtr(self);
            self.lifecycle = .live;
            self.semantic_state = .{ .terminal = .{
                .reason = .invariant_failure,
                .fd_disposition = .owner_cleanup,
            } };
            return .terminal_latched;
        }
        return .adopted;
    }

    fn validatedOwnerBackingDisjointness(
        self: *const ExternalPumpStorage,
        client: *const client_mod.Client,
        evidence: *const PreparedAdoptionEvidence,
        scratch: *client_mod.ExternalSourceOwnerRangeScratch,
    ) ?bool {
        const plan = &self.prepared_adoption;
        // Every outer slice/header authority is validated before the global proof enumerates a
        // nested screen or metadata element. `null` means another leaf is invalid; the ordinary
        // final-seal rejection path then selects its independently sealed cleanup mirror.
        if (!plan.screen_take.validateOuterTransferDescriptors(&plan.backlog))
            return null;
        const owner_backings_disjoint = adoptionOwnerBackingsPairwiseDisjoint(
            plan,
            client,
            evidence,
            scratch,
        );
        if (!owner_backings_disjoint) return false;
        if (!plan.screen_take.validate(
            &plan.backlog,
            &self.committed_screen,
            client,
            &self.inbox_ledger,
            self,
        ) or !plan.metadata_take.validate(
            &plan.metadata,
            &evidence.seed,
            &evidence.cleanup_seed,
            &self.owner_metadata,
            @intFromPtr(self),
        ) or !plan.scalar_take.validate(self) or
            !self.client_cleanup_take.validate(
                client,
                &plan.backlog.client_disarm,
                &plan.backlog.inventory,
                &plan.backlog.cleanup_inventory,
            ))
            return null;
        return true;
    }

    fn commitAdoptionUnchecked(
        self: *ExternalPumpStorage,
        comptime Recorder: type,
        recorder: *Recorder,
        permit: *AdoptedCommitPermit,
        client: *client_mod.Client,
        evidence: *PreparedAdoptionEvidence,
        plan: *PreparedExternalAdoption,
    ) void {
        // `mintAdoptedCommitPermit` is the only caller and the ledger barrier has already
        // succeeded. Consume the linear permit before touching the first destination so it cannot
        // authorize a second suffix. No validation or failure branch is permitted from here on.
        permit.consumed = true;

        // The order is part of the c3c-2b2 linearization contract; none of these mechanics
        // allocates, invokes callbacks, validates, returns an error, or panics.
        plan.backlog.commitIntoUnchecked(
            &plan.screen_take,
            &self.committed_screen,
        );
        recorder.record(.screen_destination);
        external_event_materialization.commitOwnerMetadataTakeUnchecked(
            &plan.metadata_take,
            &plan.metadata,
            &evidence.seed,
            &evidence.cleanup_seed,
            &self.owner_metadata,
        );
        recorder.record(.metadata_destination);
        bindOwnerIncarnation(self, evidence.attach_instance_id);
        self.commitOwnerScalarTakeUnchecked(&plan.scalar_take);
        bindOwnerAuthority(self);
        bindInitialControlCorrelation(self);
        self.bindPendingSummaries();
        self.owner_event_projection_generation = 0;
        recorder.record(.scalar_destination);
        client_mod.commitExternalAdoptionTakeUnchecked(
            client,
            &plan.backlog.client_disarm,
            &plan.backlog.inventory,
            &plan.backlog.cleanup_inventory,
            &self.client_cleanup_take,
        );
        recorder.record(.client_cleanup_take);
        plan.* = .{ .lifecycle = .committed_tombstone };
        recorder.record(.prepared_tombstone);
        self.semantic_state = .{ .active = .valid };
        recorder.record(.semantic_active);
        self.lifecycle = .live;
        recorder.record(.lifecycle_live);
    }

    fn latchCommitTerminal(
        self: *ExternalPumpStorage,
    ) CommitAdoptionResult {
        // No ledger ownership was published. Draining a pristine ledger would itself advance its
        // mutation epoch and would make a rejected final seal observable as a partial commit.
        const prior_lifecycle = self.lifecycle;
        const prior_semantic_state = self.semantic_state;
        self.lifecycle = .tearing_down;
        self.semantic_state = .{ .terminal = .{
            .reason = .invariant_failure,
            .fd_disposition = .owner_cleanup,
        } };
        if (self.owned_client) |*owned|
            if (owned.reserveExternalModeDeinit() == .busy) {
                self.lifecycle = prior_lifecycle;
                self.semantic_state = prior_semantic_state;
                return .transaction_busy;
            };
        self.resetPreparedAdoption();
        if (self.owned_client) |*owned| {
            if (!owned.finishReservedExternalModeDeinit())
                @panic("reserved external Client cleanup was not consumable");
            owned.deinit();
        }
        self.owned_client = null;
        if (self.owned_evidence) |*owned| owned.deinit();
        self.owned_evidence = null;
        self.client_transfer.deinit();
        self.owner_resize = .none;
        self.owner_authority = .empty;
        self.owner_request_ids = null;
        _ = self.inbox_ledger.finish() catch {};
        self.lifecycle = .dead;
        releaseActiveStorage(@intFromPtr(self));
        return .terminal_latched;
    }

    fn latchCrossOwnerAliasTerminal(
        self: *ExternalPumpStorage,
    ) CommitAdoptionResult {
        // Once two independently freed owner graphs name the same backing, neither prepared graph
        // is a trustworthy cleanup authority. Quarantine both prepared graphs rather than invoking
        // either allocator through attacker-controlled mirrors. The original Client remains the
        // canonical source owner and is the only graph reclaimed here. This bounded corruption
        // leak is preferable to an arbitrary or double free and is observable as a terminal
        // invariant failure.
        const prior_lifecycle = self.lifecycle;
        const prior_semantic_state = self.semantic_state;
        self.lifecycle = .tearing_down;
        self.semantic_state = .{ .terminal = .{
            .reason = .invariant_failure,
            .fd_disposition = .owner_cleanup,
        } };
        if (self.owned_client) |*owned|
            if (owned.reserveExternalModeDeinit() == .busy) {
                self.lifecycle = prior_lifecycle;
                self.semantic_state = prior_semantic_state;
                return .transaction_busy;
            };
        latchCrossOwnerQuarantine();
        self.prepared_adoption = .{ .lifecycle = .aborted_tombstone };
        self.client_cleanup_take = .{ .lifecycle = .aborted };
        if (self.owned_client) |*owned| {
            if (!owned.finishReservedExternalModeDeinit())
                @panic("reserved external Client cleanup was not consumable");
            owned.deinit();
        }
        self.owned_client = null;
        self.owned_evidence = null;
        self.client_transfer.deinit();
        self.owner_resize = .none;
        self.owner_authority = .empty;
        self.owner_request_ids = null;
        _ = self.inbox_ledger.finish() catch {};
        self.lifecycle = .dead;
        releaseActiveStorage(@intFromPtr(self));
        return .terminal_latched;
    }

    fn resetPreparedAdoption(self: *ExternalPumpStorage) void {
        if (self.client_cleanup_take.requiresTypedCleanup()) {
            // A forged/moved committed tag must never reach generic deinit, which requires the
            // aggregate scratch and would panic without it. The source owners are still intact on
            // every pre-ledger failure, so clean those and leave the untrusted mirror inert.
            self.prepared_adoption.deinit(if (self.owned_client) |*owned|
                owned.allocator
            else
                null);
            self.prepared_adoption = .{};
            return;
        }
        self.client_cleanup_take.deinit();
        self.client_cleanup_take = .{};
        self.prepared_adoption.deinit(if (self.owned_client) |*owned|
            owned.allocator
        else
            null);
        self.prepared_adoption = .{};
    }

    pub fn teardown(
        self: *ExternalPumpStorage,
        cleanup_scratch: *ExternalPumpCleanupScratch,
    ) TeardownResult {
        if (self.access_claim.cmpxchgStrong(
            @intFromEnum(StorageClaim.idle),
            @intFromEnum(StorageClaim.cleanup),
            .acq_rel,
            .acquire,
        )) |observed| {
            if (observed == @intFromEnum(StorageClaim.dead))
                return .already_dead;
            if (active_external_operation_addr == @intFromPtr(self))
                self.operation_reentry_latched = true;
            return .transaction_busy;
        }
        var storage_claim_owned = true;
        defer if (storage_claim_owned)
            self.access_claim.store(
                @intFromEnum(if (self.lifecycle == .dead)
                    StorageClaim.dead
                else
                    StorageClaim.idle),
                .release,
            );
        if (self.saved_self_addr != 0 and self.saved_self_addr != @intFromPtr(self))
            return .moved_storage;
        if (active_external_operation_addr != 0) {
            if (active_external_operation_addr == @intFromPtr(self))
                self.operation_reentry_latched = true;
            return .transaction_busy;
        }
        switch (self.lifecycle) {
            .empty => return .already_dead,
            .dead => {
                storage_claim_owned = false;
                self.access_claim.store(
                    @intFromEnum(StorageClaim.dead),
                    .release,
                );
                return .already_dead;
            },
            .constructing, .normalizing, .adoption_preparing, .tearing_down => return .transaction_busy,
            .adopting, .live => {},
        }
        if (self.attachment_lease != null) return .transaction_busy;
        if (self.callback_quarantine_pending) {
            storage_claim_owned = false;
            self.quarantinePublishedStorageAfterCallbackDrift();
            self.access_claim.store(@intFromEnum(StorageClaim.dead), .release);
            return .quarantined;
        }
        var cap_invariant = false;
        if (!rxResidentCapOwnerValid(self)) {
            cap_invariant = true;
            if (!restoreRxResidentCapFromClient(self)) {
                active_external_operation_addr = @intFromPtr(self);
                defer active_external_operation_addr = 0;
                return self.quarantineOwnerTeardown(cleanup_scratch, false);
            }
        }
        active_external_operation_addr = @intFromPtr(self);
        defer active_external_operation_addr = 0;
        const result = self.teardownUnderHeldOperationLease(cleanup_scratch);
        const final_result = if (cap_invariant and result == .cleaned)
            .cleaned_with_invariant
        else
            result;
        const claim_state: StorageClaim = if (self.lifecycle == .dead)
            .dead
        else
            .idle;
        storage_claim_owned = false;
        self.access_claim.store(@intFromEnum(claim_state), .release);
        return final_result;
    }

    fn prepareLiveOwnerTeardown(
        self: *ExternalPumpStorage,
        prepared: *PreparedLiveOwnerTeardown,
        frozen: *const FrozenLiveOwnerCleanup,
    ) bool {
        if (!self.liveOwnersValid() or prepared.saved_self_addr != 0 or
            prepared.lifecycle != .empty or frozen.saved_self_addr != 0 or
            frozen.lifecycle != .empty)
            return false;
        var staged: PreparedLiveOwnerTeardown = .{
            .saved_self_addr = @intFromPtr(prepared),
            .storage_addr = @intFromPtr(self),
            .lifecycle = .prepared,
        };
        switch (self.live_partial) {
            .none, .terminal => {},
            .assembling => |assembling| {
                staged.known_tokens[0] = assembling.ledger_token;
                staged.known_token_count = 1;
                staged.partial_owner_digest = assembling.owner_digest;
            },
        }
        if (self.live_screen.lifecycle == .active) {
            const capacity = external_inbox_ledger.max_live_mutations;
            for (0..self.live_screen.len) |offset| {
                if (staged.known_token_count >= staged.known_tokens.len)
                    return false;
                const index = (self.live_screen.head + offset) % capacity;
                const token = self.live_screen.tokens[index];
                for (staged.known_tokens[0..staged.known_token_count]) |prior|
                    if (prior.slot == token.slot) return false;
                staged.known_tokens[staged.known_token_count] = token;
                staged.known_token_count += 1;
            }
            staged.screen_owner_digest = self.live_screen.owner_digest;
        }
        switch (self.completed_control) {
            .none, .terminal => {},
            .completed => |pending| {
                staged.response_owner_digest = pending.owner_digest;
                staged.response_seal = pending.seal;
            },
        }
        staged.digest = preparedLiveOwnerTeardownDigest(&staged);
        prepared.* = staged;
        return true;
    }

    fn validatePreparedLiveOwnerTeardown(
        self: *const ExternalPumpStorage,
        prepared: *const PreparedLiveOwnerTeardown,
        frozen: *const FrozenLiveOwnerCleanup,
    ) bool {
        if (!self.liveOwnersValid() or
            prepared.saved_self_addr != @intFromPtr(prepared) or
            prepared.storage_addr != @intFromPtr(self) or
            prepared.lifecycle != .prepared or
            prepared.known_token_count > prepared.known_tokens.len or
            frozen.saved_self_addr != 0 or frozen.lifecycle != .empty or
            !std.mem.eql(
                u8,
                &prepared.digest,
                &preparedLiveOwnerTeardownDigest(prepared),
            ))
            return false;
        var index: usize = 0;
        switch (self.live_partial) {
            .none, .terminal => {
                if (!std.mem.allEqual(u8, &prepared.partial_owner_digest, 0))
                    return false;
            },
            .assembling => |assembling| {
                if (prepared.known_token_count == 0 or
                    !std.meta.eql(prepared.known_tokens[0], assembling.ledger_token) or
                    !std.mem.eql(
                        u8,
                        &prepared.partial_owner_digest,
                        &assembling.owner_digest,
                    ))
                    return false;
                index = 1;
            },
        }
        if (self.live_screen.lifecycle == .active) {
            if (!std.mem.eql(
                u8,
                &prepared.screen_owner_digest,
                &self.live_screen.owner_digest,
            )) return false;
            const capacity = external_inbox_ledger.max_live_mutations;
            for (0..self.live_screen.len) |offset| {
                if (index >= prepared.known_token_count) return false;
                const token_index = (self.live_screen.head + offset) % capacity;
                if (!std.meta.eql(
                    prepared.known_tokens[index],
                    self.live_screen.tokens[token_index],
                )) return false;
                index += 1;
            }
        } else if (!std.mem.allEqual(u8, &prepared.screen_owner_digest, 0)) {
            return false;
        }
        if (index != prepared.known_token_count) return false;
        return switch (self.completed_control) {
            .none, .terminal => std.meta.eql(
                prepared.response_seal,
                ResponsePayloadSeal.empty(),
            ) and
                std.mem.allEqual(u8, &prepared.response_owner_digest, 0),
            .completed => |pending| std.meta.eql(
                prepared.response_seal,
                pending.seal,
            ) and
                std.mem.eql(
                    u8,
                    &prepared.response_owner_digest,
                    &pending.owner_digest,
                ),
        };
    }

    fn commitLiveOwnerTeardownUnchecked(
        self: *ExternalPumpStorage,
        prepared: *PreparedLiveOwnerTeardown,
        frozen: *FrozenLiveOwnerCleanup,
    ) void {
        std.debug.assert(self.validatePreparedLiveOwnerTeardown(
            prepared,
            frozen,
        ));
        frozen.* = .{
            .saved_self_addr = @intFromPtr(frozen),
            .lifecycle = .frozen,
        };
        switch (self.completed_control) {
            .none, .terminal => {},
            .completed => |*pending| {
                frozen.response.payload = pending.payload;
                pending.payload = external_inbox_ledger.OwnedPayload.empty(
                    pending.payload.allocator,
                );
                frozen.response.seal = pending.seal;
                frozen.response.has_payload = true;
            },
        }
        frozen.digest = frozenLiveOwnerDigest(frozen);
        self.live_partial = .terminal;
        self.live_screen = .{ .lifecycle = .cleaned_tombstone };
        self.completed_control = .terminal;
        prepared.lifecycle = .consumed;
    }

    fn teardownUnderHeldOperationLease(
        self: *ExternalPumpStorage,
        cleanup_scratch: *ExternalPumpCleanupScratch,
    ) TeardownResult {
        if (active_external_operation_addr != @intFromPtr(self))
            return .transaction_busy;
        if (self.saved_self_addr != @intFromPtr(self))
            return .moved_storage;
        switch (self.lifecycle) {
            .adopting, .live => {},
            .empty, .dead => return .already_dead,
            else => return .transaction_busy,
        }
        if (!rxResidentCapOwnerValid(self) and
            !restoreRxResidentCapFromClient(self))
            return self.quarantineOwnerTeardown(cleanup_scratch, false);
        if (cleanupScratchOverlapsStorage(self, cleanup_scratch))
            return self.quarantineOwnerTeardown(cleanup_scratch, false);
        if (!cleanup_scratch.isReady())
            return self.quarantineOwnerTeardown(cleanup_scratch, false);
        const has_retained_aggregate = retainedRxAggregateValid(self);
        if (!has_retained_aggregate and
            !rxAggregateHandlePristine(&self.rx_aggregate_handle))
        {
            return self.quarantineOwnerTeardown(cleanup_scratch, true);
        }
        if (has_retained_aggregate and
            !self.prepareRetainedRxAggregateDestroy(
                &cleanup_scratch.aggregate_cleanup,
                &cleanup_scratch.aggregate_execution,
            ))
            return self.quarantineOwnerTeardown(cleanup_scratch, true);
        if (self.owner_teardown_generation == std.math.maxInt(u64))
            return self.quarantineOwnerTeardown(cleanup_scratch, true);
        const next_generation = self.owner_teardown_generation + 1;

        // Before adoption commit, every allocation still belongs to the prepared graph rather
        // than the committed screen/metadata/take owners. Keep that graph on its established
        // cleanup path while the same aggregate operation lease closes allocator re-entry. The
        // committed path below is reserved for the owner graph that requires the frozen suffix.
        if (self.lifecycle == .adopting and
            !self.committed_screen.requiresTypedCleanup() and
            !self.owner_metadata.requiresTypedCleanup() and
            !self.client_cleanup_take.requiresTypedCleanup() and
            self.live_partial == .none and
            self.live_screen.lifecycle == .empty and
            self.completed_control == .none)
        {
            return switch (self.closeUncommittedOwned(.invariant_failure)) {
                .cleaned => .cleaned,
                .cleaned_with_invariant => .cleaned_with_invariant,
                .invalid_committed_owner => self.quarantineOwnerTeardown(
                    cleanup_scratch,
                    true,
                ),
                .transaction_busy => .transaction_busy,
            };
        }

        self.inbox_ledger.beginOwnerTeardown(
            next_generation,
            &cleanup_scratch.ledger_permit,
        ) catch {
            return self.quarantineOwnerTeardown(cleanup_scratch, true);
        };
        if (!self.prepareLiveOwnerTeardown(
            &cleanup_scratch.live_prepared,
            &cleanup_scratch.live_frozen,
        )) {
            return self.quarantineOwnerTeardown(cleanup_scratch, true);
        }
        if (!self.intentScratchReservationValid()) {
            return self.quarantineOwnerTeardown(cleanup_scratch, true);
        }
        if (self.intent_scratch_reservation.lifecycle == .active) {
            const handle: *external_rx_intent.ExternalRxIntentHandle =
                @ptrFromInt(self.intent_scratch_reservation.handle_addr);
            if (!external_rx_intent.prepareDestroy(
                handle,
                @intFromPtr(self),
                self.intent_scratch_reservation.generation,
                &cleanup_scratch.intent_destroy_prepared,
            )) {
                return self.quarantineOwnerTeardown(cleanup_scratch, true);
            }
        }

        if (self.committed_screen.requiresTypedCleanup()) {
            if (!self.committed_screen.prepareFrozenCleanup(
                self,
                &cleanup_scratch.screen_plan,
                &cleanup_scratch.screen_prepared,
                &cleanup_scratch.screen_frozen,
            )) return self.quarantineOwnerTeardown(cleanup_scratch, true);
        } else {
            cleanup_scratch.screen_plan.initInPlace(
                &.{},
                std.StaticBitSet(external_inbox_ledger.max_items).initEmpty(),
            ) catch return self.quarantineOwnerTeardown(cleanup_scratch, true);
        }
        cleanup_scratch.screen_plan.appendRetainedTokens(
            cleanup_scratch.live_prepared
                .known_tokens[0..cleanup_scratch.live_prepared.known_token_count],
        ) catch return self.quarantineOwnerTeardown(cleanup_scratch, true);
        if (self.owner_metadata.requiresTypedCleanup() and
            !self.owner_metadata.prepareFrozenCleanup(
                self,
                &cleanup_scratch.metadata_prepared,
                &cleanup_scratch.metadata_frozen,
            ))
            return self.quarantineOwnerTeardown(cleanup_scratch, true);
        if (self.client_cleanup_take.requiresTypedCleanup() and
            !self.client_cleanup_take.prepareFrozenCleanup(
                &cleanup_scratch.client,
                &cleanup_scratch.take_prepared,
                &cleanup_scratch.take_frozen,
            ))
            return self.quarantineOwnerTeardown(cleanup_scratch, true);
        self.inbox_ledger.prepareFreezeAllForOwnerTeardown(
            &cleanup_scratch.ledger_permit,
            &cleanup_scratch.screen_plan,
            &cleanup_scratch.ledger_prepared,
            &cleanup_scratch.ledger_frozen,
        ) catch return self.quarantineOwnerTeardown(cleanup_scratch, true);

        if (self.owned_client) |*owned| {
            cleanup_scratch.range_scratch.source = .{};
            owned.preflightExternalAdoptionDestinationWithScratch(
                cleanup_scratch,
                @sizeOf(ExternalPumpCleanupScratch),
                &cleanup_scratch.range_scratch.source,
            ) catch {
                return self.quarantineOwnerTeardown(cleanup_scratch, true);
            };
        }
        if (!self.prepareAggregateOwnerRangeProof(cleanup_scratch)) {
            return self.quarantineOwnerTeardown(cleanup_scratch, true);
        }
        if (!self.validatePreparedLiveOwnerTeardown(
            &cleanup_scratch.live_prepared,
            &cleanup_scratch.live_frozen,
        )) return self.quarantineOwnerTeardown(cleanup_scratch, true);
        if (self.intent_scratch_reservation.lifecycle == .active) {
            const handle: *external_rx_intent.ExternalRxIntentHandle =
                @ptrFromInt(self.intent_scratch_reservation.handle_addr);
            if (!external_rx_intent.validatePreparedDestroy(
                handle,
                &cleanup_scratch.intent_destroy_prepared,
            )) return self.quarantineOwnerTeardown(cleanup_scratch, true);
        }

        var client_cleanup_reservation_active = false;
        var reserved_client: ?*client_mod.Client = null;
        if (self.owned_client) |*owned| {
            switch (owned.reserveExternalModeDeinit()) {
                .reserved => client_cleanup_reservation_active = true,
                .already_dead => {},
                .busy => {
                    cleanup_scratch.resetReady();
                    return .transaction_busy;
                },
            }
            reserved_client = owned;
        }
        defer if (client_cleanup_reservation_active)
            if (reserved_client) |owned|
                if (!owned.cancelReservedExternalModeDeinit())
                    @panic("external Client cleanup reservation rollback failed");

        self.tombstonePendingSummaries();
        self.lifecycle = .tearing_down;
        const terminal_state: client_pump.ExternalPumpState = switch (self.semantic_state) {
            .terminal => self.semantic_state,
            else => .{ .terminal = .{
                .reason = .invariant_failure,
                .fd_disposition = .owner_cleanup,
            } },
        };
        const storage_addr = @intFromPtr(self);
        const evidence_snapshot = self.evidence_snapshot;
        const operation_generation = self.operation_generation;
        const external_identity_teardown_generation =
            cleanup_scratch.ledger_prepared.terminal_external_identity_seal.generation;
        self.semantic_state = terminal_state;
        self.owner_teardown_generation = next_generation;

        var local_intent_destroy: ?external_rx_intent.FrozenDestroy = null;
        if (self.intent_scratch_reservation.lifecycle == .active) {
            const handle: *external_rx_intent.ExternalRxIntentHandle =
                @ptrFromInt(self.intent_scratch_reservation.handle_addr);
            local_intent_destroy = external_rx_intent.commitPreparedDestroy(
                handle,
                &cleanup_scratch.intent_destroy_prepared,
            );
            self.intent_scratch_reservation.lifecycle = .destroying;
            self.intent_scratch_reservation.digest =
                intentScratchReservationDigest(
                    self.intent_scratch_reservation,
                );
        }

        if (cleanup_scratch.metadata_prepared.lifecycle != .empty)
            self.owner_metadata.commitFrozenCleanupUnchecked(
                &cleanup_scratch.metadata_prepared,
                &cleanup_scratch.metadata_frozen,
            );
        if (cleanup_scratch.take_prepared.lifecycle != .empty)
            client_mod.commitExternalAdoptionTakeFrozenCleanupUnchecked(
                &self.client_cleanup_take,
                &cleanup_scratch.take_prepared,
                &cleanup_scratch.take_frozen,
            );
        const ledger_summary =
            self.inbox_ledger.commitFreezeAllForOwnerTeardownUnchecked(
                &cleanup_scratch.ledger_permit,
                &cleanup_scratch.ledger_prepared,
                &cleanup_scratch.ledger_frozen,
            );
        self.commitLiveOwnerTeardownUnchecked(
            &cleanup_scratch.live_prepared,
            &cleanup_scratch.live_frozen,
        );
        if (cleanup_scratch.screen_prepared.lifecycle != .empty)
            self.committed_screen.commitFrozenCleanupUnchecked(
                &cleanup_scratch.screen_prepared,
                &cleanup_scratch.screen_frozen,
            );
        if (has_retained_aggregate)
            self.commitRetainedRxAggregateDestroyUnchecked(
                &cleanup_scratch.aggregate_cleanup,
                cleanup_scratch.aggregate_execution.?,
            );
        cleanup_scratch.moved_client = self.owned_client;
        if (client_cleanup_reservation_active) {
            const source = reserved_client orelse
                @panic("external Client cleanup reservation source missing");
            const destination = if (cleanup_scratch.moved_client) |*owned|
                owned
            else
                @panic("external Client cleanup reservation destination missing");
            if (!source.transferReservedExternalModeDeinit(destination))
                @panic("external Client cleanup reservation move failed");
            reserved_client = destination;
        }
        self.owned_client = null;
        cleanup_scratch.moved_evidence = self.owned_evidence;
        self.owned_evidence = null;
        self.prepared_adoption = .{ .lifecycle = .committed_tombstone };
        self.client_transfer = .{};
        self.owner_resize = .none;
        self.owner_authority = .empty;
        self.owner_authority_seal = .{};
        self.owner_request_ids = null;
        self.control_correlation = .{};
        self.owner_incarnation = 0;
        self.owner_incarnation_seal = .{};
        self.owner_event_projection_generation = 0;
        cleanup_scratch.lifecycle = .frozen;

        var local_ledger = cleanup_scratch.ledger_frozen;
        var local_metadata = cleanup_scratch.metadata_frozen;
        var local_take = cleanup_scratch.take_frozen;
        var local_client_scratch = cleanup_scratch.client;
        var local_moved_client = cleanup_scratch.moved_client;
        if (client_cleanup_reservation_active) {
            const source = reserved_client orelse
                @panic("external Client cleanup reservation source missing");
            const destination = if (local_moved_client) |*owned|
                owned
            else
                @panic("external Client cleanup reservation destination missing");
            if (!source.transferReservedExternalModeDeinit(destination))
                @panic("external Client cleanup reservation local move failed");
            reserved_client = destination;
        }
        var local_moved_evidence = cleanup_scratch.moved_evidence;
        var local_screen = cleanup_scratch.screen_frozen;
        var local_live = cleanup_scratch.live_frozen;
        var local_aggregate: external_owner_cleanup.FrozenOwnerCleanupDescriptor = .{};
        if (cleanup_scratch.aggregate_cleanup.saved_self_addr != 0)
            external_owner_cleanup.moveFrozenUnchecked(
                &cleanup_scratch.aggregate_cleanup,
                &local_aggregate,
            );
        cleanup_scratch.* = .{
            .saved_self_addr = @intFromPtr(cleanup_scratch),
            .lifecycle = .frozen,
        };
        local_ledger.saved_self_addr = @intFromPtr(&local_ledger);
        local_metadata.saved_self_addr = if (local_metadata.saved_self_addr == 0)
            0
        else
            @intFromPtr(&local_metadata);
        local_screen.saved_self_addr = if (local_screen.saved_self_addr == 0)
            0
        else
            @intFromPtr(&local_screen);
        local_take.saved_self_addr = if (local_take.saved_self_addr == 0)
            0
        else
            @intFromPtr(&local_take);
        local_live.saved_self_addr = if (local_live.saved_self_addr == 0)
            0
        else
            @intFromPtr(&local_live);
        if (local_live.saved_self_addr != 0)
            local_live.digest = frozenLiveOwnerDigest(&local_live);

        var had_invariant = ledger_summary.had_invariant or
            ledger_summary.orphan_count != 0;
        if (local_ledger.finishCallbackHidden() != .cleaned)
            had_invariant = true;
        if (local_metadata.saved_self_addr != 0) {
            had_invariant = had_invariant or local_metadata.had_invariant;
            if (external_event_materialization.finishFrozenCleanup(
                &local_metadata,
            ) != .cleaned) had_invariant = true;
        }
        if (local_take.saved_self_addr != 0 and
            client_mod.finishFrozenCleanupWithHiddenScratch(
                &local_take,
                &local_client_scratch,
            ) != .cleaned)
            had_invariant = true;
        if (local_moved_client) |*owned| {
            if (!owned.finishReservedExternalModeDeinit())
                @panic("reserved external Client cleanup was not consumable");
            client_cleanup_reservation_active = false;
            reserved_client = null;
            owned.deinit();
        }
        local_moved_client = null;
        if (local_moved_evidence) |*owned| owned.deinit();
        local_moved_evidence = null;
        if (local_screen.saved_self_addr != 0 and
            client_external_adoption.finishFrozenCleanup(
                &local_screen,
            ) != .cleaned)
            had_invariant = true;
        if (local_live.saved_self_addr != 0 and
            !local_live.finishCallbackHidden())
            had_invariant = true;
        if (local_aggregate.saved_self_addr != 0 and
            external_owner_cleanup.finishCallbackHidden(&local_aggregate) !=
                .cleaned)
            had_invariant = true;
        if (local_intent_destroy) |frozen| {
            external_rx_intent.finishFrozenDestroy(frozen);
            // The held operation lease and callback-hidden frozen permit are the authority here.
            // Do not trust callback-mutated reservation or handle headers after the free.
            self.intent_scratch_reservation = .{};
        }

        self.saved_self_addr = storage_addr;
        self.evidence_snapshot = evidence_snapshot;
        self.owned_client = null;
        self.owned_evidence = null;
        self.client_transfer = .{};
        self.inbox_ledger.restoreFinishedOwnerTeardownUnchecked(
            next_generation,
            external_identity_teardown_generation,
        );
        self.prepared_adoption = .{ .lifecycle = .committed_tombstone };
        self.committed_screen = .{ .lifecycle = .cleaned_tombstone };
        self.live_partial = .terminal;
        self.live_screen = .{ .lifecycle = .cleaned_tombstone };
        self.completed_control = .terminal;
        self.screen_pending_summary = .{ .lifecycle = .tombstone };
        self.owner_metadata = .{ .lifecycle = .cleaned_tombstone };
        self.metadata_pending_summary = .{ .lifecycle = .tombstone };
        self.client_cleanup_take = .{ .lifecycle = .aborted };
        self.owner_resize = .none;
        self.owner_authority = .empty;
        self.owner_authority_seal = .{};
        self.owner_request_ids = null;
        self.control_correlation = .{};
        self.owner_incarnation = 0;
        self.owner_incarnation_seal = .{};
        self.owner_event_projection_generation = 0;
        self.rx_resident_cap = 0;
        self.rx_resident_cap_digest = [_]u8{0} ** 32;
        self.operation_generation = operation_generation;
        self.owner_teardown_generation = next_generation;
        self.intent_scratch_reservation = .{};
        self.semantic_state = terminal_state;
        self.lifecycle = .dead;
        releaseActiveStorage(@intFromPtr(self));
        cleanup_scratch.resetReady();
        return if (had_invariant) .cleaned_with_invariant else .cleaned;
    }

    fn prepareAggregateOwnerRangeProof(
        self: *const ExternalPumpStorage,
        cleanup_scratch: *ExternalPumpCleanupScratch,
    ) bool {
        var source_ranges = cleanup_scratch.range_scratch.source;
        cleanup_scratch.range_scratch_kind = .teardown;
        cleanup_scratch.range_scratch = .{ .teardown = .{} };
        const ranges = &cleanup_scratch.range_scratch.teardown;
        if (self.owned_client) |*owned|
            owned.appendExternalOwnerRangesForTeardown(
                &source_ranges,
                ranges,
            ) catch return false;
        if (self.owned_evidence) |*evidence|
            evidence.appendCleanupRange(ranges) catch return false;
        self.inbox_ledger.appendPreparedOwnerTeardownRanges(
            &cleanup_scratch.ledger_prepared,
            ranges,
        ) catch return false;
        if (cleanup_scratch.screen_prepared.lifecycle != .empty)
            self.committed_screen.appendPreparedFrozenCleanupRanges(
                &cleanup_scratch.screen_prepared,
                ranges,
            ) catch return false;
        if (cleanup_scratch.metadata_prepared.lifecycle != .empty)
            self.owner_metadata.appendPreparedFrozenCleanupRanges(
                &cleanup_scratch.metadata_prepared,
                ranges,
            ) catch return false;
        if (cleanup_scratch.take_prepared.lifecycle != .empty)
            self.client_cleanup_take.appendPreparedFrozenCleanupRanges(
                &cleanup_scratch.take_prepared,
                ranges,
            ) catch return false;
        appendPreparedLiveOwnerRanges(
            &cleanup_scratch.live_prepared,
            ranges,
        ) catch return false;
        if (retainedRxAggregateValid(self))
            ranges.append(
                self.rx_aggregate_handle.aggregate_addr,
                self.rx_aggregate_handle.allocation_len,
            ) catch return false;
        var forbidden = [_]external_owner_range.Range{
            .{
                .start = @intFromPtr(self),
                .len = @sizeOf(ExternalPumpStorage),
            },
            .{
                .start = @intFromPtr(cleanup_scratch),
                .len = @sizeOf(ExternalPumpCleanupScratch),
            },
            .{ .start = 0, .len = 0 },
        };
        var forbidden_len: usize = 2;
        if (self.intent_scratch_reservation.lifecycle == .active) {
            external_rx_intent.appendPreparedDestroyRange(
                &cleanup_scratch.intent_destroy_prepared,
                ranges,
            ) catch return false;
            forbidden[forbidden_len] = .{
                .start = self.intent_scratch_reservation.handle_addr,
                .len = @sizeOf(external_rx_intent.ExternalRxIntentHandle),
            };
            forbidden_len += 1;
        }
        ranges.validate(forbidden[0..forbidden_len]) catch return false;
        return true;
    }

    fn quarantineOwnerTeardown(
        self: *ExternalPumpStorage,
        cleanup_scratch: *ExternalPumpCleanupScratch,
        scratch_trusted: bool,
    ) TeardownResult {
        self.tombstonePendingSummaries();
        self.lifecycle = .dead;
        self.semantic_state = .{ .terminal = .{
            .reason = .invariant_failure,
            .fd_disposition = .owner_cleanup,
        } };
        latchCrossOwnerQuarantine();
        if (scratch_trusted)
            cleanup_scratch.lifecycle = .poisoned;
        self.owner_incarnation = 0;
        self.owner_incarnation_seal = .{};
        self.owner_event_projection_generation = 0;
        self.live_partial = .terminal;
        self.live_screen = .{ .lifecycle = .cleaned_tombstone };
        self.completed_control = .terminal;
        // Quarantine deliberately leaks an untrusted scratch graph. Remove the canonical
        // dereference authority before releasing the process-wide operation reservation.
        self.intent_scratch_reservation = .{
            .lifecycle = .poisoned_tombstone,
        };
        releaseActiveStorage(@intFromPtr(self));
        return .quarantined;
    }

    fn requireAddress(self: *const ExternalPumpStorage) AccessError!void {
        if (self.saved_self_addr != 0 and self.saved_self_addr != @intFromPtr(self))
            return error.MovedStorage;
        if (self.saved_self_addr != 0 and !rxResidentCapValid(self))
            return error.InvalidDescriptor;
    }

    fn closeUncommittedOwned(
        self: *ExternalPumpStorage,
        reason: client_pump.TerminalReason,
    ) UncommittedCloseResult {
        // This leaf owns only the pre-commit prepared graph. A committed owner must go through the
        // frozen aggregate suffix, which has caller-owned descriptor storage for callback hiding.
        const metadata_is_allocation_free_baseline =
            self.owner_metadata.isCommitted() and
            self.owner_metadata.metadata != .current;
        if (self.committed_screen.requiresTypedCleanup() or
            (self.owner_metadata.requiresTypedCleanup() and
                !metadata_is_allocation_free_baseline) or
            self.client_cleanup_take.requiresTypedCleanup())
            return .invalid_committed_owner;
        const prior_lifecycle = self.lifecycle;
        const prior_semantic_state = self.semantic_state;
        self.lifecycle = .tearing_down;
        self.semantic_state = .{ .terminal = .{
            .reason = reason,
            .fd_disposition = .owner_cleanup,
        } };
        if (self.owned_client) |*owned|
            if (owned.reserveExternalModeDeinit() == .busy) {
                self.lifecycle = prior_lifecycle;
                self.semantic_state = prior_semantic_state;
                return .transaction_busy;
            };
        self.prepared_adoption.deinit(if (self.owned_client) |*owned|
            owned.allocator
        else
            null);
        if (metadata_is_allocation_free_baseline)
            self.owner_metadata.deinitCommitted();
        if (self.owned_client) |*owned| {
            if (!owned.finishReservedExternalModeDeinit())
                @panic("reserved external Client cleanup was not consumable");
            owned.deinit();
        }
        self.owned_client = null;
        if (self.owned_evidence) |*owned| owned.deinit();
        self.owned_evidence = null;
        self.client_transfer.deinit();
        self.owner_resize = .none;
        self.owner_authority = .empty;
        self.owner_request_ids = null;
        const drain_report = self.inbox_ledger.drainAll() catch
            external_inbox_ledger.DrainReport{
                .drained_active_count = 0,
                .drained_bytes = 0,
                .had_sticky_invariant = true,
            };
        const ledger_result = self.inbox_ledger.finish();
        self.rx_resident_cap = 0;
        self.rx_resident_cap_digest = [_]u8{0} ** 32;
        self.lifecycle = .dead;
        releaseActiveStorage(@intFromPtr(self));
        if (drain_report.drained_active_count != 0 or
            drain_report.had_sticky_invariant)
            return .cleaned_with_invariant;
        return if (ledger_result) |_| .cleaned else |_| .cleaned_with_invariant;
    }
};

fn exactCr3aOwnerSchema(comptime Actual: type, comptime Expected: type) bool {
    const actual = std.meta.fields(Actual);
    const expected = std.meta.fields(Expected);
    if (actual.len != expected.len) return false;
    inline for (actual, expected) |a, e| {
        if (!std.mem.eql(u8, a.name, e.name) or a.type != e.type) return false;
    }
    return true;
}

comptime {
    @setEvalBranchQuota(100_000);
    const Expected = struct {
        access_claim: std.atomic.Value(u8),
        lifecycle: StorageLifecycle,
        saved_self_addr: usize,
        rx_resident_cap: usize,
        rx_resident_cap_digest: external_owner_seal.Digest,
        semantic_state: client_pump.ExternalPumpState,
        evidence_snapshot: AttachmentEvidence,
        owned_client: ?client_mod.Client,
        owned_evidence: ?PreparedAdoptionEvidence,
        client_transfer: client_mod.PreparedExternalPumpTransfer,
        inbox_ledger: external_inbox_ledger.ExternalInboxLedger,
        prepared_adoption: PreparedExternalAdoption,
        client_cleanup_take: client_mod.ExternalAdoptionTake,
        committed_screen: client_external_adoption.CommittedScreenBacklog,
        attachment_lease: ?external_inbox_ledger.Token,
        live_partial: LivePartialBatch,
        live_screen: LiveScreenBacklog,
        completed_control: CompletedControlOwner,
        completed_control_generation: u64,
        screen_pending_summary: ScreenPendingSummarySeal,
        owner_metadata: external_event_materialization.OwnerMetadataState,
        metadata_pending_summary: MetadataPendingSummarySeal,
        owner_resize: OwnerResizeState,
        owner_authority: OwnerAuthorityState,
        owner_authority_seal: OwnerAuthoritySeal,
        owner_request_ids: ?client_pump.RequestIdState,
        control_correlation: ControlCorrelationOwner,
        owner_incarnation: u64,
        owner_incarnation_seal: OwnerIncarnationSeal,
        owner_event_projection_generation: u64,
        operation_generation: u64,
        operation_reentry_latched: bool,
        callback_quarantine_pending: bool,
        callback_quarantine_accounted: bool,
        owner_teardown_generation: u64,
        intent_scratch_generation: u64,
        intent_scratch_reservation: IntentScratchReservation,
        rx_aggregate_generation: u64,
        rx_aggregate_handle: PreparedRxAggregateHandle,
        rx_aggregate_reservation: RxAggregateScratchReservation,
    };
    if (!exactCr3aOwnerSchema(ExternalPumpStorage, Expected))
        @compileError("CR3a ExternalPumpStorage schema changed; update SSOT before implementation");
}

