fn armResponseCorrelationForTest(
    storage: *ExternalPumpStorage,
    request_id: u64,
    now_ns: i128,
) bool {
    if (comptime !builtin.is_test) unreachable;
    if (!controlCorrelationValid(storage)) return false;
    const authority = switch (storage.owner_authority) {
        .current => |value| value,
        .empty => return false,
    };
    const controller_generation = switch (authority.generation) {
        .tracked => |value| value,
        .untracked => return false,
    };
    const target = client_control_correlation.Target{
        .stream_id = storage.evidence_snapshot.stream_id,
        .controller_generation = controller_generation,
    };
    const admitted = switch (client_control_correlation.prepareAdmission(
        storage.control_correlation.state,
        .resize,
        .{ .resize = .{ .client_sequence = 1 } },
        target,
        request_id,
        protocol.header_size + 1,
        now_ns,
    )) {
        .admitted => |value| value,
        else => return false,
    };
    const waiting = switch (client_control_correlation.observeProgress(
        admitted,
        .response_wait,
        request_id,
        target,
    )) {
        .updated => |value| value,
        else => return false,
    };
    return publishControlCorrelation(storage, .{ .in_flight = waiting });
}

fn rewindControlCorrelationToQueuedForTest(
    storage: *ExternalPumpStorage,
) bool {
    if (comptime !builtin.is_test) unreachable;
    var in_flight = switch (storage.control_correlation.state) {
        .in_flight => |value| value,
        .idle, .completed, .terminal => return false,
    };
    in_flight.progress = .queued;
    return publishControlCorrelation(storage, .{ .in_flight = in_flight });
}

fn activateSyntheticLiveOwnersForTest(
    storage: *ExternalPumpStorage,
    partial_token: external_inbox_ledger.Token,
    screen_tokens: *const [external_inbox_ledger.max_live_mutations]external_inbox_ledger.Token,
    response_payload: external_inbox_ledger.OwnedPayload,
) void {
    if (comptime !builtin.is_test) unreachable;
    storage.live_partial = .{ .assembling = .{
        .ledger_token = partial_token,
        .generation = 1,
        .owner_digest = livePartialDigest(storage, partial_token, 1),
    } };
    storage.live_screen = .{
        .saved_self_addr = @intFromPtr(&storage.live_screen),
        .storage_addr = @intFromPtr(storage),
        .tokens = screen_tokens.*,
        .len = external_inbox_ledger.max_live_mutations,
        .generation = 1,
        .lifecycle = .active,
    };
    storage.live_screen.owner_digest =
        liveScreenDigest(storage, &storage.live_screen);
    const target = client_control_correlation.Target{
        .stream_id = storage.evidence_snapshot.stream_id,
        .controller_generation = 1,
    };
    std.debug.assert(publishControlCorrelation(storage, .{ .completed = .{
        .kind = .resize,
        .expectation = .{ .resize = .{ .client_sequence = 1 } },
        .target = target,
        .request_id = 1,
        .wire_len = protocol.header_size + 1,
    } }));
    var pending = CompletedControlState{
        .payload = response_payload,
        .seal = ResponsePayloadSeal.fromPayload(&response_payload),
        .request_id = 1,
        .control_kind = .resize,
        .expectation = .{ .resize = .{ .client_sequence = 1 } },
        .target_stream_id = target.stream_id,
        .expected_controller_generation = target.controller_generation,
        .control_wire_len = protocol.header_size + 1,
        .correlation_generation = storage.control_correlation.generation,
        .source_turn_generation = storage.operation_generation,
        .source_parser_generation = 1,
        .source_start_absolute = 1,
        .source_end_absolute = 2,
        .source_owner_digest = external_owner_cleanup.contentDigest(
            response_payload.bytes(),
        ),
        .generation = 1,
        .owner_digest = undefined,
    };
    pending.owner_digest = completedControlDigest(storage, &pending);
    storage.completed_control = .{ .completed = pending };
    storage.completed_control_generation = pending.generation;
}

fn seedSyntheticLiveOwnersForTest(
    storage: *ExternalPumpStorage,
    allocator: std.mem.Allocator,
) !void {
    if (comptime !builtin.is_test) unreachable;
    const identity = external_rx_types.RxIdentity{
        .attach_instance_id = storage.owner_incarnation,
        .destination_slot_addr = @intFromPtr(storage),
    };
    var partial_batch: external_inbox_ledger.PreparedLiveBatch = .{};
    try storage.inbox_ledger.beginLiveBatch(
        &partial_batch,
        allocator,
        identity,
    );
    var partial_bytes = try allocator.dupe(u8, "p");
    var partial_payload =
        external_inbox_ledger.OwnedPayload.takeOwned(allocator, &partial_bytes);
    _ = try storage.inbox_ledger.prepareLiveAdmission(
        &partial_batch,
        .{ .partial = .{
            .stream_id = 900,
            .is_snapshot = false,
            .chunk_count = 1,
            .provenance = .{ .external = .{
                .start_absolute = 0,
                .span = protocol.header_size + 1,
            } },
        } },
        &partial_payload,
    );
    try storage.inbox_ledger.finishLiveBatch(&partial_batch);
    var partial_retirement =
        external_inbox_ledger.PreparedLiveRetirement.init(allocator);
    var partial_dispositions =
        [_]external_inbox_ledger.LiveCommitDisposition{.unused} **
        external_inbox_ledger.max_live_mutations;
    _ = try storage.inbox_ledger.commitPreparedLiveBatch(
        &partial_batch,
        &partial_retirement,
        &partial_dispositions,
    );
    try std.testing.expect(
        partial_retirement.lifecycle == .retired,
    );
    try std.testing.expectEqual(
        external_inbox_ledger.RetireLiveResult.already_retired,
        partial_retirement.retire(),
    );
    const partial_token = partial_dispositions[0].final_live.token;

    var screen_batch: external_inbox_ledger.PreparedLiveBatch = .{};
    try storage.inbox_ledger.beginLiveBatch(
        &screen_batch,
        allocator,
        identity,
    );
    for (0..external_inbox_ledger.max_live_mutations) |index| {
        var bytes = try allocator.dupe(u8, "s");
        var payload =
            external_inbox_ledger.OwnedPayload.takeOwned(allocator, &bytes);
        _ = try storage.inbox_ledger.prepareLiveAdmission(
            &screen_batch,
            .{ .completed = .{
                .stream_id = 1000 + index,
                .is_snapshot = false,
                .provenance = .{ .external = .{
                    .start_absolute = (index + 1) * (protocol.header_size + 1),
                    .span = protocol.header_size + 1,
                } },
            } },
            &payload,
        );
    }
    try storage.inbox_ledger.finishLiveBatch(&screen_batch);
    var screen_retirement =
        external_inbox_ledger.PreparedLiveRetirement.init(allocator);
    var screen_dispositions =
        [_]external_inbox_ledger.LiveCommitDisposition{.unused} **
        external_inbox_ledger.max_live_mutations;
    _ = try storage.inbox_ledger.commitPreparedLiveBatch(
        &screen_batch,
        &screen_retirement,
        &screen_dispositions,
    );
    try std.testing.expect(
        screen_retirement.lifecycle == .retired,
    );
    try std.testing.expectEqual(
        external_inbox_ledger.RetireLiveResult.already_retired,
        screen_retirement.retire(),
    );
    var screen_tokens =
        [_]external_inbox_ledger.Token{.{ .slot = 0, .generation = 0 }} **
        external_inbox_ledger.max_live_mutations;
    for (0..external_inbox_ledger.max_live_mutations) |index|
        screen_tokens[index] =
            screen_dispositions[index].final_live.token;

    var response_bytes = try allocator.dupe(u8, "response");
    const response_payload =
        external_inbox_ledger.OwnedPayload.takeOwned(
            allocator,
            &response_bytes,
        );
    activateSyntheticLiveOwnersForTest(
        storage,
        partial_token,
        &screen_tokens,
        response_payload,
    );
}

