        external_inbox_ledger.RetireLiveResult.retired,
        release_retirement.retire(),
    );
    switch (storage.completed_control) {
        .completed => |*pending| pending.payload.deinit(),
        else => unreachable,
    }
    storage.completed_control = .none;
