const QuarantineAllocationTracker = struct {
    // Test-only tracker for an ArenaAllocator parent: arena frees never recycle an address before
    // arena deinit. Do not reuse this helper with an allocator that can recycle freed addresses;
    // stale-pointer detection there requires an allocation generation in addition to the address.
    const max_records = 64;
    const Record = struct { addr: usize = 0, len: usize = 0, live: bool = false };

    parent: std.mem.Allocator,
    records: [max_records]Record = [_]Record{.{}} ** max_records,
    record_count: usize = 0,
    free_count: usize = 0,
    invalid_free: bool = false,
    duplicate_free: bool = false,

    fn allocator(self: *QuarantineAllocationTracker) std.mem.Allocator {
        return .{ .ptr = self, .vtable = &.{
            .alloc = alloc,
            .resize = resize,
            .remap = remap,
            .free = free,
        } };
    }

    fn find(self: *QuarantineAllocationTracker, addr: usize) ?*Record {
        var prior: ?*Record = null;
        for (self.records[0..self.record_count]) |*record| {
            if (record.addr != addr) continue;
            if (record.live) return record;
            prior = record;
        }
        return prior;
    }

    fn alloc(context: *anyopaque, len: usize, alignment: std.mem.Alignment, ret_addr: usize) ?[*]u8 {
        const self: *QuarantineAllocationTracker = @ptrCast(@alignCast(context));
        if (self.record_count == max_records) return null;
        const memory = self.parent.vtable.alloc(self.parent.ptr, len, alignment, ret_addr) orelse return null;
        self.records[self.record_count] = .{ .addr = @intFromPtr(memory), .len = len, .live = true };
        self.record_count += 1;
        return memory;
    }

    fn resize(context: *anyopaque, memory: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) bool {
        const self: *QuarantineAllocationTracker = @ptrCast(@alignCast(context));
        const record = self.find(@intFromPtr(memory.ptr)) orelse {
            self.invalid_free = true;
            return false;
        };
        if (!record.live) {
            self.duplicate_free = true;
            return false;
        }
        if (!self.parent.vtable.resize(self.parent.ptr, memory, alignment, new_len, ret_addr)) return false;
        record.len = new_len;
        return true;
    }

    fn remap(context: *anyopaque, memory: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) ?[*]u8 {
        const self: *QuarantineAllocationTracker = @ptrCast(@alignCast(context));
        const record = self.find(@intFromPtr(memory.ptr)) orelse {
            self.invalid_free = true;
            return null;
        };
        if (!record.live) {
            self.duplicate_free = true;
            return null;
        }
        const remapped = self.parent.vtable.remap(self.parent.ptr, memory, alignment, new_len, ret_addr) orelse return null;
        record.addr = @intFromPtr(remapped);
        record.len = new_len;
        return remapped;
    }

    fn free(context: *anyopaque, memory: []u8, alignment: std.mem.Alignment, ret_addr: usize) void {
        const self: *QuarantineAllocationTracker = @ptrCast(@alignCast(context));
        const record = self.find(@intFromPtr(memory.ptr)) orelse {
            self.invalid_free = true;
            return;
        };
        if (!record.live) {
            self.duplicate_free = true;
            return;
        }
        if (record.len != memory.len) {
            self.invalid_free = true;
            return;
        }
        record.live = false;
        self.free_count += 1;
        self.parent.vtable.free(self.parent.ptr, memory, alignment, ret_addr);
    }

    fn liveBytes(self: *const QuarantineAllocationTracker) usize {
        var total: usize = 0;
        for (self.records[0..self.record_count]) |record| {
            if (record.live) total +|= record.len;
        }
        return total;
    }
};

/// Every f2 terminal fixture ends in the same canonical owner graph. Explicit field assertions
/// keep `.cleaned` from becoming a weak proxy that could hide a retained TX/payload authority.
fn expectF2FinalZero(storage: *ExternalPumpStorage) !void {
    var tx_receipt: client_external_mode.testing.TxDeinitReceipt = .{};
    try std.testing.expect(
        client_external_mode.testing.beginTxDeinitReceipt(&tx_receipt),
    );
    defer std.debug.assert(
        client_external_mode.testing.endTxDeinitReceipt(&tx_receipt),
    );
    try std.testing.expectEqual(TeardownResult.cleaned, teardownForTest(storage));
    try std.testing.expect(tx_receipt.observed);
    try std.testing.expectEqual(@as(usize, 0), tx_receipt.items);
    try std.testing.expectEqual(@as(usize, 0), tx_receipt.capacity);
    try std.testing.expectEqual(@as(usize, 0), tx_receipt.bytes);
    try std.testing.expectEqual(@as(usize, 0), tx_receipt.retiring_bytes);
    try std.testing.expect(tx_receipt.lifecycle == .dead);
    try std.testing.expect(tx_receipt.claim_dead);
    try std.testing.expect(storage.owned_client == null);
    try std.testing.expect(storage.owner_request_ids == null);
    try std.testing.expect(storage.control_correlation.state == .idle);
    const accounting = storage.inbox_ledger.accountingView();
    try std.testing.expect(accounting.valid);
    try std.testing.expectEqual(@as(usize, 0), accounting.charged_bytes);
    try std.testing.expectEqual(@as(usize, 0), accounting.charged_items);
    try std.testing.expect(storage.completed_control == .terminal);
    try std.testing.expect(storage.live_partial == .terminal);
    try std.testing.expect(
        storage.live_screen.lifecycle == .cleaned_tombstone,
    );
}

test "f3c0 f3c1 completed control defers pending TX to a fresh authority turn" {
    const Probe = struct {
        var wire: []const u8 = &.{};
        var exposed_len: usize = 0;
        var offset: usize = 0;

        fn read(
            _: *anyopaque,
            _: posix.fd_t,
            buffer: []u8,
        ) client_external_rx_read.RxReadOutcome {
            if (offset >= exposed_len) return .would_block;
            const count = @min(buffer.len, exposed_len - offset);
            @memcpy(buffer[0..count], wire[offset..][0..count]);
            offset += count;
            return .{ .bytes = count };
        }

        fn apply(
            _: *anyopaque,
            _: external_inbox_ledger.PayloadView,
        ) LiveScreenApplyResult {
            return .applied;
        }
    };

    var fixture = try TestClient.init();
    defer fixture.deinitPeer();
    var storage: ExternalPumpStorage = .{};
    try std.testing.expect(
        initTestStorage(&storage, &fixture.client, valid_evidence) ==
            .initialized,
    );
    try std.testing.expect(prepareAdoptionForTest(&storage) == .prepared_adopted);
    try std.testing.expect(storage.commitAdoption() == .adopted);
    try std.testing.expect(testing.clearInitialFence(&storage));

    const admitted = storage.admitControl(.{
        .request = .{ .resize = .{
            .stream_id = valid_evidence.stream_id,
            .cols = 80,
            .rows = 24,
            .client_sequence = 1,
        } },
        .expected_controller_generation = valid_evidence.initial_controller_generation,
    }, 100);
    const request_id = switch (admitted) {
        .admitted => |value| value.request_id,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(u64, 1), request_id);
    const correlation = storage.control_correlation.state.in_flight;
    try std.testing.expectEqual(request_id, correlation.request_id);
    try std.testing.expectEqual(
        @as(u64, 1),
        correlation.expectation.resize.client_sequence,
    );
    try std.testing.expectEqual(
        client_control_correlation.Progress.queued,
        correlation.progress,
    );
    try std.testing.expect(controlCorrelationValid(&storage));
    const sealed_correlation = storage.control_correlation;
    storage.control_correlation.state.in_flight.expectation.resize.client_sequence = 2;
    try std.testing.expect(!controlCorrelationValid(&storage));
    storage.control_correlation = sealed_correlation;
    try std.testing.expect(controlCorrelationValid(&storage));
    const external = switch (storage.owned_client.?.io_mode) {
        .external => |*state| state,
        .blocking => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 1), external.external_tx.items.len);
    try std.testing.expect(std.meta.eql(
        storage.owner_request_ids.?,
        client_pump.RequestIdState{ .available = 2 },
    ));

    const queue_generation = external.tx_queue_generation;
    const request_state = storage.owner_request_ids.?;
    try std.testing.expect(storage.admitControl(.{
        .request = .{ .resync = .{
            .stream_id = valid_evidence.stream_id,
            .recovery_authority = .{
                .owner_incarnation = storage.owner_incarnation,
                .origin = .client,
                .recovery_epoch = 1,
            },
        } },
        .expected_controller_generation = valid_evidence.initial_controller_generation,
    }, 101) == .backpressure);
    try std.testing.expectEqual(queue_generation, external.tx_queue_generation);
    try std.testing.expect(std.meta.eql(
        request_state,
        storage.owner_request_ids.?,
    ));

    const scratch = try std.testing.allocator.create(ExternalRxTurnScratch);
    defer std.testing.allocator.destroy(scratch);
    scratch.* = .{};
    try std.testing.expect(ExternalRxTurnScratch.initInPlace(scratch));
    Probe.wire = &.{};
    Probe.exposed_len = 0;
    Probe.offset = 0;
    defer {
        Probe.wire = &.{};
        Probe.exposed_len = 0;
        Probe.offset = 0;
    }
    var read_probe: u8 = 0;
    var apply_probe: u8 = 0;
    const ops = RxTurnOps{
        .buffered = .{
            .context = &apply_probe,
            .context_len = @sizeOf(bool),
            .apply_live_screen = Probe.apply,
        },
        .transport = .{
            .context = &read_probe,
            .context_len = @sizeOf(u8),
            .read = Probe.read,
        },
    };
    const turn = storage.pumpRxTurn(
        .{ .readable = true, .writable = true, .now_ns = 102 },
        &ops,
        scratch,
    );
    try std.testing.expectEqual(
        @as(?client_pump.ExternalPumpTerminal, null),
        turn.terminal,
    );
    try std.testing.expectEqual(@as(usize, 1), turn.tx_frames);
    try std.testing.expectEqual(
        client_control_correlation.Progress.response_wait,
        storage.control_correlation.state.in_flight.progress,
    );
    try std.testing.expect(controlCorrelationValid(&storage));
    var request_wire: [protocol.max_control_json + protocol.header_size]u8 = undefined;
    const request_bytes = c.recv(
        fixture.peer_fd,
        &request_wire,
        request_wire.len,
        0,
    );
    try std.testing.expect(request_bytes > 0);
    const response_wire = try framing.encodeFrame(
        std.testing.allocator,
        .{ .kind = .response, .request_id = request_id },
        "{\"result\":{\"cols\":80,\"rows\":24,\"client_sequence\":1,\"resize_generation\":2,\"changed\":true}}",
    );
    defer std.testing.allocator.free(response_wire);
    const response_split = response_wire.len / 2;
    try std.testing.expect(response_split > protocol.header_size);
    Probe.wire = response_wire;
    Probe.exposed_len = response_split;
    try std.testing.expect(storage.settleRxTurnForSiblingOperation(scratch));
    try std.testing.expect(storage.admitTx(.{
        .kind = .input_bytes,
        .stream_id = valid_evidence.stream_id,
        .payload = "queued-after-resize",
        .request_policy = .zero,
    }, 102) == .admitted);
    try std.testing.expectEqual(@as(usize, 1), external.external_tx.items.len);
    const partial_response_turn = storage.pumpRxTurn(
        .{ .readable = true, .writable = true, .now_ns = 103 },
        &ops,
        scratch,
    );
    try std.testing.expectEqual(
        @as(?client_pump.ExternalPumpTerminal, null),
        partial_response_turn.terminal,
    );
    try std.testing.expect(!partial_response_turn.authority_clear);
    try std.testing.expectEqual(@as(usize, 0), partial_response_turn.tx_frames);
    try std.testing.expectEqual(@as(usize, 1), external.external_tx.items.len);
    Probe.exposed_len = response_wire.len;
    const response_turn = storage.pumpRxTurn(
        .{ .readable = true, .writable = true, .now_ns = 104 },
        &ops,
        scratch,
    );
    try std.testing.expect(response_turn.terminal == null);
    try std.testing.expect(!response_turn.authority_clear);
    try std.testing.expect(response_turn.immediate_rx);
    try std.testing.expectEqual(@as(usize, 0), response_turn.tx_frames);
    try std.testing.expectEqual(@as(usize, 1), external.external_tx.items.len);
    try std.testing.expectEqual(RxDrainEvidenceLifecycle.empty, scratch.drain_evidence.lifecycle);
    try std.testing.expect(storage.completed_control == .none);
    try std.testing.expect(storage.control_correlation.state == .idle);
    try std.testing.expect(storage.owner_resize == .current);
    try std.testing.expectEqual(@as(u16, 80), storage.owner_resize.current.event.cols);
    try std.testing.expectEqual(@as(u16, 24), storage.owner_resize.current.event.rows);
    try std.testing.expectEqual(@as(u64, 2), storage.owner_resize.current.event.resize_generation);
    try std.testing.expectEqual(ExternalRxTurnScratchLifecycle.ready, scratch.lifecycle);
    try std.testing.expect(ExternalPumpStorage.controlSemanticDestinationsPristine(scratch));
    try std.testing.expect(storage.settleRxTurnForSiblingOperation(scratch));
    var cleanup_scratch: ExternalPumpCleanupScratch = .{};
    try std.testing.expect(ExternalPumpCleanupScratch.initInPlace(&cleanup_scratch));
    try std.testing.expectEqual(
        CliOwnerProjectionResult.applied,
        storage.consumeCliOwnerProjection(&cleanup_scratch),
    );
    const fresh_turn = storage.pumpRxTurn(
        .{ .readable = true, .writable = false, .now_ns = 105 },
        &ops,
        scratch,
    );
    try std.testing.expect(fresh_turn.terminal == null);
    try std.testing.expect(fresh_turn.authority_clear);
    try std.testing.expect(fresh_turn.write_interest);
    try std.testing.expectEqual(@as(usize, 0), fresh_turn.tx_frames);
    const tx_turn = storage.pumpRxTurn(
        .{ .readable = true, .writable = true, .now_ns = 106 },
        &ops,
        scratch,
    );
    try std.testing.expect(tx_turn.terminal == null);
    try std.testing.expectEqual(@as(usize, 1), tx_turn.tx_frames);
    try std.testing.expectEqual(@as(usize, 0), external.external_tx.items.len);
    try std.testing.expect(storage.completed_control == .none);
    try std.testing.expect(storage.control_correlation.state == .idle);
    try std.testing.expect(storage.owner_resize == .current);
    try std.testing.expectEqual(TeardownResult.cleaned, teardownForTest(&storage));
}

const F3c1FailAllocator = struct {
    parent: std.mem.Allocator,
    fail: bool = false,
    free_count: usize = 0,

    fn allocator(self: *@This()) std.mem.Allocator {
        return .{ .ptr = self, .vtable = &.{
            .alloc = alloc,
            .resize = resize,
            .remap = remap,
            .free = free,
        } };
    }

    fn alloc(ctx: *anyopaque, len: usize, alignment: std.mem.Alignment, ret_addr: usize) ?[*]u8 {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        if (self.fail) return null;
        return self.parent.vtable.alloc(self.parent.ptr, len, alignment, ret_addr);
    }

    fn resize(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) bool {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        if (self.fail) return false;
        return self.parent.vtable.resize(self.parent.ptr, memory, alignment, new_len, ret_addr);
    }

    fn remap(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) ?[*]u8 {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        if (self.fail) return null;
        return self.parent.vtable.remap(self.parent.ptr, memory, alignment, new_len, ret_addr);
    }

    fn free(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, ret_addr: usize) void {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        self.free_count += 1;
        self.parent.vtable.free(self.parent.ptr, memory, alignment, ret_addr);
    }
};

