            &storage,
            &fixture,
            scratch,
            &lease,
            .{ .resize = .{
                .stream_id = valid_evidence.stream_id,
                .cols = 81,
                .rows = 25,
                .client_sequence = 1,
            } },
            "{\"result\":{\"cols\":81,\"rows\":25,\"client_sequence\":1,\"resize_generation\":2,\"changed\":true}}",
            .request_id_max,
            null,
        ),
    );
    try std.testing.expect(storage.owner_request_ids.? == .max_consumed);
    try std.testing.expect(storage.prepareResizeSemanticCommitUnderHeldLease(
        &lease,
        scratch,
    ));
    try std.testing.expectEqual(
        ConsumeResizeSemanticResult.consumed_resize_cleaned,
        storage.consumeResizeSemanticCommitUnderHeldLease(&lease, scratch),
    );
    try std.testing.expectEqual(
        std.math.maxInt(u64),
        scratch.resize_semantic_frozen_response.request_id,
    );
    try std.testing.expectEqual(
        WholeTurnReleaseResult.released,
        storage.releaseWholeTurnLease(&lease),
    );
    const external = switch (storage.owned_client.?.io_mode) {
        .external => |*state| state,
        .blocking => return error.TestUnexpectedResult,
    };
    const tx_len_before = external.external_tx.items.len;
    const tx_bytes_before = external.external_tx_bytes;
    const tx_generation_before = external.tx_queue_generation;
    const request_ids_before = storage.owner_request_ids.?;
    const correlation_before = storage.control_correlation;
    const exhausted = storage.admitControl(.{
        .request = .{ .resize = .{
            .stream_id = valid_evidence.stream_id,
            .cols = 82,
            .rows = 26,
            .client_sequence = 2,
        } },
        .expected_controller_generation = valid_evidence.initial_controller_generation,
    }, 103);
    try std.testing.expect(exhausted == .terminal);
    try std.testing.expectEqual(
        client_pump.TerminalReason.request_id_exhausted,
        exhausted.terminal,
    );
    try std.testing.expectEqual(tx_len_before, external.external_tx.items.len);
    try std.testing.expectEqual(tx_bytes_before, external.external_tx_bytes);
    try std.testing.expectEqual(tx_generation_before, external.tx_queue_generation);
    try std.testing.expect(std.meta.eql(request_ids_before, storage.owner_request_ids.?));
    try std.testing.expect(std.meta.eql(correlation_before, storage.control_correlation));
    var peer_byte: [1]u8 = undefined;
    try std.testing.expectEqual(
        @as(isize, -1),
        c.recv(fixture.peer_fd, &peer_byte, peer_byte.len, posix.MSG.DONTWAIT),
    );
    try std.testing.expect(posix.errno(-1) == .AGAIN);
}

test "f3c1 actual resize and resync responses prepare typed pairs" {
    const cases = [_]struct {
        request_kind: client_pump.ControlKind,
        payload: []const u8,
    }{
        .{ .request_kind = .resize, .payload = "{\"result\":{\"cols\":80,\"rows\":24,\"client_sequence\":1,\"resize_generation\":2,\"changed\":true}}" },
        .{ .request_kind = .resync, .payload = "{\"result\":{\"resync\":true}}" },
    };
    for (cases) |case| {
        var fixture = try TestClient.init();
        defer fixture.deinitPeer();
        var storage: ExternalPumpStorage = .{};
        const scratch = try std.testing.allocator.create(ExternalRxTurnScratch);
        defer std.testing.allocator.destroy(scratch);
        defer if (storage.lifecycle != .dead) {
            _ = teardownForTest(&storage);
        };
        var lease: ExternalWholeTurnLease = .{};
        const request: control_response_wire.ControlRequest = switch (case.request_kind) {
            .resize => .{ .resize = .{
                .stream_id = valid_evidence.stream_id,
                .cols = 80,
                .rows = 24,
                .client_sequence = 1,
            } },
            .resync => .{ .resync = .{
                .stream_id = valid_evidence.stream_id,
                .recovery_authority = .{
                    .owner_incarnation = fixture.client.attach_instance_id,
                    .origin = .client,
                    .recovery_epoch = 9,
                },
            } },
            // Terminal detach retires correlation when its frame is sent and never prepares a
            // response pair, so it is outside this resize/resync response-only fixture.
            .detach => unreachable,
        };
        const result = try prepareF3c1ActualResponse(
            &storage,
            &fixture,
            scratch,
            &lease,
            request,
            case.payload,
            .none,
            null,
        );
        try std.testing.expectEqual(ControlSemanticPreparationResult.prepared_pair, result);
        try std.testing.expect(storage.preparedControlSemanticPairCurrent(&lease, scratch));
        const completed = switch (storage.completed_control) {
            .completed => |value| value,
            .none, .terminal => return error.TestUnexpectedResult,
        };
        const permit = &scratch.whole_drain_permit;
        try std.testing.expectEqual(completed.source_start_absolute, permit.parser_absolute_start);
        try std.testing.expect(permit.parser_absolute_end >= completed.source_end_absolute);
        try std.testing.expectEqual(@intFromPtr(&scratch.drain_evidence), permit.drain_evidence_addr);
        try std.testing.expect(std.mem.eql(u8, &scratch.drain_evidence.digest, &permit.drain_evidence_digest));
        try std.testing.expect(std.mem.eql(
            u8,
            &scratch.drain_evidence.completed_exception_digest,
            &permit.completed_exception_digest,
        ));
        switch (case.request_kind) {
            .resize => try std.testing.expect(scratch.control_semantic_verdict.value == .resize),
            .resync => try std.testing.expect(scratch.control_semantic_verdict.value == .resync_ack),
            .detach => unreachable,
        }
        try std.testing.expectEqual(WholeTurnReleaseResult.released, storage.releaseWholeTurnLease(&lease));
    }
}

test "2b2e integration resync ACK transaction publishes before payload cleanup" {
    var fixture = try TestClient.init();
    defer fixture.deinitPeer();
    var storage: ExternalPumpStorage = .{};
    const scratch = try std.testing.allocator.create(ExternalRxTurnScratch);
    defer std.testing.allocator.destroy(scratch);
    defer if (storage.lifecycle != .dead) {
        _ = teardownForTest(&storage);
    };
    var lease: ExternalWholeTurnLease = .{};
    try std.testing.expectEqual(
        ControlSemanticPreparationResult.prepared_pair,
        try prepareF3c1ActualResponse(
            &storage,
            &fixture,
            scratch,
            &lease,
            .{ .resync = .{
                .stream_id = valid_evidence.stream_id,
                .recovery_authority = .{
                    .owner_incarnation = fixture.client.attach_instance_id,
                    .origin = .client,
                    .recovery_epoch = 9,
                },
            } },
            "{\"result\":{\"resync\":true}}",
            .none,
            null,
        ),
    );
    const completed_payload = storage.completed_control.completed.payload.bytes();
    try std.testing.expectEqualStrings(
        "{\"result\":{\"resync\":true}}",
        completed_payload,
    );
    try std.testing.expect(storage.prepareResyncAckTransitionUnderHeldLease(
        &lease,
        scratch,
    ));
    try std.testing.expect(storage.preparedResyncAckTransitionCurrent(
        &lease,
        scratch,
        &scratch.whole_drain_permit,
        &scratch.control_semantic_verdict,
        &scratch.resync_ack_transition,
    ));
    const barrier = scratch.resync_ack_transition.recovery_barrier_absolute;
    try std.testing.expect(barrier != 0);
    try std.testing.expectEqual(
        ConsumeResyncAckResult.consumed,
        storage.consumeResyncAckUnderHeldLease(
            &lease,
            scratch,
            &scratch.whole_drain_permit,
            &scratch.control_semantic_verdict,
            &scratch.resync_ack_transition,
        ),
    );
    const waiting = storage.semantic_state.active.client_recovery.awaiting_snapshot;
    try std.testing.expectEqual(@as(u64, 9), waiting.context.epoch);
    try std.testing.expectEqual(barrier, waiting.recovery_barrier_absolute);
    try std.testing.expect(storage.control_correlation.state == .idle);
    try std.testing.expect(storage.completed_control == .none);
    try std.testing.expectEqual(
        FrozenControlResponseLifecycle.owned,
        scratch.resync_ack_frozen_response.lifecycle,
    );
    try std.testing.expectEqualStrings(
        "{\"result\":{\"resync\":true}}",
        scratch.resync_ack_frozen_response.payload.bytes(),
    );
    try std.testing.expectEqual(
        ConsumeResyncAckResult.invalid,
        storage.consumeResyncAckUnderHeldLease(
            &lease,
            scratch,
            &scratch.whole_drain_permit,
            &scratch.control_semantic_verdict,
            &scratch.resync_ack_transition,
        ),
    );
    ExternalPumpStorage.finishControlResponsePayloadCleanupUnchecked(
        &scratch.resync_ack_frozen_response,
    );
    try std.testing.expectEqual(
        WholeTurnReleaseResult.released,
        storage.releaseWholeTurnLease(&lease),
    );
}

test "2b2e integration ACK receipt tamper move and replay are mutation zero" {
    var fixture = try TestClient.init();
    defer fixture.deinitPeer();
    var storage: ExternalPumpStorage = .{};
    const scratch = try std.testing.allocator.create(ExternalRxTurnScratch);
    defer std.testing.allocator.destroy(scratch);
    defer if (storage.lifecycle != .dead) {
        _ = teardownForTest(&storage);
    };
    var lease: ExternalWholeTurnLease = .{};
    try std.testing.expectEqual(
        ControlSemanticPreparationResult.prepared_pair,
        try prepareF3c1ActualResponse(
            &storage,
            &fixture,
            scratch,
            &lease,
            .{ .resync = .{
                .stream_id = valid_evidence.stream_id,
                .recovery_authority = .{
                    .owner_incarnation = fixture.client.attach_instance_id,
                    .origin = .client,
                    .recovery_epoch = 23,
                },
            } },
            "{\"result\":{\"resync\":true}}",
            .none,
            null,
        ),
    );
    try std.testing.expect(storage.prepareResyncAckTransitionUnderHeldLease(
        &lease,
        scratch,
    ));
    const semantic_before = storage.semantic_state;
    const correlation_before = storage.control_correlation;
    const completed_before = storage.completed_control;
    const saved = scratch.resync_ack_transition;

    scratch.resync_ack_transition.recovery_barrier_absolute += 1;
    scratch.resync_ack_transition.digest = preparedResyncAckTransitionDigest(
        &scratch.resync_ack_transition,
    );
    try std.testing.expectEqual(
        ConsumeResyncAckResult.invalid,
        storage.consumeResyncAckUnderHeldLease(
            &lease,
            scratch,
            &scratch.whole_drain_permit,
            &scratch.control_semantic_verdict,
            &scratch.resync_ack_transition,
        ),
    );
    try std.testing.expect(std.meta.eql(semantic_before, storage.semantic_state));
    try std.testing.expect(std.meta.eql(correlation_before, storage.control_correlation));
    try std.testing.expect(std.meta.eql(completed_before, storage.completed_control));

    scratch.resync_ack_transition = saved;
    var moved = saved;
    try std.testing.expectEqual(
        ConsumeResyncAckResult.invalid,
        storage.consumeResyncAckUnderHeldLease(
            &lease,
            scratch,
            &scratch.whole_drain_permit,
            &scratch.control_semantic_verdict,
            &moved,
        ),
    );
    try std.testing.expect(std.meta.eql(semantic_before, storage.semantic_state));
    try std.testing.expectEqual(
        ConsumeResyncAckResult.consumed,
        storage.consumeResyncAckUnderHeldLease(
            &lease,
            scratch,
            &scratch.whole_drain_permit,
            &scratch.control_semantic_verdict,
            &scratch.resync_ack_transition,
        ),
    );
    try std.testing.expectEqual(
        ConsumeResyncAckResult.invalid,
        storage.consumeResyncAckUnderHeldLease(
            &lease,
            scratch,
            &scratch.whole_drain_permit,
            &scratch.control_semantic_verdict,
            &scratch.resync_ack_transition,
        ),
    );
    ExternalPumpStorage.finishControlResponsePayloadCleanupUnchecked(
        &scratch.resync_ack_frozen_response,
    );
    try std.testing.expectEqual(
        WholeTurnReleaseResult.released,
        storage.releaseWholeTurnLease(&lease),
    );
}

