test "external local screen item cap commits client recovery" {
    var fixture = try TestClient.init();
    defer fixture.deinitPeer();
    const batch_count = external_inbox_limits.max_items / 2 + 1;
    const stream_count = external_inbox_limits.max_items + 1 - batch_count;
    var index: usize = 0;
    while (index < batch_count) : (index += 1) {
        const payload = try fixture.client.allocator.dupe(u8, "s");
        try fixture.client.pending_batches.append(fixture.client.allocator, .{
            .is_snapshot = false,
            .stream_id = valid_evidence.stream_id,
            .bytes = payload,
            .allocator = fixture.client.allocator,
        });
        fixture.client.pending_batch_bytes += payload.len;
    }
    index = 0;
    while (index < stream_count) : (index += 1) {
        const payload = try fixture.client.allocator.dupe(u8, "s");
        try fixture.client.pending_stream.append(fixture.client.allocator, .{
            .header = .{
                .kind = .delta_chunk,
                .stream_id = valid_evidence.stream_id,
                .payload_len = @intCast(payload.len),
                .flags = protocol.Flags.end_stream,
            },
            .payload = payload,
        });
        fixture.client.pending_stream_bytes += payload.len;
    }
    var storage: ExternalPumpStorage = .{};
    try std.testing.expect(
        initTestStorage(&storage, &fixture.client, valid_evidence) ==
            .initialized,
    );
    defer _ = teardownForTest(&storage);
    var cleanup_scratch: ExternalPumpCleanupScratch = .{};
    try std.testing.expect(cleanup_scratch.initInPlace());

    try std.testing.expect(
        storage.prepareAdoption(9, &cleanup_scratch) == .recovery_committed,
    );
    const recovery = storage.semantic_state.active.client_recovery.control_wait;
    try std.testing.expectEqual(@as(u64, 1), recovery.epoch);
    try std.testing.expectEqual(
        @as(i128, 9) + 30 * @as(i128, std.time.ns_per_s),
        recovery.deadline_ns,
    );
    try std.testing.expectEqual(StorageLifecycle.live, storage.lifecycle);
    try std.testing.expectEqual(
        @as(usize, 0),
        storage.owned_client.?.pending_batches.items.len,
    );
    try std.testing.expect(storage.inbox_ledger.accountingView().pristine_zero);
    try std.testing.expectEqual(TeardownResult.cleaned, teardownForTest(&storage));
}

fn recoveryCoreStorage(
    storage: *ExternalPumpStorage,
    incarnation: u64,
    origin: client_pump.RecoveryOrigin,
    epoch: u64,
    token_generation: u64,
    deadline_ns: i128,
) void {
    storage.* = .{
        .lifecycle = .live,
        .saved_self_addr = @intFromPtr(storage),
        .semantic_state = .{ .active = switch (origin) {
            .host => .{ .host_recovery = .{ .snapshot_in_flight = .{
                .context = .{ .epoch = epoch, .deadline_ns = deadline_ns },
                .recovery_barrier_absolute = 1,
                .expected_token_generation = token_generation,
            } } },
            .client => .{ .client_recovery = .{ .snapshot_in_flight = .{
                .context = .{ .epoch = epoch, .deadline_ns = deadline_ns },
                .recovery_barrier_absolute = 1,
                .expected_token_generation = token_generation,
            } } },
        } },
        .evidence_snapshot = .{
            .runtime_id = 1,
            .stream_id = 7,
            .initial_role = .observer,
            .initial_controller_generation = 0,
        },
    };
    bindOwnerIncarnation(storage, incarnation);
}

test "e-core mark publishes applied-pending and read-only immediate poll hint" {
    var storage: ExternalPumpStorage = .{};
    recoveryCoreStorage(&storage, 41, .host, 3, 9, 100);
    const key = client_pump.RecoveryKey{
        .owner_incarnation = 41,
        .origin = .host,
        .recovery_epoch = 3,
        .expected_token_generation = 9,
    };

    const before = ExternalPumpStorage.recoveryPollHint(storage.semantic_state);
    try std.testing.expect(!before.immediate);
    try std.testing.expectEqual(@as(?i128, 100), before.next_deadline_ns);
    try std.testing.expectEqual(
        external_recovery_types.BatchAuthority.recovery_exact,
        storage.preflightBatchAuthority(7, true, key),
    );
    try std.testing.expectEqual(
        client_pump.RecoveryMarkResult.commit_pending,
        storage.markResyncApplied(7, key),
    );
    try std.testing.expect(
        storage.semantic_state.active.host_recovery == .applied_pending,
    );
    const first = ExternalPumpStorage.recoveryPollHint(storage.semantic_state);
    const second = ExternalPumpStorage.recoveryPollHint(storage.semantic_state);
    try std.testing.expect(first.immediate);
    try std.testing.expect(std.meta.eql(first, second));
    try std.testing.expectEqual(@as(?i128, 100), first.next_deadline_ns);
}

test "e-core preflight rejects null recovery and nonnull valid authority" {
    var recovery: ExternalPumpStorage = .{};
