    );
    try std.testing.expect(before.semantic_state.active == .valid);
    try std.testing.expect(
        !ExternalPumpStorage.recoveryPollHint(before.semantic_state).immediate,
    );

    for ([_]i128{ 100, 101 }) |now_ns| {
