test "C4b shared owner snapshot rebuilds freshly and projects each authority" {
    var fixture = try TestClient.init();
    defer fixture.deinitPeer();
    var storage: ExternalPumpStorage = .{};
    try std.testing.expect(
        initTestStorage(&storage, &fixture.client, valid_evidence) ==
            .initialized,
    );
    try std.testing.expect(prepareAdoptionForTest(&storage) == .prepared_adopted);
    try std.testing.expect(storage.commitAdoption() == .adopted);

    const scratch = try std.testing.allocator.create(ExternalRxTurnScratch);
    defer std.testing.allocator.destroy(scratch);
    defer _ = teardownForTest(&storage);
    scratch.* = .{};
    try std.testing.expect(ExternalRxTurnScratch.initInPlace(scratch));
    const invalid_raw_cases = [_]usize{
        1,
        @intFromPtr(&scratch.callback_region) +
            @sizeOf(CallbackRegionToken),
        std.math.maxInt(usize) &
            ~(@as(usize, @alignOf(CallbackRegionToken)) - 1),
    };
    for (invalid_raw_cases) |raw_addr|
        try std.testing.expect(callbackRegionCurrent(
            @ptrFromInt(raw_addr),
            @intFromPtr(&scratch.read),
        ) == null);
    try std.testing.expect(callbackRegionCurrent(
        @ptrFromInt(1),
        @offsetOf(ExternalRxTurnScratch, "read") - 1,
    ) == null);
    var lease: ExternalWholeTurnLease = .{};
    try storage.acquireWholeTurnLease(
        &lease,
        @intFromPtr(scratch),
        @sizeOf(ExternalRxTurnScratch),
    );
    scratch.lifecycle = .busy;
    scratch.authority_ranges_generation = storage.operation_generation;
    defer {
        scratch.lifecycle = .ready;
        _ = storage.releaseWholeTurnLease(&lease);
    }

    const first = buildRxOwnerAuthoritySnapshot(
        &storage,
        &lease,
        scratch,
    ) orelse return error.TestUnexpectedResult;
    const first_digest = first.digest;
    const first_count = first.inventory_count;
    const second = buildRxOwnerAuthoritySnapshot(
        &storage,
        &lease,
        scratch,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 2), scratch.authority_snapshot_build_count);
    try std.testing.expectEqual(first_count, second.inventory_count);
    try std.testing.expectEqualSlices(u8, &first_digest, &second.digest);
    var range_probe: FrozenRxTurnOps = .{};
    const scratch_addr = @intFromPtr(scratch);
    const scratch_end = scratch_addr + @sizeOf(ExternalRxTurnScratch);
    try std.testing.expect(!rxTurnOpsOuterRangeValid(
        @ptrCast(scratch),
        &range_probe,
        second,
        scratch,
    ));
    try std.testing.expect(!rxTurnOpsOuterRangeValid(
        @ptrFromInt(scratch_end - @alignOf(RxTurnOps)),
        &range_probe,
        second,
        scratch,
    ));
    try std.testing.expect(rxTurnOpsOuterRangeValid(
        @ptrFromInt(scratch_end),
        &range_probe,
        second,
        scratch,
    ));
    try std.testing.expect(!rxTurnOpsOuterRangeValid(
        @ptrFromInt(
            std.math.maxInt(usize) &
                ~(@as(usize, @alignOf(RxTurnOps)) - 1),
        ),
        &range_probe,
        second,
        scratch,
    ));

    var intent = ProductIntentAuthority{
        .storage = &storage,
        .lease = &lease,
        .scratch = scratch,
    };
    const intent_view = ProductIntentAuthority.current(&intent) orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 3), scratch.authority_snapshot_build_count);
    try std.testing.expectEqual(second.inventory_count, intent_view.forbidden_ranges.len);

    const ReadProbe = struct {
        value: u8 = 0,

        fn read(
            _: *anyopaque,
            _: posix.fd_t,
            _: []u8,
        ) client_external_rx_read.RxReadOutcome {
            return .would_block;
        }
    };
    const BufferedProbe = struct {
        fn apply(
            _: *anyopaque,
            _: external_inbox_ledger.PayloadView,
        ) LiveScreenApplyResult {
            return .applied;
        }
    };
    var read_probe = ReadProbe{};
    var buffered_probe: u8 = 0;
    const turn_ops = RxTurnOps{
        .buffered = .{
            .context = &buffered_probe,
            .context_len = @sizeOf(u8),
            .apply_live_screen = BufferedProbe.apply,
        },
        .transport = .{
            .context = &read_probe,
            .context_len = @sizeOf(ReadProbe),
            .read = ReadProbe.read,
        },
    };
    var frozen_ops = FrozenRxTurnOps{
        .saved_self_addr = 0,
        .original_ops_addr = @intFromPtr(&turn_ops),
        .fd = second.fd,
        .ops = turn_ops,
    };
    frozen_ops.saved_self_addr = @intFromPtr(&frozen_ops);
    frozen_ops.digest = frozenRxTurnOpsDigest(&frozen_ops);
    var read_authority = ProductRxReadAuthority{
        .storage = &storage,
        .lease = &lease,
        .scratch = scratch,
        .read_ops = &frozen_ops.ops.transport,
        .original_ops = &turn_ops,
        .frozen_ops = &frozen_ops,
    };
    const read_view = ProductRxReadAuthority.current(&read_authority) orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 4), scratch.authority_snapshot_build_count);
    try std.testing.expect(read_view.protected_range_count <=
        client_external_rx_read.max_rx_read_protected_ranges);
    try std.testing.expectEqual(
        @intFromPtr(&scratch.read),
        read_view.scratch_addr,
    );
    const aliased_read_ops = client_external_rx_read.RxReadOps{
        .context = &read_authority,
        .context_len = @sizeOf(ProductRxReadAuthority),
        .read = ReadProbe.read,
    };
    read_authority.read_ops = &aliased_read_ops;
    try std.testing.expect(ProductRxReadAuthority.current(&read_authority) == null);

    var replacement = ProductReplacementAllocationGuard{
        .storage = &storage,
        .lease = &lease,
        .scratch = scratch,
    };
    const captured = ProductReplacementAllocationGuard.check(
        &replacement,
        .capture_before_allocate,
        null,
        null,
    );
    const seal = switch (captured) {
        .seal => |value| value,
        else => return error.TestUnexpectedResult,
    };
    var candidate: u8 = 0;
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &replacement,
            .capture_after_allocate,
            seal,
            .{ .addr = @intFromPtr(&candidate), .len = 1 },
        ) == .seal,
    );
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &replacement,
            .validate_allocated,
            seal,
            .{ .addr = @intFromPtr(&candidate), .len = 1 },
        ) == .accepted,
    );
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &replacement,
            .validate_after_cleanup,
            seal,
            .{
                .addr = @intFromPtr(scratch),
                .len = @sizeOf(ExternalRxTurnScratch),
            },
        ) == .quarantined,
    );
    var stale_seal = seal;
    stale_seal.digest[0] +%= 1;
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &replacement,
            .capture_after_validate,
            stale_seal,
            null,
        ) == .quarantined,
    );
}

test "C4d callback hidden release clears TLS and quarantines every public token drift" {
    var fixture = try TestClient.init();
    defer fixture.deinitPeer();
    var storage: ExternalPumpStorage = .{};
    try std.testing.expect(
        initTestStorage(&storage, &fixture.client, valid_evidence) ==
            .initialized,
    );
    try std.testing.expect(prepareAdoptionForTest(&storage) == .prepared_adopted);
    try std.testing.expect(storage.commitAdoption() == .adopted);
    defer _ = teardownForTest(&storage);
    const scratch = try std.testing.allocator.create(ExternalRxTurnScratch);
    defer std.testing.allocator.destroy(scratch);
    scratch.* = .{};
    try std.testing.expect(ExternalRxTurnScratch.initInPlace(scratch));
    var lease: ExternalWholeTurnLease = .{};
    try storage.acquireWholeTurnLease(
        &lease,
        @intFromPtr(scratch),
        @sizeOf(ExternalRxTurnScratch),
    );
    defer _ = storage.releaseWholeTurnLease(&lease);
    scratch.lifecycle = .busy;

    const Mutation = enum {
        saved_self,
        scratch,
        permit,
        storage,
        lease,
        generation,
        thread,
        epoch,
        lifecycle,
        digest,
    };
    inline for (std.meta.tags(Mutation)) |mutation| {
        scratch.callback_region = .{};
        scratch.lifecycle = .busy;
        var authority: CallbackReleaseAuthority = .{};
        try std.testing.expect(beginPumpCallbackRegion(
            &storage,
            &lease,
            scratch,
            &authority,
        ));
        switch (mutation) {
            .saved_self => scratch.callback_region.saved_self_addr +%= 1,
            .scratch => scratch.callback_region.scratch_addr +%= 1,
            .permit => scratch.callback_region.permit_addr +%= 1,
            .storage => scratch.callback_region.storage_addr +%= 1,
            .lease => scratch.callback_region.lease_addr +%= 1,
            .generation => scratch.callback_region.operation_generation +%= 1,
            .thread => scratch.callback_region.thread_id +%= 1,
            .epoch => scratch.callback_region.epoch +%= 1,
            .lifecycle => scratch.callback_region.lifecycle = .consumed,
            .digest => scratch.callback_region.digest[0] +%= 1,
        }
        try std.testing.expectEqual(
            CallbackReleaseResult.quarantined,
            releaseCallbackRegion(&authority),
        );
        try std.testing.expectEqual(@as(usize, 0), active_callback_region_addr);
        try std.testing.expectEqual(@as(usize, 0), active_callback_release_addr);
        try std.testing.expectEqual(
            ExternalRxTurnScratchLifecycle.terminal,
            scratch.lifecycle,
        );
        try std.testing.expectEqual(
            CallbackRegionLifecycle.quarantined,
            scratch.callback_region.lifecycle,
        );
    }

    scratch.callback_region = .{};
    scratch.lifecycle = .busy;
    var authority: CallbackReleaseAuthority = .{};
    try std.testing.expect(beginPumpCallbackRegion(
        &storage,
        &lease,
        scratch,
        &authority,
    ));
    var copied_authority = authority;
    try std.testing.expectEqual(
        CallbackReleaseResult.invalid_authority,
        releaseCallbackRegion(&copied_authority),
    );
    try std.testing.expect(active_callback_region_addr != 0);
    const CrossThread = struct {
        fn run(
            target: *CallbackReleaseAuthority,
            result: *CallbackReleaseResult,
        ) void {
            result.* = releaseCallbackRegion(target);
        }
    };
    var cross_result: CallbackReleaseResult = .released;
    const thread = try std.Thread.spawn(
        .{},
        CrossThread.run,
        .{ &authority, &cross_result },
    );
    thread.join();
    try std.testing.expectEqual(
        CallbackReleaseResult.invalid_authority,
        cross_result,
    );
    try std.testing.expect(active_callback_region_addr != 0);
    const copied_token = scratch.callback_region;
    try std.testing.expect(!callbackRegionTokenValid(&copied_token));
    try std.testing.expectEqual(
        CallbackReleaseResult.released,
        releaseCallbackRegion(&authority),
    );
    try std.testing.expect(!finishPumpCallbackRegion(
        scratch,
        &authority,
    ));
    try std.testing.expect(resetConsumedCallbackRegion(
        scratch,
        &scratch.callback_region,
    ));

    const saved_epoch = callback_region_epoch;
    callback_region_epoch = std.math.maxInt(u64);
    defer callback_region_epoch = saved_epoch;
    var exhausted: CallbackReleaseAuthority = .{};
    try std.testing.expect(!beginPumpCallbackRegion(
        &storage,
        &lease,
        scratch,
        &exhausted,
    ));
    try std.testing.expect(callbackRegionTokenPristine(
        &scratch.callback_region,
    ));
    try std.testing.expect(callbackReleasePristine(&exhausted));
}

test "C4d drifted A callback releases TLS and leaves B reusable after nested blocker" {
    var fixture_a = try TestClient.init();
    defer fixture_a.deinitPeer();
    var fixture_b = try TestClient.init();
    defer fixture_b.deinitPeer();
    var storage_a: ExternalPumpStorage = .{};
    var storage_b: ExternalPumpStorage = .{};
    inline for (.{ .{ &storage_a, &fixture_a.client }, .{ &storage_b, &fixture_b.client } }) |pair| {
        try std.testing.expect(
            initTestStorage(pair[0], pair[1], valid_evidence) == .initialized,
        );
        try std.testing.expect(
            prepareAdoptionForTest(pair[0]) == .prepared_adopted,
        );
        try std.testing.expect(pair[0].commitAdoption() == .adopted);
    }
    defer _ = teardownForTest(&storage_a);
    defer _ = teardownForTest(&storage_b);
    const scratch_a = try std.testing.allocator.create(ExternalRxTurnScratch);
    defer std.testing.allocator.destroy(scratch_a);
    const scratch_b = try std.testing.allocator.create(ExternalRxTurnScratch);
    defer std.testing.allocator.destroy(scratch_b);
    scratch_a.* = .{};
    scratch_b.* = .{};
    try std.testing.expect(ExternalRxTurnScratch.initInPlace(scratch_a));
    try std.testing.expect(ExternalRxTurnScratch.initInPlace(scratch_b));

    const BProbe = struct {
        fn apply(
            _: *anyopaque,
            _: external_inbox_ledger.PayloadView,
        ) LiveScreenApplyResult {
            return .applied;
        }
        fn read(
            _: *anyopaque,
            _: posix.fd_t,
            _: []u8,
        ) client_external_rx_read.RxReadOutcome {
            return .would_block;
        }
    };
    var b_probe: u8 = 0;
    var b_buffered_probe: u8 = 0;
    const b_ops = RxTurnOps{
        .buffered = .{
            .context = &b_buffered_probe,
            .context_len = @sizeOf(u8),
            .apply_live_screen = BProbe.apply,
        },
        .transport = .{
            .context = &b_probe,
            .context_len = @sizeOf(u8),
            .read = BProbe.read,
        },
    };
    const AProbe = struct {
        scratch_a: *ExternalRxTurnScratch,
        storage_b: *ExternalPumpStorage,
        scratch_b: *ExternalRxTurnScratch,
        b_ops: *const RxTurnOps,
        nested: ?client_pump.TurnResult = null,

        fn apply(
            _: *anyopaque,
            _: external_inbox_ledger.PayloadView,
        ) LiveScreenApplyResult {
            return .applied;
        }
        fn read(
            raw: *anyopaque,
            _: posix.fd_t,
            _: []u8,
        ) client_external_rx_read.RxReadOutcome {
            const self: *@This() = @ptrCast(@alignCast(raw));
            self.nested = self.storage_b.pumpRxTurn(
                .{ .readable = true, .writable = false, .now_ns = 1 },
                self.b_ops,
                self.scratch_b,
            );
            self.scratch_a.callback_region.digest[0] +%= 1;
            return .would_block;
        }
    };
    var a_probe = AProbe{
        .scratch_a = scratch_a,
        .storage_b = &storage_b,
        .scratch_b = scratch_b,
        .b_ops = &b_ops,
    };
    var a_buffered_probe: u8 = 0;
    const a_ops = RxTurnOps{
        .buffered = .{
            .context = &a_buffered_probe,
            .context_len = @sizeOf(u8),
            .apply_live_screen = AProbe.apply,
        },
        .transport = .{
            .context = &a_probe,
            .context_len = @sizeOf(AProbe),
            .read = AProbe.read,
        },
    };
    const a_result = storage_a.pumpRxTurn(
        .{ .readable = true, .writable = false, .now_ns = 1 },
        &a_ops,
        scratch_a,
    );
    try std.testing.expect(a_result.terminal != null);
    try std.testing.expect(a_probe.nested.?.inherited_work_ready);
    try std.testing.expect(a_probe.nested.?.terminal == null);
    try std.testing.expectEqual(@as(usize, 0), active_callback_region_addr);
    try std.testing.expectEqual(@as(usize, 0), active_callback_release_addr);
    try std.testing.expectEqual(
        ExternalRxTurnScratchLifecycle.terminal,
        scratch_a.lifecycle,
    );
    try std.testing.expectEqual(
        ExternalRxTurnScratchLifecycle.ready,
        scratch_b.lifecycle,
    );
    const b_result = storage_b.pumpRxTurn(
        .{ .readable = true, .writable = false, .now_ns = 2 },
        &b_ops,
        scratch_b,
    );
    try std.testing.expect(b_result.terminal == null);
}

test "C4d product replacement guard rejects phase copy candidate parser inventory and lease drift" {
    var fixture = try TestClient.init();
    defer fixture.deinitPeer();
    var storage: ExternalPumpStorage = .{};
    try std.testing.expect(
        initTestStorage(&storage, &fixture.client, valid_evidence) ==
            .initialized,
    );
    try std.testing.expect(prepareAdoptionForTest(&storage) == .prepared_adopted);
    try std.testing.expect(storage.commitAdoption() == .adopted);

    const scratch = try std.testing.allocator.create(ExternalRxTurnScratch);
    defer std.testing.allocator.destroy(scratch);
    defer _ = teardownForTest(&storage);
    scratch.* = .{};
    try std.testing.expect(ExternalRxTurnScratch.initInPlace(scratch));
    var lease: ExternalWholeTurnLease = .{};
    try storage.acquireWholeTurnLease(
        &lease,
        @intFromPtr(scratch),
        @sizeOf(ExternalRxTurnScratch),
    );
    defer {
        scratch.lifecycle = .ready;
        _ = storage.releaseWholeTurnLease(&lease);
    }
    scratch.lifecycle = .busy;
    scratch.authority_ranges_generation = storage.operation_generation;

    var candidate: u8 = 0;
    const candidate_range = client_external_mode.ReplacementCandidate{
        .addr = @intFromPtr(&candidate),
        .len = 1,
    };
    var guard = ProductReplacementAllocationGuard{
        .storage = &storage,
        .lease = &lease,
        .scratch = scratch,
        .admitted_len = 1,
    };
    const captured = ProductReplacementAllocationGuard.check(
        &guard,
        .capture_before_allocate,
        null,
        null,
    );
    const seal = switch (captured) {
        .seal => |value| value,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &guard,
            .validate_allocated,
            seal,
            candidate_range,
        ) == .quarantined,
    );
    var copied = guard;
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &copied,
            .capture_after_allocate,
            seal,
            candidate_range,
        ) == .quarantined,
    );
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &guard,
            .capture_after_allocate,
            seal,
            candidate_range,
        ) == .seal,
    );
    var wrong_candidate = candidate_range;
    wrong_candidate.addr +%= 1;
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &guard,
            .validate_allocated,
            seal,
            wrong_candidate,
        ) == .quarantined,
    );
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &guard,
            .validate_allocated,
            seal,
            candidate_range,
        ) == .accepted,
    );

    const client = &storage.owned_client.?;
    client.parser.expected_major +%= 1;
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &guard,
            .capture_after_validate,
            seal,
            candidate_range,
        ) == .quarantined,
    );
    client.parser.expected_major -%= 1;
    lease.digest[0] +%= 1;
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &guard,
            .capture_after_validate,
            seal,
            candidate_range,
        ) == .quarantined,
    );
    lease.digest[0] -%= 1;
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &guard,
            .capture_after_validate,
            seal,
            candidate_range,
        ) == .seal,
    );

    var inventory_guard = ProductReplacementAllocationGuard{
        .storage = &storage,
        .lease = &lease,
        .scratch = scratch,
        .admitted_len = 1,
    };
    const inventory_captured = ProductReplacementAllocationGuard.check(
        &inventory_guard,
        .capture_before_allocate,
        null,
        null,
    );
    const inventory_seal = switch (inventory_captured) {
        .seal => |value| value,
        else => return error.TestUnexpectedResult,
    };
    storage.completed_control = .terminal;
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &inventory_guard,
            .capture_after_allocate,
            inventory_seal,
            candidate_range,
        ) == .quarantined,
    );
    storage.completed_control = .none;

    var alias_guard = ProductReplacementAllocationGuard{
        .storage = &storage,
        .lease = &lease,
        .scratch = scratch,
        .admitted_len = 1,
    };
    const alias_captured = ProductReplacementAllocationGuard.check(
        &alias_guard,
        .capture_before_allocate,
        null,
        null,
    );
    const alias_seal = switch (alias_captured) {
        .seal => |value| value,
        else => return error.TestUnexpectedResult,
    };
    const alias_candidate = client_external_mode.ReplacementCandidate{
        .addr = @intFromPtr(scratch),
        .len = @sizeOf(ExternalRxTurnScratch),
    };
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &alias_guard,
            .capture_after_allocate,
            alias_seal,
            alias_candidate,
        ) == .seal,
    );
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &alias_guard,
            .validate_allocated,
            alias_seal,
            alias_candidate,
        ) == .quarantined,
    );
}

test "C4d product replacement cleanup requires validated capture and seals abort and zero-cap commit" {
    const Helper = struct {
        fn advance(
            guard: *ProductReplacementAllocationGuard,
            candidate: client_external_mode.ReplacementCandidate,
        ) !client_external_mode.ReplacementAuthoritySeal {
            const captured = ProductReplacementAllocationGuard.check(
                guard,
                .capture_before_allocate,
                null,
                null,
            );
            const seal = switch (captured) {
                .seal => |value| value,
                else => return error.TestUnexpectedResult,
            };
            try std.testing.expect(
                ProductReplacementAllocationGuard.check(
                    guard,
                    .capture_after_allocate,
                    seal,
                    candidate,
                ) == .seal,
            );
            try std.testing.expect(
                ProductReplacementAllocationGuard.check(
                    guard,
                    .validate_allocated,
                    seal,
                    candidate,
                ) == .accepted,
            );
            return seal;
        }

        fn captureValidated(
            guard: *ProductReplacementAllocationGuard,
            seal: client_external_mode.ReplacementAuthoritySeal,
            candidate: client_external_mode.ReplacementCandidate,
        ) !void {
            try std.testing.expect(
                ProductReplacementAllocationGuard.check(
                    guard,
                    .capture_after_validate,
                    seal,
                    candidate,
                ) == .seal,
            );
        }
    };

    var fixture = try TestClient.init();
    defer fixture.deinitPeer();
    var storage: ExternalPumpStorage = .{};
    try std.testing.expect(
        initTestStorage(&storage, &fixture.client, valid_evidence) ==
            .initialized,
    );
    try std.testing.expect(prepareAdoptionForTest(&storage) == .prepared_adopted);
    try std.testing.expect(storage.commitAdoption() == .adopted);

    const scratch = try std.testing.allocator.create(ExternalRxTurnScratch);
    defer std.testing.allocator.destroy(scratch);
    defer _ = teardownForTest(&storage);
    scratch.* = .{};
    try std.testing.expect(ExternalRxTurnScratch.initInPlace(scratch));
    var lease: ExternalWholeTurnLease = .{};
    try storage.acquireWholeTurnLease(
        &lease,
        @intFromPtr(scratch),
        @sizeOf(ExternalRxTurnScratch),
    );
    defer {
        scratch.lifecycle = .ready;
        _ = storage.releaseWholeTurnLease(&lease);
    }
    scratch.lifecycle = .busy;
    scratch.authority_ranges_generation = storage.operation_generation;

    const client = &storage.owned_client.?;
    const state = switch (client.io_mode) {
        .external => |*external| external,
        .blocking => return error.TestUnexpectedResult,
    };
    const bound_provenance = state.rx_provenance;
    var candidate_byte: u8 = 0;
    const candidate = client_external_mode.ReplacementCandidate{
        .addr = @intFromPtr(&candidate_byte),
        .len = 1,
    };

    var skipped = ProductReplacementAllocationGuard{
        .storage = &storage,
        .lease = &lease,
        .scratch = scratch,
        .admitted_len = 1,
    };
    const skipped_seal = try Helper.advance(&skipped, candidate);
    state.rx_provenance = .{ .lifecycle = .terminal };
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &skipped,
            .capture_before_cleanup,
            skipped_seal,
            candidate,
        ) == .quarantined,
    );
    state.rx_provenance = bound_provenance;

    var aborted = ProductReplacementAllocationGuard{
        .storage = &storage,
        .lease = &lease,
        .scratch = scratch,
        .admitted_len = 1,
    };
    const abort_seal = try Helper.advance(&aborted, candidate);
    try Helper.captureValidated(&aborted, abort_seal, candidate);
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &aborted,
            .capture_after_validate,
            abort_seal,
            candidate,
        ) == .quarantined,
    );
    state.rx_provenance = .{ .lifecycle = .terminal };
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &aborted,
            .capture_before_cleanup,
            abort_seal,
            candidate,
        ) == .seal,
    );
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &aborted,
            .validate_after_cleanup,
            abort_seal,
            candidate,
        ) == .accepted,
    );
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &aborted,
            .validate_after_cleanup,
            abort_seal,
            candidate,
        ) == .quarantined,
    );
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &aborted,
            .capture_after_cleanup_validate,
            abort_seal,
            candidate,
        ) == .seal,
    );
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &aborted,
            .capture_after_cleanup_validate,
            abort_seal,
            candidate,
        ) == .quarantined,
    );
    state.rx_provenance = bound_provenance;

    var abort_drift = ProductReplacementAllocationGuard{
        .storage = &storage,
        .lease = &lease,
        .scratch = scratch,
        .admitted_len = 1,
    };
    const drift_seal = try Helper.advance(&abort_drift, candidate);
    try Helper.captureValidated(&abort_drift, drift_seal, candidate);
    state.rx_provenance = .{ .lifecycle = .terminal };
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &abort_drift,
            .capture_before_cleanup,
            drift_seal,
            candidate,
        ) == .seal,
    );
    client.parser.expected_major +%= 1;
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &abort_drift,
            .validate_after_cleanup,
            drift_seal,
            candidate,
        ) == .quarantined,
    );
    client.parser.expected_major -%= 1;
    state.rx_provenance = bound_provenance;

    try std.testing.expectEqual(@as(usize, 0), client.parser.buf.capacity);
    const replacement = try client.parser.allocator.alloc(u8, 1);
    defer client.parser.allocator.free(replacement);
    var committed = ProductReplacementAllocationGuard{
        .storage = &storage,
        .lease = &lease,
        .scratch = scratch,
        .admitted_len = 1,
    };
    const commit_candidate = client_external_mode.ReplacementCandidate{
        .addr = @intFromPtr(replacement.ptr),
        .len = replacement.len,
    };
    const commit_seal = try Helper.advance(&committed, commit_candidate);
    try Helper.captureValidated(&committed, commit_seal, commit_candidate);
    const source_buf = client.parser.buf;
    const source_head = client.parser.head;
    state.rx_provenance = .{ .lifecycle = .terminal };
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &committed,
            .capture_before_cleanup,
            commit_seal,
            null,
        ) == .seal,
    );
    client.parser.buf.items = replacement;
    client.parser.buf.capacity = replacement.len;
    client.parser.head = 0;
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &committed,
            .validate_after_cleanup,
            commit_seal,
            null,
        ) == .accepted,
    );
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &committed,
            .capture_after_cleanup_validate,
            commit_seal,
            null,
        ) == .seal,
    );
    client.parser.buf = source_buf;
    client.parser.head = source_head;
    state.rx_provenance = bound_provenance;
}

test "C4d injected zero-prefix would-block settles and publishes drain once" {
    const ApplyProbe = struct {
        apply_calls: *usize,

        fn apply(
            raw: *anyopaque,
            _: external_inbox_ledger.PayloadView,
        ) LiveScreenApplyResult {
            const self: *@This() = @ptrCast(@alignCast(raw));
            self.apply_calls.* += 1;
            return .applied;
        }
    };
    const Probe = struct {
        read_calls: usize = 0,
        apply_calls: usize = 0,

        fn read(
            raw: *anyopaque,
            _: posix.fd_t,
            _: []u8,
        ) client_external_rx_read.RxReadOutcome {
            const self: *@This() = @ptrCast(@alignCast(raw));
            self.read_calls += 1;
            return .would_block;
        }
    };

    var fixture = try TestClient.init();
    defer fixture.deinitPeer();
    var storage: ExternalPumpStorage = .{};
    try std.testing.expect(
        initTestStorage(&storage, &fixture.client, valid_evidence) ==
            .initialized,
    );
    try std.testing.expect(prepareAdoptionForTest(&storage) == .prepared_adopted);
    try std.testing.expect(storage.commitAdoption() == .adopted);
    var fence_clear: projection_test.PreparedInitialFenceClear = .{};
    try std.testing.expect(projection_test.prepare(&storage, &fence_clear));
    try std.testing.expectEqual(
        projection_test.InitialFenceClearResult.cleared,
        projection_test.commit(&storage, &fence_clear),
    );
    defer _ = teardownForTest(&storage);

    const scratch = try std.testing.allocator.create(ExternalRxTurnScratch);
    defer std.testing.allocator.destroy(scratch);
    scratch.* = .{};
    try std.testing.expect(ExternalRxTurnScratch.initInPlace(scratch));
    var probe = Probe{};
    var apply_probe = ApplyProbe{ .apply_calls = &probe.apply_calls };
    const ops = RxTurnOps{
        .buffered = .{
            .context = &apply_probe,
            .context_len = @sizeOf(ApplyProbe),
            .apply_live_screen = ApplyProbe.apply,
        },
        .transport = .{
            .context = &probe,
            .context_len = @sizeOf(Probe),
            .read = Probe.read,
        },
    };
    var drain_recorder = RxDrainTestRecorder{};
    var authority_recorder = AuthorityAdapterTestRecorder{};
    rx_drain_test_recorder = &drain_recorder;
    authority_adapter_test_recorder = &authority_recorder;
    defer rx_drain_test_recorder = null;
    defer authority_adapter_test_recorder = null;
    const result = storage.pumpRxTurn(
        .{ .readable = true, .writable = false, .now_ns = 1 },
        &ops,
        scratch,
    );
    try std.testing.expect(result.terminal == null);
    try std.testing.expect(result.authority_clear);
    try std.testing.expectEqual(@as(usize, 1), probe.read_calls);
    try std.testing.expectEqual(@as(usize, 0), probe.apply_calls);
    try std.testing.expectEqual(@as(usize, 0), result.rx_read_bytes);
    try std.testing.expectEqual(@as(usize, 0), result.rx_bytes);
    try std.testing.expectEqual(@as(usize, 0), result.rx_frames);
    try std.testing.expectEqual(@as(u8, 3), drain_recorder.len);
    try std.testing.expectEqual(
        [_]RxDrainTestEvent{ .consumed, .published, .decide },
        drain_recorder.events,
    );
    rx_drain_test_recorder = null;
    authority_adapter_test_recorder = null;
    try std.testing.expectEqual(@as(u8, 4), authority_recorder.len);
    try std.testing.expectEqual(
        [_]AuthorityAdapterTestEvent{
            .prepared,
            .validated,
            .aborted,
            .reset,
        },
        authority_recorder.events[0..4].*,
    );
    try std.testing.expect(
        ExternalPumpStorage.authorityDestinationsPristine(scratch),
    );
    try std.testing.expectEqual(@as(u64, 2), scratch.turn_generation);
    try std.testing.expect(scratch.read.isReady());
    try std.testing.expectEqual(
        RxDrainEvidenceLifecycle.finished,
        scratch.drain_evidence.lifecycle,
    );
    try std.testing.expect(ExternalPumpStorage.rxDrainEvidenceSealed(
        &scratch.drain_evidence,
    ));
    const first_generation = scratch.drain_evidence.read_attempt_generation;
    const first_operation_generation =
        scratch.drain_evidence.operation_generation;
    const first_digest = scratch.drain_evidence.digest;
    var stale_copy = scratch.drain_evidence;
    try std.testing.expect(!ExternalPumpStorage.rxDrainEvidenceSealed(
        &stale_copy,
    ));

    const second = storage.pumpRxTurn(
        .{ .readable = true, .writable = false, .now_ns = 2 },
        &ops,
        scratch,
    );
    try std.testing.expect(second.terminal == null);
    try std.testing.expect(second.authority_clear);
    try std.testing.expectEqual(@as(usize, 2), probe.read_calls);
    try std.testing.expectEqual(
        RxDrainEvidenceLifecycle.finished,
        scratch.drain_evidence.lifecycle,
    );
    try std.testing.expect(ExternalPumpStorage.rxDrainEvidenceSealed(
        &scratch.drain_evidence,
    ));
    try std.testing.expectEqual(
        first_generation,
        scratch.drain_evidence.read_attempt_generation,
    );
    try std.testing.expect(
        scratch.drain_evidence.operation_generation >
            first_operation_generation,
    );
    try std.testing.expect(!std.mem.eql(
        u8,
        &first_digest,
        &scratch.drain_evidence.digest,
    ));

    scratch.drain_evidence.lifecycle = .consumed;
    scratch.drain_evidence.digest =
        ExternalPumpStorage.drainEvidenceDigest(&scratch.drain_evidence);
    const before_callback_finish = scratch.drain_evidence;
    active_callback_region_addr = @intFromPtr(scratch);
    try std.testing.expect(!ExternalPumpStorage.armRxDrainEvidence(
        scratch,
        scratch.drain_evidence.read_attempt_generation,
    ));
    try std.testing.expect(!ExternalPumpStorage.finishRxDrainEvidence(scratch));
    active_callback_region_addr = 0;
    try std.testing.expect(std.meta.eql(
        before_callback_finish,
        scratch.drain_evidence,
    ));
    try std.testing.expect(ExternalPumpStorage.finishRxDrainEvidence(scratch));

    const pristine = scratch.drain_evidence;
    inline for ([_][]const u8{
        "storage_addr",
        "lease_generation",
        "parser_addr",
        "owner_inventory_generation",
        "receipt_addr",
        "seed_addr",
        "prepared_seed_authority_digest",
    }) |field_name| {
        if (comptime std.mem.eql(u8, field_name, "storage_addr"))
            scratch.drain_evidence.storage_addr +%= 1
        else if (comptime std.mem.eql(u8, field_name, "lease_generation"))
            scratch.drain_evidence.lease_generation +%= 1
        else if (comptime std.mem.eql(u8, field_name, "parser_addr"))
            scratch.drain_evidence.parser_addr +%= 1
        else if (comptime std.mem.eql(
            u8,
            field_name,
            "owner_inventory_generation",
        ))
            scratch.drain_evidence.owner_inventory_generation +%= 1
        else if (comptime std.mem.eql(u8, field_name, "receipt_addr"))
            scratch.drain_evidence.receipt_addr +%= 1
        else if (comptime std.mem.eql(u8, field_name, "seed_addr"))
            scratch.drain_evidence.seed_addr +%= 1
        else
            scratch.drain_evidence.prepared_seed_authority_digest[0] ^= 1;
        const corrupted = scratch.drain_evidence;
        try std.testing.expect(!ExternalPumpStorage.rxDrainEvidenceSealed(
            &scratch.drain_evidence,
        ));
        try std.testing.expect(!storage.resetFinishedRxDrainEvidence(scratch));
        try std.testing.expect(std.meta.eql(
            corrupted,
            scratch.drain_evidence,
        ));
        scratch.drain_evidence = pristine;
        try std.testing.expect(ExternalPumpStorage.rxDrainEvidenceSealed(
            &scratch.drain_evidence,
        ));
    }

    var foreign_storage = storage;
    const before_foreign_reset = scratch.drain_evidence;
    try std.testing.expect(
        !foreign_storage.resetFinishedRxDrainEvidence(scratch),
    );
    try std.testing.expect(std.meta.eql(
        before_foreign_reset,
        scratch.drain_evidence,
    ));
    var moved_scratch = scratch.*;
    const before_moved_reset = moved_scratch.drain_evidence;
    try std.testing.expect(
        !storage.resetFinishedRxDrainEvidence(&moved_scratch),
    );
    try std.testing.expect(std.meta.eql(
        before_moved_reset,
        moved_scratch.drain_evidence,
    ));

    try std.testing.expect(storage.resetFinishedRxDrainEvidence(scratch));
    try std.testing.expect(rxDrainEvidencePristine(&scratch.drain_evidence));
    const reset_once = scratch.drain_evidence;
    try std.testing.expect(!storage.resetFinishedRxDrainEvidence(scratch));
    try std.testing.expect(std.meta.eql(reset_once, scratch.drain_evidence));

    const third = storage.pumpRxTurn(
        .{ .readable = true, .writable = false, .now_ns = 3 },
        &ops,
        scratch,
    );
    try std.testing.expect(third.terminal == null);
    try std.testing.expect(third.authority_clear);
    try std.testing.expectEqual(@as(usize, 3), probe.read_calls);
    try std.testing.expectEqual(
        RxDrainEvidenceLifecycle.finished,
        scratch.drain_evidence.lifecycle,
    );
    try std.testing.expect(
        scratch.drain_evidence.operation_generation >
            first_operation_generation,
    );
    try std.testing.expect(!ExternalPumpStorage.rxDrainEvidenceSealed(
        &stale_copy,
    ));

    const evidence_before_reconstruction = scratch.drain_evidence;
    try std.testing.expectEqual(TeardownResult.cleaned, teardownForTest(&storage));
    storage = .{};
    var replacement_fixture = try TestClient.init();
    defer replacement_fixture.deinitPeer();
    try std.testing.expect(
        initTestStorageWithAttachInstanceForTest(
            &storage,
            &replacement_fixture.client,
            valid_evidence,
            .{ .test_skip_process_owner_reservation = true },
            2,
        ) == .initialized,
    );
    try std.testing.expect(prepareAdoptionForTest(&storage) == .prepared_adopted);
    try std.testing.expect(storage.commitAdoption() == .adopted);
    try std.testing.expect(!storage.resetFinishedRxDrainEvidence(scratch));
    try std.testing.expect(std.meta.eql(
        evidence_before_reconstruction,
        scratch.drain_evidence,
    ));

    try std.testing.expectEqual(TeardownResult.cleaned, teardownForTest(&storage));
    storage = .{};
