    const payload = [_]u8{'x'} ** (client_external_rx_read.max_rx_read_attempts_per_turn * 2);
    const wire = try framing.encodeFrame(
        std.testing.allocator,
        .{
            .kind = .delta_chunk,
            .stream_id = valid_evidence.stream_id,
            .flags = protocol.Flags.end_stream,
